/**
 * Bible Book 16: நெகேமியா (Nehemiah)
 */
if (typeof window.registerBibleBook === 'function') {
  window.registerBibleBook(16, {"id": 16, "testament": "OT", "code": "NEH", "name_en": "Nehemiah", "name_ta": "நெகேமியா", "category": "History", "category_ta": "சரித்திரம்", "total_chapters": 13, "chapters": {"1": {"chapter": 1, "duration": 180.92, "audio_url": "audio_ot/OT16_01.mp3", "total_verses": 11, "verses": [{"verse": 1, "start": 4.8, "end": 15.78, "ta": "அகலியாவின் குமாரனாகிய நெகேமியாவின் நடபடிகள்: இருபதாம் வருஷம் கிஸ்லேயு மாதத்தில் நான் சூசானென்னும் அரமனையில் இருக்கும்போது சம்பவித்தது என்னவென்றால்,", "en": "The words of Nehemiah the son of Hachaliah. And it came to pass in the month Chisleu, in the twentieth year, as I was in Shushan the palace,"}, {"verse": 2, "start": 15.78, "end": 31.08, "ta": "என் சகோதரரில் ஒருவனாகிய ஆனானியும், வேறே சில மனுஷரும் யூதாவிலிருந்து வந்தார்கள்; அவர்களிடத்தில் நான் சிறையிருப்பில் மீந்து தப்பின யூதரின் செய்தியையும், எருசலேமின் செய்தியையும் விசாரித்தேன்.", "en": "That Hanani, one of my brethren, came, he and certain men of Judah; and I asked them concerning the Jews that had escaped, which were left of the captivity, and concerning Jerusalem."}, {"verse": 3, "start": 31.08, "end": 48.66, "ta": "அதற்கு அவர்கள்: சிறையிருப்பில் மீந்திருக்கிறவர்கள் அந்தத் தேசத்திலே மகா தீங்கையும் நிந்தையையும் அநுபவிக்கிறார்கள்; எருசலேமின் அலங்கம் இடிபட்டதும், அதின் வாசல்கள் அக்கினியால் சுட்டெரிக்கப்பட்டதுமாய்க் கிடக்கிறது என்றார்கள்.", "en": "And they said unto me, The remnant that are left of the captivity there in the province are in great affliction and reproach: the wall of Jerusalem also is broken down, and the gates thereof are burned with fire."}, {"verse": 4, "start": 48.66, "end": 58.54, "ta": "இந்த வார்த்தைகளைக் கேட்டபோது நான் உட்கார்ந்து அழுது, சிலநாளாய்த் துக்கித்து, உபவாசித்து, மன்றாடி, பரலோகத்தின் தேவனை நோக்கி:", "en": "And it came to pass, when I heard these words, that I sat down and wept, and mourned certain days, and fasted, and prayed before the God of heaven,"}, {"verse": 5, "start": 58.54, "end": 71.87, "ta": "பரலோகத்தின் தேவனாகிய கர்த்தாவே, உம்மில் அன்புகூர்ந்து, உம்முடைய கற்பனைகளைக் கைக்கொள்ளுகிறவர்களுக்கு, உடன்படிக்கையையும் கிருபையையும் காக்கிற மகத்துவமும் பயங்கரமுமான தேவனே,", "en": "And said, I beseech thee, O LORD God of heaven, the great and terrible God, that keepeth covenant and mercy for them that love him and observe his commandments:"}, {"verse": 6, "start": 71.87, "end": 95.73, "ta": "உமது அடியாராகிய இஸ்ரவேல் புத்திரருக்காக இன்று இரவும்பகலும் உமக்கு முன்பாக மன்றாடி, இஸ்ரவேல் புத்திரராகிய நாங்கள் உமக்கு விரோதமாகச் செய்த பாவங்களை அறிக்கையிடுகிற அடியேனுடைய ஜெபத்தைக்கேட்கிறதற்கு, உம்முடைய செவி கவனித்தும், உம்முடைய கண்கள் திறந்தும் இருப்பதாக; நானும் என் தகப்பன் வீட்டாரும் பாவஞ்செய்தோம்.", "en": "Let thine ear now be attentive, and thine eyes open, that thou mayest hear the prayer of thy servant, which I pray before thee now, day and night, for the children of Israel thy servants, and confess the sins of the children of Israel, which we have sinned against thee: both I and my father’s house have sinned."}, {"verse": 7, "start": 95.73, "end": 109.06, "ta": "நாங்கள் உமக்கு முன்பாக மிகவும் கெட்டவர்களாய் நடந்தோம்; நீர் உம்முடைய தாசனாகிய மோசேக்குக்கற்பித்த கற்பனைகளையும், கட்டளைகளையும், நியாயங்களையும் கைக்கொள்ளாதேபோனோம்.", "en": "We have dealt very corruptly against thee, and have not kept the commandments, nor the statutes, nor the judgments, which thou commandedst thy servant Moses."}, {"verse": 8, "start": 109.06, "end": 115.06, "ta": "நீங்கள் கட்டளையை மீறினால், நான் உங்களை ஜாதிகளுக்குள்ளே சிதறடிப்பேன் என்றும்,", "en": "Remember, I beseech thee, the word that thou commandedst thy servant Moses, saying, If ye transgress, I will scatter you abroad among the nations:"}, {"verse": 9, "start": 115.06, "end": 142.74, "ta": "நீங்கள் என்னிடத்தில் திரும்பி, என் கற்பனைகளைக் கைக்கொண்டு, அவைகளின்படி செய்வீர்களானால், உங்களிலே தள்ளுண்டு போனவர்கள் வானத்தின் கடையாந்தரத்தில் இருந்தாலும், நான் அங்கேயிருந்து அவர்களைச் சேர்த்து, என் நாமம் விளங்கும்படி நான் தெரிந்துகொண்ட ஸ்தலத்துக்கு அவர்களைக் கொண்டுவருவேனேன்றும் தேவரீர் உம்முடைய தாசனாகிய மோசேக்குக் கட்டளையிட்ட வார்த்தையை நினைத்தருளும்.", "en": "But if ye turn unto me, and keep my commandments, and do them; though there were of you cast out unto the uttermost part of the heaven, yet will I gather them from thence, and will bring them unto the place that I have chosen to set my name there."}, {"verse": 10, "start": 142.74, "end": 152.18, "ta": "தேவரீர் உமது மகா வல்லமையினாலும், உமது பலத்த கரத்தினாலும், மீட்டுக்கொண்ட உமது அடியாரும் உமது ஜனங்களும் இவர்கள்தானே.", "en": "Now these are thy servants and thy people, whom thou hast redeemed by thy great power, and by thy strong hand."}, {"verse": 11, "start": 152.18, "end": 179.42, "ta": "ஆண்டவரே, உமது அடியானின் ஜெபத்தையும், உமது நாமத்துக்குப் பயப்படவேண்டும் என்று விரும்புகிற உமது அடியாரின் ஜெபத்தையும் உமது செவிகள் கவனித்திருப்பதாக; இன்றைக்கு உமது அடியானுக்குக் காரியத்தைக் கைக்கூடி வரப்பண்ணி, இந்த மனுஷனுக்கு முன்பாக எனக்கு இரக்கம் கிடைக்கப்பண்ணியருளும் என்று பிரார்த்தித்தேன். நான் ராஜாவுக்குப் பானபாத்திரக்காரனாயிருந்தேன்.", "en": "O Lord, I beseech thee, let now thine ear be attentive to the prayer of thy servant, and to the prayer of thy servants, who desire to fear thy name: and prosper, I pray thee, thy servant this day, and grant him mercy in the sight of this man. For I was the king’s cupbearer."}]}, "2": {"chapter": 2, "duration": 330.58, "audio_url": "audio_ot/OT16_02.mp3", "total_verses": 20, "verses": [{"verse": 1, "start": 3.8, "end": 19.83, "ta": "அர்தசஷ்டா ராஜாவின் இருபதாம் வருஷம் நிசான் மாதத்திலே, திராட்சரசம் ராஜாவுக்கு முன்பாக வைத்திருக்கையில், நான் அதை எடுத்து அவருக்குக் கொடுத்தேன்; நான் முன் ஒருபோதும் அவர் சமுகத்தில் துக்கமாயிருந்ததில்லை.", "en": "And it came to pass in the month Nisan, in the twentieth year of Artaxerxes the king, that wine was before him: and I took up the wine, and gave it unto the king. Now I had not been beforetime sad in his presence."}, {"verse": 2, "start": 19.83, "end": 33.38, "ta": "அப்பொழுது ராஜா என்னைப்பார்த்து: நீ துக்கமுகமாயிருக்கிறது என்ன? உனக்கு வியாதியில்லையே, இது மனதின் துக்கமே ஒழிய வேறொன்றும் அல்ல என்றார்; அப்பொழுது நான் மிகவும் பயந்து,", "en": "Wherefore the king said unto me, Why is thy countenance sad, seeing thou art not sick? this is nothing else but sorrow of heart. Then I was very sore afraid,"}, {"verse": 3, "start": 33.38, "end": 50.8, "ta": "ராஜாவை நோக்கி: ராஜா என்றைக்கும் வாழ்க; என் பிதாக்களின் கல்லறைகள் இருக்கும் ஸ்தலமாகிய நகரம் பாழானதும், அதின் வாசல்கள் அக்கினியால் சுட்டெரிக்கப்பட்டதுமாய்க் கிடக்கும்போது, நான் துக்கமுகத்தோடு இராதிருப்பது எப்படி என்றேன்.", "en": "And said unto the king, Let the king live for ever: why should not my countenance be sad, when the city, the place of my fathers’ sepulchres, lieth waste, and the gates thereof are consumed with fire?"}, {"verse": 4, "start": 50.8, "end": 60.27, "ta": "அப்பொழுது ராஜா என்னைப் பார்த்து: நீ கேட்கிற காரியம் என்ன என்றார். அப்பொழுது நான்: பரலோகத்தின் தேவனை நோக்கி ஜெபம்பண்ணி,", "en": "Then the king said unto me, For what dost thou make request? So I prayed to the God of heaven."}, {"verse": 5, "start": 60.27, "end": 77.54, "ta": "ராஜாவைப் பார்த்து: ராஜாவுக்குச் சித்தமாயிருந்து, அடியேனுக்கு உமது சமுகத்தில் தயை கிடைத்ததானால், என் பிதாக்களின் கல்லறைகளிலிருக்கும் பட்டணத்தைக் கட்டும்படி, யூதா தேசத்துக்கு நீர் என்னை அனுப்பவேண்டிக்கொள்ளுகிறேன் என்றேன்.", "en": "And I said unto the king, If it please the king, and if thy servant have found favour in thy sight, that thou wouldest send me unto Judah, unto the city of my fathers’ sepulchres, that I may build it."}, {"verse": 6, "start": 77.54, "end": 98.31, "ta": "அப்பொழுது ராஜஸ்திரீயும் பக்கத்தில் உட்கார்ந்திருந்தாள். ராஜா என்னைப் பார்த்து: உன் பிரயாணம் எத்தனை நாள் செல்லும், நீ எப்பொழுது திரும்பிவருவாய் என்று கேட்டார். இவ்வளவுகாலம் செல்லுமென்று நான் ராஜாவுக்குச் சொன்னபோது, என்னை அனுப்ப அவருக்குச் சித்தமாயிற்று.", "en": "And the king said unto me, (the queen also sitting by him,) For how long shall thy journey be? and when wilt thou return? So it pleased the king to send me; and I set him a time."}, {"verse": 7, "start": 98.31, "end": 115.07, "ta": "பின்னும் நான் ராஜாவைப் பார்த்து ராஜாவுக்குச் சித்தமாயிருந்தால், நான் யூதாதேசத்துக்குப் போய்ச்சேருமட்டும், நதிக்கு அப்புறத்திலிருக்கிற தேசாதிபதிகள் என்னை வழிவிட்டனுப்பும்படிக்கு அவர்களுக்குக் கடிதங்கள் கொடுக்கும்படிக்கும்,", "en": "Moreover I said unto the king, If it please the king, let letters be given me to the governors beyond the river, that they may convey me over till I come into Judah;"}, {"verse": 8, "start": 115.07, "end": 141.08, "ta": "தேவாலயத்துக்கு இருக்கிற அரணின் கதவு வேலைக்கும், நகர அலங்கத்தின் வேலைக்கும், நான் தங்கப்போகிற வீட்டின் வேலைக்கும் வேண்டிய மரங்களை ராஜாவின் வனத்துக் காவலாளனாகிய ஆசாப் எனக்குக் கொடுக்கும்படிக்கும், அவனுக்கும் ஒரு கடிதம் கட்டளையிடப்படுவதாக என்றேன்; என் தேவனுடைய தயவுள்ள கரம் என்மேல் இருந்தபடியால், ராஜா அவைகளை எனக்குக் கட்டளையிட்டார்.", "en": "And a letter unto Asaph the keeper of the king’s forest, that he may give me timber to make beams for the gates of the palace which appertained to the house, and for the wall of the city, and for the house that I shall enter into. And the king granted me, according to the good hand of my God upon me."}, {"verse": 9, "start": 141.08, "end": 156.75, "ta": "அப்படியே நான் நதிக்கு அப்புறத்திலிருக்கிற தேசாதிபதிகளிடத்துக்கு வந்து, ராஜாவின் கடிதங்களை அவர்களுக்குக் கொடுத்தேன்; ராஜா என்னோடேகூட இராணுவச் சேர்வைக்காரரையும், குதிரைவீரரையும் அனுப்பியிருந்தார்.", "en": "Then I came to the governors beyond the river, and gave them the king’s letters. Now the king had sent captains of the army and horsemen with me."}, {"verse": 10, "start": 156.75, "end": 170.88, "ta": "இதை ஓரோனியனான சன்பல்லாத்தும், அம்மோனியனான தொபியா என்னும் ஊழியக்காரனும் கேட்டபோது, இஸ்ரவேல் புத்திரரின் நன்மையை விசாரிக்க ஒருவன் வந்தான் என்பது அவர்களுக்கு மிகவும் விசனமாயிருந்தது.", "en": "When Sanballat the Horonite, and Tobiah the servant, the Ammonite, heard of it , it grieved them exceedingly that there was come a man to seek the welfare of the children of Israel."}, {"verse": 11, "start": 170.88, "end": 175.33, "ta": "நான் எருசலேமுக்கு வந்து, அங்கே மூன்றுநாள் இருந்தபின்பு,", "en": "So I came to Jerusalem, and was there three days."}, {"verse": 12, "start": 175.33, "end": 194.57, "ta": "நான் சில மனுஷரைக் கூட்டிக்கொண்டு, ராத்திரியில் எழுந்து நகர சோதனை செய்தேன்; ஆனாலும் எருசலேமுக்காகச் செய்யும்படி என் தேவன் என் மனதிலே வைத்ததை நான் ஒருவருக்கும் அறிவிக்கவில்லை; நான் ஏறிப்போன மிருகமேயல்லாமல் வேறொரு மிருகமும் என்னோடிருந்ததில்லை.", "en": "And I arose in the night, I and some few men with me; neither told I any man what my God had put in my heart to do at Jerusalem: neither was there any beast with me, save the beast that I rode upon."}, {"verse": 13, "start": 194.57, "end": 212.2, "ta": "நான் அன்று ராத்திரி பள்ளத்தாக்கின் வாசல்வழியாய்ப் புறப்பட்டு, வலுசர்ப்பத் துரவைக் கடந்து, குப்பைமேட்டு வாசலுக்கு வந்து, எருசலேமில் இடிந்துபோன அலங்கத்தையும், அக்கினியால் சுட்டெரிக்கப்பட்ட அதின் வாசல்களையும் பார்வையிட்டேன்.", "en": "And I went out by night by the gate of the valley, even before the dragon well, and to the dung port, and viewed the walls of Jerusalem, which were broken down, and the gates thereof were consumed with fire."}, {"verse": 14, "start": 212.2, "end": 223.71, "ta": "அவ்விடத்தை விட்டு ஊருணி வாசலண்டைக்கும், ராஜாவின் குளத்தண்டைக்கும் போனேன்; நான் ஏறியிருந்த மிருகம் அங்கே நடந்துபோகிறதற்கு வழியில்லாதிருந்தது.", "en": "Then I went on to the gate of the fountain, and to the king’s pool: but there was no place for the beast that was under me to pass."}, {"verse": 15, "start": 223.71, "end": 233.84, "ta": "அன்று ராத்திரியிலேயே நான் ஆற்றோரமாய்ப் போய், அலங்கத்தைப் பார்வையிட்டுத் திரும்பி, பள்ளத்தாக்கின் வாசல்வழியாய் வந்துவிட்டேன்.", "en": "Then went I up in the night by the brook, and viewed the wall, and turned back, and entered by the gate of the valley, and so returned."}, {"verse": 16, "start": 233.84, "end": 250.16, "ta": "நான் போனதும், நான் செய்ததும் அதிகாரிகள் ஒருவருக்கும் தெரியாது; அதுவரையிலும் நான் யூதருக்காகிலும், ஆசாரியர்கள் பெரியவர்கள் அதிகாரிகளுக்காகிலும், வேலைசெய்கிற மற்றவர்களுக்காகிலும் ஒன்றும் அறிவிக்கவில்லை.", "en": "And the rulers knew not whither I went, or what I did; neither had I as yet told it to the Jews, nor to the priests, nor to the nobles, nor to the rulers, nor to the rest that did the work."}, {"verse": 17, "start": 250.16, "end": 270.28, "ta": "பின்பு நான் அவர்களை நோக்கி: எருசலேம் பாழாயிருக்கிறதையும், அதின் வாசல்கள் அக்கினியால் சுட்டெரிக்கப்பட்டுக்கிடக்கிறதையும், நாம் இருக்கிற சிறுமையையும் பார்க்கிறீர்களே; நாம் இனி நிந்தைக்குள்ளாயிராதபடிக்கு, எருசலேமின் அலங்கத்தைக் கட்டுவோம் வாருங்கள் என்று சொல்லி,", "en": "Then said I unto them, Ye see the distress that we are in, how Jerusalem lieth waste, and the gates thereof are burned with fire: come, and let us build up the wall of Jerusalem, that we be no more a reproach."}, {"verse": 18, "start": 270.28, "end": 287.98, "ta": "என் தேவனுடைய கரம் என்மேல் நன்மையாக இருக்கிறதையும், ராஜா என்னோடே சொன்ன வார்த்தைகளைய`ή் அவர்களுக்கρ அறிவித்தேனͻ அப்பெޠδுது அவர்கள்: எழுந்து கட்Οுவோம் வாருங்கள் என்று சொல்லி, அந்த நல்ல வேலைக்குத் தங்கள் கைகளைத் திடப்படுத்தினார்கள்.", "en": "Then I told them of the hand of my God which was good upon me; as also the king’s words that he had spoken unto me. And they said, Let us rise up and build. So they strengthened their hands for this good work ."}, {"verse": 19, "start": 287.98, "end": 308.17, "ta": "ஓரோனியனான சன்பல்லாத்தும், அம்மோனியனான தொபியா என்னும் ஊழியக்காரனும், அரபியனான கேஷேமும் இதைக் கேட்டபோது, எங்களைப் பரியாசம்பண்ணி, எங்களை நிந்தித்து: நீங்கள் செய்கிற இந்தக் காரியம் என்ன? நீங்கள் ராஜாவுக்கு விரோதமாகக் கலகம்பண்ணப்போகிறீர்களோ என்றார்கள்.", "en": "But when Sanballat the Horonite, and Tobiah the servant, the Ammonite, and Geshem the Arabian, heard it , they laughed us to scorn, and despised us, and said, What is this thing that ye do? will ye rebel against the king?"}, {"verse": 20, "start": 308.17, "end": 329.08, "ta": "அதற்கு நான் மறுமொழியாக: பரலோகத்தின் தேவனானவர் எங்களுக்குக் காரியத்தைக் கைகூடிவரப்பண்ணுவார்; அவருடைய ஊழியக்காரராகிய நாங்கள் எழுந்து கட்டுவோம்; உங்களுக்கோவென்றால் எருசலேமிலே பங்குமில்லை பாத்தியமுமில்லை; உங்கள் பேர் விளங்க ஒன்றும் இல்லையென்று அவர்களுடனே சொன்னேன்.", "en": "Then answered I them, and said unto them, The God of heaven, he will prosper us; therefore we his servants will arise and build: but ye have no portion, nor right, nor memorial, in Jerusalem."}]}, "3": {"chapter": 3, "duration": 450.57, "audio_url": "audio_ot/OT16_03.mp3", "total_verses": 32, "verses": [{"verse": 1, "start": 3.8, "end": 23.67, "ta": "அப்பொழுது பிரதான ஆசாரியனாகிய எலியாசீபும், அவன் சகோதரராகிய ஆசாரியர்களும் எழுந்து ஆட்டுவாசலைக் கட்டினார்கள்; அதைக் கட்டி, அவர்கள் பிரதிஷ்டைபண்ணி, அதின் கதவுகளை வைத்து, மேயா என்கிற கொம்மை முதல் அனானெயேலின் கொம்மைமட்டும் கட்டிப் பிரதிஷ்டைபண்ணினார்கள்.", "en": "Then Eliashib the high priest rose up with his brethren the priests, and they builded the sheep gate; they sanctified it, and set up the doors of it; even unto the tower of Meah they sanctified it, unto the tower of Hananeel."}, {"verse": 2, "start": 23.67, "end": 31.43, "ta": "அவன் அருகே எரிகோவின் மனுஷர் கட்டினார்கள், அவர்கள் அருகே இம்ரியின் குமாரனாகிய சக்கூர் கட்டினான்.", "en": "And next unto him builded the men of Jericho. And next to them builded Zaccur the son of Imri."}, {"verse": 3, "start": 31.43, "end": 41.95, "ta": "மீன்வாசலை அசெனாவின் குமாரர் கட்டினார்கள்; அதற்கு உத்தரம்பாவி, அதற்குக் கதவுகளையும் பூட்டுகளையும் தாழ்ப்பாள்களையும் போட்டார்கள்.", "en": "But the fish gate did the sons of Hassenaah build, who also laid the beams thereof, and set up the doors thereof, the locks thereof, and the bars thereof."}, {"verse": 4, "start": 41.95, "end": 61.24, "ta": "அவர்கள் அருகே கோசின் குமாரனாகிய உரியாவின் மகன் மெரெமோத் பழுதுபார்த்துக் கட்டினான்; அவர்கள் அருகே மெஷேசாபெயேலின் குமாரனாகிய பெரகியாவின் மகன் மெசுல்லாம் பழுதுபார்த்துக் கட்டினான்; அவர்கள் அருகே பானாவின் குமாரனாகிய சாதோக் பழுதுபார்த்துக் கட்டினான்.", "en": "And next unto them repaired Meremoth the son of Urijah, the son of Koz. And next unto them repaired Meshullam the son of Berechiah, the son of Meshezabeel. And next unto them repaired Zadok the son of Baana."}, {"verse": 5, "start": 61.24, "end": 72.85, "ta": "அவர்கள் அருகே தெக்கோவா ஊரார் பழுதுபார்த்துக் கட்டினார்கள்; அவர்களுடைய பிரபுக்களோ, தங்கள் ஆண்டவருடைய வேலைக்குத் தங்கள் கழுத்தைக் கொடுக்கவில்லை.", "en": "And next unto them the Tekoites repaired; but their nobles put not their necks to the work of their Lord."}, {"verse": 6, "start": 72.85, "end": 89.31, "ta": "பழைய வாசலைப் பசெயாசின் குமாரனாகிய யோய்தாவும், பேசோதியாவின் குமாரனாகிய மெசுல்லாமும் பழுதுபார்த்துக் கட்டினார்கள்; அவர்கள் அதற்கு உத்தரம்பாவி, அதற்குக் கதவுகளையும் பூட்டுகளையும் தாழ்ப்பாள்களையும் போட்டார்கள்.", "en": "Moreover the old gate repaired Jehoiada the son of Paseah, and Meshullam the son of Besodeiah; they laid the beams thereof, and set up the doors thereof, and the locks thereof, and the bars thereof."}, {"verse": 7, "start": 89.31, "end": 104.11, "ta": "அவர்கள் அருகே கிபியோன் மிஸ்பா ஊர்களின் மனுஷரான மெலதீயா என்னும் கிபியோனியனும் யாதோன் என்னும் மெரொனோத்தியனும், நதிக்கு இப்புறத்திலிருக்கிற அதிபதியின் சமஸ்தானமட்டும் பழுதுபார்த்துக் கட்டினார்கள்.", "en": "And next unto them repaired Melatiah the Gibeonite, and Jadon the Meronothite, the men of Gibeon, and of Mizpah, unto the throne of the governor on this side the river."}, {"verse": 8, "start": 104.11, "end": 122.46, "ta": "அவர்கள் அருகே தட்டாரில் ஒருவனாகிய அராயாவின் குமாரன் ஊசியேல் பழுதுபார்த்துக் கட்டினான்; அவன் அருகே தைலக்காரரில் ஒருவன் குமாரனாகிய அனனியா பழுதுபார்த்துக்கட்டினான்; அதுமுதற்கொண்டு அகலமான மதில் மட்டும் எருசலேம் இடிக்காமல் விட்டிருந்தது.", "en": "Next unto him repaired Uzziel the son of Harhaiah, of the goldsmiths. Next unto him also repaired Hananiah the son of one of the apothecaries, and they fortified Jerusalem unto the broad wall."}, {"verse": 9, "start": 122.46, "end": 130.8, "ta": "அவர்கள் அருகே எருசலேம் பட்டணத்தின் பாதிக்குப் பிரபுவாகிய ஊரின் குமாரன் ரெப்பாயா பழுதுபார்த்துக் கட்டினான்.", "en": "And next unto them repaired Rephaiah the son of Hur, the ruler of the half part of Jerusalem."}, {"verse": 10, "start": 130.8, "end": 143.57, "ta": "அவர்கள் அருகே அருமாப்பின் குமாரன் யெதாயா தன் வீட்டுக்கு எதிரானதைப் பழுதுபார்த்துக் கட்டினான்; அவன் அருகே ஆசாப்நெயாவின் குமாரன் அத்தூஸ் பழுதுபார்த்துக் கட்டினான்.", "en": "And next unto them repaired Jedaiah the son of Harumaph, even over against his house. And next unto him repaired Hattush the son of Hashabniah."}, {"verse": 11, "start": 143.57, "end": 154.38, "ta": "மற்றப் பங்கையும், சூளைகளின் கொம்மையையும், ஆரீமின் குமாரன் மல்கிஜாவும், பாகாத்மோவாபின் குமாரன் அசூபும் பழுதுபார்த்துக் கட்டினார்கள்.", "en": "Malchijah the son of Harim, and Hashub the son of Pahath-moab, repaired the other piece, and the tower of the furnaces."}, {"verse": 12, "start": 154.38, "end": 165.11, "ta": "அவன் அருகே எருசலேம் பட்டணத்தின் மறுபாதிக்குப் பிரபுவாகிய அலோகேசின் குமாரன் சல்லுூமும், அவன் குமாரத்திகளும் பழுதுபார்த்துக் கட்டினார்கள்.", "en": "And next unto him repaired Shallum the son of Halohesh, the ruler of the half part of Jerusalem, he and his daughters."}, {"verse": 13, "start": 165.11, "end": 183.24, "ta": "பள்ளத்தாக்கின் வாசலை ஆனூனும், சானோவாகின் குடிகளும் பழுதுபார்த்துக் கட்டினார்கள்; அவர்கள் அதைக் கட்டி, அதற்குக் கதவுகளையும் பூட்டுகளையும் தாழ்ப்பாள்களையும் போட்டு, குப்பைமேட்டு வாசல்மட்டாக அலங்கத்தில் ஆயிரம் முழம் கட்டினார்கள்.", "en": "The valley gate repaired Hanun, and the inhabitants of Zanoah; they built it, and set up the doors thereof, the locks thereof, and the bars thereof, and a thousand cubits on the wall unto the dung gate."}, {"verse": 14, "start": 183.24, "end": 196.59, "ta": "குப்பைமேட்டு வாசலைப் பெத்கேரேமின் மகாணத்துப் பிரபுவாகிய ரெக்காவின் குமாரன் மல்கியா பழுதுபார்த்து அதைக் கட்டி, அதற்குக் கதவுகளையும் பூட்டுகளையும் தாழ்ப்பாள்களையும் போட்டான்.", "en": "But the dung gate repaired Malchiah the son of Rechab, the ruler of part of Beth-haccerem; he built it, and set up the doors thereof, the locks thereof, and the bars thereof."}, {"verse": 15, "start": 196.59, "end": 221.54, "ta": "ஊருணிவாசலை மிஸ்பாவின் மாகாணத்துப் பிரபுவாகிய கொல்லோசேயின் குமாரன் சல்லுூம் பழுதுபார்த்து, அதைக் கட்டி மச்சுப்பாவி, அதற்குக் கதவுகளையும் பூட்டுகளையும் தாழ்ப்பாள்களையும் போட்டு, ராஜாவின் சிங்காரத் தோட்டத்தண்டையிலிருக்கிற சீலோவாவின் குளத்து மதிலையும், தாவீதின் நகரத்திலிருந்து இறங்குகிற படிகள் மட்டாக இருக்கிறதையும் கட்டினான்.", "en": "But the gate of the fountain repaired Shallun the son of Col-hozeh, the ruler of part of Mizpah; he built it, and covered it, and set up the doors thereof, the locks thereof, and the bars thereof, and the wall of the pool of Siloah by the king’s garden, and unto the stairs that go down from the city of David."}, {"verse": 16, "start": 221.54, "end": 239.67, "ta": "அவனுக்குப் பின்னாகப் பெத்சூர் மாகாணத்தின் பாதிக்குப் பிரபுவாகிய அஸ்பூகின் குமாரன் நெகேமியா தாவீதின் கல்லறைகளுக்கு எதிரான இடமட்டாகவும், வெட்டப்பட்ட குளமட்டாகவும், பராக்கிரமசாலிகளின் வீடுமட்டாகவும் இருக்கிறதைப் பழுதுபார்த்துக் கட்டினான்.", "en": "After him repaired Nehemiah the son of Azbuk, the ruler of the half part of Beth-zur, unto the place over against the sepulchres of David, and to the pool that was made, and unto the house of the mighty."}, {"verse": 17, "start": 239.67, "end": 252.44, "ta": "அவனுக்குப் பின்னாக லேவியரில் பானியின் குமாரன் ரேகூமும், அவன் அருகே கேகிலா மாகாணத்தில் தன்னுடைய பாதிப்பங்குக்குப் பிரபுவாகிய அசபியாவும் பழுதுபார்த்துக் கட்டினார்கள்.", "en": "After him repaired the Levites, Rehum the son of Bani. Next unto him repaired Hashabiah, the ruler of the half part of Keilah, in his part."}, {"verse": 18, "start": 252.44, "end": 262.52, "ta": "அவனுக்குப் பின்னாக அவனுடைய சகோதரரில் கேகிலா மாகாணத்து மறுபாதிக்குப் பிரபுவாகிய எனாதாதின் குமாரன் பாபாயி பழுதுபார்த்துக் கட்டினான்.", "en": "After him repaired their brethren, Bavai the son of Henadad, the ruler of the half part of Keilah."}, {"verse": 19, "start": 262.52, "end": 274.92, "ta": "அவன் அருகே மிஸ்பாவின் பிரபுவாகிய யெசுவாவின் குமாரன் ஏசர் என்பவன் மதிலின் கோடியிலே ஆயுதசாலையின் படிகளுக்கு எதிரேயிருக்கிற வேறொரு பங்கைப் பழுதுபார்த்துக் கட்டினான்.", "en": "And next to him repaired Ezer the son of Jeshua, the ruler of Mizpah, another piece over against the going up to the armoury at the turning of the wall ."}, {"verse": 20, "start": 274.92, "end": 288.85, "ta": "அவனுக்குப் பின்னாகச் சாபாயின் குமாரன் பாரூக் அந்தக் கோடி துவக்கிப் பிரதான ஆசாரியனாகிய எலியாசீபின் வாசற்படிமட்டும் இருக்கிற பின்னொரு பங்கை வெகு ஜாக்கிரதையோடே பழுதுபார்த்துக் கட்டினான்.", "en": "After him Baruch the son of Zabbai earnestly repaired the other piece, from the turning of the wall unto the door of the house of Eliashib the high priest."}, {"verse": 21, "start": 288.85, "end": 302.92, "ta": "அவனுக்குப் பின்னாகக் கோசின் குமாரனாகிய உரியாவின் மகன் மெரெமோத் எலியாசீபின் வீட்டு வாசற்படி துவக்கி அவனுடைய வீட்டின் கடைக்கோடிமட்டும் இருக்கிற பின்னொரு பங்கைப் பழுதுபார்த்துக் கட்டினான்.", "en": "After him repaired Meremoth the son of Urijah the son of Koz another piece, from the door of the house of Eliashib even to the end of the house of Eliashib."}, {"verse": 22, "start": 302.92, "end": 310.24, "ta": "அவனுக்குப் பின்னாகச் சமனான பூமியில் வாசமாயிருக்கிற ஆசாரியர்கள் பழுதுபார்த்துக் கட்டினார்கள்.", "en": "And after him repaired the priests, the men of the plain."}, {"verse": 23, "start": 310.24, "end": 328.6, "ta": "அவர்களுக்குப் பின்னாக பென்யமீனும், அசூபும் தங்கள் வீட்டுக்கு எதிரே இருக்கிறதைப் பழுதுபார்த்துக் கட்டினார்கள்; அவர்களுக்குப் பின்னாக அனனியாவின் குமாரனாகிய மாசேயாவின் மகன் அசரியா தன் வீட்டின் அருகே இருக்கிறதைப் பழுதுபார்த்துக் கட்டினான்.", "en": "After him repaired Benjamin and Hashub over against their house. After him repaired Azariah the son of Maaseiah the son of Ananiah by his house."}, {"verse": 24, "start": 328.6, "end": 340.27, "ta": "அவனுக்குப் பின்னாக எனாதாதின் குமாரன் பின்னூவி அசரியாவின் வீடு துவக்கி அலங்கத்துக் கோடி வளைவுவரைக்கும் இருக்கிற வேறொரு பங்கைப் பழுதுபார்த்துக் கட்டினான்.", "en": "After him repaired Binnui the son of Henadad another piece, from the house of Azariah unto the turning of the wall , even unto the corner."}, {"verse": 25, "start": 340.27, "end": 356.96, "ta": "ஊசாயின் குமாரன் பாலால் வளைவுக்கு எதிரேயும், காவல் வீட்டின் முற்றத்துக்கடுத்த ராஜாவின் உயரமான அரமனைக்கு வெளிப்புறமாயிருக்கிற கொம்மைக்கு எதிரேயும் இருக்கிறதைக் கட்டினான்; அவனுக்குப் பின்னாகப் பாரோஷின் குமாரன் பெதாயாவும்,", "en": "Palal the son of Uzai, over against the turning of the wall , and the tower which lieth out from the king’s high house, that was by the court of the prison. After him Pedaiah the son of Parosh."}, {"verse": 26, "start": 356.96, "end": 368.42, "ta": "ஓபேலிலே குடியிருக்கிற நிதனீமியரைச் சேர்ந்த மனிதரும் கிழக்கேயிருக்கிற தண்ணீர் வாசலுக்கு வெளிப்புறமான கொம்மைக்கு எதிரேயிருக்கிற இடமட்டும் கட்டினார்கள்.", "en": "Moreover the Nethinims dwelt in Ophel, unto the place over against the water gate toward the east, and the tower that lieth out."}, {"verse": 27, "start": 368.42, "end": 380.02, "ta": "அவர்களுக்குப் பின்னாகத் தெக்கோவா ஊரார் வெளிப்புறமான பெரிய கொம்மைக்கு எதிரே ஓபேலின் மதில்மட்டும் இருக்கிற பின்னொரு பங்கைப் பழுதுபார்த்துக் கட்டினார்கள்.", "en": "After them the Tekoites repaired another piece, over against the great tower that lieth out, even unto the wall of Ophel."}, {"verse": 28, "start": 380.02, "end": 388.65, "ta": "குதிரைவாசல் முதற்கொண்டு ஆசாரியர்கள் அவரவர் தங்கள் வீடுகளுக்கு எதிரே இருக்கிறதைப் பழுதுபார்த்துக் கட்டினார்கள்.", "en": "From above the horse gate repaired the priests, every one over against his house."}, {"verse": 29, "start": 388.65, "end": 404.83, "ta": "அவர்களுக்குப் பின்னாக இம்மேரின் குமாரன் சாதோக் தன் வீட்டுக்கு எதிரே இருக்கிறதைப் பழுதுபார்த்துக் கட்டினான்; அவனுக்குப் பின்னாகக் கிழக்கு வாசலைக் காக்கிற செக்கனியாவின் குமாரன் செமாயா பழுதுபார்த்துக் கட்டினான்.", "en": "After them repaired Zadok the son of Immer over against his house. After him repaired also Shemaiah the son of Shechaniah, the keeper of the east gate."}, {"verse": 30, "start": 404.83, "end": 424.92, "ta": "அவனுக்குப் பின்னாகச் செல்மீயாவின் குமாரன் அனனியாவும், சாலாபின் ஆறாவது குமாரனாகிய ஆனூனும், வேறொரு பங்கைப் பழுதுபார்த்துக்கட்டினார்கள்; அவர்களுக்குப் பின்னாகப் பெரகியாவின் குமாரன் மெசுல்லாம், தன் அறைவீட்டுக்கு எதிரே இருக்கிறதைப் பழுதுபார்த்துக் கட்டினான்.", "en": "After him repaired Hananiah the son of Shelemiah, and Hanun the sixth son of Zalaph, another piece. After him repaired Meshullam the son of Berechiah over against his chamber."}, {"verse": 31, "start": 424.92, "end": 440.0, "ta": "அவனுக்குப் பின்னாகத் தட்டானின் குமாரன் மல்கியா மிப்காத் என்னும் வாசலுக்கு எதிரே நிதனீமியரும் மளிகைக்காரரும் குடியிருக்கிற ஸ்தலமுதல் கோடியின் மேல்வீடுமட்டாகவும் இருக்கிறதைப் பழுதுபார்த்துக் கட்டினான்.", "en": "After him repaired Malchiah the goldsmith’s son unto the place of the Nethinims, and of the merchants, over against the gate Miphkad, and to the going up of the corner."}, {"verse": 32, "start": 440.0, "end": 449.07, "ta": "கோடியின் மேல்வீட்டுக்கும் ஆட்டுவாசலுக்கும் நடுவே இருக்கிறதைத் தட்டாரும் மளிகைக்காரரும் பழுதுபார்த்துக் கட்டினார்கள்.", "en": "And between the going up of the corner unto the sheep gate repaired the goldsmiths and the merchants."}]}, "4": {"chapter": 4, "duration": 298.03, "audio_url": "audio_ot/OT16_04.mp3", "total_verses": 23, "verses": [{"verse": 1, "start": 3.8, "end": 12.46, "ta": "நாங்கள் அலங்கத்தைக் கட்டுகிற செய்தியைச் சன்பல்லாத் கேட்டபோது, அவன் கோபித்து, எரிச்சலடைந்து, யூதரைச் சக்கந்தம்பண்ணி:", "en": "But it came to pass, that when Sanballat heard that we builded the wall, he was wroth, and took great indignation, and mocked the Jews."}, {"verse": 2, "start": 12.46, "end": 31.74, "ta": "அந்த அற்பமான யூதர் செய்கிறது என்ன, அவர்களுக்கு இடங்கொடுக்கப்படுமோ, பலியிடுவார்களோ, ஒருநாளிலே முடித்துப்போடுவார்களோ, சுட்டெரித்துப் போடப்பட்டு மண்மேடுகளான கற்களுக்கு உயிர் கொடுப்பார்களோ, என்று தன் சகோதரருக்கும் சமாரியாவின் சேனைக்கும் முன்பாகச் சொன்னான்.", "en": "And he spake before his brethren and the army of Samaria, and said, What do these feeble Jews? will they fortify themselves? will they sacrifice? will they make an end in a day? will they revive the stones out of the heaps of the rubbish which are burned?"}, {"verse": 3, "start": 31.74, "end": 42.64, "ta": "அப்பொழுது அம்மோனியனாகிய தொபியா அவன் பக்கத்தில் நின்று: அவர்கள் கட்டினாலும் என்ன, ஒரு நரி ஏறிப்போனால் அவர்களுடைய கல் மதில் இடிந்துபோகும் என்றான்.", "en": "Now Tobiah the Ammonite was by him, and he said, Even that which they build, if a fox go up, he shall even break down their stone wall."}, {"verse": 4, "start": 42.64, "end": 55.63, "ta": "எங்கள் தேவனே, நாங்கள் அவமதிக்கப்படுகிறதைக் கேட்டு, அவர்கள் நிந்திக்கிற நிந்தையை அவர்கள் தலையின்மேல் திருப்பி, அவர்களைச் சிறையிருப்பின் தேசத்திலே சூறைக்கு ஒப்புக்கொடும்.", "en": "Hear, O our God; for we are despised: and turn their reproach upon their own head, and give them for a prey in the land of captivity:"}, {"verse": 5, "start": 55.63, "end": 66.8, "ta": "அவர்கள் அக்கிரமத்தை மூடிப்போடாதேயும்; அவர்கள் பாவம் உமக்கு முன்பாகக் கொலைக்கப்படாதிருப்பதாக; கட்டுகிறவர்களுக்கு மனமடிவுண்டாகப் பேசினார்களே.", "en": "And cover not their iniquity, and let not their sin be blotted out from before thee: for they have provoked thee to anger before the builders."}, {"verse": 6, "start": 66.8, "end": 77.35, "ta": "நாங்கள் அலங்கத்தைக் கட்டிவந்தோம்; அலங்கமெல்லாம் பாதிமட்டும் ஒன்றாய் இணைந்து உயர்ந்தது; ஜனங்கள் வேலைசெய்கிறதற்கு ஆவலாயிருந்தார்கள்.", "en": "So built we the wall; and all the wall was joined together unto the half thereof: for the people had a mind to work."}, {"verse": 7, "start": 77.35, "end": 93.48, "ta": "எருசலேமின் அலங்கத்தைக் கட்டுகிற வேலை வளர்ந்தேறுகிறது என்றும் இடிக்கப்பட்ட இடங்கள் அடைபட்டுவருகிறது என்றும் சன்பல்லாத்தும், தொபியாவும், அரபியரும், அம்மோனியரும், அஸ்தோத்தியரும் கேட்டபோது, அவர்கள் மிகவும் எரிச்சலாகி,", "en": "But it came to pass, that when Sanballat, and Tobiah, and the Arabians, and the Ammonites, and the Ashdodites, heard that the walls of Jerusalem were made up, and that the breaches began to be stopped, then they were very wroth,"}, {"verse": 8, "start": 93.48, "end": 100.82, "ta": "எருசலேமின்மேல் யுத்தம்பண்ண எல்லாரும் ஏகமாய் வரவும் வேலையைத் தடுக்கவும் கட்டுப்பாடு பண்ணினார்கள்.", "en": "And conspired all of them together to come and to fight against Jerusalem, and to hinder it."}, {"verse": 9, "start": 100.82, "end": 109.13, "ta": "ஆனாலும் நாங்கள் எங்கள் தேவனை நோக்கி ஜெபம்பண்ணி, அவர்கள் நிமித்தம் இரவும்பகலும் ஜாமங்காக்கிறவர்களை வைத்தோம்.", "en": "Nevertheless we made our prayer unto our God, and set a watch against them day and night, because of them."}, {"verse": 10, "start": 109.13, "end": 119.54, "ta": "அப்பொழுது யூதா மனிதர்: சுமைகாரரின் பெலன் குறைந்துபோகிறது, மண்மேடு மிச்சமாயிருக்கிறது; நாங்கள் அலங்கத்தைக் கட்டக் கூடாது என்றார்கள்.", "en": "And Judah said, The strength of the bearers of burdens is decayed, and there is much rubbish; so that we are not able to build the wall."}, {"verse": 11, "start": 119.54, "end": 133.86, "ta": "எங்கள் சத்துருக்களோவென்றால்: நாங்கள் அவர்கள் நடுவே வந்து, அவர்களைக் கொன்றுபோடுமட்டும், அவர்கள் அதை அறியாமலும் பாராமலும் இருக்கவேண்டும்; இவ்விதமாய் அந்த வேலையை ஓயப்பண்ணுவோம் என்றார்கள்.", "en": "And our adversaries said, They shall not know, neither see, till we come in the midst among them, and slay them, and cause the work to cease."}, {"verse": 12, "start": 133.86, "end": 143.35, "ta": "அதை அவர்களண்டையிலே குடியிருக்கிற யூதரும், பல இடங்களிலுமிருந்து எங்களிடத்துக்கு வந்து, பத்துவிசை எங்களுக்குச் சொன்னார்கள்.", "en": "And it came to pass, that when the Jews which dwelt by them came, they said unto us ten times, From all places whence ye shall return unto us they will be upon you ."}, {"verse": 13, "start": 143.35, "end": 156.98, "ta": "அப்பொழுது நான் அலங்கத்துக்குப் பின்னாக இருக்கிற பள்ளமான இடங்களிலும் மேடுகளிலும் பட்டயங்களையும், ஈட்டிகளையும் வில்லுகளையும் பிடித்திருக்கிற ஜனங்களைக் குடும்பங் குடும்பமாக நிறுத்தினேன்.", "en": "Therefore set I in the lower places behind the wall, and on the higher places, I even set the people after their families with their swords, their spears, and their bows."}, {"verse": 14, "start": 156.98, "end": 181.63, "ta": "அதை நான் பார்த்து எழும்பி, பிரபுக்களையும் அதிகாரிகளையும் மற்ற ஜனங்களையும் நோக்கி: அவர்களுக்குப் பயப்படாதிருங்கள்; நீங்கள் மகத்துவமும் பயங்கரமுமான ஆண்டவரை நினைத்து, உங்கள் சகோதரருக்காகவும், உங்கள் குமாரருக்காகவும், உங்கள் குமாரத்திகளுக்காகவும், உங்கள் மனைவிகளுக்காகவும், உங்கள் வீடுகளுக்காகவும் யுத்தம்பண்ணுங்கள் என்றேன்.", "en": "And I looked, and rose up, and said unto the nobles, and to the rulers, and to the rest of the people, Be not ye afraid of them: remember the Lord, which is great and terrible, and fight for your brethren, your sons, and your daughters, your wives, and your houses."}, {"verse": 15, "start": 181.63, "end": 195.88, "ta": "எங்களுக்குச் செய்தி தெரியவந்ததென்றும், தேவன் அவர்கள் ஆலோசனையை அபத்தமாக்கினாரென்றும், எங்கள் பகைஞர் கேட்டபோது, நாங்கள் எல்லோரும் அவரவர் தங்கள் வேலையைச் செய்ய அலங்கத்துக்குத் திரும்பினோம்.", "en": "And it came to pass, when our enemies heard that it was known unto us, and God had brought their counsel to nought, that we returned all of us to the wall, every one unto his work."}, {"verse": 16, "start": 195.88, "end": 211.88, "ta": "அன்று முதற்கொண்டு என் வேலைக்காரரில் பாதிப்பேர் வேலைசெய்தார்கள், பாதிப்பேர் ஈட்டிகளையும் பரிசைகளையும் வில்லுகளையும் கவசங்களையும் பிடித்து நின்றார்கள்; அதிகாரிகள் யூதா வம்சத்தார் எல்லாருக்கும் பின்னாக நின்றார்கள்.", "en": "And it came to pass from that time forth, that the half of my servants wrought in the work, and the other half of them held both the spears, the shields, and the bows, and the habergeons; and the rulers were behind all the house of Judah."}, {"verse": 17, "start": 211.88, "end": 223.47, "ta": "அலங்கத்திலே கட்டுகிறவர்களும், சுமைசுமக்கிறவர்களும், சுமையேற்றுகிறவர்களும், அவரவர் ஒரு கையினாலே வேலைசெய்து, மறுகையினாலே ஆயுதம் தரித்திருந்தார்கள்.", "en": "They which builded on the wall, and they that bare burdens, with those that laded, every one with one of his hands wrought in the work, and with the other hand held a weapon."}, {"verse": 18, "start": 223.47, "end": 234.09, "ta": "கட்டுகிறவர்கள் அவரவர் தங்கள் பட்டயத்தைத் தங்கள் இடுப்பிலே கட்டிக்கொண்டவர்களாய் வேலைசெய்தார்கள்; எக்காளம் ஊதுகிறவன் என்னண்டையிலே நின்றான்.", "en": "For the builders, every one had his sword girded by his side, and so builded. And he that sounded the trumpet was by me."}, {"verse": 19, "start": 234.09, "end": 246.8, "ta": "நான் பிரபுக்களையும் அதிகாரிகளையும் மற்ற ஜனங்களையும் நோக்கி: வேலை பெரிதும் விஸ்தாரமுமாயிருக்கிறது; நாம் அலங்கத்தின்மேல் சிதறப்பட்டு ஒருவருக்கு ஒருவர் தூரமாயிருக்கிறோம்.", "en": "And I said unto the nobles, and to the rulers, and to the rest of the people, The work is great and large, and we are separated upon the wall, one far from another."}, {"verse": 20, "start": 246.8, "end": 258.04, "ta": "நீங்கள் எவ்விடத்திலே எக்காளச் சத்தத்தைக் கேட்கிறீர்களோ அவ்விடத்திலே வந்து, எங்களோடே கூடுங்கள்; நம்முடைய தேவன் நமக்காக யுத்தம்பண்ணுவார் என்றேன்.", "en": "In what place therefore ye hear the sound of the trumpet, resort ye thither unto us: our God shall fight for us."}, {"verse": 21, "start": 258.04, "end": 269.57, "ta": "இப்படியே நாங்கள் வேலைசெய்துகொண்டிருந்தோம்; அவர்களிலே பாதிப்பேர் கிழக்கு வெளுக்கும் நேரமுதல் நட்சத்திரங்கள் காணுமட்டும் ஈட்டிகளைப் பிடித்திருந்தார்கள்.", "en": "So we laboured in the work: and half of them held the spears from the rising of the morning till the stars appeared."}, {"verse": 22, "start": 269.57, "end": 282.21, "ta": "அக்காலத்திலே நான் ஜனங்களைப் பார்த்து: இராமாறு நமக்குக் காவலுக்கும் பகல்மாறு வேலைக்கும் உதவ, அவரவர் தங்கள் வேலைக்காரரோடுங்கூட எருசலேமுக்குள்ளே இராத்தங்கக்கடவர்கள் என்று சொல்லி,", "en": "Likewise at the same time said I unto the people, Let every one with his servant lodge within Jerusalem, that in the night they may be a guard to us, and labour on the day."}, {"verse": 23, "start": 282.21, "end": 296.53, "ta": "நானாகிலும், என் சகோதரராகிலும், என் வேலைக்காரராகிலும், என்னைப் பின்பற்றி காவல்காக்கிற சேவகராகிலும் எங்கள் வஸ்திரங்களைக் களைந்துபோடாதிருந்தோம்; அவரவருக்கு ஆயுதமும் தண்ணீரும் இருந்தது.", "en": "So neither I, nor my brethren, nor my servants, nor the men of the guard which followed me, none of us put off our clothes, saving that every one put them off for washing."}]}, "5": {"chapter": 5, "duration": 311.78, "audio_url": "audio_ot/OT16_05.mp3", "total_verses": 19, "verses": [{"verse": 1, "start": 3.8, "end": 12.43, "ta": "ஜனங்களுக்குள் அநேகரும் அவர்களுடைய ஸ்திரீகளும் யூதராகிய தங்கள் சகோதரர்மேல் முறையிடுகிற பெரிய கூக்குரலுண்டாயிற்று.", "en": "And there was a great cry of the people and of their wives against their brethren the Jews."}, {"verse": 2, "start": 12.43, "end": 26.34, "ta": "அதென்னவென்றால், அவர்களில் சிலர் நாங்கள் எங்கள் குமாரரோடும் எங்கள் குமாரத்திகளோடும் அநேகரானபடியினால், சாப்பிட்டுப் பிழைக்கும்படிக்கு நாங்கள் தானியத்தைக் கடனாக வாங்கினோம் என்றார்கள்.", "en": "For there were that said, We, our sons, and our daughters, are many: therefore we take up corn for them , that we may eat, and live."}, {"verse": 3, "start": 26.34, "end": 38.26, "ta": "வேறு சிலர் எங்கள் நிலங்களையும் எங்கள் திராட்சத்தோட்டங்களையும் எங்கள் வீடுகளையும் நாங்கள் அடைமானமாக வைத்து, இந்தப் பஞ்சத்திலே தானியம் வாங்கினோம் என்றார்கள்.", "en": "Some also there were that said, We have mortgaged our lands, vineyards, and houses, that we might buy corn, because of the dearth."}, {"verse": 4, "start": 38.26, "end": 49.1, "ta": "இன்னும் சிலர் ராஜாவுக்குத் தீர்வைசெலுத்த, நாங்கள் எங்கள் நிலங்கள்மேலும் எங்கள் திராட்சத்தோட்டங்கள்மேலும், பணத்தைக் கடனாக வாங்கினோம் என்றும்;", "en": "There were also that said, We have borrowed money for the king’s tribute, and that upon our lands and vineyards."}, {"verse": 5, "start": 49.1, "end": 79.71, "ta": "எங்கள் உடலும் எங்கள் சகோதரர் உடலும் சரி; எங்கள் பிள்ளைகளும் அவர்கள் பிள்ளைகளும் சரி; ஆனாலும், இதோ நாங்கள் எங்கள் குமாரரையும் எங்கள் குமாரத்திகளையும் அடிமைத்தனத்திற்கு உட்படுத்தவேண்டியதாயிருக்கிறது; அப்படியே எங்கள் குமாரத்திகளில் சிலர் அடிமைப்பட்டுமிருக்கிறார்கள்; அவர்களை மீட்க எங்களுக்கு நிர்வாகமில்லை; எங்கள் நிலங்களும் எங்கள் திராட்சத்தோட்டங்களும் வேறே மனிதர் கைவசமாயிற்று என்றார்கள்.", "en": "Yet now our flesh is as the flesh of our brethren, our children as their children: and, lo, we bring into bondage our sons and our daughters to be servants, and some of our daughters are brought unto bondage already: neither is it in our power to redeem them; for other men have our lands and vineyards."}, {"verse": 6, "start": 79.71, "end": 85.98, "ta": "அவர்கள் கூக்குரலையும், இந்தவார்த்தைகளையும் நான் கேட்டபோது, மிகவும் கோபங்கொண்டு,", "en": "And I was very angry when I heard their cry and these words."}, {"verse": 7, "start": 85.98, "end": 101.04, "ta": "என் மனதிலே ஆலோசனைபண்ணி, பிற்பாடு பிரபுக்களையும் அதிகாரிகளையும் கடிந்துகொண்டு: நீங்கள் அவரவர் தங்கள் சகோதரர்மேல் ஏன் வட்டி சுமத்துகிறீர்கள் என்று சொல்லி, அவர்களுக்கு விரோதமாக ஒரு பெரிய சபைகூடிவரச்செய்து,", "en": "Then I consulted with myself, and I rebuked the nobles, and the rulers, and said unto them, Ye exact usury, every one of his brother. And I set a great assembly against them."}, {"verse": 8, "start": 101.04, "end": 122.65, "ta": "அவர்களை நோக்கி: புறஜாதியாருக்கு விற்கப்பட்ட யூதராகிய எங்கள் சகோதரரை நாங்கள் எங்கள் சக்திக்குத்தக்கதாய் மீட்டிருக்கையில், நீங்கள் திரும்ப உங்கள் சகோதரரை விற்கலாமா? இவர்கள் நமக்கு விலைப்பட்டுப்போகலாமா என்றேன்; அப்பொழுது அவர்கள் மறு உத்தரவு சொல்ல இடமில்லாமல் மவுனமாயிருந்தார்கள்.", "en": "And I said unto them, We after our ability have redeemed our brethren the Jews, which were sold unto the heathen; and will ye even sell your brethren? or shall they be sold unto us? Then held they their peace, and found nothing to answer ."}, {"verse": 9, "start": 122.65, "end": 135.71, "ta": "பின்னும் நான் அவர்களை நோக்கி: நீங்கள் செய்கிற காரியம் நல்லதல்ல; நம்முடைய பகைஞராகிய புறஜாதியார் நிந்திக்கிறதினிமித்தம் நீங்கள் நம்முடைய தேவனுக்குப் பயந்து நடக்கவேண்டாமா?", "en": "Also I said, It is not good that ye do: ought ye not to walk in the fear of our God because of the reproach of the heathen our enemies?"}, {"verse": 10, "start": 135.71, "end": 146.62, "ta": "நானும் என் சகோதரரும் என் வேலைக்காரரும் இவ்விதமாகவா அவர்களுக்குப் பணமும் தானியமும் கடன்கொடுத்திருக்கிறோம்? இந்த வட்டியை விட்டுவிடுவோமாக.", "en": "I likewise, and my brethren, and my servants, might exact of them money and corn: I pray you, let us leave off this usury."}, {"verse": 11, "start": 146.62, "end": 169.52, "ta": "நீங்கள் இன்றைக்கு அவர்கள் நிலங்களையும், அவர்கள் திராட்சத்தோட்டங்களையும், அவர்கள் ஒலிவத்தோப்புகளையும், அவர்கள் வீடுகளையும், நீங்கள் பணத்திலும் தானியத்திலும் திராட்சரசத்திலும் எண்ணெயிலும் நூற்றுக்கொன்று வீதமாக அவர்களிடத்தில் தண்டிவருகிற வட்டியையும், அவர்களுக்குத் திரும்பக்கொடுத்துவிடுங்கள் என்றேன்.", "en": "Restore, I pray you, to them, even this day, their lands, their vineyards, their oliveyards, and their houses, also the hundredth part of the money, and of the corn, the wine, and the oil, that ye exact of them."}, {"verse": 12, "start": 169.52, "end": 188.57, "ta": "அதற்கு அவர்கள் நாங்கள் அதைத் திரும்பக் கொடுத்துவிட்டு, இனி அப்படி அவர்களிடத்தில் கேட்கமாட்டோம்; நீர் சொல்லுகிறபடியே செய்வோம் என்றார்கள்; அப்பொழுது நான் ஆசாரியர்களை அழைத்து, அவர்கள் இந்த வார்த்தையின்படி செய்ய அவர்களை ஆணையிடுவித்துக்கொண்டேன்.", "en": "Then said they, We will restore them , and will require nothing of them; so will we do as thou sayest. Then I called the priests, and took an oath of them, that they should do according to this promise."}, {"verse": 13, "start": 188.57, "end": 215.75, "ta": "நான் என் வஸ்திரத்தை உதறிப்போட்டு, இப்படி இந்த வார்த்தையை நிறைவேற்றாத எந்த மனிதனையும் அவன் வீட்டிலும் அவன் சம்பாத்தியத்திலும் இருந்து தேவன் உதறிப்போடக்கடவர்; இந்தப்பிரகாரமாக அவன் உதறிப்போடப்பட்டு, வெறுமையாய்ப் போவானாக என்றேன்; அதற்குச் சபையார் எல்லாரும் ஆமென் என்று சொல்லி கர்த்தரைத் துதித்தார்கள்; பின்பு ஜனங்கள் இந்த வார்த்தையின்படியே செய்தார்கள்.", "en": "Also I shook my lap, and said, So God shake out every man from his house, and from his labour, that performeth not this promise, even thus be he shaken out, and emptied. And all the congregation said, Amen, and praised the LORD . And the people did according to this promise."}, {"verse": 14, "start": 215.75, "end": 235.59, "ta": "நான் யூதாதேசத்திலே அதிபதியாயிருக்கும்படி ராஜாவாகிய அர்தசஷ்டா எனக்குக் கற்பித்த நாளாகிய அவருடைய இருபதாம் வருஷம் தொடங்கி, அவருடைய முப்பத்திரண்டாம் வருஷம் வரைக்கும் இருந்த பன்னிரண்டு வருஷகாலமாய், நானும் என் சகோதரரும் அதிபதிகள் வாங்குகிற படியை வாங்கிச் சாப்பிடவில்லை.", "en": "Moreover from the time that I was appointed to be their governor in the land of Judah, from the twentieth year even unto the two and thirtieth year of Artaxerxes the king, that is , twelve years, I and my brethren have not eaten the bread of the governor."}, {"verse": 15, "start": 235.59, "end": 257.35, "ta": "எனக்கு முன்னிருந்த அதிபதிகள் ஜனங்களுக்குப் பாரமாயிருந்து, அவர்கள் கையிலே அப்பமும் திராட்சரசமும் வாங்கினதும் அல்லாமல், நாற்பதுசேக்கல் வெள்ளியும் வாங்கிவந்தார்கள்; அவர்கள் வேலைக்காரர் முதலாய் ஜனங்கள்மேல் அதிகாரம் செலுத்தினார்கள்; நானோ தேவனுக்குப் பயந்ததினால் இப்படிச் செய்யவில்லை.", "en": "But the former governors that had been before me were chargeable unto the people, and had taken of them bread and wine, beside forty shekels of silver; yea, even their servants bare rule over the people: but so did not I, because of the fear of God."}, {"verse": 16, "start": 257.35, "end": 268.97, "ta": "ஒரு வயலையாவது நாங்கள் கொள்ளவில்லை; அந்த அலங்கத்தின் வேலையிலே முயன்று நின்றேன்; என் வேலைக்காரரனைவரும் கூட்டமாய் அந்த வேலைக்குக் கூடிவந்தார்கள்.", "en": "Yea, also I continued in the work of this wall, neither bought we any land: and all my servants were gathered thither unto the work."}, {"verse": 17, "start": 268.97, "end": 280.39, "ta": "யூதரும் மூப்பருமான நூற்றைம்பதுபேரும், எங்களைச் சுற்றிலுமிருக்கிற புறஜாதிகளிடத்திலிருந்து எங்களிடத்திற்கு வந்தவர்களும் என் பந்தியில் சாப்பிட்டார்கள்.", "en": "Moreover there were at my table an hundred and fifty of the Jews and rulers, beside those that came unto us from among the heathen that are about us."}, {"verse": 18, "start": 280.39, "end": 302.22, "ta": "நாளொன்றுக்கு ஒரு காளையும், முதல் தரமான ஆறு ஆடும் சமைக்கப்பட்டது; பட்சிகளும் சமைக்கப்பட்டது; பத்துநாளைக்கு ஒருதரம் நானாவிதத் திராட்சரசமும் செலவழிந்தது. இப்படியெல்லாம் இருந்தபோதும், இந்த ஜனங்கள் பட்டபாடு கடினமாயிருந்தபடியால், அதிபதிகள் வாங்குகிற படியை நான் வாங்கவில்லை.", "en": "Now that which was prepared for me daily was one ox and six choice sheep; also fowls were prepared for me, and once in ten days store of all sorts of wine: yet for all this required not I the bread of the governor, because the bondage was heavy upon this people."}, {"verse": 19, "start": 302.22, "end": 310.28, "ta": "என் தேவனே, நான் இந்த ஜனத்துக்காகச் செய்த எல்லாவற்றின்படியும் எனக்கு நன்மையுண்டாக என்னை நினைத்தருளும்.", "en": "Think upon me, my God, for good, according to all that I have done for this people."}]}, "6": {"chapter": 6, "duration": 264.85, "audio_url": "audio_ot/OT16_06.mp3", "total_verses": 19, "verses": [{"verse": 1, "start": 3.8, "end": 17.17, "ta": "நான் அலங்கத்தைக் கட்டிமுடித்ததையும், இனி அதிலே திறப்பு ஒன்றுமில்லை என்பதையும், சன்பல்லாத்தும், தொபியாவும், அரபியனான கேஷேமும் எங்களுக்குண்டாயிருந்த மற்றப் பகைஞரும் கேள்விப்பட்டபோது,", "en": "Now it came to pass, when Sanballat, and Tobiah, and Geshem the Arabian, and the rest of our enemies, heard that I had builded the wall, and that there was no breach left therein; (though at that time I had not set up the doors upon the gates;)"}, {"verse": 2, "start": 17.17, "end": 36.37, "ta": "நான் வாசல்களுக்கு இன்னும் கதவுபோடாதிருக்கையில், சன்பல்லாத்தும், கேஷேமும் ஆள் அனுப்பி: நாம் ஓனோ பள்ளத்தாக்கில் இருக்கிற கிராமங்கள் ஒன்றில் ஒருவரையொருவர் கண்டு பேசுவோம் வாரும் என்று கூப்பிட்டார்கள்; அவர்களோவென்றால், எனக்குப் பொல்லாப்புச் செய்ய நினைத்தார்கள்.", "en": "That Sanballat and Geshem sent unto me, saying, Come, let us meet together in some one of the villages in the plain of Ono. But they thought to do me mischief."}, {"verse": 3, "start": 36.37, "end": 50.91, "ta": "அப்பொழுது நான் அவர்களிடத்திற்கு ஆட்களை அனுப்பி: நான் பெரிய வேலையைச் செய்கிறேன், நான் வரக் கூடாது, நான் அந்த வேலையைவிட்டு உங்களிடத்திற்கு வருகிறதினால் அது மினக்கட்டுப்போவானேன் என்று சொல்லச்சொன்னேன்.", "en": "And I sent messengers unto them, saying, I am doing a great work, so that I cannot come down: why should the work cease, whilst I leave it, and come down to you?"}, {"verse": 4, "start": 50.91, "end": 60.24, "ta": "அவர்கள் இந்தப்பிரகாரமாக நாலுதரம் எனக்குச் சொல்லியனுப்பினார்கள்; நானும் இந்தப்பிரகாரமாகவே அவர்களுக்கு மறுமொழி அனுப்பினேன்.", "en": "Yet they sent unto me four times after this sort; and I answered them after the same manner."}, {"verse": 5, "start": 60.24, "end": 69.9, "ta": "ஐந்தாந்தரமும் சன்பல்லாத்து அந்தப் பிரகாரமாகவே தன் வேலைக்காரனையும், அவன் கையிலே முத்திரைபோடாத ஒரு கடிதத்தையும் எனக்கு அனுப்பினான்.", "en": "Then sent Sanballat his servant unto me in like manner the fifth time with an open letter in his hand;"}, {"verse": 6, "start": 69.9, "end": 81.29, "ta": "அதிலே: நீரும் யூதரும் கலகம்பண்ண நினைக்கிறீர்கள் என்றும், அதற்காக நீர் அலங்கத்தைக் கட்டுகிறீர் என்றும், இவ்விதமாக நீர் அவர்களுக்கு ராஜாவாகப் போகிறீர் என்றும்,", "en": "Wherein was written, It is reported among the heathen, and Gashmu saith it, that thou and the Jews think to rebel: for which cause thou buildest the wall, that thou mayest be their king, according to these words."}, {"verse": 7, "start": 81.29, "end": 104.67, "ta": "யூதாவிலே ஒரு ராஜா இருக்கிறார் என்று உம்மைக்குறித்து எருசலேமிலே கூறுகிற தீர்க்கதரிசிகளையும் சம்பாதித்தீரென்றும் புறஜாதிகளுக்குள்ளே பிரஸ்தாபமாயிருக்கிறது, கஷ்மூமுவும் அப்படிச் சொல்லுகிறான்; இப்போதும் அந்தச் செய்தி ராஜாவுக்கு எட்டுமே; ஆகையால் நாம் ஒருவரோடொருவர் ஆலோசனைபண்ணுகிறதற்காக நீர் வரவேண்டும் என்று எழுதியிருந்தது.", "en": "And thou hast also appointed prophets to preach of thee at Jerusalem, saying, There is a king in Judah: and now shall it be reported to the king according to these words. Come now therefore, and let us take counsel together."}, {"verse": 8, "start": 104.67, "end": 114.68, "ta": "அதற்கு நான் நீர் சொல்லுகிற அந்தக் காரியங்களில் ஒன்றும் நடக்கவில்லை; அவைகள் உம்முடைய மனோராஜ்யமே ஒழிய வேறல்ல என்று சொல்லியனுப்பினேன்.", "en": "Then I sent unto him, saying, There are no such things done as thou sayest, but thou feignest them out of thine own heart."}, {"verse": 9, "start": 114.68, "end": 127.23, "ta": "அந்த வேலை நடந்தேறாதபடிக்கு எங்கள் கை சலித்துப்போம் என்று சொல்லி, அவர்கள் எல்லாரும் எங்களைப் பயமுறுத்தப்பார்த்தார்கள். ஆதலால் தேவனே நீர் என் கைகளைத் திடப்படுத்தியருளும்,", "en": "For they all made us afraid, saying, Their hands shall be weakened from the work, that it be not done. Now therefore, O God , strengthen my hands."}, {"verse": 10, "start": 127.23, "end": 149.52, "ta": "மெகதாபெயேலின் குமாரனாகிய தெலாயாவின் மகன் செமாயா தன் வீட்டிலே அடைக்கப்பட்டிருக்கும்போது, நான் அவனிடத்தில் போனேன்; அப்பொழுது அவன் நாம் இருவருமாய் தேவனுடைய வீடாகிய ஆலயத்துக்குள்ளே போய் தேவாலயத்தின் கதவுகளைப் பூட்டுவோம் வாரும்; உம்மைக் கொன்றுபோட வருவார்கள், இரவிலே உம்மைக் கொன்றுபோட வருவார்கள் என்றான்.", "en": "Afterward I came unto the house of Shemaiah the son of Delaiah the son of Mehetabeel, who was shut up; and he said, Let us meet together in the house of God, within the temple, and let us shut the doors of the temple: for they will come to slay thee; yea, in the night will they come to slay thee."}, {"verse": 11, "start": 149.52, "end": 161.18, "ta": "அதற்கு நான்; என்னைப்போன்ற மனிதன் ஓடிப்போவானோ? என்னைப்போன்றவன் உயிர்பிழைக்கும்படி தேவாலயத்திலே போய்ப் பதுங்குவானோ? நான் போவதில்லை என்றேன்.", "en": "And I said, Should such a man as I flee? and who is there , that, being as I am , would go into the temple to save his life? I will not go in."}, {"verse": 12, "start": 161.18, "end": 173.86, "ta": "தேவன் அவனை அனுப்பவில்லையென்றும், தொபியாவும் சன்பல்லாத்தும் அவனுக்குக் கூலிகொடுத்ததினால், அவன் எனக்கு விரோதமாய் அந்தத் தீர்க்கதரிசனத்தைச் சொன்னான் என்றும் அறிந்துகொண்டேன்.", "en": "And, lo, I perceived that God had not sent him; but that he pronounced this prophecy against me: for Tobiah and Sanballat had hired him."}, {"verse": 13, "start": 173.86, "end": 186.07, "ta": "நான் பயந்து அப்படிச் செய்து பாவங்கட்டிக்கொள்ளுகிறதற்கும், என்னை நிந்திக்கத்தக்க அபகீர்த்திக்கு முகாந்தரம் உண்டாக்குகிறதற்கும் அவனுக்குக் கைக்கூலி கொடுத்திருந்தார்கள்.", "en": "Therefore was he hired, that I should be afraid, and do so, and sin, and that they might have matter for an evil report, that they might reproach me."}, {"verse": 14, "start": 186.07, "end": 201.63, "ta": "என் தேவனே, தொபியாவும் சன்பல்லாத்தும் செய்த இந்தச் செய்கைகளுக்குத்தக்கதாக நீர் அவர்களையும், நொவதியாள் என்னும் தீர்க்கதரிசியானவளையும், எனக்குப் பயமுண்டாக்கப்பார்த்த மற்றத் தீர்க்கதரிசிகளையும் நினைத்துக்கொள்ளும்.", "en": "My God, think thou upon Tobiah and Sanballat according to these their works, and on the prophetess Noadiah, and the rest of the prophets, that would have put me in fear."}, {"verse": 15, "start": 201.63, "end": 209.73, "ta": "அப்படியே அலங்கமானது ஐம்பத்திரண்டு நாளைக்குள்ளே கட்டப்பட்டு, எலுூல் மாதம் இருபத்தைந்தாந்தேதியிலே முடிந்தது.", "en": "So the wall was finished in the twenty and fifth day of the month Elul, in fifty and two days."}, {"verse": 16, "start": 209.73, "end": 223.85, "ta": "எங்கள் பகைஞர் எல்லாரும் அதைக் கேட்டபோதும், எங்கள் சுற்றுப்புறத்தாராகிய புறஜாதியான அனைவரும் கண்டபோதும், மிகவும் முனையற்றுப்போய், இந்தக் கிரியை எங்கள் தேவனால் கைகூடி வந்ததென்று அறிந்தார்கள்.", "en": "And it came to pass, that when all our enemies heard thereof , and all the heathen that were about us saw these things , they were much cast down in their own eyes: for they perceived that this work was wrought of our God."}, {"verse": 17, "start": 223.85, "end": 235.17, "ta": "அந்த நாட்களில் யூதாவிலுள்ள பெரிய மனிதரிடத்திலிருந்து தொபியாவுக்குப் போகிறதும், தொபியாவினிடத்திலிருந்து அவர்களுக்கு வருகிறதுமான கடிதங்கள் அநேகமாயிருந்தது.", "en": "Moreover in those days the nobles of Judah sent many letters unto Tobiah, and the letters of Tobiah came unto them."}, {"verse": 18, "start": 235.17, "end": 251.49, "ta": "அவன் ஆராகின் குமாரனாகிய செகனியாவுக்கு மருமகனாயிருந்ததுமல்லாமல், அவன் குமாரனாகிய யோகனான் பெரகியாவின் குமாரனாகிய மெசுல்லாமின் குமாரத்தியை விவாகம்பண்ணியிருந்தபடியாலும், யூதாவில் அநேகர் அவனுக்கு ஆணையிட்டுக் கொடுத்திருந்தார்கள்.", "en": "For there were many in Judah sworn unto him, because he was the son in law of Shechaniah the son of Arah; and his son Johanan had taken the daughter of Meshullam the son of Berechiah."}, {"verse": 19, "start": 251.49, "end": 263.35, "ta": "அவன் செய்யும் நன்மைகளையும் அவர்கள் எனக்கு முன்பாக விவரித்து, என் வார்த்தைகளை அவனுக்குக் கொண்டுபோவார்கள்; தொபியா எனக்குப் பயமுண்டாகக் கடிதங்களை அனுப்புவான்.", "en": "Also they reported his good deeds before me, and uttered my words to him. And Tobiah sent letters to put me in fear."}]}, "7": {"chapter": 7, "duration": 509.15, "audio_url": "audio_ot/OT16_07.mp3", "total_verses": 73, "verses": [{"verse": 1, "start": 3.8, "end": 12.0, "ta": "அலங்கம் கட்டிமுடிந்து, கதவுகள் போடப்பட்டு, வாசல் காவலாளரையும் பாடகரையும், லேவியரையும் ஏற்படுத்தினபின்பு,", "en": "Now it came to pass, when the wall was built, and I had set up the doors, and the porters and the singers and the Levites were appointed,"}, {"verse": 2, "start": 12.0, "end": 25.35, "ta": "நான் என் சகோதரனாகிய ஆனானியையும், அநேகரைப்பார்க்கிலும் உண்மையுள்ளவனும் தேவனுக்குப் பயந்தவனுமாயிருந்த அரமனைத்தலைவனாகிய அனனியாவையும், எருசலேமின் காவல்விசாரணைக்கு ஏற்படுத்தினேன்.", "en": "That I gave my brother Hanani, and Hananiah the ruler of the palace, charge over Jerusalem: for he was a faithful man, and feared God above many."}, {"verse": 3, "start": 25.35, "end": 44.08, "ta": "அவர்களை நோக்கி: வெயில் ஏறுமட்டும் எருசலேமின் வாசல்கள் திறக்கப்படவேண்டாம், நீங்கள் நிற்கும்போதே கதவுகளைச் சாத்தித் தாழ்ப்பாள் போட்டு, எருசலேமின் குடிகளில் காவலாளர் அவரவர் தங்கள் காவலிலே, அவரவர் தங்கள் வீடுகளுக்கு எதிராக நிறுத்தப்படவேண்டும் என்றேன்.", "en": "And I said unto them, Let not the gates of Jerusalem be opened until the sun be hot; and while they stand by, let them shut the doors, and bar them: and appoint watches of the inhabitants of Jerusalem, every one in his watch, and every one to be over against his house."}, {"verse": 4, "start": 44.08, "end": 52.56, "ta": "பட்டணம் விஸ்தாரமும் பெரிதுமாயிருந்தது, அதற்குள்ளே ஜனங்கள் கொஞ்சமாயிருந்தார்கள், வீடுகளும் கட்டப்படவில்லை.", "en": "Now the city was large and great: but the people were few therein, and the houses were not builded."}, {"verse": 5, "start": 52.56, "end": 73.26, "ta": "அப்பொழுது வம்ச அட்டவணைகளைப் பார்க்கிறதற்கு, நான் பிரபுக்களையும் அதிகாரிகளையும் ஜனங்களையும் கூடிவரச்செய்ய, என் தேவன் என் மனதிலே ஒரு எண்ணத்தை உண்டாக்கினார்; முந்தி வந்தவர்களின் வம்ச அட்டவணைப் புஸ்தகம் அப்பொழுது எனக்கு அகப்பட்டது; அதிலே எழுதியிருக்க நான் கண்டது என்னவென்றால்,", "en": "And my God put into mine heart to gather together the nobles, and the rulers, and the people, that they might be reckoned by genealogy. And I found a register of the genealogy of them which came up at the first, and found written therein,"}, {"verse": 6, "start": 73.26, "end": 91.78, "ta": "பாபிலோன் ராஜாவாகிய நேபுகாத்நேச்சார் சிறைபிடித்துப்போனவர்களும், சிறையிருப்பிலிருந்து செருபாபேலோடும், யெசுவா, நெகேமியா, அசரியா, ராமியா, நகமானி, மொர்தெகாய், பில்சான், மிஸ்பெரேத், பிக்வாயி, நெகூம், பானா என்பவர்களோடுங்கூட வந்து,", "en": "These are the children of the province, that went up out of the captivity, of those that had been carried away, whom Nebuchadnezzar the king of Babylon had carried away, and came again to Jerusalem and to Judah, every one unto his city;"}, {"verse": 7, "start": 91.78, "end": 102.73, "ta": "எருசலேமுக்கும் யூதாவுக்கும் திரும்பித் தங்கள் தங்கள் பட்டணங்களிலே குடியிறங்கினவர்களுமான இந்தத் தேசத்தின் புத்திரராகிய இஸ்ரவேல் ஜனங்களான மனிதரின் தொகையாவது:", "en": "Who came with Zerubbabel, Jeshua, Nehemiah, Azariah, Raamiah, Nahamani, Mordecai, Bilshan, Mispereth, Bigvai, Nehum, Baanah. The number, I say , of the men of the people of Israel was this;"}, {"verse": 8, "start": 102.73, "end": 107.47, "ta": "பாரோஷின் புத்திரர் இரண்டாயிரத்து நூற்று எழுபத்திரண்டுபேர்.", "en": "The children of Parosh, two thousand an hundred seventy and two."}, {"verse": 9, "start": 107.47, "end": 111.85, "ta": "செபத்தியாவின் புத்திரர் முந்நூற்று எழுபத்திரண்டுபேர்.", "en": "The children of Shephatiah, three hundred seventy and two."}, {"verse": 10, "start": 111.85, "end": 115.74, "ta": "ஆராகின் புத்திரர் அறுநூற்று ஐம்பத்திரண்டுபேர்.", "en": "The children of Arah, six hundred fifty and two."}, {"verse": 11, "start": 115.74, "end": 124.43, "ta": "யெசுவா யோவாப் என்பவர்களின் சந்ததிக்குள்ளிருந்த பாகாத்மோவாபின் புத்திரர் இரண்டாயிரத்து எண்ணூற்றுப் பதினெட்டுப்பேர்.", "en": "The children of Pahath-moab, of the children of Jeshua and Joab, two thousand and eight hundred and eighteen."}, {"verse": 12, "start": 124.43, "end": 128.74, "ta": "ஏலாமின் புத்திரர் ஆயிரத்திருநூற்று ஐம்பத்துநாலுபேர்.", "en": "The children of Elam, a thousand two hundred fifty and four."}, {"verse": 13, "start": 128.74, "end": 132.77, "ta": "சத்தூவின் புத்திரர் எண்ணூற்று நாற்பத்தைந்துபேர்.", "en": "The children of Zattu, eight hundred forty and five."}, {"verse": 14, "start": 132.77, "end": 136.3, "ta": "சக்காயின் புத்திரர் எழுநூற்று அறுபதுபேர்.", "en": "The children of Zaccai, seven hundred and threescore."}, {"verse": 15, "start": 136.3, "end": 140.54, "ta": "பின்னூவின் புத்திரர் அறுநூற்று நாற்பத்தெட்டுப்பேர்.", "en": "The children of Binnui, six hundred forty and eight."}, {"verse": 16, "start": 140.54, "end": 144.57, "ta": "பெபாயின் புத்திரர் அறுநூற்று இருபத்தெட்டுப்பேர்.", "en": "The children of Bebai, six hundred twenty and eight."}, {"verse": 17, "start": 144.57, "end": 149.66, "ta": "அஸ்காதின் புத்திரர் இரண்டாயிரத்து முந்நூற்று இருபத்திரண்டுபேர்.", "en": "The children of Azgad, two thousand three hundred twenty and two."}, {"verse": 18, "start": 149.66, "end": 153.61, "ta": "அதோனிகாமின் புத்திரர் அறுநூற்று அறுபத்தேழுபேர்.", "en": "The children of Adonikam, six hundred threescore and seven."}, {"verse": 19, "start": 153.61, "end": 157.78, "ta": "பிக்வாயின் புத்திரர் இரண்டாயிரத்து அறுபத்தேழுபேர்.", "en": "The children of Bigvai, two thousand threescore and seven."}, {"verse": 20, "start": 157.78, "end": 161.6, "ta": "ஆதீனின் புத்திரர் அறுநூற்று ஐம்பத்தைந்துபேர்.", "en": "The children of Adin, six hundred fifty and five."}, {"verse": 21, "start": 161.6, "end": 166.83, "ta": "எசேக்கியாவின் சந்ததியான ஆதேரின் புத்திரர் தொண்ணூற்று எட்டுப்பேர்.", "en": "The children of Ater of Hezekiah, ninety and eight."}, {"verse": 22, "start": 166.83, "end": 170.85, "ta": "ஆசூமின் புத்திரர் முந்நூற்று இருபத்தெட்டுப்பேர்.", "en": "The children of Hashum, three hundred twenty and eight."}, {"verse": 23, "start": 170.85, "end": 174.81, "ta": "பேசாயின் புத்திரர் முந்நூற்று இருபத்துநாலுபேர்.", "en": "The children of Bezai, three hundred twenty and four."}, {"verse": 24, "start": 174.81, "end": 178.49, "ta": "ஆரீப்பின் புத்திரர் நூற்றுப்பன்னிரண்டுபேர்.", "en": "The children of Hariph, an hundred and twelve."}, {"verse": 25, "start": 178.49, "end": 182.09, "ta": "கிபியோனின் புத்திரர் தொண்ணூற்று ஐந்துபேர்.", "en": "The children of Gibeon, ninety and five."}, {"verse": 26, "start": 182.09, "end": 187.32, "ta": "பெத்லகேம் ஊராரும், நெத்தோபா ஊராரும் நூற்று எண்பத்தெட்டுப்பேர்.", "en": "The men of Beth-lehem and Netophah, an hundred fourscore and eight."}, {"verse": 27, "start": 187.32, "end": 191.07, "ta": "ஆனதோத்தூர் மனிதர் நூற்று இருபத்தெட்டுப்பேர்.", "en": "The men of Anathoth, an hundred twenty and eight."}, {"verse": 28, "start": 191.07, "end": 194.46, "ta": "பெத்அஸ்மாவேத் ஊரார் நாற்பத்திரண்டுபேர்.", "en": "The men of Beth-azmaveth, forty and two."}, {"verse": 29, "start": 194.46, "end": 200.61, "ta": "கீரியாத்யாரீம், கெபிராபேரோத் ஊர்களின் மனிதர் எழுநூற்று நாற்பத்துமூன்றுபேர்.", "en": "The men of Kirjath-jearim, Chephirah, and Beeroth, seven hundred forty and three."}, {"verse": 30, "start": 200.61, "end": 205.13, "ta": "ராமா, காபா ஊர்களின் மனிதர் அறுநூற்று இருபத்தொருபேர்.", "en": "The men of Ramah and Geba, six hundred twenty and one."}, {"verse": 31, "start": 205.13, "end": 208.59, "ta": "மிக்மாஸ் ஊரார் நூற்று இருபத்திரண்டுபேர்.", "en": "The men of Michmas, an hundred and twenty and two."}, {"verse": 32, "start": 208.59, "end": 213.4, "ta": "பெத்தேல், ஆயி ஊர்களின் மனிதர் நூற்று இருபத்துமூன்றுபேர்.", "en": "The men of Beth-el and Ai, an hundred twenty and three."}, {"verse": 33, "start": 213.4, "end": 216.58, "ta": "வேறொரு நேபோ ஊரார் ஐம்பத்திரண்டுபேர்.", "en": "The men of the other Nebo, fifty and two."}, {"verse": 34, "start": 216.58, "end": 221.45, "ta": "மற்றொரு ஏலாம் புத்திரர் ஆயிரத்து இருநூற்று ஐம்பத்துநாலுபேர்.", "en": "The children of the other Elam, a thousand two hundred fifty and four."}, {"verse": 35, "start": 221.45, "end": 224.77, "ta": "ஆரீம் புத்திரர் முந்நூற்று இருபதுபேர்.", "en": "The children of Harim, three hundred and twenty."}, {"verse": 36, "start": 224.77, "end": 228.52, "ta": "எரிகோ புத்திரர் முந்நூற்று அறுபத்தைந்துபேர்.", "en": "The children of Jericho, three hundred forty and five."}, {"verse": 37, "start": 228.52, "end": 233.89, "ta": "லோத், ஆதீத், ஓனோ ஊர்களின் புத்திரர் எழுநூற்று இருபத்தொருபேர்.", "en": "The children of Lod, Hadid, and Ono, seven hundred twenty and one."}, {"verse": 38, "start": 233.89, "end": 238.41, "ta": "செனாகா புத்திரர் மூவாயிரத்துத் தொளாயிரத்து முப்பதுபேர்.", "en": "The children of Senaah, three thousand nine hundred and thirty."}, {"verse": 39, "start": 238.41, "end": 245.62, "ta": "ஆசாரியரானவர்கள்: யெசுவா குடும்பத்தானாகிய யெதாயாவின் புத்திரர் தொளாயிரத்து எழுபத்துமூன்றுபேர்.", "en": "The priests: the children of Jedaiah, of the house of Jeshua, nine hundred seventy and three."}, {"verse": 40, "start": 245.62, "end": 249.58, "ta": "இம்மேரின் புத்திரர் ஆயிரத்து ஐம்பத்திரண்டுபேர்.", "en": "The children of Immer, a thousand fifty and two."}, {"verse": 41, "start": 249.58, "end": 254.1, "ta": "பஸ்கூரின் புத்திரர் ஆயிரத்து இருநூற்று நாற்பத்தேழுபேர்.", "en": "The children of Pashur, a thousand two hundred forty and seven."}, {"verse": 42, "start": 254.1, "end": 257.63, "ta": "ஆரீமின் புத்திரர் ஆயிரத்துப் பதினேழுபேர்.", "en": "The children of Harim, a thousand and seventeen."}, {"verse": 43, "start": 257.63, "end": 265.69, "ta": "லேவியரானவர்கள்: ஒதியாவின் புத்திரருக்குள்ளே கத்மியேலின் குமாரனாகிய யெசுவாவின் புத்திரர் எழுபத்துநாலுபேர்.", "en": "The Levites: the children of Jeshua, of Kadmiel, and of the children of Hodevah, seventy and four."}, {"verse": 44, "start": 265.69, "end": 270.56, "ta": "பாடகரானவர்கள்: ஆசாபின் புத்திரர் நூற்று நாற்பத்தெட்டுப்பேர்.", "en": "The singers: the children of Asaph, an hundred forty and eight."}, {"verse": 45, "start": 270.56, "end": 285.12, "ta": "வாசல் காவலாளரானவர்கள்; சல்லுூமின் புத்திரர் அதேரின் புத்திரர், தல்மோனின் புத்திரர், அக்கூபின் புத்திரர், அதிதாவின் புத்திரர், சோபாயின் புத்திரர், ஆக நூற்று முப்பத்தெட்டுப்பேர்.", "en": "The porters: the children of Shallum, the children of Ater, the children of Talmon, the children of Akkub, the children of Hatita, the children of Shobai, an hundred thirty and eight."}, {"verse": 46, "start": 285.12, "end": 291.48, "ta": "நிதனீமியரானவர்கள்: சீகாவின்புத்திரர், அசுபாவின் புத்திரர், தபாகோத்தின் புத்திரர்,", "en": "The Nethinims: the children of Ziha, the children of Hashupha, the children of Tabbaoth,"}, {"verse": 47, "start": 291.48, "end": 296.29, "ta": "கேரோசின் புத்திரர், சீயாவின் புத்திரர், பாதோனின் புத்திரர்,", "en": "The children of Keros, the children of Sia, the children of Padon,"}, {"verse": 48, "start": 296.29, "end": 301.38, "ta": "லெபானாவின் புத்திரர், அகாபாவின் புத்திரர், சல்மாயின் புத்திரர்,", "en": "The children of Lebana, the children of Hagaba, the children of Shalmai,"}, {"verse": 49, "start": 301.38, "end": 306.25, "ta": "ஆனானின் புத்திரர், கித்தேலின் புத்திரர், காகாரின் புத்திரர்,", "en": "The children of Hanan, the children of Giddel, the children of Gahar,"}, {"verse": 50, "start": 306.25, "end": 311.34, "ta": "ராயாகின் புத்திரர், ரேத்சீனின் புத்திரர், நெகோதாவின் புத்திரர்,", "en": "The children of Reaiah, the children of Rezin, the children of Nekoda,"}, {"verse": 51, "start": 311.34, "end": 316.22, "ta": "காசாமின் புத்திரர், ஊசாவின் புத்திரர், பாசெயாகின் புத்திரர்,", "en": "The children of Gazzam, the children of Uzza, the children of Phaseah,"}, {"verse": 52, "start": 316.22, "end": 321.37, "ta": "பேசாயின் புத்திரர், மெயுநீமின் புத்திரர், நெபிஷசீமின் புத்திரர்,", "en": "The children of Besai, the children of Meunim, the children of Nephishesim,"}, {"verse": 53, "start": 321.37, "end": 326.53, "ta": "பக்பூக்கின் புத்திரர், அகுபாவின் புத்திரர், அர்கூரின் புத்திரர்,", "en": "The children of Bakbuk, the children of Hakupha, the children of Harhur,"}, {"verse": 54, "start": 326.53, "end": 331.62, "ta": "பஸ்லீதின் புத்திரர், மெகிதாவின் புத்திரர், அர்ஷாவின் புத்திரர்,", "en": "The children of Bazlith, the children of Mehida, the children of Harsha,"}, {"verse": 55, "start": 331.62, "end": 336.64, "ta": "பர்கோசின் புத்திரர், சிசெராவின் புத்திரர், தாமாவின் புத்திரர்,", "en": "The children of Barkos, the children of Sisera, the children of Tamah,"}, {"verse": 56, "start": 336.64, "end": 340.17, "ta": "நெத்சியாகின் புத்திரர், அதிபாவின் புத்திரர்,", "en": "The children of Neziah, the children of Hatipha."}, {"verse": 57, "start": 340.17, "end": 348.51, "ta": "சாலொமோனுடைய வேலைக்காரரின் புத்திரரானவர்கள்: சோதாயின் புத்திரர், சொபெரேத்தின் புத்திரர், பெருதாவின் புத்திரர்,", "en": "The children of Solomon’s servants: the children of Sotai, the children of Sophereth, the children of Perida,"}, {"verse": 58, "start": 348.51, "end": 353.53, "ta": "யாலாவின் புத்திரர், தர்கோனின் புத்திரர், கித்தேலின் புத்திரர்,", "en": "The children of Jaala, the children of Darkon, the children of Giddel,"}, {"verse": 59, "start": 353.53, "end": 361.72, "ta": "செபத்தியாவின் புத்திரர், அத்தீலின் புத்திரர், பொகெரேத் செபாயிமிலுள்ள புத்திரர், ஆமோனின் புத்திரர்.", "en": "The children of Shephatiah, the children of Hattil, the children of Pochereth of Zebaim, the children of Amon."}, {"verse": 60, "start": 361.72, "end": 369.07, "ta": "நிதனிமியரும் சாலொமோனுடைய வேலையாட்களின் புத்திரரும் ஏகத்துக்கு முந்நூற்றுத் தொண்ணூற்றிரண்டுபேர்.", "en": "All the Nethinims, and the children of Solomon’s servants, were three hundred ninety and two."}, {"verse": 61, "start": 369.07, "end": 384.13, "ta": "தெல்மெலாகிலும், தெல்அர்சாவிலும், கேருபிலும், ஆதோனிலும், இம்மேரிலும் இருந்துவந்தும், தாங்கள் இஸ்ரவேலர் என்று தங்கள் பிதாக்களின் வம்சத்தையும், தங்கள் பூர்வோத்தரத்தையும் சொல்லமாட்டாமல் இருந்தவர்கள்:", "en": "And these were they which went up also from Tel-melah, Tel-haresha, Cherub, Addon, and Immer: but they could not shew their father’s house, nor their seed, whether they were of Israel."}, {"verse": 62, "start": 384.13, "end": 392.32, "ta": "தெலாயாவின் புத்திரர், தொபியாவின் புத்திரர், நெகோதாவின் புத்திரர், ஆக அறுநூற்று நாற்பத்திரண்டுபேர்.", "en": "The children of Delaiah, the children of Tobiah, the children of Nekoda, six hundred forty and two."}, {"verse": 63, "start": 392.32, "end": 406.1, "ta": "ஆசாரியர்களில் அபாயாவின் புத்திரர், கோசின் புத்திரர், கிலேயாத்தியனான பர்சில்லாயின் குமாரத்திகளில் ஒருத்தியை விவாகம்பண்ணி, அவர்கள் வம்ச நாமம் தரிக்கப்பட்ட பர்சில்லாயின் புத்திரர்.", "en": "And of the priests: the children of Habaiah, the children of Koz, the children of Barzillai, which took one of the daughters of Barzillai the Gileadite to wife, and was called after their name."}, {"verse": 64, "start": 406.1, "end": 415.08, "ta": "இவர்கள் தங்கள் வம்ச அட்டவணையைத் தேடி, அதைக் காணாமற்போய் ஆசாரிய ஊழியத்துக்கு விலக்கமானவர்கள் என்று எண்ணப்பட்டார்கள்.", "en": "These sought their register among those that were reckoned by genealogy, but it was not found: therefore were they, as polluted, put from the priesthood."}, {"verse": 65, "start": 415.08, "end": 425.54, "ta": "ஊரீம் தும்மீம் என்பவைகளுள்ள ஒரு ஆசாரியன் எழும்புமட்டும், அவர்கள் மகா பரிசுத்தமானதிலே புசிக்கத்தகாதென்று திர்ஷாதா அவர்களுக்குச் சொன்னான்.", "en": "And the Tirshatha said unto them, that they should not eat of the most holy things, till there stood up a priest with Urim and Thummim."}, {"verse": 66, "start": 425.54, "end": 432.04, "ta": "சபையார் எல்லாரும் ஏகத்துக்கு நாற்பத்தீராயிரத்து முந்நூற்று அறுபதுபேராயிருந்தார்கள்.", "en": "The whole congregation together was forty and two thousand three hundred and threescore,"}, {"verse": 67, "start": 432.04, "end": 444.12, "ta": "அவர்களைத்தவிர ஏழாயிரத்துமுந்நூற்று முப்பத்தேழுபேரான அவர்களுடைய வேலைக்காரரும் வேலைக்காரிகளும் இருநூற்று நாற்பத்தைந்து பாடகரும் பாடகிகளும் அவர்களுக்கு இருந்தார்கள்.", "en": "Beside their manservants and their maidservants, of whom there were seven thousand three hundred thirty and seven: and they had two hundred forty and five singing men and singing women."}, {"verse": 68, "start": 444.12, "end": 451.47, "ta": "அவர்களுடைய குதிரைகள் எழுநூற்று முப்பத்தாறு, அவர்கள் கோவேறு கழுதைகள் இருநூற்று நாற்பத்தைந்து.", "en": "Their horses, seven hundred thirty and six: their mules, two hundred forty and five:"}, {"verse": 69, "start": 451.47, "end": 457.41, "ta": "ஒட்டகங்கள் நானூற்று முப்பத்தைந்து, கழுதைகள் ஆறாயிரத்து எழுநூற்று இருபது.", "en": "Their camels, four hundred thirty and five: six thousand seven hundred and twenty asses."}, {"verse": 70, "start": 457.41, "end": 470.2, "ta": "வம்சத்தலைவரில் சிலர் வேலைக்கென்று கொடுத்ததாவது: திர்ஷாதா ஆயிரம் தங்கக்காசையும் ஐம்பது கலங்களையும், ஐந்நூற்று முப்பது ஆசாரிய வஸ்திரங்களையும் பொக்கிஷத்துக்குக் கொடுத்தான்.", "en": "And some of the chief of the fathers gave unto the work. The Tirshatha gave to the treasure a thousand drams of gold, fifty basons, five hundred and thirty priests’ garments."}, {"verse": 71, "start": 470.2, "end": 480.44, "ta": "வம்சத்தலைவரில் சிலர் வேலையின் பொக்கிஷத்துக்கு இருபதினாயிரம் தங்கக்காசையும், இரண்டாயிரத்து இருநூறு ராத்தல் வெள்ளியையும் கொடுத்தார்கள்.", "en": "And some of the chief of the fathers gave to the treasure of the work twenty thousand drams of gold, and two thousand and two hundred pound of silver."}, {"verse": 72, "start": 480.44, "end": 490.34, "ta": "மற்ற ஜனங்கள் இருபதினாயிரம் தங்கக்காசையும், இரண்டாயிரம் ராத்தல் வெள்ளியையும், அறுபத்தேழு ஆசாரிய வஸ்திரங்களையும் கொடுத்தார்கள்.", "en": "And that which the rest of the people gave was twenty thousand drams of gold, and two thousand pound of silver, and threescore and seven priests’ garments."}, {"verse": 73, "start": 490.34, "end": 507.65, "ta": "ஆசாரியரும் லேவியரும், வாசல் காவலாளரும், பாடகரும், ஜனங்களில் சிலரும் நிதனீமியரும், இஸ்ரவேலர் அனைவரும் தங்கள் தங்கள் பட்டணங்களில் குடியேறினார்கள்; ஏழாம் மாதமானபோது, இஸ்ரவேல் புத்திரர் தங்கள் பட்டணங்களில் இருந்தார்கள்.", "en": "So the priests, and the Levites, and the porters, and the singers, and some of the people, and the Nethinims, and all Israel, dwelt in their cities; and when the seventh month came, the children of Israel were in their cities."}]}, "8": {"chapter": 8, "duration": 317.71, "audio_url": "audio_ot/OT16_08.mp3", "total_verses": 18, "verses": [{"verse": 1, "start": 3.8, "end": 19.49, "ta": "ஜனங்கள் எல்லாரும் தண்ணீர்வாசலுக்கு முன்னான வீதியிலே ஒருமனப்பட்டுக் கூடி, கர்த்தர் இஸ்ரவேலுக்குக் கற்பித்த மோசேயின் நியாயப்பிரமாண புஸ்தகத்தைக் கொண்டுவரவேண்டுமென்று வேதபாரகனாகிய எஸ்றாவுக்குச் சொன்னார்கள்.", "en": "And all the people gathered themselves together as one man into the street that was before the water gate; and they spake unto Ezra the scribe to bring the book of the law of Moses, which the LORD had commanded to Israel."}, {"verse": 2, "start": 19.49, "end": 31.36, "ta": "அப்படியே ஏழாம் மாதம் முதல்தேதியில் ஆசாரியனாகிய எஸ்றா நியாயப்பிரமாணத்தைப் புருஷரும் ஸ்திரீகளும், கேட்டு அறியத்தக்க அனைவருமாகிய சபைக்கு முன்பாகக் கொண்டுவந்து,", "en": "And Ezra the priest brought the law before the congregation both of men and women, and all that could hear with understanding, upon the first day of the seventh month."}, {"verse": 3, "start": 31.36, "end": 50.35, "ta": "தண்ணீர் வாசலுக்கு முன்னான வீதிக்கு எதிரேயிருந்து காலமேதொடங்கி மத்தியானமட்டும் புருஷருக்கும் ஸ்திரீகளுக்கும், கேட்டு அறியத்தக்க மற்றவர்களுக்கும் முன்பாக அதை வாசித்தான்; சகல ஜனங்களும் நியாயப்பிரமாண புஸ்தகத்திற்குக் கவனமாய்ச் செவிகொடுத்தார்கள்.", "en": "And he read therein before the street that was before the water gate from the morning until midday, before the men and the women, and those that could understand; and the ears of all the people were attentive unto the book of the law."}, {"verse": 4, "start": 50.35, "end": 76.81, "ta": "வேதபாரகனாகிய எஸ்றா அதற்கென்று மரத்தால் செய்யப்பட்ட ஒரு பிரசங்கபீடத்தின்மேல் நின்றான்; அவனண்டையில் அவனுக்கு வலதுபக்கமாக மத்தித்தியாவும், செமாவும், அனாயாவும், உரியாவும், இல்க்கியாவும் மாசெயாவும், அவனுக்கு இடதுபக்கமாகப் பெதாயாவும், மீசவேலும், மல்கியாவும், அசூமும், அஸ்பதானாவும், சகரியாவும், மெசுல்லாமும் நின்றார்கள்.", "en": "And Ezra the scribe stood upon a pulpit of wood, which they had made for the purpose; and beside him stood Mattithiah, and Shema, and Anaiah, and Urijah, and Hilkiah, and Maaseiah, on his right hand; and on his left hand, Pedaiah, and Mishael, and Malchiah, and Hashum, and Hashbadana, Zechariah, and Meshullam."}, {"verse": 5, "start": 76.81, "end": 88.46, "ta": "எஸ்றா சகல ஜனங்களுக்கும் உயரநின்று, சகல ஜனங்களும் காணப் புஸ்தகத்தைத் திறந்தான்; அவன் அதைத்திறந்தபோது, ஜனங்கள் எல்லாரும் எழுந்துநின்றார்கள்.", "en": "And Ezra opened the book in the sight of all the people; (for he was above all the people;) and when he opened it, all the people stood up:"}, {"verse": 6, "start": 88.46, "end": 106.28, "ta": "அப்பொழுது எஸ்றா மகத்துவமுள்ள தேவனாகிய கர்த்தரை ஸ்தோத்திரித்தான்; ஜனங்களெல்லாரும் தங்கள் கைகளைக் குவித்து, அதற்கு மறுமொழியாக, ஆமென் ஆமென் என்று சொல்லி, குனிந்து, முகங்குப்புறவிழுந்து, கர்த்தரைப் பணிந்துகொண்டார்கள்.", "en": "And Ezra blessed the LORD , the great God. And all the people answered, Amen, Amen, with lifting up their hands: and they bowed their heads, and worshipped the LORD with their faces to the ground."}, {"verse": 7, "start": 106.28, "end": 126.07, "ta": "யெசுவா, பானி, செரெபியா, யாமின், அக்கூப், சபெதாயி, ஒதியா, மாசெயா கேலிதா, அசரியா, யோசபாத், ஆனான், பெலாயா என்பவர்களும், லேவியரும், நியாயப்பிரமாணத்தை ஜனங்களுக்கு விளங்கப்பண்ணினார்கள்; ஜனங்கள் தங்கள் நிலையிலே நின்றார்கள்.", "en": "Also Jeshua, and Bani, and Sherebiah, Jamin, Akkub, Shabbethai, Hodijah, Maaseiah, Kelita, Azariah, Jozabad, Hanan, Pelaiah, and the Levites, caused the people to understand the law: and the people stood in their place."}, {"verse": 8, "start": 126.07, "end": 136.62, "ta": "அவர்கள் தேவனுடைய நியாயப்பிரமாணப் புஸ்தகத்தை தீர்க்கதரிசனமாக வாசித்து, அர்த்தஞ்சொல்லி, வாசித்ததை அவர்களுக்கு விளங்கப்பண்ணினார்கள்.", "en": "So they read in the book in the law of God distinctly, and gave the sense, and caused them to understand the reading."}, {"verse": 9, "start": 136.62, "end": 161.76, "ta": "ஜனங்கள் எல்லாரும் நியாயப்பிரமாணத்தின் வார்த்தைகளைக் கேட்டபோது, அழுதபடியால் திர்ஷாதா என்னப்பட்ட நெகேமியாவும், வேதபாரகனாகிய எஸ்றா என்னும் ஆசாரியனும், ஜனங்களுக்கு விளக்கிக்காட்டின லேவியரும் சகல ஜனங்களையும் நோக்கி: இந்த நாள் உங்கள் தேவனாகிய கர்த்தருக்குப் பரிசுத்தமான நாள்; நீங்கள் துக்கப்படவும் அழவும் வேண்டாம் என்றார்கள்.", "en": "And Nehemiah, which is the Tirshatha, and Ezra the priest the scribe, and the Levites that taught the people, said unto all the people, This day is holy unto the LORD your God; mourn not, nor weep. For all the people wept, when they heard the words of the law."}, {"verse": 10, "start": 161.76, "end": 183.68, "ta": "பின்னும் அவன் அவர்களை நோக்கி: நீங்கள் போய்க் கொழுமையானதைப் புசித்து, மதுரமானதைக் குடித்து, ஒன்றுமில்லாதவர்களுக்குப் பங்குகளை அனுப்புங்கள்; இந்த நாள் நம்முடைய ஆண்டவருக்குப் பரிசுத்தமான நாள், விசாரப்படவேண்டாம்; கர்த்தருக்குள் மகிழ்ச்சியாயிருப்பதே உங்களுடைய பெலன் என்றான்.", "en": "Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our Lord: neither be ye sorry; for the joy of the LORD is your strength."}, {"verse": 11, "start": 183.68, "end": 192.62, "ta": "லேவியரும் ஜனங்களையெல்லாம் அமர்த்தி: அழாதிருங்கள், இந்த நாள் பரிசுத்தமான நாள், விசாரப்படவேண்டாம் என்றார்கள்.", "en": "So the Levites stilled all the people, saying, Hold your peace, for the day is holy; neither be ye grieved."}, {"verse": 12, "start": 192.62, "end": 206.55, "ta": "அப்பொழுது ஜனங்கள் எல்லாரும் தங்களுக்கு அறிவிக்கப்பட்ட வார்த்தைகளை உணர்ந்துகொண்டபடியால், புசித்துக் குடிக்கவும், பங்குகளை அனுப்பவும், மிகுந்த சந்தோஷம் கொண்டாடவும் போனார்கள்.", "en": "And all the people went their way to eat, and to drink, and to send portions, and to make great mirth, because they had understood the words that were declared unto them."}, {"verse": 13, "start": 206.55, "end": 220.11, "ta": "மறுநாளில் ஜனத்தின் சகல வம்சத்தலைவரும், ஆசாரியரும், லேவியரும், நியாயப்பிரமாணத்தின் வார்த்தைகளை அறிந்துகொள்ளவேண்டும் என்று வேதபாரகனாகிய எஸ்றாவினிடத்தில் கூடி வந்தார்கள்.", "en": "And on the second day were gathered together the chief of the fathers of all the people, the priests, and the Levites, unto Ezra the scribe, even to understand the words of the law."}, {"verse": 14, "start": 220.11, "end": 234.77, "ta": "அப்பொழுது நியாயப்பிரமாணத்திலே, இஸ்ரவேல் புத்திரர் ஏழாம் மாதத்தின் பண்டிகையிலே கூடாரங்களில் குடியிருக்கவேண்டும் என்று கர்த்தர் மோசேயைக்கொண்டு கற்பித்த காரியம் எழுதியிருக்கிறதைக் கண்டவர்கள்.", "en": "And they found written in the law which the LORD had commanded by Moses, that the children of Israel should dwell in booths in the feast of the seventh month:"}, {"verse": 15, "start": 234.77, "end": 258.82, "ta": "ஆகையால் எழுதியிருக்கிறபடி கூடாரங்களைப் போடும்படிக்கு நீங்கள் மலைகளுக்குப் புறப்பட்டுப்போய் ஒலிவக்கிளைகளையும், காட்டு ஒலிவக்கிளைகளையும், மிருதுச் செடிகளின் கிளைகளையும் பேரீச்ச மட்டைகளையும், அடர்ந்தமரக்கிளைகளையும் கொண்டுவாருங்களென்று தங்களுடைய சகல பட்டணங்களிலும், எருசலேமிலும் கூறிப் பிரசித்தப்படுத்தினார்கள்.", "en": "And that they should publish and proclaim in all their cities, and in Jerusalem, saying, Go forth unto the mount, and fetch olive branches, and pine branches, and myrtle branches, and palm branches, and branches of thick trees, to make booths, as it is written."}, {"verse": 16, "start": 258.82, "end": 276.99, "ta": "அப்படியே ஜனங்கள் வெளியேபோய் அவைகளைக் கொண்டுவந்து, அவரவர் தங்கள் வீடுகள்மேலும், தங்கள் முற்றங்களிலும், தேவனுடைய ஆலயப்பிராகாரங்களிலும், தண்ணீர்வாசல் வீதியிலும், எப்பிராயீம் வாசல் வீதியிலும் தங்களுக்குக் கூடாரங்களை போட்டார்கள்.", "en": "So the people went forth, and brought them , and made themselves booths, every one upon the roof of his house, and in their courts, and in the courts of the house of God, and in the street of the water gate, and in the street of the gate of Ephraim."}, {"verse": 17, "start": 276.99, "end": 299.42, "ta": "இந்தப்பிரகாரமாகச் சிறையிருப்பிலிருந்து திரும்பி வந்தவர்களின் சபையார் எல்லாரும் கூடாரங்களைப்போட்டு, கூடாரங்களில் குடியிருந்தார்கள்; இப்படியே நூனின் குமாரனாகிய யோசுவாவின் நாட்கள்முதல் அந்நாள்மட்டும் இஸ்ரவேல் புத்திரர் செய்யாதிருந்து இப்பொழுது செய்தபடியால், மிகுந்த சந்தோஷமுண்டாயிருந்தது.", "en": "And all the congregation of them that were come again out of the captivity made booths, and sat under the booths: for since the days of Jeshua the son of Nun unto that day had not the children of Israel done so. And there was very great gladness."}, {"verse": 18, "start": 299.42, "end": 316.21, "ta": "முதலாம் நாள் தொடங்கிக் கடைசிநாள்மட்டும், தினம்தினம் தேவனுடைய நியாயப்பிரமாண புஸ்தகம் வாசிக்கப்பட்டது; ஏழுநாள் பண்டிகையை ஆசரித்தார்கள்; எட்டாம்நாளோவெனில், முறைமையின்படியே விசேஷித்த ஆசரிப்பு நாளாயிருந்தது.", "en": "Also day by day, from the first day unto the last day, he read in the book of the law of God. And they kept the feast seven days; and on the eighth day was a solemn assembly, according unto the manner."}]}, "9": {"chapter": 9, "duration": 660.34, "audio_url": "audio_ot/OT16_09.mp3", "total_verses": 38, "verses": [{"verse": 1, "start": 3.8, "end": 15.08, "ta": "அந்த மாதம் இருபத்துநாலாந்தேதியிலே இஸ்ரவேல் புத்திரர் உபவாசம்பண்ணி, இரட்டுடுத்தி, தங்கள்மேல் புழுதியைப் போட்டுக்கொண்டவர்களாய்க் கூடிவந்தார்கள்.", "en": "Now in the twenty and fourth day of this month the children of Israel were assembled with fasting, and with sackclothes, and earth upon them."}, {"verse": 2, "start": 15.08, "end": 26.21, "ta": "இஸ்ரவேல் சந்ததியார் மறு ஜாதியாரையெல்லொம் விட்டுப்பிரிந்து வந்து நின்று தங்கள் பாவங்களையும் தங்கள் பிதாக்களின் அக்கிரமங்களையும் அறிக்கையிட்டார்கள்.", "en": "And the seed of Israel separated themselves from all strangers, and stood and confessed their sins, and the iniquities of their fathers."}, {"verse": 3, "start": 26.21, "end": 45.75, "ta": "அவர்கள் எழுந்திருந்து, தங்கள் நிலையில் நின்றார்கள்; அப்பொழுது ஒரு ஜாமமட்டும் அவர்களுடைய தேவனாகிய கர்த்தரின் நியாயப்பிரமாணப் புஸ்தகம் வாசிக்கப்பட்டது; பின்பு ஒரு ஜாமமட்டும் அவர்கள் பாவ அறிக்கை பண்ணி, தங்கள் தேவனாகிய கர்த்தரைப் பணிந்துகொண்டார்கள்.", "en": "And they stood up in their place, and read in the book of the law of the LORD their God one fourth part of the day; and another fourth part they confessed, and worshipped the LORD their God."}, {"verse": 4, "start": 45.75, "end": 59.04, "ta": "யெசுவா, பானி கத்மியேல் செப்பனியா, புன்னி, செரெபியா பானி, கெனானி என்பவர்கள் லேவியருடையபடிகளின்மேல் நின்று தங்கள் தேவனாகிய கர்த்தரை நோக்கி மகா சத்தமாய் ஓலமிட்டார்கள்.", "en": "Then stood up upon the stairs, of the Levites, Jeshua, and Bani, Kadmiel, Shebaniah, Bunni, Sherebiah, Bani, and Chenani, and cried with a loud voice unto the LORD their God."}, {"verse": 5, "start": 59.04, "end": 85.98, "ta": "பின்பு லேவியரான யெசுவா, கத்மியேல், பானி, ஆசாப்நெயா, செரெபியா, ஒதியா, செபனியா, பெத்தகியா என்பவர்கள் ஜனங்களைப் பார்த்து: நீங்கள் எழுந்திருந்து, அநாதியாய் என்றென்றைக்குமிருக்கிற உங்கள் தேவனாகிய கர்த்தரை ஸ்தோத்திரியுங்கள் என்று சொல்லி, கர்த்தரை நோக்கி: எந்த ஸ்துதி ஸ்தோத்திரத்துக்கும் மேலான உம்முடைய மகிமையுள்ள நாமத்துக்கு ஸ்தோத்திரமுண்டாவதாக.", "en": "Then the Levites, Jeshua, and Kadmiel, Bani, Hashabniah, Sherebiah, Hodijah, Shebaniah, and Pethahiah, said, Stand up and bless the LORD your God for ever and ever: and blessed be thy glorious name, which is exalted above all blessing and praise."}, {"verse": 6, "start": 85.98, "end": 107.31, "ta": "நீர் ஒருவரே கர்த்தர்; நீர் வானங்களையும், வானாதி வானங்களையும், அவைகளுடைய சர்வ சேனைகளையும் பூமியையும் அதிலுள்ள எல்லாவற்றையும், சமுத்திரங்களையும் அவைகளிலுள்ள எல்லாவற்றையும் உண்டாக்கினீர்; அவைகளையெல்லாம் நீர் காப்பாற்றுகிறீர்; வானசேனைகள் உம்மைப் பணிந்துகொள்ளுகிறது.", "en": "Thou, even thou, art LORD alone; thou hast made heaven, the heaven of heavens, with all their host, the earth, and all things that are therein, the seas, and all that is therein, and thou preservest them all; and the host of heaven worshippeth thee."}, {"verse": 7, "start": 107.31, "end": 118.8, "ta": "ஆபிராமைத் தெரிந்துகொண்டு, அவனை ஊர் என்னும் கல்தேயரின் பட்டணத்திலிருந்து புறப்படப்பண்ணி, அவனுக்கு ஆபிரகாம் என்னும் பேரிட்ட தேவனாகிய கர்த்தர் நீர்.", "en": "Thou art the LORD the God, who didst choose Abram, and broughtest him forth out of Ur of the Chaldees, and gavest him the name of Abraham;"}, {"verse": 8, "start": 118.8, "end": 138.56, "ta": "அவன் இருதயத்தை உமக்கு முன்பாக உண்மையுள்ளதாகக்கண்டு, கானானியர் ஏத்தியர், எமோரியர், பெரிசியர், எபூசியர், கிர்காசியருடைய தேசத்தை அவன் சந்ததிக்குக் கொடுக்கும்படி, அவனோடு உடன்படிக்கைபண்ணி, உம்முடைய வார்த்தைகளை நிறைவேற்றினீர்; நீர் நீதியுள்ளவர்.", "en": "And foundest his heart faithful before thee, and madest a covenant with him to give the land of the Canaanites, the Hittites, the Amorites, and the Perizzites, and the Jebusites, and the Girgashites, to give it, I say , to his seed, and hast performed thy words; for thou art righteous:"}, {"verse": 9, "start": 138.56, "end": 147.32, "ta": "எகிப்திலே எங்கள் பிதாக்கள் அநுபவித்த சிறுமையை நீர் கண்டு, சிவந்த சமுத்திரத்தில் அவர்கள் கூப்பிடுதலைக்கேட்டீர்.", "en": "And didst see the affliction of our fathers in Egypt, and heardest their cry by the Red sea;"}, {"verse": 10, "start": 147.32, "end": 169.37, "ta": "பார்வோனிடத்திலும், அவனுடைய எல்லா ஊழியக்காரரிடத்திலும், அவன் தேசத்தின் சகல ஜனத்தினிடத்திலும், அடையாளங்களையும் அற்புதங்களையும் செய்தீர்; அவர்கள் உமது ஜனங்களை அகந்தையாய் நடத்தினார்கள் என்பதை அறிந்திருந்தீர்; இப்படியே இந்நாள்வரைக்கும் இருக்கிறபடி உமக்குக் கீர்த்தியை உண்டாக்கினீர்.", "en": "And shewedst signs and wonders upon Pharaoh, and on all his servants, and on all the people of his land: for thou knewest that they dealt proudly against them. So didst thou get thee a name, as it is this day."}, {"verse": 11, "start": 169.37, "end": 184.53, "ta": "நீர் அவர்களுக்கு முன்பாகச் சமுத்திரத்தைப் பிரித்ததினால், கடலின் நடுவாகக் கால்நனையாமல் நடந்தார்கள்; வலுவான தண்ணீர்களிலே கல்லைப்போடுகிறதுபோல, அவர்களைத் தொடர்ந்தவர்களை ஆழங்களிலே போட்டுவிட்டீர்.", "en": "And thou didst divide the sea before them, so that they went through the midst of the sea on the dry land; and their persecutors thou threwest into the deeps, as a stone into the mighty waters."}, {"verse": 12, "start": 184.53, "end": 195.38, "ta": "நீர் பகலிலே மேகஸ்தம்பத்தினாலும் அவர்கள் நடக்கவேண்டிய வழியை அவர்களுக்கு வெளிச்சமாக்க இரவிலே அக்கினி ஸ்தம்பத்தினாலும், அவர்களை வழிநடத்தினீர்.", "en": "Moreover thou leddest them in the day by a cloudy pillar; and in the night by a pillar of fire, to give them light in the way wherein they should go."}, {"verse": 13, "start": 195.38, "end": 208.59, "ta": "நீர் சீனாய் மலையிலிறங்கி வானத்திலிருந்து அவர்களோடே பேசி, அவர்களுக்குச் செம்மையான நீதிநியாயங்களையும், நல்ல கட்டளைகளும் கற்பனைகளுமாகிய உண்மையான பிரமாணங்களையும் கொடுத்தீர்.", "en": "Thou camest down also upon mount Sinai, and spakest with them from heaven, and gavest them right judgments, and true laws, good statutes and commandments:"}, {"verse": 14, "start": 208.59, "end": 221.52, "ta": "உமது பரிசுத்த ஓய்வுநாளை அவர்களுக்குத் தெரியப்படுத்தி, உமது தாசனாகிய மோசேயைக்கொண்டு, அவர்களுக்குக் கற்பனைகளையும், கட்டளைகளையும் நியாயப்பிரமாணங்களையும் கற்பித்தீர்.", "en": "And madest known unto them thy holy sabbath, and commandedst them precepts, statutes, and laws, by the hand of Moses thy servant:"}, {"verse": 15, "start": 221.52, "end": 239.34, "ta": "அவர்கள் பசிக்கு வானத்திலிருந்து அப்பம் கொடுத்து, அவர்கள் தாகத்துக்குக் கன்மலையிலிருந்து தண்ணீர் புறப்படப்பண்ணி, நீர் அவர்களுக்குக் கொடுப்பேன் என்று ஆணையிட்ட தேசத்தைச் சுதந்தரித்துக்கொள்ளப் பிரவேசியுங்கள் என்று அவர்களுக்குச் சொன்னீர்.", "en": "And gavest them bread from heaven for their hunger, and broughtest forth water for them out of the rock for their thirst, and promisedst them that they should go in to possess the land which thou hadst sworn to give them."}, {"verse": 16, "start": 239.34, "end": 249.4, "ta": "எங்கள் பிதாக்களாகிய அவர்களோ அகங்காரமாய் நடந்து, தங்கள் கழுத்தைக் கடினப்படுத்தி, உம்முடைய கற்பனைகளுக்குச் செவிகொடாதேபோனார்கள்.", "en": "But they and our fathers dealt proudly, and hardened their necks, and hearkened not to thy commandments,"}, {"verse": 17, "start": 249.4, "end": 277.7, "ta": "அவர்கள் செவிகொடுக்க மனதில்லாமலும், அவர்களிடத்திலே நீர் செய்த உம்முடைய அற்புதங்களை நினையாமலும் போய், தங்கள் கழுத்தைக் கடினப்படுத்தி, தங்கள் அடிமைத்தனத்துக்குத் திரும்பும்படிக்கு அவர்கள் கலகம்பண்ணி, ஒரு தலைவனை ஏற்படுத்தினார்கள்; ஆகிலும் வெகுவாய் மன்னிக்கிறவரும் இரக்கமும் மனஉருக்கமும், நீடிய சாந்தமும், மகா கிருபையுமுள்ளவருமான தேவனாகிய நீர் அவர்களைக் கைவிடவில்லை.", "en": "And refused to obey, neither were mindful of thy wonders that thou didst among them; but hardened their necks, and in their rebellion appointed a captain to return to their bondage: but thou art a God ready to pardon, gracious and merciful, slow to anger, and of great kindness, and forsookest them not."}, {"verse": 18, "start": 277.7, "end": 291.49, "ta": "அவர்கள் வார்ப்பிக்கப்பட்ட ஒரு கன்றுக்குட்டியைத் தங்களுக்கு உண்டாக்கி: இது உன்னை எகிப்திலிருந்து கொண்டுவந்த உன் தெய்வம் என்று சொல்லி, கோபமூட்டத்தக்க பெரிய அக்கிரமங்களைச் செய்திருந்தாலும்,", "en": "Yea, when they had made them a molten calf, and said, This is thy God that brought thee up out of Egypt, and had wrought great provocations;"}, {"verse": 19, "start": 291.49, "end": 310.31, "ta": "நீர் உம்முடைய மிகுந்த மன உருக்கத்தின்படியே, அவர்களை வனாந்தரத்திலே கைவிடவில்லை; அவர்களை வழிநடத்தப் பகலிலே மேகஸ்தம்பமும், அவர்களுக்கு வெளிச்சத்தையும் அவர்கள் நடக்கவேண்டிய வழியையும் காட்ட இரவிலே அக்கினி ஸ்தம்பமும், அவர்களை விட்டு விலகவில்லை.", "en": "Yet thou in thy manifold mercies forsookest them not in the wilderness: the pillar of the cloud departed not from them by day, to lead them in the way; neither the pillar of fire by night, to shew them light, and the way wherein they should go."}, {"verse": 20, "start": 310.31, "end": 322.02, "ta": "அவர்களுக்கு அறிவை உணர்த்த உம்முடைய நல்ல ஆவியைக் கட்டளையிட்டீர், அவர்கள் வாய்க்கு உம்முடைய மன்னாவை அருளி, அவர்கள் தாகத்துக்குத் தண்ணீரைக் கொடுத்தீர்.", "en": "Thou gavest also thy good spirit to instruct them, and withheldest not thy manna from their mouth, and gavest them water for their thirst."}, {"verse": 21, "start": 322.02, "end": 336.03, "ta": "இப்படி நாற்பது வருஷமாக வனாந்தரத்தில் அவர்களுக்கு ஒன்றும் குறைவுபடாதபடிக்கு அவர்களைப் பராமரித்துவந்தீர்; அவர்கள் வஸ்திரங்கள் பழமையாய்ப்போகவுமில்லை, அவர்கள் கால்கள் வீங்கவுமில்லை.", "en": "Yea, forty years didst thou sustain them in the wilderness, so that they lacked nothing; their clothes waxed not old, and their feet swelled not."}, {"verse": 22, "start": 336.03, "end": 351.83, "ta": "அவர்களுக்கு ராஜ்யங்களையும் ஜனங்களையும் ஒப்புக்கொடுத்து, அவைகளை எல்லை எல்லையாக அவர்களுக்குப் பங்கிட்டீர்; எஸ்போனின் ராஜாவாகிய சீகோனின் தேசத்தையும் பாசானின் ராஜாவாகிய ஓகின் தேசத்தையும் கட்டிக்கொண்டார்கள்.", "en": "Moreover thou gavest them kingdoms and nations, and didst divide them into corners: so they possessed the land of Sihon, and the land of the king of Heshbon, and the land of Og king of Bashan."}, {"verse": 23, "start": 351.83, "end": 363.97, "ta": "அவர்கள் பிள்ளைகளை வானத்து நட்சத்திரங்களைப்போலப் பெருகப்பண்ணி, சுதந்தரித்துக்கொள்ளும்படி நீர் அவர்கள் பிதாக்களுக்குச் சொன்ன தேசத்திலே அவர்களை அழைத்து வந்தீர்.", "en": "Their children also multipliedst thou as the stars of heaven, and broughtest them into the land, concerning which thou hadst promised to their fathers, that they should go in to possess it ."}, {"verse": 24, "start": 363.97, "end": 384.58, "ta": "அப்படியே பிள்ளைகள் உட்பிரவேசித்து, தேசத்தைச் சுதந்தரித்துக்கொண்டார்கள்; நீர் அவர்களுக்கு முன்பாகத் தேசத்தின் குடிகளாகிய கானானியரைத் தாழ்த்தி, அவர்களையும் அவர்கள் ராஜாக்களையும், தேசத்தின் ஜனங்களையும், தங்கள் இஷ்டப்படி செய்ய, அவர்கள் கையிலே ஒப்புக்கொடுத்தீர்.", "en": "So the children went in and possessed the land, and thou subduedst before them the inhabitants of the land, the Canaanites, and gavest them into their hands, with their kings, and the people of the land, that they might do with them as they would."}, {"verse": 25, "start": 384.58, "end": 409.08, "ta": "அவர்கள் அரணான பட்டணங்களையும், செழுமையான பூமியையும் கட்டிக்கொண்டு, சகலவித உடமைகள் நிறைந்த வீடுகளையும், வெட்டப்பட்ட துரவுகளையும் ஏராளமான திராட்சத்தோட்டங்களையும் ஒலிவத்தோப்புகளையும், கனிகொடுக்கும் விருட்சங்களையும் சுதந்தரித்துக்கொண்டு புசித்துத் திருப்தியாகிக் கொழுத்து, உம்முடைய பெரிய தயையினால் செல்வமாய் வாழ்ந்தார்கள்.", "en": "And they took strong cities, and a fat land, and possessed houses full of all goods, wells digged, vineyards, and oliveyards, and fruit trees in abundance: so they did eat, and were filled, and became fat, and delighted themselves in thy great goodness."}, {"verse": 26, "start": 409.08, "end": 431.27, "ta": "ஆனாலும் அவர்கள் கீழ்ப்படியாதவர்களாகி உமக்கு விரோதமாய்க் கலகம்பண்ணி, உம்முடைய நியாயப்பிரமாணத்தை தங்களுக்குப் புறம்பே எறிந்துவிட்டு, தங்களை உம்மிடத்தில் திருப்பும்படி அவர்களைத் திடசாட்சியாய்க் கடிந்துகொண்ட உம்முடைய தீர்க்கதரிசிகளைக் கொன்றுபோட்டு, கோபமூட்டுகிற பெரிய அக்கிரமங்களைச் செய்தார்கள்.", "en": "Nevertheless they were disobedient, and rebelled against thee, and cast thy law behind their backs, and slew thy prophets which testified against them to turn them to thee, and they wrought great provocations."}, {"verse": 27, "start": 431.27, "end": 455.2, "ta": "ஆகையால் அவர்களை நெருக்குகிற அவர்கள் சத்துருக்களின் கையில் அவர்களை ஒப்புக்கொடுத்தீர்; அவர்கள் நெருக்கம் அநுபவிக்கிற காலத்தில் அவர்கள் உம்மை நோக்கிக் கூப்பிடுகிறபோதோ, நீர் பரலோகத்திலிருந்து கேட்டு உம்முடைய மிகுந்த இரக்கத்தினால் அவர்களை அவர்கள் சத்துருக்களுக்கு நீங்கலாக்கிவிடுகிற இரட்சகர்களை அவர்களுக்குக் கொடுத்தீர்.", "en": "Therefore thou deliveredst them into the hand of their enemies, who vexed them: and in the time of their trouble, when they cried unto thee, thou heardest them from heaven; and according to thy manifold mercies thou gavest them saviours, who saved them out of the hand of their enemies."}, {"verse": 28, "start": 455.2, "end": 481.27, "ta": "அவர்களுக்கு இளைப்பாறுதல் உண்டானபோதோ, உமக்கு முன்பாக மறுபடியும் பொல்லாப்புச் செய்யத்தொடங்கினார்கள்; ஆகையால் அவர்கள் சத்துருக்கள் அவர்களை ஆளும்படிக்கு அவர்கள் கையிலே ஒப்புவித்தீர்; அவர்கள் மனந்திரும்பி உம்மை நோக்கிக் கூப்பிட்டபோதோ, நீர் பரலோகத்திலிருந்து கேட்டு, அவர்களை உம்முடைய இரக்கங்களின்படியே அநேகந்தரம், விடுதலையாக்கிவிட்டீர்.", "en": "But after they had rest, they did evil again before thee: therefore leftest thou them in the hand of their enemies, so that they had the dominion over them: yet when they returned, and cried unto thee, thou heardest them from heaven; and many times didst thou deliver them according to thy mercies;"}, {"verse": 29, "start": 481.27, "end": 507.92, "ta": "அவர்களை உம்முடைய நியாயப்பிரமாணத்துக்குத் திருப்ப அவர்களைத் திடசாட்சியாய்க் கடிந்துகொண்டீர்; அவர்கள் அகங்காரங் கொண்டு, உம்முடைய கற்பனைகளுக்குச் செவிகொடாமல் கீழ்ப்படிந்து நடக்கிற மனுஷன் செய்து பிழைக்கிற உம்முடைய நீதி நியாயங்களுக்கு விரோதமாகப் பாவஞ்செய்து, தங்கள் தோளை முரண்டுத்தனமாய் விலக்கி, செவிகொடாமல் தங்கள் கழுத்தைக் கடினப்படுத்திக்கொண்டார்கள்.", "en": "And testifiedst against them, that thou mightest bring them again unto thy law: yet they dealt proudly, and hearkened not unto thy commandments, but sinned against thy judgments, (which if a man do, he shall live in them;) and withdrew the shoulder, and hardened their neck, and would not hear."}, {"verse": 30, "start": 507.92, "end": 525.88, "ta": "நீர் அநேக வருஷமாக அவர்கள்மேல் பொறுமையாயிருந்து, உம்முடைய ஆவியினால் பேசின உம்முடைய தீர்க்கதரிசிகளைக்கொண்டு அவர்களைத் திடசாட்சியாய்க் கடிந்துகொண்டாலும், அவர்கள் செவிகொடாதபடியினாலே, அவர்களை அந்நிய தேசஜனங்களின் கையில் ஒப்புக்கொடுத்தீர்.", "en": "Yet many years didst thou forbear them, and testifiedst against them by thy spirit in thy prophets: yet would they not give ear: therefore gavest thou them into the hand of the people of the lands."}, {"verse": 31, "start": 525.88, "end": 537.16, "ta": "ஆகிலும் உம்முடைய மிகுந்த இரக்கங்களின்படியே, அவர்களை நிர்மூலமாக்காமலும் அவர்களைக் கைவிடாமலும் இருந்தீர்; நீர் கிருபையும் இரக்கமுமுள்ள தேவன்.", "en": "Nevertheless for thy great mercies’ sake thou didst not utterly consume them, nor forsake them; for thou art a gracious and merciful God."}, {"verse": 32, "start": 537.16, "end": 567.25, "ta": "இப்பொழுதும் உடன்படிக்கையையும் கிருபையையும் காக்கிற வல்லமையும் பயங்கரமுமுள்ள மகா தேவனாகிய எங்கள் தேவனே, அசீரியா ராஜாக்களின் நாட்கள் முதற்கொண்டு இந்நாள்வரைக்கும் எங்களுக்கும் எங்கள் ராஜாக்களுக்கும், எங்கள் பிரபுக்களுக்கும், எங்கள் ஆசாரியர்களுக்கும் எங்கள் தீர்க்கதரிசிகளுக்கும், எங்கள் பிதாக்களுக்கும் உம்முடைய ஜனங்கள் அனைவருக்கும் நேரிட்ட சகல வருத்தமும் உமக்கு முன்பாக அற்பமாய்க் காணப்படாதிருப்பதாக.", "en": "Now therefore, our God, the great, the mighty, and the terrible God, who keepest covenant and mercy, let not all the trouble seem little before thee, that hath come upon us, on our kings, on our princes, and on our priests, and on our prophets, and on our fathers, and on all thy people, since the time of the kings of Assyria unto this day."}, {"verse": 33, "start": 567.25, "end": 577.02, "ta": "எங்களுக்கு நேரிடப்பண்ணின எல்லாவற்றிலும் நீர் நீதியுள்ளவர்; நீர் உண்மையாய் நடப்பித்தீர்; நாங்களோ ஆகாமியம் பண்ணினோம்.", "en": "Howbeit thou art just in all that is brought upon us; for thou hast done right, but we have done wickedly:"}, {"verse": 34, "start": 577.02, "end": 594.19, "ta": "எங்கள் ராஜாக்களும், எங்கள் பிரபுக்களும், எங்கள் ஆசாரியர்களும் எங்கள் பிதாக்களும் உம்முடைய நியாயப்பிரமாணத்தின்படி செய்யாமலும், உம்முடைய கற்பனைகளையும் நீர் அவர்களைக் கடிந்துகொண்ட உம்முடைய சாட்சிகளையும் கவனியாமலும்போனார்கள்.", "en": "Neither have our kings, our princes, our priests, nor our fathers, kept thy law, nor hearkened unto thy commandments and thy testimonies, wherewith thou didst testify against them."}, {"verse": 35, "start": 594.19, "end": 612.65, "ta": "அவர்கள் தங்கள் ராஜ்யத்திலும், நீர் அவர்களுக்குக் கொடுத்த உம்முடைய பெரிய தயையிலும், நீர் அவர்களுக்கு முன்பாகத் திறந்துவைத்த விசாலமும் செழிப்புமான தேசத்திலும் உமக்கு ஊழியஞ்செய்யாமலும், தங்கள் துர்க்கருமங்களை விட்டுத் திரும்பாமலும் போனார்கள்.", "en": "For they have not served thee in their kingdom, and in thy great goodness that thou gavest them, and in the large and fat land which thou gavest before them, neither turned they from their wicked works."}, {"verse": 36, "start": 612.65, "end": 626.23, "ta": "இதோ, இன்றையதினம் நாங்கள் அடிமைகளாயிருக்கிறோம், இதோ பலனையும் நன்மையையும் அனுபவிக்கும்படி நீர் எங்கள் பிதாக்களுக்குக் கொடுத்த இந்தத் தேசத்தில்தானே நாங்கள் அடிமைகளாயிருக்கிறோம்.", "en": "Behold, we are servants this day, and for the land that thou gavest unto our fathers to eat the fruit thereof and the good thereof, behold, we are servants in it:"}, {"verse": 37, "start": 626.23, "end": 644.33, "ta": "அதின் வருமானம் எங்கள் பாவங்களினிமித்தம் நீர் எங்கள்மேல் வைத்த ராஜாக்களுக்குத் திரளாகப்போகிறது; அவர்கள் தங்களுக்கு இஷ்டமானபடியே எங்கள் சரீரங்களையும் எங்கள் மிருக ஜீவன்களையும் ஆளுகிறார்கள்; நாங்கள் மகா இக்கட்டில் அகப்பட்டிருக்கிறோம்.", "en": "And it yieldeth much increase unto the kings whom thou hast set over us because of our sins: also they have dominion over our bodies, and over our cattle, at their pleasure, and we are in great distress."}, {"verse": 38, "start": 644.33, "end": 658.84, "ta": "இவையெல்லாம் இப்படி இருக்கிறபடியால் நாங்கள் உறுதியான உடன்படிக்கைபண்ணி அதை எழுதிவைக்கிறோம்; எங்கள் பிரபுக்களும் எங்கள் லேவியரும், எங்கள் ஆசாரியரும் அதற்கு முத்திரைபோடுவார்கள் என்றார்கள்.", "en": "And because of all this we make a sure covenant , and write it; and our princes, Levites, and priests, seal unto it ."}]}, "10": {"chapter": 10, "duration": 349.74, "audio_url": "audio_ot/OT16_10.mp3", "total_verses": 39, "verses": [{"verse": 1, "start": 3.8, "end": 11.44, "ta": "முத்திரைபோட்டவர்கள் யாரென்றால்: அகலியாவின் குமாரனாகிய திர்ஷாதா என்னும் நெகேமியா, சிதேகியா,", "en": "Now those that sealed were , Nehemiah, the Tirshatha, the son of Hachaliah, and Zidkijah,"}, {"verse": 2, "start": 11.44, "end": 14.07, "ta": "செராயா, அசரியா, எரேமியா,", "en": "Seraiah, Azariah, Jeremiah,"}, {"verse": 3, "start": 14.07, "end": 16.45, "ta": "பஸ்கூர் அமரியா, மல்கிஜா,", "en": "Pashur, Amariah, Malchijah,"}, {"verse": 4, "start": 16.45, "end": 19.32, "ta": "அத்தூஸ், செபனியா, மல்லுூக்,", "en": "Hattush, Shebaniah, Malluch,"}, {"verse": 5, "start": 19.32, "end": 21.95, "ta": "ஆரீம், மெரெமோத், ஒபதியா,", "en": "Harim, Meremoth, Obadiah,"}, {"verse": 6, "start": 21.95, "end": 24.81, "ta": "தானியேல், கிநேதோன், பாருக்,", "en": "Daniel, Ginnethon, Baruch,"}, {"verse": 7, "start": 24.81, "end": 27.75, "ta": "மெசுல்லாம், அபியா, மீயாமின்,", "en": "Meshullam, Abijah, Mijamin,"}, {"verse": 8, "start": 27.75, "end": 32.21, "ta": "மாசியா, பில்காய், செமாயா என்னும் ஆசாரியர்களும்,", "en": "Maaziah, Bilgai, Shemaiah: these were the priests."}, {"verse": 9, "start": 32.21, "end": 40.97, "ta": "லேவியராகிய அசனியாவின் குமாரன் யெசுவா, எனாதாதின் குமாரரில் ஒருவனாகிய பின்னூயி, கத்மியேல் என்பவர்களும்,", "en": "And the Levites: both Jeshua the son of Azaniah, Binnui of the sons of Henadad, Kadmiel;"}, {"verse": 10, "start": 40.97, "end": 46.7, "ta": "அவர்கள் சகோதரராகிய செபனியா, ஒதியா, கேலிதா, பெலாயா, ஆனான்,", "en": "And their brethren, Shebaniah, Hodijah, Kelita, Pelaiah, Hanan,"}, {"verse": 11, "start": 46.7, "end": 49.08, "ta": "மீகா, ரேகோப், அசபியா,", "en": "Micha, Rehob, Hashabiah,"}, {"verse": 12, "start": 49.08, "end": 51.95, "ta": "சக்கூர், செரெபியா, செபனியா,", "en": "Zaccur, Sherebiah, Shebaniah,"}, {"verse": 13, "start": 51.95, "end": 55.29, "ta": "ஒதியா, பானி, பெனினு என்பவர்களும்,", "en": "Hodijah, Bani, Beninu."}, {"verse": 14, "start": 55.29, "end": 61.26, "ta": "ஜனத்தின் தலைவராகிய பாரோஷ், பாகாத்மோவாப், ஏலாம், சத்தூ, பானி,", "en": "The chief of the people; Parosh, Pahath-moab, Elam, Zatthu, Bani,"}, {"verse": 15, "start": 61.26, "end": 63.89, "ta": "புன்னி, அஸ்காத், பெபாயி,", "en": "Bunni, Azgad, Bebai,"}, {"verse": 16, "start": 63.89, "end": 66.59, "ta": "அதோனியா, பிக்வாய், ஆதின்,", "en": "Adonijah, Bigvai, Adin,"}, {"verse": 17, "start": 66.59, "end": 69.06, "ta": "ஆதேர், இஸ்கியா, அசூர்,", "en": "Ater, Hizkijah, Azzur,"}, {"verse": 18, "start": 69.06, "end": 71.45, "ta": "ஒதியா, ஆசூ, பெத்சாய்,", "en": "Hodijah, Hashum, Bezai,"}, {"verse": 19, "start": 71.45, "end": 73.91, "ta": "ஆரீப், ஆனதோத், நெபாய்,", "en": "Hariph, Anathoth, Nebai,"}, {"verse": 20, "start": 73.91, "end": 76.94, "ta": "மக்பியாஸ், மெசுல்லாம், ஏசீர்,", "en": "Magpiash, Meshullam, Hezir,"}, {"verse": 21, "start": 76.94, "end": 79.88, "ta": "மெஷெசாபெயேல், சாதோக், யதுவா,", "en": "Meshezabeel, Zadok, Jaddua,"}, {"verse": 22, "start": 79.88, "end": 82.51, "ta": "பெலத்தியா, ஆனான், ஆனாயா,", "en": "Pelatiah, Hanan, Anaiah,"}, {"verse": 23, "start": 82.51, "end": 84.9, "ta": "ஓசெயா, அனனியா, அசூப்,", "en": "Hoshea, Hananiah, Hashub,"}, {"verse": 24, "start": 84.9, "end": 87.6, "ta": "அல்லோகேஸ், பிலகா, சோபேக்,", "en": "Hallohesh, Pileha, Shobek,"}, {"verse": 25, "start": 87.6, "end": 90.07, "ta": "ரேகூம், அஷபனா, மாசெயா,", "en": "Rehum, Hashabnah, Maaseiah,"}, {"verse": 26, "start": 90.07, "end": 92.46, "ta": "அகியா, கானான், ஆனான்,", "en": "And Ahijah, Hanan, Anan,"}, {"verse": 27, "start": 92.46, "end": 96.44, "ta": "மல்லுூக், ஆரிம், பானா என்பவர்களுமே.", "en": "Malluch, Harim, Baanah."}, {"verse": 28, "start": 96.44, "end": 120.47, "ta": "ஜனங்களில் மற்றவர்களாகிய ஆசாரியரும், லேவியரும் வாசல் காவலாளரும், பாடகரும், நிதனீமியரும், தேசங்களின் ஜனங்களைவிட்டுப் பிரிந்து விலகி தேவனுடைய நியாயப்பிரமாணத்துக்குத் திரும்பின அனைவரும் அவர்கள் மனைவிகளும், அவர்கள் குமாரரும் அவர்கள் குமாரத்திகளுΠξகிய அறிவும் Ϊுத்தியும் உள͠γவர்களெல்லாரும்,", "en": "And the rest of the people, the priests, the Levites, the porters, the singers, the Nethinims, and all they that had separated themselves from the people of the lands unto the law of God, their wives, their sons, and their daughters, every one having knowledge, and having understanding;"}, {"verse": 29, "start": 120.47, "end": 144.66, "ta": "தங்களுக்குப் பெரியவர்களாகிய தங்கள் சகோதரரோடே கூடிக்கொண்டு: தேவனுடைய தாசனாகிய மோசேயைக்கொண்டு கொடுக்கப்பட்ட தேவனுடைய நியாயப்பிரமாணத்தின்படி நடந்துகொள்வோம் என்றும், எங்கள் ஆண்டவராகிய கர்த்தரின் கற்பனைகளையும் சகல நீதிநியாயங்களையும், கட்டளைகளையும் எல்லாம் கைக்கொண்டு, அவைகளின்படி செய்வோம் என்றும்,", "en": "They clave to their brethren, their nobles, and entered into a curse, and into an oath, to walk in God’s law, which was given by Moses the servant of God, and to observe and do all the commandments of the LORD our Lord, and his judgments and his statutes;"}, {"verse": 30, "start": 144.66, "end": 155.89, "ta": "நாங்கள் எங்கள் குமாரத்திகளை தேசத்தின் ஜனங்களுக்குக் கொடாமலும், எங்கள் குமாரருக்கு அவர்கள் குமாரத்திகளைக் கொள்ளாமலும் இருப்போம் என்றும்,", "en": "And that we would not give our daughters unto the people of the land, nor take their daughters for our sons:"}, {"verse": 31, "start": 155.89, "end": 181.35, "ta": "தேசத்தின் ஜனங்கள் ஓய்வுநாளிலே சரக்குகளையும், எந்தவிதத் தானியதவசத்தையும் விற்கிறதற்குக் கொண்டுவந்தால், நாங்கள் அதை ஓய்வுநாளிலும் பரிசுத்தநாளிலும் அவர்கள் கையில் கொள்ளாதிருப்போம் என்றும், நாங்கள் ஏழாம் வருஷத்தை விடுதலை வருஷமாக்கிச் சகல கடன்களையும் விட்டுவிடுவோம் என்றும் ஆணையிட்டுப் பிரமாணம்பண்ணினார்கள்.", "en": "And if the people of the land bring ware or any victuals on the sabbath day to sell, that we would not buy it of them on the sabbath, or on the holy day: and that we would leave the seventh year, and the exaction of every debt."}, {"verse": 32, "start": 181.35, "end": 204.59, "ta": "மேலும்: நாங்கள் எங்கள் தேவனுடைய ஆலயத்தின் ஆராதனைக்காக சமுகத்தப்பங்களுக்கும், நித்தியபோஜனபலிக்கும் ஓய்வுநாட்களிலும் மாதப்பிறப்புகளிலும் செலுத்தும் நித்திய சர்வாங்க தகனபலிகளுக்கும் பண்டிகைகளுக்கும், பிரதிஷ்டையான பொருள்களுக்கும், இஸ்ரவேலுக்காக பாவநிவிர்த்தி உண்டாக்கும் பலிகளுக்கும்,", "en": "Also we made ordinances for us, to charge ourselves yearly with the third part of a shekel for the service of the house of our God;"}, {"verse": 33, "start": 204.59, "end": 217.01, "ta": "எங்கள் தேவனுடைய ஆலயத்தின் சகல வேலைக்கும், வருஷந்தோறும் நாங்கள் சேக்கலில் மூன்றில் ஒரு பங்கைக் கொடுப்போம் என்கிற கடனை எங்கள்மேல் ஏற்றுக்கொண்டோம்.", "en": "For the shewbread, and for the continual meat offering, and for the continual burnt offering, of the sabbaths, of the new moons, for the set feasts, and for the holy things , and for the sin offerings to make an atonement for Israel, and for all the work of the house of our God."}, {"verse": 34, "start": 217.01, "end": 243.35, "ta": "நியாயப்பிரமாணத்தில் எழுதியிருக்கிறபடியே எங்கள் தேவனாகிய கர்த்தருடைய பலிபீடத்தின்மேல் எரிகிறதற்காக, குறிக்கப்பட்ட காலங்களில் வருஷாவருஷம் எங்கள் பிதாக்களுடைய குடும்பங்களின்படியே, எங்கள் தேவனுடைய ஆலயத்துக்கு கொண்டுவரவேண்டிய விறகு காணிக்கைக்காகவும், ஆசாரியருக்கும், லேவியருக்கும், ஜனத்துக்கும் சீட்டுப்போட்டோம்.", "en": "And we cast the lots among the priests, the Levites, and the people, for the wood offering, to bring it into the house of our God, after the houses of our fathers, at times appointed year by year, to burn upon the altar of the LORD our God, as it is written in the law:"}, {"verse": 35, "start": 243.35, "end": 254.81, "ta": "நாங்கள் வருஷந்தோறும் எங்கள் தேவனுடைய ஆலயத்துக்கு எங்கள் தேசத்தின் முதற்பலனையும், சகலவித விருட்சங்களின் எல்லா முதற்கனிகளையும் கொண்டுவரவும்,", "en": "And to bring the firstfruits of our ground, and the firstfruits of all fruit of all trees, year by year, unto the house of the LORD :"}, {"verse": 36, "start": 254.81, "end": 274.39, "ta": "நியாயப்பிரமாணத்தில் எழுதியிருக்கிறபடியே, எங்கள் குமாரரில் முதற்பேறுகளையும், எங்கள் ஆடுமாடுகளாகிய மிருகஜீவன்களின் தலையீற்றுகளையும், எங்கள் தேவனுடைய ஆலயத்துக்கும் எங்கள் தேவனுடைய ஆலயத்திலே ஊழியஞ்செய்கிற ஆசாரியரிடத்துக்கும் கொண்டுவரவும்,", "en": "Also the firstborn of our sons, and of our cattle, as it is written in the law, and the firstlings of our herds and of our flocks, to bring to the house of our God, unto the priests that minister in the house of our God:"}, {"verse": 37, "start": 274.39, "end": 303.27, "ta": "நாங்கள் எங்கள் பிசைந்தமாவில் முதற்பாகத்தையும் எங்கள் படைப்புகளையும், சகல மரங்களின் முந்தின பலனாகிய திராட்சப்பழரசத்தையும் எண்ணெயையும், எங்கள் தேவனுடைய ஆலயத்தின் அறைகளில் வைக்கும்படி ஆசாரியரிடத்துக்கும், எங்கள் நிலப்பயிர்களில் தசமபாகம் லேவியரிடத்திற்கும் கொண்டுவரவும், லேவியராகிய இவர்கள் எங்கள் வெள்ளாண்மையின் பட்டணங்களிலெல்லாம் தசமபாகம் சேர்க்கவும்,", "en": "And that we should bring the firstfruits of our dough, and our offerings, and the fruit of all manner of trees, of wine and of oil, unto the priests, to the chambers of the house of our God; and the tithes of our ground unto the Levites, that the same Levites might have the tithes in all the cities of our tillage."}, {"verse": 38, "start": 303.27, "end": 321.34, "ta": "லேவியர் தசமபாகம் சேர்க்கும்போது ஆரோனின் குமாரனாகிய ஒரு ஆசாரியன் லேவியரோடேகூட இருக்கவும், தசமபாகமாகிய அதிலே லேவியர் பத்தில் ஒரு பங்கை எங்கள் தேவனுடைய ஆலயத்திலுள்ள பொக்கிஷ அறைகளில் கொண்டுவரவும் திட்டம்பண்ணிக்கொண்டோம்.", "en": "And the priest the son of Aaron shall be with the Levites, when the Levites take tithes: and the Levites shall bring up the tithe of the tithes unto the house of our God, to the chambers, into the treasure house."}, {"verse": 39, "start": 321.34, "end": 348.24, "ta": "பரிசுத்தஸ்தலத்தின் பணிமுட்டுகளும், ஊழியஞ்செய்கிற ஆசாரியரும் வாசல் காவலாளரும், பாடகரும் இருக்கிற அந்த அறைகளிலே இஸ்ரவேல் புத்திரரும் லேவிபுத்திரரும் தானியம் திராட்சரசம் எண்ணெய் என்பவைகளின் படைப்புகளைக் கொண்டுவரவேண்டியது; இவ்விதமாய் நாங்கள் எங்கள் தேவனுடைய ஆலயத்தைப் பராமரியாமல் விடுவதில்லையென்று திட்டம்பண்ணிக்கொண்டோம்.", "en": "For the children of Israel and the children of Levi shall bring the offering of the corn, of the new wine, and the oil, unto the chambers, where are the vessels of the sanctuary, and the priests that minister, and the porters, and the singers: and we will not forsake the house of our God."}]}, "11": {"chapter": 11, "duration": 374.73, "audio_url": "audio_ot/OT16_11.mp3", "total_verses": 36, "verses": [{"verse": 1, "start": 3.8, "end": 22.24, "ta": "ஜனத்தின் அதிகாரிகள் எருசலேமிலே குடியிருந்தார்கள்; மற்ற ஜனங்கள், தங்களுக்குள்ளே பத்துப்பேரில் ஒருவனை எருசலேமென்னும் பரிசுத்த நகரத்திலும் ஒன்பதுபேரை மற்றப் பட்டணங்களிலும் குடியிருக்கப்பண்ணி, சீட்டுகளைப் போட்டார்கள்.", "en": "And the rulers of the people dwelt at Jerusalem: the rest of the people also cast lots, to bring one of ten to dwell in Jerusalem the holy city, and nine parts to dwell in other cities."}, {"verse": 2, "start": 22.24, "end": 30.76, "ta": "ஆனாலும் எருசலேமிலே குடியிருக்க மனப்பூர்வமாய்ச் சம்மதித்த மனுஷர்களையெல்லாம் ஜனங்கள் வாழ்த்தினார்கள்.", "en": "And the people blessed all the men, that willingly offered themselves to dwell at Jerusalem."}, {"verse": 3, "start": 30.76, "end": 49.67, "ta": "யூதாவின் பட்டணங்களில் இஸ்ரவேலரும் ஆசாரியரும், லேவியரும் நிதனீமியரும் சாலொமோனுடைய வேலைக்காரரின் புத்திரரும், அவரவர் தங்கள் பட்டணங்களிலுள்ள தங்கள் காணிபூமியிலே குடியிருந்தார்கள்; எருசலேமிலே குடியிருந்த நாடுகளின் தலைவர் யாரென்றால்:", "en": "Now these are the chief of the province that dwelt in Jerusalem: but in the cities of Judah dwelt every one in his possession in their cities, to wit , Israel, the priests, and the Levites, and the Nethinims, and the children of Solomon’s servants."}, {"verse": 4, "start": 49.67, "end": 70.56, "ta": "எருசலேமிலே யூதா புத்திரரில் சிலரும், பென்யமீன் புத்திரரில் சிலரும் குடியிருந்தார்கள்; யூதா புத்திரரிலே பேரேசின் புத்திரருக்குள் ஒருவனான மகலாலெயேலின் குமாரனாகிய செபதியாவின் குமாரன் அமரியாவுக்குப் பிறந்த சகரியாவுக்குக் குமாரனான உசியாவின் மகன் அத்தாயாவும்,", "en": "And at Jerusalem dwelt certain of the children of Judah, and of the children of Benjamin. Of the children of Judah; Athaiah the son of Uzziah, the son of Zechariah, the son of Amariah, the son of Shephatiah, the son of Mahalaleel, of the children of Perez;"}, {"verse": 5, "start": 70.56, "end": 82.86, "ta": "சீலோனின் குமாரன் சகரியாவுக்குக் குமாரனாகிய யோயாரிபுக்குக் குமாரனான அதாயாவுக்குப் பிறந்த அசாயாவின் குமாரன் கொல்லோசேபெற்ற பாருக்கின் மகன் மாசெயாவுமே.", "en": "And Maaseiah the son of Baruch, the son of Col-hozeh, the son of Hazaiah, the son of Adaiah, the son of Joiarib, the son of Zechariah, the son of Shiloni."}, {"verse": 6, "start": 82.86, "end": 91.92, "ta": "எருசலேமிலே குடியிருக்கிற பேரேசின் புத்திரரெல்லாரும் நானூற்று அறுபத்தெட்டுப் பராக்கிரமசாலிகளாயிருந்தார்கள்.", "en": "All the sons of Perez that dwelt at Jerusalem were four hundred threescore and eight valiant men."}, {"verse": 7, "start": 91.92, "end": 110.6, "ta": "பென்யமீன் புத்திரரில் யாரென்றால் சல்லு என்பவன்; இவன் மெசுல்லாமுக்கும், இவன் யோவேலுக்கும், இவன் பெதாயாவுக்கும், இவன் கொலாயாவுக்கும், இவன் மாசெயாவுக்கும், இவன் இதியேலுக்கும், இவன் எசாயாவுக்கும் குமாரனானவன்.", "en": "And these are the sons of Benjamin; Sallu the son of Meshullam, the son of Joed, the son of Pedaiah, the son of Kolaiah, the son of Maaseiah, the son of Ithiel, the son of Jesaiah."}, {"verse": 8, "start": 110.6, "end": 117.54, "ta": "அவனுக்குப்பின் கப்பாய், சல்லாய் முதலானவர்கள் தொளாயிரத்து இருபத்தெட்டுப்பேர்.", "en": "And after him Gabbai, Sallai, nine hundred twenty and eight."}, {"verse": 9, "start": 117.54, "end": 128.65, "ta": "அவர்கள்மேல் விசாரிப்புக்காரனான சிக்ரியின் குமாரன் யோவேலும் பட்டணத்தின்மேல் இரண்டாவது விசாரிப்புக்காரனான செனுவாவின் குமாரன் யூதாவுமே.", "en": "And Joel the son of Zichri was their overseer: and Judah the son of Senuah was second over the city."}, {"verse": 10, "start": 128.65, "end": 133.93, "ta": "ஆசாரியர்களில் யோயாரிபின் குமாரன் யெதாயா, யாகின் என்பவர்களும்,", "en": "Of the priests: Jedaiah the son of Joiarib, Jachin."}, {"verse": 11, "start": 133.93, "end": 146.07, "ta": "அகிதூபின் குமாரன் மெராயோத்துக்குப் பிறந்த சாதோக்கின் குமாரன் மெசுல்லாம் பெற்ற இல்க்கியாவின் மகன் செராயா என்னும் தேவனுடைய ஆலயத்தின் விசாரணைக்கர்த்தனும்,", "en": "Seraiah the son of Hilkiah, the son of Meshullam, the son of Zadok, the son of Meraioth, the son of Ahitub, was the ruler of the house of God."}, {"verse": 12, "start": 146.07, "end": 162.62, "ta": "ஆலயத்திலே பணிவிடை செய்கிற அவர்கள் சகோதரராகிய எண்ணூற்று இருபத்திரண்டுபேரும், மல்கியாவின் குமாரன் பஸ்கூருக்கு மகனான சகரியாவின் குமாரன் அம்சிக்குப் பிறந்த பெல்லியாவின் குமாரன் எரோகாமுக்குப் பிறந்த அதாயாவும்,", "en": "And their brethren that did the work of the house were eight hundred twenty and two: and Adaiah the son of Jeroham, the son of Pelaliah, the son of Amzi, the son of Zechariah, the son of Pashur, the son of Malchiah,"}, {"verse": 13, "start": 162.62, "end": 175.31, "ta": "பிதா வம்சத்தலைவனாகிய அவனுடைய சகோதரர் இருநூற்று நாற்பத்திரண்டுபேரும் இம்மேரின் குமாரன் மெசில்லேமோத்தின் மகனாகிய அகசாய்க்குப் பிறந்த அசரெயேலின் மகனான அமாசாயும்,", "en": "And his brethren, chief of the fathers, two hundred forty and two: and Amashai the son of Azareel, the son of Ahasai, the son of Meshillemoth, the son of Immer,"}, {"verse": 14, "start": 175.31, "end": 187.14, "ta": "அவர்களுடைய சகோதரராகிய பராக்கிரமசாலிகள் நூற்று இருபத்தெட்டுப்பேருமே, இவர்கள்மேல் அகெதோலிமின் குமாரன் சப்தியேல் விசாரிப்புக்காரனாயிருந்தான்.", "en": "And their brethren, mighty men of valour, an hundred twenty and eight: and their overseer was Zabdiel, the son of one of the great men."}, {"verse": 15, "start": 187.14, "end": 194.78, "ta": "லேவியரிலே புன்னியின் குமாரன் சபியாவின் மகனாகிய அஸ்ரிக்காமின் குமாரனான அசூபின் மகன் செமாயாவும்,", "en": "Also of the Levites: Shemaiah the son of Hashub, the son of Azrikam, the son of Hashabiah, the son of Bunni;"}, {"verse": 16, "start": 194.78, "end": 201.88, "ta": "தேவனுடைய ஆலயத்தின் வெளிவேலையை விசாரிக்கிற லேவியரின் தலைவரிலே சபெதாயும், யோசபாத்தும்,", "en": "And Shabbethai and Jozabad, of the chief of the Levites, had the oversight of the outward business of the house of God."}, {"verse": 17, "start": 201.88, "end": 221.03, "ta": "ஆசாபின் குமாரன் சப்தியின் குமாரனாகிய மீகாவின் மகன் மத்தனியா ஜெபத்தில் ஸ்தோத்திரப்பாட்டைத் துவக்குகிற தலைவனும் அவன் சகோதரரில் இரண்டாவதான பக்பூக்கியா என்னும் ஒருவனும், எதுத்தூனின் குமாரன் காலாவின் மகனாகிய சமுவாவின் குமாரன் அப்தாவுமே.", "en": "And Mattaniah the son of Micha, the son of Zabdi, the son of Asaph, was the principal to begin the thanksgiving in prayer: and Bakbukiah the second among his brethren, and Abda the son of Shammua, the son of Galal, the son of Jeduthun."}, {"verse": 18, "start": 221.03, "end": 227.33, "ta": "பரிசுத்த பட்டணத்திலிருந்த லேவியர் எல்லாரும் இருநூற்று எண்பத்துநாலுபேர்.", "en": "All the Levites in the holy city were two hundred fourscore and four."}, {"verse": 19, "start": 227.33, "end": 236.32, "ta": "வாசல் காவலாளர் அக்கூபும், தல்மோனும் வாசல்களில் காவல்காக்கிற அவர்கள் சகோதரரும் நூற்றுஎழுபத்திரண்டுபேர்.", "en": "Moreover the porters, Akkub, Talmon, and their brethren that kept the gates, were an hundred seventy and two."}, {"verse": 20, "start": 236.32, "end": 246.25, "ta": "மற்ற இஸ்ரவேலரும், ஆசாரியரும், லேவியரும் யூதாவின் சகல பட்டணங்களிலும், அவரவர் தங்கள் சுதந்தரத்திலிருந்தார்கள்.", "en": "And the residue of Israel, of the priests, and the Levites, were in all the cities of Judah, every one in his inheritance."}, {"verse": 21, "start": 246.25, "end": 255.39, "ta": "நிதனீமியர் ஒபேலிலே குடியிருந்தார்கள்; அவர்கள்மேல் சீகாவும் கிஸ்பாவும் விசாரிப்புக்காரராயிருந்தார்கள்.", "en": "But the Nethinims dwelt in Ophel: and Ziha and Gispa were over the Nethinims."}, {"verse": 22, "start": 255.39, "end": 272.66, "ta": "எருசலேமிலிருக்கிற லேவியரின் விசாரிப்புக்காரன் மீகாவின் குமாரன் மத்தனியாவின் மகனாகிய அசபியாவுக்குப் பிறந்த பானியின் குமாரன் ஊசி என்பவன் தேவனுடைய ஆலயத்தின் ஊழியத்துக்கு நிற்கிற பாடகராகிய ஆசாபின் குமாரரில் ஒருவன்.", "en": "The overseer also of the Levites at Jerusalem was Uzzi the son of Bani, the son of Hashabiah, the son of Mattaniah, the son of Micha. Of the sons of Asaph, the singers were over the business of the house of God."}, {"verse": 23, "start": 272.66, "end": 280.38, "ta": "பாடகராகிய அவர்களுக்காக அன்றாடகப்படி கொடுக்கப்படும்படி ராஜாவினால் கட்டளையிடப்பட்டிருந்தது.", "en": "For it was the king’s commandment concerning them, that a certain portion should be for the singers, due for every day."}, {"verse": 24, "start": 280.38, "end": 291.65, "ta": "யூதாவின் குமாரனாகிய சேராக்கின் புத்திரரில் மெசசாபெயேலின் குமாரன் பெத்தகியா ஜனத்தின் காரியங்களுக்கெல்லாம் ராஜாவின் சமுகத்தில் நின்றான்.", "en": "And Pethahiah the son of Meshezabeel, of the children of Zerah the son of Judah, was at the king’s hand in all matters concerning the people."}, {"verse": 25, "start": 291.65, "end": 308.12, "ta": "தங்கள் நாட்டுப்புறங்களான கிராமங்களில் இருக்கிறவர்களுக்குள்ளே யூதாவின் புத்திரரில் சிலர் கீரியாத்அர்பாவிலும் அதின் கிராமங்களிலும், தீபோனிலும் அதின் கிராமங்களிலும், எகாப்செயேலிலும் அதின் கிராமங்களிலும்,", "en": "And for the villages, with their fields, some of the children of Judah dwelt at Kirjath-arba, and in the villages thereof, and at Dibon, and in the villages thereof, and at Jekabzeel, and in the villages thereof,"}, {"verse": 26, "start": 308.12, "end": 312.22, "ta": "யெசுவாவிலும், மோலாதாகிலும், பெத்பெலேதிலும்,", "en": "And at Jeshua, and at Moladah, and at Beth-phelet,"}, {"verse": 27, "start": 312.22, "end": 317.5, "ta": "ஆத்சார்சூகாவிலும், பெயெர்செபாவிலும், அதின் கிராமங்களிலும்,", "en": "And at Hazar-shual, and at Beer-sheba, and in the villages thereof,"}, {"verse": 28, "start": 317.5, "end": 322.08, "ta": "சிக்லாகிலும், மேகோனாகிலும், அதின் கிராமங்களிலும்,", "en": "And at Ziklag, and at Mekonah, and in the villages thereof,"}, {"verse": 29, "start": 322.08, "end": 326.33, "ta": "என்ரிம்மோனிலும், சாரேயாகிலும், யர்மூத்திலும்,", "en": "And at En-rimmon, and at Zareah, and at Jarmuth,"}, {"verse": 30, "start": 326.33, "end": 343.04, "ta": "சானோவாலும், அதுல்லாமிலும் அவைகளின் கிராமங்களிலும், லாகீசிலும் அதின் நாட்டுப்புறங்களிலும், அசெக்காவிலும் அதின் கிராமங்களிலும், பெயெர்செபா தொடங்கி இன்னோமின் பள்ளத்தாக்குமட்டும் குடியேறினார்கள்.", "en": "Zanoah, Adullam, and in their villages, at Lachish, and the fields thereof, at Azekah, and in the villages thereof. And they dwelt from Beer-sheba unto the valley of Hinnom."}, {"verse": 31, "start": 343.04, "end": 351.55, "ta": "கேபாவின் ஊராராயிருந்த பென்யமீன் புத்திரர், மிக்மாஸ், ஆயா, பெத்தேல் ஊர்களிலும் அதின் கிளைகளிலும்,", "en": "The children also of Benjamin from Geba dwelt at Michmash, and Aija, and Beth-el, and in their villages,"}, {"verse": 32, "start": 351.55, "end": 353.92, "ta": "ஆனதோத், நோப், அனனியா,", "en": "And at Anathoth, Nob, Ananiah,"}, {"verse": 33, "start": 353.92, "end": 356.6, "ta": "ஆத்சோர், ஆமா, கித்தாயிம்,", "en": "Hazor, Ramah, Gittaim,"}, {"verse": 34, "start": 356.6, "end": 359.28, "ta": "ஆதீத், செபோயிம், நெபலாத்,", "en": "Hadid, Zeboim, Neballat,"}, {"verse": 35, "start": 359.28, "end": 366.85, "ta": "லோத், ஓனோ என்னும் ஊர்களிலும், சிற்பாசாரிகளின் பள்ளத்தாக்கிலும் குடியிருந்தார்கள்.", "en": "Lod, and Ono, the valley of craftsmen."}, {"verse": 36, "start": 366.85, "end": 373.23, "ta": "லேவியரிலே சில வகுப்பார் யூதாவிலும், சிலர் பென்யமீனிலும் இருந்தார்கள்.", "en": "And of the Levites were divisions in Judah, and in Benjamin."}]}, "12": {"chapter": 12, "duration": 501.24, "audio_url": "audio_ot/OT16_12.mp3", "total_verses": 47, "verses": [{"verse": 1, "start": 3.8, "end": 13.02, "ta": "செயல்த்தியேலின் குமாரனாகிய செருபாபேலோடும் யெசுவாவோடும் வந்த ஆசாரியரும் லேவியரும் யாரென்றால்: செராயா எரேமியா, எஸ்றா,", "en": "Now these are the priests and the Levites that went up with Zerubbabel the son of Shealtiel, and Jeshua: Seraiah, Jeremiah, Ezra,"}, {"verse": 2, "start": 13.02, "end": 15.61, "ta": "அமரியா, மல்லூக், அத்தூஸ்,", "en": "Amariah, Malluch, Hattush,"}, {"verse": 3, "start": 15.61, "end": 18.28, "ta": "செகனியா, ரெகூம், மெரெமோத்,", "en": "Shechaniah, Rehum, Meremoth,"}, {"verse": 4, "start": 18.28, "end": 20.57, "ta": "இத்தோ, கிநேதோ, அபியா,", "en": "Iddo, Ginnetho, Abijah,"}, {"verse": 5, "start": 20.57, "end": 23.16, "ta": "மியாமின், மாதியா, பில்கா,", "en": "Miamin, Maadiah, Bilgah,"}, {"verse": 6, "start": 23.16, "end": 25.75, "ta": "செமாயா, யோயாரிப், யெதாயா,", "en": "Shemaiah, and Joiarib, Jedaiah,"}, {"verse": 7, "start": 25.75, "end": 37.71, "ta": "சல்லு, ஆமோக், இல்க்கியா, யெதாயா என்பவர்கள்; இவர்கள் யெசுவாவின் நாட்களில், ஆசாரியருக்கும் தங்கள் சகோதரருக்கும் தலைவராயிருந்தார்கள்.", "en": "Sallu, Amok, Hilkiah, Jedaiah. These were the chief of the priests and of their brethren in the days of Jeshua."}, {"verse": 8, "start": 37.71, "end": 50.06, "ta": "லேவியர் யாரென்றால்: யெசுவா பின்னூயி, கத்மியேல், செரெபியா, யூதா, மத்தனியா என்பவர்கள்; இவனும் இவன் சகோதரரும் துதிசெய்தலை விசாரித்தார்கள்.", "en": "Moreover the Levites: Jeshua, Binnui, Kadmiel, Sherebiah, Judah, and Mattaniah, which was over the thanksgiving, he and his brethren."}, {"verse": 9, "start": 50.06, "end": 57.3, "ta": "பக்புக்கியா, உன்னி என்கிற அவர்கள் சகோதரர் அவர்களுக்கு எதிரே காவல்காத்திருந்தார்கள்.", "en": "Also Bakbukiah and Unni, their brethren, were over against them in the watches."}, {"verse": 10, "start": 57.3, "end": 65.07, "ta": "யெசுவா யொயாசீமைப் பெற்றான், யாயசீம் எலியாசிபைப் பெற்றான், எலியாசிப் யொயதாவைப் பெற்றான்.", "en": "And Jeshua begat Joiakim, Joiakim also begat Eliashib, and Eliashib begat Joiada,"}, {"verse": 11, "start": 65.07, "end": 70.33, "ta": "யொயதா யோனத்தானைப் பெற்றான், யோனத்தான் யதுவாலைப் பெற்றான்.", "en": "And Joiada begat Jonathan, and Jonathan begat Jaddua."}, {"verse": 12, "start": 70.33, "end": 80.61, "ta": "யொயகீமின் நாட்களிலே பிதா வம்சங்களின் தலைவரான ஆசாரியர்கள் யாரென்றால்: செராயாவின் சந்ததியில் மெராயா, எரேமியாவின் சந்ததியில் அனனியா,", "en": "And in the days of Joiakim were priests, the chief of the fathers: of Seraiah, Meraiah; of Jeremiah, Hananiah;"}, {"verse": 13, "start": 80.61, "end": 85.87, "ta": "எஸ்றாவின் சந்ததியில் மெசுல்லாம், அமரியாவின் சந்ததியில் யோகனான்,", "en": "Of Ezra, Meshullam; of Amariah, Jehohanan;"}, {"verse": 14, "start": 85.87, "end": 91.28, "ta": "மெலிகுவின் சந்ததியில் யோனத்தான், செபனியாவின் சந்ததியில் யோசேப்பு,", "en": "Of Melicu, Jonathan; of Shebaniah, Joseph;"}, {"verse": 15, "start": 91.28, "end": 96.01, "ta": "ஆரீமின் சந்ததியில் அத்னா, மெராயோதின் சந்ததியில் எல்காய்,", "en": "Of Harim, Adna; of Meraioth, Helkai;"}, {"verse": 16, "start": 96.01, "end": 101.19, "ta": "இத்தோவின் சந்ததியில் சகரியா, கிநெதோனின் சந்ததியில் மெசுல்லாம்,", "en": "Of Iddo, Zechariah; of Ginnethon, Meshullam;"}, {"verse": 17, "start": 101.19, "end": 108.05, "ta": "அபியாவின் சந்ததியில் சிக்ரி, மினியாமீன்மொவதியா, என்பவர்களின் சந்ததியில் பில்தாய்,", "en": "Of Abijah, Zichri; of Miniamin, of Moadiah, Piltai;"}, {"verse": 18, "start": 108.05, "end": 113.76, "ta": "பில்காவின் சந்ததியில் சம்முவா, செமாயாவின் சந்ததியில் யோனத்தான்.", "en": "Of Bilgah, Shammua; of Shemaiah, Jehonathan;"}, {"verse": 19, "start": 113.76, "end": 120.24, "ta": "யோயாரிபின் சந்ததியில் மத்தனா, யெதாயாவின் சந்ததியில் நெதனெயேல் என்பவர்கள்.", "en": "And of Joiarib, Mattenai; of Jedaiah, Uzzi;"}, {"verse": 20, "start": 120.24, "end": 125.04, "ta": "சல்லாயின் சந்ததியில் கல்லாய், ஆமோக்கின் சந்ததியில் ஏபேர்,", "en": "Of Sallai, Kallai; of Amok, Eber;"}, {"verse": 21, "start": 125.04, "end": 131.75, "ta": "இல்க்கியாவின் சந்ததியில் அசபியா, யெதாயாவின் சந்ததியில் நெதனெயேல் என்பவர்கள்.", "en": "Of Hilkiah, Hashabiah; of Jedaiah, Nethaneel."}, {"verse": 22, "start": 131.75, "end": 147.45, "ta": "எலியாசிபின் நாட்களில் யொயதா, யோகனான், யதுவா என்கிற லேவியர் பிதா வம்சங்களின் தலைவராக எழுதப்பட்டார்கள்; பெர்சியனாகிய தரியுவின் ராஜ்யபாரமட்டும் இருந்த ஆசாரியர்களும் அப்படியே எழுதப்பட்டார்கள்;", "en": "The Levites in the days of Eliashib, Joiada, and Johanan, and Jaddua, were recorded chief of the fathers: also the priests, to the reign of Darius the Persian."}, {"verse": 23, "start": 147.45, "end": 157.96, "ta": "லேவி புத்திரராகிய பிதா வம்சங்களின் தலைவர் எலியாசிபின் குமாரனாகிய யோகனானின் நாட்கள்மட்டும் நாளாகமப் புஸ்தகத்தில் எழுதப்பட்டார்கள்.", "en": "The sons of Levi, the chief of the fathers, were written in the book of the chronicles, even until the days of Johanan the son of Eliashib."}, {"verse": 24, "start": 157.96, "end": 179.15, "ta": "லேவியரின் தலைவராகிய அபியாவும், செரெபியாவும், கத்மியேலின் குமாரன் யெசுவாவும், அவர்களுக்கு எதிரே நிற்கிற அவர்கள் சகோதரரும், தேவனுடைய மனுஷனாகிய தாவீதினுடைய கற்பனையின்படியே துதிக்கவும், தோத்திரிக்கவும், ஒருவருக்கொருவர் எதிர்முகமாக முறைமுறையாயிருந்தார்கள்.", "en": "And the chief of the Levites: Hashabiah, Sherebiah, and Jeshua the son of Kadmiel, with their brethren over against them, to praise and to give thanks, according to the commandment of David the man of God, ward over against ward."}, {"verse": 25, "start": 179.15, "end": 191.49, "ta": "மத்தனியா, பக்புக்கியா, ஒபதியா, மெசுல்லாம், தல்மோன், அக்கூப் என்பவர்கள் வாசல்களிலிருக்கிற பொக்கிஷ அறைகளைக் காவல்காக்கிறவர்களாயிருந்தார்கள்.", "en": "Mattaniah, and Bakbukiah, Obadiah, Meshullam, Talmon, Akkub, were porters keeping the ward at the thresholds of the gates."}, {"verse": 26, "start": 191.49, "end": 205.82, "ta": "யோத்சதாக்கின் குமாரனாகிய யெசுவாவின் குமாரன் யொயகீமின் நாட்களிலும், அதிபதியாகிய நெகேமியாவும், வேதபாரகனாகிய எஸ்றா என்னும் ஆசாரியனும் இருக்கிற நாட்களிலும் அவர்கள் இருந்தார்கள்.", "en": "These were in the days of Joiakim the son of Jeshua, the son of Jozadak, and in the days of Nehemiah the governor, and of Ezra the priest, the scribe."}, {"verse": 27, "start": 205.82, "end": 224.95, "ta": "எருசலேமின் அலங்கத்தைப் பிரதிஷ்டைபண்ணுகையில், துதியினாலும், பாடலினாலும் கைத்தாளம் தம்புரு சுரமண்டலம் முதலான கீதவாத்தியங்களினாலும், பிரதிஷ்டையை மகிழ்ச்சியோடே கொண்டாட எல்லா இடங்களிலும் இருக்கிற லேவியரை எருசலேமுக்கு வரும்படி தேடினார்கள்.", "en": "And at the dedication of the wall of Jerusalem they sought the Levites out of all their places, to bring them to Jerusalem, to keep the dedication with gladness, both with thanksgivings, and with singing, with cymbals, psalteries, and with harps."}, {"verse": 28, "start": 224.95, "end": 233.33, "ta": "அப்படியே பாடகரின் புத்திரர் எருசலேமின் சுற்றுப்புறங்களான சமபூமியிலும், நெத்தோபாத்தியரின் கிராமங்களிலும்,", "en": "And the sons of the singers gathered themselves together, both out of the plain country round about Jerusalem, and from the villages of Netophathi;"}, {"verse": 29, "start": 233.33, "end": 247.27, "ta": "பெத்கில்காலிலும், கேபா, அஸ்மாவேத் ஊர்களின் நாட்டுப்புறங்களிலுமிருந்துவந்து கூடினார்கள்; பாடகர் எருசலேமைச் சுற்றிலும் தங்களுக்குக் கிராமங்களைக் கட்டியிருந்தார்கள்.", "en": "Also from the house of Gilgal, and out of the fields of Geba and Azmaveth: for the singers had builded them villages round about Jerusalem."}, {"verse": 30, "start": 247.27, "end": 256.95, "ta": "ஆசாரியரும் லேவியரும் தங்களைச் சுத்தம்பண்ணிக்கொண்டு, ஜனத்தையும் பட்டணவாசல்களையும் அலங்கத்தையும் சுத்தம்பண்ணினார்கள்.", "en": "And the priests and the Levites purified themselves, and purified the people, and the gates, and the wall."}, {"verse": 31, "start": 256.95, "end": 274.94, "ta": "அப்பொழுது நான் யூதாவின் பிரபுக்களை அலங்கத்தின்மேல் ஏறப்பண்ணி, துதிசெய்து நடந்துபோகும்படி இரண்டு பெரிய கூட்டத்தாரை நிறுத்தினேன்; அவர்களில் ஒரு கூட்டத்தார் அலங்கத்தின்மேல் வலதுபுறமாகக் குப்பைமேட்டு வாசலுக்குப் போனார்கள்.", "en": "Then I brought up the princes of Judah upon the wall, and appointed two great companies of them that gave thanks, whereof one went on the right hand upon the wall toward the dung gate:"}, {"verse": 32, "start": 274.94, "end": 280.12, "ta": "அவர்கள் பிறகாலே ஒசாயாவும், யூதாவின் பிரபுக்களில் பாதிப்பேரும்,", "en": "And after them went Hoshaiah, and half of the princes of Judah,"}, {"verse": 33, "start": 280.12, "end": 282.79, "ta": "அசரியா, எஸ்றா, மெசுல்லாம்,", "en": "And Azariah, Ezra, and Meshullam,"}, {"verse": 34, "start": 282.79, "end": 287.21, "ta": "யூதா, பென்யமீன், செமாயா, எரேமியா என்பவர்களும்,", "en": "Judah, and Benjamin, and Shemaiah, and Jeremiah,"}, {"verse": 35, "start": 287.21, "end": 300.85, "ta": "பூரிகைகளைப் பிடிக்கிற ஆசாரியரின் புத்திரரில் ஆசாப்பின் குமாரன் சக்கூரின் மகனாகிய மிகாயாவுக்குக் குமாரனான மத்தனியாவின் மகன் செமாயாவுக்குப் பிறந்த யோனத்தானின் குமாரன் சகரியாவும்,", "en": "And certain of the priests’ sons with trumpets; namely , Zechariah the son of Jonathan, the son of Shemaiah, the son of Mattaniah, the son of Michaiah, the son of Zaccur, the son of Asaph:"}, {"verse": 36, "start": 300.85, "end": 319.44, "ta": "தேவனுடைய மனுஷனாகிய தாவீதின் கீதவாத்தியங்களை வாசிக்கிற அவன் சகோதரரான செமாயா, அசரெயேல், மிலாலாய், கிலாலாய், மகாய், நெதனெயேல், யூதா, அனானி என்பவர்களும் போனார்கள்; வேதபாரகனாகிய எஸ்றா இவர்களுக்கு முன்பாக நடந்தான்.", "en": "And his brethren, Shemaiah, and Azarael, Milalai, Gilalai, Maai, Nethaneel, and Judah, Hanani, with the musical instruments of David the man of God, and Ezra the scribe before them."}, {"verse": 37, "start": 319.44, "end": 335.67, "ta": "அங்கேயிருந்து அவர்கள் தங்களுக்கு எதிரான ஊருணிவாசலுக்கு வந்தபோது, அலங்கத்தைப்பார்க்கிலும் உயரமான தாவீது நகரத்தின் படிகளில் ஏறி, தாவீது வீட்டின்மேலாகக் கிழக்கேயிருக்கிற தண்ணீர் வாசல்மட்டும் போனார்கள்.", "en": "And at the fountain gate, which was over against them, they went up by the stairs of the city of David, at the going up of the wall, above the house of David, even unto the water gate eastward."}, {"verse": 38, "start": 335.67, "end": 351.75, "ta": "துதிசெய்கிற இரண்டாம் கூட்டத்தார் எதிரேயிருக்கிற வழியாய் நடந்துபோனார்கள், அவர்கள் பிறகாலே நான் போனேன்; ஜனத்தில் பாதிப்பேர் அலங்கத்தின்மேல் சூளைகளின் கொம்மையைக்கடந்து, அகழ் மதில்மட்டும் நெடுகப்போய்,", "en": "And the other company of them that gave thanks went over against them , and I after them, and the half of the people upon the wall, from beyond the tower of the furnaces even unto the broad wall;"}, {"verse": 39, "start": 351.75, "end": 366.61, "ta": "எப்பிராயீம் வாசலையும் பழையவாசலையும், மீன் வாசலையும், அனானெயேலின் கொம்மையையும், மேயா என்கிற கொம்மையையும் கடந்து, ஆட்டுவாசல்மட்டும் புறப்பட்டுக் காவல்வீட்டுவாசலிலே நின்றார்கள்.", "en": "And from above the gate of Ephraim, and above the old gate, and above the fish gate, and the tower of Hananeel, and the tower of Meah, even unto the sheep gate: and they stood still in the prison gate."}, {"verse": 40, "start": 366.61, "end": 377.66, "ta": "அதற்குப்பின்பு துதி செய்கிற இரண்டு கூட்டத்தாரும் தேவனுடைய ஆலயத்திலே வந்து நின்றார்கள்; நானும் என்னோடேகூட இருக்கிற தலைவரில் பாதிப்பேரும்,", "en": "So stood the two companies of them that gave thanks in the house of God, and I, and the half of the rulers with me:"}, {"verse": 41, "start": 377.66, "end": 387.72, "ta": "பூரிகைகளைப் பிடிக்கிற எலியாக்கீம், மாசெயா, மினியாமீன், மிகாயா, எலியோனாய், சகரியா, அனானியா என்கிற ஆசாரியர்களும்,", "en": "And the priests; Eliakim, Maaseiah, Miniamin, Michaiah, Elioenai, Zechariah, and Hananiah, with trumpets;"}, {"verse": 42, "start": 387.72, "end": 402.58, "ta": "மாசெயா, செமாயா, எலெயாசார், ஊசி, யோகனான், மல்கியா, ஏலாம், ஏசேர் என்பவர்களும் நின்றோம்; பாடகரும் அவர்கள் விசாரிப்புக்காரனாகிய யெஷாகியாவும சத்தமாய்ப் பாடினார்கள்.", "en": "And Maaseiah, and Shemaiah, and Eleazar, and Uzzi, and Jehohanan, and Malchijah, and Elam, and Ezer. And the singers sang loud, with Jezrahiah their overseer."}, {"verse": 43, "start": 402.58, "end": 419.65, "ta": "அந்நாளிலே மிகுதியான பலிகளைச் செலுத்தி தேவன் தங்களுக்கு மகா சந்தோஷத்தை உண்டாக்கினதினால் மகிழ்ச்சியாயிருந்தார்கள்; ஸ்திரீகளும் பிள்ளைகளுங்கூடக் களிகூர்ந்தார்கள்; எருசலேமின் களிப்பு தூரத்திலே கேட்கப்பட்டது.", "en": "Also that day they offered great sacrifices, and rejoiced: for God had made them rejoice with great joy: the wives also and the children rejoiced: so that the joy of Jerusalem was heard even afar off."}, {"verse": 44, "start": 419.65, "end": 449.98, "ta": "அன்றையதினம் பொக்கிஷங்களையும், படைப்புகளையும், முதல் கனிகளையும், தசமபாகங்களையும் வைக்கும் அறைகளின்மேல், ஆசாரியர்களுக்கும் லேவியர்களுக்கும் நியாயப்பிரமாணத்தின்படியே வரவேண்டிய பட்டணங்களுடைய நிலங்களின் பங்குகளை அவைகளில் சேர்க்கும்படிக்கு, சில மனுஷர் விசாரிப்புக்காரராக வைக்கப்பட்டார்கள்; ஊழியஞ்செய்து நிற்கிற ஆசாரியர்மேலும் லேவியர்மேலும் யூதா மனிதர் சந்தோஷமாயிருந்தார்கள்.", "en": "And at that time were some appointed over the chambers for the treasures, for the offerings, for the firstfruits, and for the tithes, to gather into them out of the fields of the cities the portions of the law for the priests and Levites: for Judah rejoiced for the priests and for the Levites that waited."}, {"verse": 45, "start": 449.98, "end": 462.25, "ta": "பாடகரும், வாசல் காவலாளரும், தாவீதும் அவன் குமாரனாகிய சாலொமோனும் கற்பித்தபடியே தங்கள் தேவனுடைய காவலையும், சுத்திகரிப்பின் காவலையும் காத்தார்கள்.", "en": "And both the singers and the porters kept the ward of their God, and the ward of the purification, according to the commandment of David, and of Solomon his son."}, {"verse": 46, "start": 462.25, "end": 475.28, "ta": "தாவீதும் ஆசாப்பும் இருந்த பூர்வநாட்களில் பாடகரின் தலைவரும் வைக்கப்பட்டு, தேவனுக்குத் துதியும் தோத்திரங்களும் செலுத்துகிற சங்கீதங்கள் திட்டம்பண்ணப்பட்டிருந்தது.", "en": "For in the days of David and Asaph of old there were chief of the singers, and songs of praise and thanksgiving unto God."}, {"verse": 47, "start": 475.28, "end": 499.74, "ta": "ஆகையால் செரூபாபேலின் நாட்களிலும், நெகேமியாவின் நாட்களிலும் இஸ்ரவேலர் எல்லாரும் பாடகருக்கும் வாசல் காவலாளருக்கும் அன்றாடகத் திட்டமாகிய பங்குகளைக் கொடுத்தார்கள்; அவர்கள் லேவியருக்கென்று பிரதிஷ்டைபண்ணிக் கொடுத்தார்கள்; லேவியர் ஆரோனின் புத்திரருக்கென்று அவர்கள் பங்கைப் பிரதிஷ்டைபண்ணிக் கொடுத்தார்கள்.", "en": "And all Israel in the days of Zerubbabel, and in the days of Nehemiah, gave the portions of the singers and the porters, every day his portion: and they sanctified holy things unto the Levites; and the Levites sanctified them unto the children of Aaron."}]}, "13": {"chapter": 13, "duration": 467.7, "audio_url": "audio_ot/OT16_13.mp3", "total_verses": 31, "verses": [{"verse": 1, "start": 3.8, "end": 22.84, "ta": "அன்றையதினம் ஜனங்கள் கேட்க மோசேயின் புஸ்தகத்தை வாசித்தார்கள்; அதிலே அம்மோனியரும் மோவாபியரும், இஸ்ரவேல் புத்திரருக்கு அப்பமும் தண்ணீரும் கொடுக்க எதிர்கொண்டுவராமல், அவர்களைச் சபிக்க அவர்களுக்கு விரோதமாய்ப் பிலேயாமைக் கூலிபொருந்திக்கொண்டபடியினால்,", "en": "On that day they read in the book of Moses in the audience of the people; and therein was found written, that the Ammonite and the Moabite should not come into the congregation of God for ever;"}, {"verse": 2, "start": 22.84, "end": 33.47, "ta": "அவர்கள் என்றைக்கும், அந்தச் சாபத்தை ஆசீர்வாதமாகத் திருப்பின எங்கள் தேவனுடைய சபைக்குட்படலாகாது என்று எழுதியிருக்கிறதாகக் காணப்பட்டது.", "en": "Because they met not the children of Israel with bread and with water, but hired Balaam against them, that he should curse them: howbeit our God turned the curse into a blessing."}, {"verse": 3, "start": 33.47, "end": 42.4, "ta": "ஆகையால் அவர்கள் அந்தக் கட்டளையைக் கேட்டபோது, பல ஜாதியான ஜனங்களையெல்லாம் இஸ்ரவேலைவிட்டுப் பிரித்துவிட்டார்கள்.", "en": "Now it came to pass, when they had heard the law, that they separated from Israel all the mixed multitude."}, {"verse": 4, "start": 42.4, "end": 52.0, "ta": "இதற்குமுன்னே எங்கள் தேவனுடைய ஆலயத்தின் அறைகளை விசாரிக்க வைக்கப்பட்ட ஆசாரியனாகிய எலியாசிப் தொபியாவோடே சம்பந்தங்கலந்தவனாயிருந்து,", "en": "And before this, Eliashib the priest, having the oversight of the chamber of the house of our God, was allied unto Tobiah:"}, {"verse": 5, "start": 52.0, "end": 74.8, "ta": "முற்காலத்தில் காணிக்கைகளும் சாம்பிராணியும், பணிமுட்டுகளும், லேவியருக்கும் பாடகருக்கும் வாசல்காவலருக்கும் கட்டளைபண்ணப்பட்ட தானியம் திராட்சரசம் எண்ணெய் என்பவைகளிலே தசமபாகமும், ஆசாரியரைச் சேருகிற படைப்பான காணிக்கைகளும் வைக்கப்பட்டிருந்த இடத்தில் ஒரு பெரிய அறையை அவனுக்கு ஆயத்தம்பண்ணியிருந்தான்.", "en": "And he had prepared for him a great chamber, where aforetime they laid the meat offerings, the frankincense, and the vessels, and the tithes of the corn, the new wine, and the oil, which was commanded to be given to the Levites, and the singers, and the porters; and the offerings of the priests."}, {"verse": 6, "start": 74.8, "end": 90.82, "ta": "இதெல்லாம் நடக்கும்போது நான் எருசலேமில் இல்லை; பாபிலோன் ராஜாவாகிய அர்தசஷ்டாவின் முப்பத்திரண்டாம் வருஷத்திலே நான் ராஜாவினிடத்திற்குப்போய், சில நாளுக்குப்பின்பு திரும்ப ராஜாவினிடத்தில் உத்தரவு பெற்றுக்கொண்டு,", "en": "But in all this time was not I at Jerusalem: for in the two and thirtieth year of Artaxerxes king of Babylon came I unto the king, and after certain days obtained I leave of the king:"}, {"verse": 7, "start": 90.82, "end": 103.14, "ta": "எருசலேமுக்கு வந்தேன்; அப்பொழுது எலியாசிப் தொபியாவுக்கு தேவனுடைய ஆலயத்துப் பிராகாரங்களில் ஒரு அறையை ஆயத்தம்பண்ணினதினால் செய்த பொல்லாப்பை அறிந்துகொண்டேன்.", "en": "And I came to Jerusalem, and understood of the evil that Eliashib did for Tobiah, in preparing him a chamber in the courts of the house of God."}, {"verse": 8, "start": 103.14, "end": 112.67, "ta": "அதினால் நான் மிகவும் மனமடிவாகி, தொபியாவின் வீட்டுத் தட்டுமுட்டுகளையெல்லாம் அந்த அறையிலிருந்து வெளியே எறிந்துவிட்டேன்.", "en": "And it grieved me sore: therefore I cast forth all the household stuff of Tobiah out of the chamber."}, {"verse": 9, "start": 112.67, "end": 124.4, "ta": "பின்பு நான் அறைவீடுகளைச் சுத்திகரிக்கச்சொல்லி, தேவனுடைய ஆலயப்பணிமுட்டுகளையும் காணிக்கைகளையும் சாம்பிராணியையும் அங்கே திரும்பக்கொண்டுவந்து வைத்தேன்.", "en": "Then I commanded, and they cleansed the chambers: and thither brought I again the vessels of the house of God, with the meat offering and the frankincense."}, {"verse": 10, "start": 124.4, "end": 138.79, "ta": "பின்னையும் லேவியருக்கு அவர்கள் பங்குகள் கொடுக்கப்படவில்லையென்பதையும், பணிவிடை செய்கிற லேவியரும் பாடகரும் அவரவர் தங்கள் வெளிநிலங்களுக்கு ஓடிப்போனார்கள் என்பதையும் நான் அறிந்துகொண்டேன்.", "en": "And I perceived that the portions of the Levites had not been given them: for the Levites and the singers, that did the work, were fled every one to his field."}, {"verse": 11, "start": 138.79, "end": 150.97, "ta": "அப்பொழுது நான் தலைமையானவர்களோடே வழக்காடி, தேவனுடைய ஆலயம் கைவிடப்பட்டுப்போவானேன் என்று சொல்லி, அவர்களைச் சேர்த்து, அவரவர் நிலையில் அவர்களை வைத்தேன்.", "en": "Then contended I with the rulers, and said, Why is the house of God forsaken? And I gathered them together, and set them in their place."}, {"verse": 12, "start": 150.97, "end": 159.98, "ta": "அப்பொழுது யூதர் எல்லாரும் தானியம் திராட்சரசம் எண்ணெய் என்பவைகளில் தசமபாகத்தைப் பொக்கிஷ அறைகளில் கொண்டுவந்தார்கள்.", "en": "Then brought all Judah the tithe of the corn and the new wine and the oil unto the treasuries."}, {"verse": 13, "start": 159.98, "end": 186.77, "ta": "அப்பொழுது நான் ஆசாரியராகிய செலேமியாவையும் வேதபாரகனாகிய சாதோக்கையும் லேவியரில் பெதாயாவையும், இவர்களுக்குக் கைத்துணையாக மத்தனியாவின் குமாரன்சக்கூரின் மகனாகிய ஆனானையும் பொக்கிஷ அறைகளின்மேல் விசாரிப்புக்காரராக வைத்தேன்; அவர்கள் உண்மையுள்ளவர்களென்று எண்ணப்பட்டார்கள்; ஆகையால் தங்கள் சகோதரருக்குப் பங்கிடுகிற வேலை அவர்களுக்கு ஒப்புவிக்கப்பட்டது.", "en": "And I made treasurers over the treasuries, Shelemiah the priest, and Zadok the scribe, and of the Levites, Pedaiah: and next to them was Hanan the son of Zaccur, the son of Mattaniah: for they were counted faithful, and their office was to distribute unto their brethren."}, {"verse": 14, "start": 186.77, "end": 198.95, "ta": "என் தேவனே, நான் என் தேவனுடைய ஆலயத்துக்காகவும் அதின் முறைமைகளுக்காகவும் செய்த நற்கிரியைகளைக் குலைத்துப்போடாமல், இந்தக் காரியத்திலே என்னை நினைத்தருளும்.", "en": "Remember me, O my God, concerning this, and wipe not out my good deeds that I have done for the house of my God, and for the offices thereof."}, {"verse": 15, "start": 198.95, "end": 225.88, "ta": "அந்த நாட்களில் நான் யூதாவிலே ஓய்வுநாளில் சிலர் ஆலைகளை மிதிக்கிறதையும், சிலர் ஆலைகளை தானியப் பொதிகளைக் கழுதைகள்மேல் ஏற்றிக்கொண்டு வருகிறதையும் திராட்சரசம், திராட்சப்பழம், அத்திப்பழம் முதலானவைகளின் பற்பல சுமைகளை ஓய்வுநாளிலே எருசலேமுக்குக் கொண்டுவருகிறதையும் கண்டு, அவர்கள் தின்பண்டம் விற்கிற நாளைப்பற்றி அவர்களைத் திடசாட்சியாய்க் கடிந்துகொண்டேன்.", "en": "In those days saw I in Judah some treading wine presses on the sabbath, and bringing in sheaves, and lading asses; as also wine, grapes, and figs, and all manner of burdens, which they brought into Jerusalem on the sabbath day: and I testified against them in the day wherein they sold victuals."}, {"verse": 16, "start": 225.88, "end": 238.14, "ta": "மீனையும் சகலவித சரக்குகளையும் கொண்டுவந்து, ஓய்வுநாளிலே யூதா புத்திரருக்கும் எருசலேமில் இருக்கிறவர்களுக்கும் விற்கிற சில தீரியரும் உள்ளே குடியிருந்தார்கள்.", "en": "There dwelt men of Tyre also therein, which brought fish, and all manner of ware, and sold on the sabbath unto the children of Judah, and in Jerusalem."}, {"verse": 17, "start": 238.14, "end": 248.1, "ta": "ஆகையால் நான் யூதாவின் பெரியவர்களைக் கடிந்துகொண்டு: நீங்கள் ஓய்வுநாளைப் பரிசுத்தக் குலைச்சலாக்குகிற இந்தப் பொல்லாத செய்கையென்ன?", "en": "Then I contended with the nobles of Judah, and said unto them, What evil thing is this that ye do, and profane the sabbath day?"}, {"verse": 18, "start": 248.1, "end": 269.28, "ta": "உங்கள் பிதாக்கள் இப்படிச்செய்ததினாலல்லவா, நமது தேவன் நம்மேலும் இந்தநகரத்தின்மேலும் இந்தத்தீங்கையெல்லாம் வரப்பண்ணினார்; நீங்களோவென்றால் ஓய்வுநாளைப் பரிசுத்தக் குலைச்சலாக்குகிறதினால் இஸ்ரவேலின்மேலிருக்கிற உக்கிரத்தை அதிகரிக்கப்பண்ணுகிறீர்கள் என்று அவர்களுக்குச் சொன்னேன்.", "en": "Did not your fathers thus, and did not our God bring all this evil upon us, and upon this city? yet ye bring more wrath upon Israel by profaning the sabbath."}, {"verse": 19, "start": 269.28, "end": 290.1, "ta": "ஆகையால் ஓய்வுநாளுக்குமுன்னே எருசலேமின் பட்டணவாசலில், மாலைமயங்கும்போது, கதவுகளைப்பூட்டவும், ஓய்வுநாள் முடியுமட்டும் அவைகளைத் திறவாதிருக்கவும் வேண்டுமென்று கட்டளையிட்டு, ஓய்வுநாளிலே ஒரு சுமையும் உள்ளே வராதபடிக்கு வாசலண்டையிலே என் வேலைக்காரரில் சிலரை நிறுத்தினேன்.", "en": "And it came to pass, that when the gates of Jerusalem began to be dark before the sabbath, I commanded that the gates should be shut, and charged that they should not be opened till after the sabbath: and some of my servants set I at the gates, that there should no burden be brought in on the sabbath day."}, {"verse": 20, "start": 290.1, "end": 299.25, "ta": "அதினால் வர்த்தகரும், சகலவித சரக்குகளை விற்கிறவர்களும், இரண்டொருதரம் எருசலேமுக்குப் புறம்பே இராத்தங்கினார்கள்.", "en": "So the merchants and sellers of all kind of ware lodged without Jerusalem once or twice."}, {"verse": 21, "start": 299.25, "end": 318.81, "ta": "அப்பொழுது நான் அவர்களைத் திடசாட்சியாய்க் கடிந்துகொன்டு, நீங்கள் அலங்கத்தண்டையிலே இராத்தங்குகிறது என்ன? நீங்கள் மறுபடியும் இப்படிச் செய்தால், உங்கள்மேல் கைபோடுவேன் என்று அவர்களோடே சொன்னேன்; அதுமுதல் அவர்கள் ஓய்வுநாளில் வராதிருந்தார்கள்.", "en": "Then I testified against them, and said unto them, Why lodge ye about the wall? if ye do so again, I will lay hands on you. From that time forth came they no more on the sabbath."}, {"verse": 22, "start": 318.81, "end": 336.3, "ta": "ஓய்வுநாளைப் பரிசுத்தமாக்கும்படிக்கு, உங்களைச் சுத்தம்பண்ணிக்கொண்டு வாசல்களைக் காக்க வாருங்களென்று லேவியருக்கும் சொன்னேன்என் தேவனே, இதைக்குறித்து நீர் என்னை நினைத்தருளி, உம்முடைய மிகுந்த கிருபையின்படி எனக்கு இரங்குவீராக.", "en": "And I commanded the Levites that they should cleanse themselves, and that they should come and keep the gates, to sanctify the sabbath day. Remember me, O my God, concerning this also, and spare me according to the greatness of thy mercy."}, {"verse": 23, "start": 336.3, "end": 344.71, "ta": "அஸ்தோத், அம்மோன், மோவாப் ஜாதிகளான ஸ்திரீகளைச் சேர்த்துக்கொண்ட சில யூதரையும் அந்த நாட்களில் கண்டேன்.", "en": "In those days also saw I Jews that had married wives of Ashdod, of Ammon, and of Moab:"}, {"verse": 24, "start": 344.71, "end": 356.89, "ta": "அவர்கள் பிள்ளைகள் பேசின பேச்சில் பாதி அஸ்தோத் பாஷையாயிருந்தது; இவர்கள் அந்தந்த ஜாதிகளின் பாஷையைத் தவிர யூதபாஷையைத் திட்டமாய்ப் பேச அறியாதிருந்தார்கள்.", "en": "And their children spake half in the speech of Ashdod, and could not speak in the Jews’ language, but according to the language of each people."}, {"verse": 25, "start": 356.89, "end": 381.76, "ta": "அவர்களையும் நான் கடிந்துகொண்டு அவர்கள்மேல் வரும் சாபத்தைக் கூறி அவர்களில் சிலரை அடித்து, மயிரைப் பிய்த்து: நீங்கள் உங்கள் குமாரத்திகளை அவர்கள் குமாரருக்குக் கொடாமலும், அவர்கள் குமாரத்திகளில் ஒருவரையும் உங்கள் குமாரருக்காகிலும் உங்களுக்காகிலும் கொள்ளாமலும் இருக்கவேண்டுமென்று அவர்களை தேவன்மேல் ஆணையிடப்பண்ணி, நான் அவர்களை நோக்கி:", "en": "And I contended with them, and cursed them, and smote certain of them, and plucked off their hair, and made them swear by God, saying , Ye shall not give your daughters unto their sons, nor take their daughters unto your sons, or for yourselves."}, {"verse": 26, "start": 381.76, "end": 405.24, "ta": "இஸ்ரவேலின் ராஜாவாகிய சாலொமோன் இதினாலே பாவஞ்செய்தானல்லவா? அவனைப்போன்ற ராஜா அநேகம் ஜாதிகளுக்குள்ளே உண்டாயிருந்ததில்லை; அவன் தன் தேவனாலே சிநேகிக்கப்பட்டவனாயிருந்தான்; தேவன் அவனை இஸ்ரவேலனைத்தின்மேலும் ராஜாவாக வைத்தார்; அப்பபடிப்பட்டவனையும் மறுஜாதியான ஸ்திரீகள் பாவஞ்செய்யப்பண்ணினார்களே.", "en": "Did not Solomon king of Israel sin by these things? yet among many nations was there no king like him, who was beloved of his God, and God made him king over all Israel: nevertheless even him did outlandish women cause to sin."}, {"verse": 27, "start": 405.24, "end": 419.19, "ta": "நீங்கள் மறுஜாதியான ஸ்திரீகளைச் சேர்த்துக்கொள்ளுகிறதினால், நம்முடைய தேவனுக்குத் துரோகிகளாகி, இந்தப் பெரிய பொல்லாப்பையெல்லாம் செய்யும்படி, உங்களுக்கு இடங்கொடுப்போமோ என்றேன்.", "en": "Shall we then hearken unto you to do all this great evil, to transgress against our God in marrying strange wives?"}, {"verse": 28, "start": 419.19, "end": 431.36, "ta": "யொயதாவின் புத்திரரிலே பிரதான ஆசாரியனாகிய எலியாசிபினுடைய குமாரன் ஒருவன் ஓரோனியனான சன்பல்லாத்துக்கு மருமகனானான்; ஆகையால் அவனை என்னைவிட்டுத் துரத்தினேன்.", "en": "And one of the sons of Joiada, the son of Eliashib the high priest, was son in law to Sanballat the Horonite: therefore I chased him from me."}, {"verse": 29, "start": 431.36, "end": 444.06, "ta": "என் தேவனே, அவர்கள் ஆசாரிய ஊழியத்தையும், ஆசாரிய ஊழியத்துக்கும் லேவியருக்கும் இருக்கிற உடன்படிக்கையையும் தீட்டுப்படுத்தினார்களென்று அவர்களை நினைத்துக்கொள்ளும்.", "en": "Remember them, O my God, because they have defiled the priesthood, and the covenant of the priesthood, and of the Levites."}, {"verse": 30, "start": 444.06, "end": 453.95, "ta": "இப்படியே நான் மறுஜாதியாரையெல்லாம் நீக்கி, ஆசாரியரையும் லேவியரையும் சுத்திகரித்து, அவரவரை அவர்கள் வேலையின் முறைகளில் நிறுத்தி,", "en": "Thus cleansed I them from all strangers, and appointed the wards of the priests and the Levites, every one in his business;"}, {"verse": 31, "start": 453.95, "end": 466.2, "ta": "குறிக்கப்பட்ட காலங்களில் செலுத்தப்படவேண்டிய விறகுகாணிக்கையையும் முதற்பலன்களையுங்குறித்துத் திட்டம்பண்ணினேன்என் தேவனே எனக்கு நன்மையுண்டாக என்னை நினைத்தருளும்.", "en": "And for the wood offering, at times appointed, and for the firstfruits. Remember me, O my God, for good."}]}}});
} else {
  window.BIBLE_CACHE = window.BIBLE_CACHE || {};
  window.BIBLE_CACHE['16'] = {"id": 16, "testament": "OT", "code": "NEH", "name_en": "Nehemiah", "name_ta": "நெகேமியா", "category": "History", "category_ta": "சரித்திரம்", "total_chapters": 13, "chapters": {"1": {"chapter": 1, "duration": 180.92, "audio_url": "audio_ot/OT16_01.mp3", "total_verses": 11, "verses": [{"verse": 1, "start": 4.8, "end": 15.78, "ta": "அகலியாவின் குமாரனாகிய நெகேமியாவின் நடபடிகள்: இருபதாம் வருஷம் கிஸ்லேயு மாதத்தில் நான் சூசானென்னும் அரமனையில் இருக்கும்போது சம்பவித்தது என்னவென்றால்,", "en": "The words of Nehemiah the son of Hachaliah. And it came to pass in the month Chisleu, in the twentieth year, as I was in Shushan the palace,"}, {"verse": 2, "start": 15.78, "end": 31.08, "ta": "என் சகோதரரில் ஒருவனாகிய ஆனானியும், வேறே சில மனுஷரும் யூதாவிலிருந்து வந்தார்கள்; அவர்களிடத்தில் நான் சிறையிருப்பில் மீந்து தப்பின யூதரின் செய்தியையும், எருசலேமின் செய்தியையும் விசாரித்தேன்.", "en": "That Hanani, one of my brethren, came, he and certain men of Judah; and I asked them concerning the Jews that had escaped, which were left of the captivity, and concerning Jerusalem."}, {"verse": 3, "start": 31.08, "end": 48.66, "ta": "அதற்கு அவர்கள்: சிறையிருப்பில் மீந்திருக்கிறவர்கள் அந்தத் தேசத்திலே மகா தீங்கையும் நிந்தையையும் அநுபவிக்கிறார்கள்; எருசலேமின் அலங்கம் இடிபட்டதும், அதின் வாசல்கள் அக்கினியால் சுட்டெரிக்கப்பட்டதுமாய்க் கிடக்கிறது என்றார்கள்.", "en": "And they said unto me, The remnant that are left of the captivity there in the province are in great affliction and reproach: the wall of Jerusalem also is broken down, and the gates thereof are burned with fire."}, {"verse": 4, "start": 48.66, "end": 58.54, "ta": "இந்த வார்த்தைகளைக் கேட்டபோது நான் உட்கார்ந்து அழுது, சிலநாளாய்த் துக்கித்து, உபவாசித்து, மன்றாடி, பரலோகத்தின் தேவனை நோக்கி:", "en": "And it came to pass, when I heard these words, that I sat down and wept, and mourned certain days, and fasted, and prayed before the God of heaven,"}, {"verse": 5, "start": 58.54, "end": 71.87, "ta": "பரலோகத்தின் தேவனாகிய கர்த்தாவே, உம்மில் அன்புகூர்ந்து, உம்முடைய கற்பனைகளைக் கைக்கொள்ளுகிறவர்களுக்கு, உடன்படிக்கையையும் கிருபையையும் காக்கிற மகத்துவமும் பயங்கரமுமான தேவனே,", "en": "And said, I beseech thee, O LORD God of heaven, the great and terrible God, that keepeth covenant and mercy for them that love him and observe his commandments:"}, {"verse": 6, "start": 71.87, "end": 95.73, "ta": "உமது அடியாராகிய இஸ்ரவேல் புத்திரருக்காக இன்று இரவும்பகலும் உமக்கு முன்பாக மன்றாடி, இஸ்ரவேல் புத்திரராகிய நாங்கள் உமக்கு விரோதமாகச் செய்த பாவங்களை அறிக்கையிடுகிற அடியேனுடைய ஜெபத்தைக்கேட்கிறதற்கு, உம்முடைய செவி கவனித்தும், உம்முடைய கண்கள் திறந்தும் இருப்பதாக; நானும் என் தகப்பன் வீட்டாரும் பாவஞ்செய்தோம்.", "en": "Let thine ear now be attentive, and thine eyes open, that thou mayest hear the prayer of thy servant, which I pray before thee now, day and night, for the children of Israel thy servants, and confess the sins of the children of Israel, which we have sinned against thee: both I and my father’s house have sinned."}, {"verse": 7, "start": 95.73, "end": 109.06, "ta": "நாங்கள் உமக்கு முன்பாக மிகவும் கெட்டவர்களாய் நடந்தோம்; நீர் உம்முடைய தாசனாகிய மோசேக்குக்கற்பித்த கற்பனைகளையும், கட்டளைகளையும், நியாயங்களையும் கைக்கொள்ளாதேபோனோம்.", "en": "We have dealt very corruptly against thee, and have not kept the commandments, nor the statutes, nor the judgments, which thou commandedst thy servant Moses."}, {"verse": 8, "start": 109.06, "end": 115.06, "ta": "நீங்கள் கட்டளையை மீறினால், நான் உங்களை ஜாதிகளுக்குள்ளே சிதறடிப்பேன் என்றும்,", "en": "Remember, I beseech thee, the word that thou commandedst thy servant Moses, saying, If ye transgress, I will scatter you abroad among the nations:"}, {"verse": 9, "start": 115.06, "end": 142.74, "ta": "நீங்கள் என்னிடத்தில் திரும்பி, என் கற்பனைகளைக் கைக்கொண்டு, அவைகளின்படி செய்வீர்களானால், உங்களிலே தள்ளுண்டு போனவர்கள் வானத்தின் கடையாந்தரத்தில் இருந்தாலும், நான் அங்கேயிருந்து அவர்களைச் சேர்த்து, என் நாமம் விளங்கும்படி நான் தெரிந்துகொண்ட ஸ்தலத்துக்கு அவர்களைக் கொண்டுவருவேனேன்றும் தேவரீர் உம்முடைய தாசனாகிய மோசேக்குக் கட்டளையிட்ட வார்த்தையை நினைத்தருளும்.", "en": "But if ye turn unto me, and keep my commandments, and do them; though there were of you cast out unto the uttermost part of the heaven, yet will I gather them from thence, and will bring them unto the place that I have chosen to set my name there."}, {"verse": 10, "start": 142.74, "end": 152.18, "ta": "தேவரீர் உமது மகா வல்லமையினாலும், உமது பலத்த கரத்தினாலும், மீட்டுக்கொண்ட உமது அடியாரும் உமது ஜனங்களும் இவர்கள்தானே.", "en": "Now these are thy servants and thy people, whom thou hast redeemed by thy great power, and by thy strong hand."}, {"verse": 11, "start": 152.18, "end": 179.42, "ta": "ஆண்டவரே, உமது அடியானின் ஜெபத்தையும், உமது நாமத்துக்குப் பயப்படவேண்டும் என்று விரும்புகிற உமது அடியாரின் ஜெபத்தையும் உமது செவிகள் கவனித்திருப்பதாக; இன்றைக்கு உமது அடியானுக்குக் காரியத்தைக் கைக்கூடி வரப்பண்ணி, இந்த மனுஷனுக்கு முன்பாக எனக்கு இரக்கம் கிடைக்கப்பண்ணியருளும் என்று பிரார்த்தித்தேன். நான் ராஜாவுக்குப் பானபாத்திரக்காரனாயிருந்தேன்.", "en": "O Lord, I beseech thee, let now thine ear be attentive to the prayer of thy servant, and to the prayer of thy servants, who desire to fear thy name: and prosper, I pray thee, thy servant this day, and grant him mercy in the sight of this man. For I was the king’s cupbearer."}]}, "2": {"chapter": 2, "duration": 330.58, "audio_url": "audio_ot/OT16_02.mp3", "total_verses": 20, "verses": [{"verse": 1, "start": 3.8, "end": 19.83, "ta": "அர்தசஷ்டா ராஜாவின் இருபதாம் வருஷம் நிசான் மாதத்திலே, திராட்சரசம் ராஜாவுக்கு முன்பாக வைத்திருக்கையில், நான் அதை எடுத்து அவருக்குக் கொடுத்தேன்; நான் முன் ஒருபோதும் அவர் சமுகத்தில் துக்கமாயிருந்ததில்லை.", "en": "And it came to pass in the month Nisan, in the twentieth year of Artaxerxes the king, that wine was before him: and I took up the wine, and gave it unto the king. Now I had not been beforetime sad in his presence."}, {"verse": 2, "start": 19.83, "end": 33.38, "ta": "அப்பொழுது ராஜா என்னைப்பார்த்து: நீ துக்கமுகமாயிருக்கிறது என்ன? உனக்கு வியாதியில்லையே, இது மனதின் துக்கமே ஒழிய வேறொன்றும் அல்ல என்றார்; அப்பொழுது நான் மிகவும் பயந்து,", "en": "Wherefore the king said unto me, Why is thy countenance sad, seeing thou art not sick? this is nothing else but sorrow of heart. Then I was very sore afraid,"}, {"verse": 3, "start": 33.38, "end": 50.8, "ta": "ராஜாவை நோக்கி: ராஜா என்றைக்கும் வாழ்க; என் பிதாக்களின் கல்லறைகள் இருக்கும் ஸ்தலமாகிய நகரம் பாழானதும், அதின் வாசல்கள் அக்கினியால் சுட்டெரிக்கப்பட்டதுமாய்க் கிடக்கும்போது, நான் துக்கமுகத்தோடு இராதிருப்பது எப்படி என்றேன்.", "en": "And said unto the king, Let the king live for ever: why should not my countenance be sad, when the city, the place of my fathers’ sepulchres, lieth waste, and the gates thereof are consumed with fire?"}, {"verse": 4, "start": 50.8, "end": 60.27, "ta": "அப்பொழுது ராஜா என்னைப் பார்த்து: நீ கேட்கிற காரியம் என்ன என்றார். அப்பொழுது நான்: பரலோகத்தின் தேவனை நோக்கி ஜெபம்பண்ணி,", "en": "Then the king said unto me, For what dost thou make request? So I prayed to the God of heaven."}, {"verse": 5, "start": 60.27, "end": 77.54, "ta": "ராஜாவைப் பார்த்து: ராஜாவுக்குச் சித்தமாயிருந்து, அடியேனுக்கு உமது சமுகத்தில் தயை கிடைத்ததானால், என் பிதாக்களின் கல்லறைகளிலிருக்கும் பட்டணத்தைக் கட்டும்படி, யூதா தேசத்துக்கு நீர் என்னை அனுப்பவேண்டிக்கொள்ளுகிறேன் என்றேன்.", "en": "And I said unto the king, If it please the king, and if thy servant have found favour in thy sight, that thou wouldest send me unto Judah, unto the city of my fathers’ sepulchres, that I may build it."}, {"verse": 6, "start": 77.54, "end": 98.31, "ta": "அப்பொழுது ராஜஸ்திரீயும் பக்கத்தில் உட்கார்ந்திருந்தாள். ராஜா என்னைப் பார்த்து: உன் பிரயாணம் எத்தனை நாள் செல்லும், நீ எப்பொழுது திரும்பிவருவாய் என்று கேட்டார். இவ்வளவுகாலம் செல்லுமென்று நான் ராஜாவுக்குச் சொன்னபோது, என்னை அனுப்ப அவருக்குச் சித்தமாயிற்று.", "en": "And the king said unto me, (the queen also sitting by him,) For how long shall thy journey be? and when wilt thou return? So it pleased the king to send me; and I set him a time."}, {"verse": 7, "start": 98.31, "end": 115.07, "ta": "பின்னும் நான் ராஜாவைப் பார்த்து ராஜாவுக்குச் சித்தமாயிருந்தால், நான் யூதாதேசத்துக்குப் போய்ச்சேருமட்டும், நதிக்கு அப்புறத்திலிருக்கிற தேசாதிபதிகள் என்னை வழிவிட்டனுப்பும்படிக்கு அவர்களுக்குக் கடிதங்கள் கொடுக்கும்படிக்கும்,", "en": "Moreover I said unto the king, If it please the king, let letters be given me to the governors beyond the river, that they may convey me over till I come into Judah;"}, {"verse": 8, "start": 115.07, "end": 141.08, "ta": "தேவாலயத்துக்கு இருக்கிற அரணின் கதவு வேலைக்கும், நகர அலங்கத்தின் வேலைக்கும், நான் தங்கப்போகிற வீட்டின் வேலைக்கும் வேண்டிய மரங்களை ராஜாவின் வனத்துக் காவலாளனாகிய ஆசாப் எனக்குக் கொடுக்கும்படிக்கும், அவனுக்கும் ஒரு கடிதம் கட்டளையிடப்படுவதாக என்றேன்; என் தேவனுடைய தயவுள்ள கரம் என்மேல் இருந்தபடியால், ராஜா அவைகளை எனக்குக் கட்டளையிட்டார்.", "en": "And a letter unto Asaph the keeper of the king’s forest, that he may give me timber to make beams for the gates of the palace which appertained to the house, and for the wall of the city, and for the house that I shall enter into. And the king granted me, according to the good hand of my God upon me."}, {"verse": 9, "start": 141.08, "end": 156.75, "ta": "அப்படியே நான் நதிக்கு அப்புறத்திலிருக்கிற தேசாதிபதிகளிடத்துக்கு வந்து, ராஜாவின் கடிதங்களை அவர்களுக்குக் கொடுத்தேன்; ராஜா என்னோடேகூட இராணுவச் சேர்வைக்காரரையும், குதிரைவீரரையும் அனுப்பியிருந்தார்.", "en": "Then I came to the governors beyond the river, and gave them the king’s letters. Now the king had sent captains of the army and horsemen with me."}, {"verse": 10, "start": 156.75, "end": 170.88, "ta": "இதை ஓரோனியனான சன்பல்லாத்தும், அம்மோனியனான தொபியா என்னும் ஊழியக்காரனும் கேட்டபோது, இஸ்ரவேல் புத்திரரின் நன்மையை விசாரிக்க ஒருவன் வந்தான் என்பது அவர்களுக்கு மிகவும் விசனமாயிருந்தது.", "en": "When Sanballat the Horonite, and Tobiah the servant, the Ammonite, heard of it , it grieved them exceedingly that there was come a man to seek the welfare of the children of Israel."}, {"verse": 11, "start": 170.88, "end": 175.33, "ta": "நான் எருசலேமுக்கு வந்து, அங்கே மூன்றுநாள் இருந்தபின்பு,", "en": "So I came to Jerusalem, and was there three days."}, {"verse": 12, "start": 175.33, "end": 194.57, "ta": "நான் சில மனுஷரைக் கூட்டிக்கொண்டு, ராத்திரியில் எழுந்து நகர சோதனை செய்தேன்; ஆனாலும் எருசலேமுக்காகச் செய்யும்படி என் தேவன் என் மனதிலே வைத்ததை நான் ஒருவருக்கும் அறிவிக்கவில்லை; நான் ஏறிப்போன மிருகமேயல்லாமல் வேறொரு மிருகமும் என்னோடிருந்ததில்லை.", "en": "And I arose in the night, I and some few men with me; neither told I any man what my God had put in my heart to do at Jerusalem: neither was there any beast with me, save the beast that I rode upon."}, {"verse": 13, "start": 194.57, "end": 212.2, "ta": "நான் அன்று ராத்திரி பள்ளத்தாக்கின் வாசல்வழியாய்ப் புறப்பட்டு, வலுசர்ப்பத் துரவைக் கடந்து, குப்பைமேட்டு வாசலுக்கு வந்து, எருசலேமில் இடிந்துபோன அலங்கத்தையும், அக்கினியால் சுட்டெரிக்கப்பட்ட அதின் வாசல்களையும் பார்வையிட்டேன்.", "en": "And I went out by night by the gate of the valley, even before the dragon well, and to the dung port, and viewed the walls of Jerusalem, which were broken down, and the gates thereof were consumed with fire."}, {"verse": 14, "start": 212.2, "end": 223.71, "ta": "அவ்விடத்தை விட்டு ஊருணி வாசலண்டைக்கும், ராஜாவின் குளத்தண்டைக்கும் போனேன்; நான் ஏறியிருந்த மிருகம் அங்கே நடந்துபோகிறதற்கு வழியில்லாதிருந்தது.", "en": "Then I went on to the gate of the fountain, and to the king’s pool: but there was no place for the beast that was under me to pass."}, {"verse": 15, "start": 223.71, "end": 233.84, "ta": "அன்று ராத்திரியிலேயே நான் ஆற்றோரமாய்ப் போய், அலங்கத்தைப் பார்வையிட்டுத் திரும்பி, பள்ளத்தாக்கின் வாசல்வழியாய் வந்துவிட்டேன்.", "en": "Then went I up in the night by the brook, and viewed the wall, and turned back, and entered by the gate of the valley, and so returned."}, {"verse": 16, "start": 233.84, "end": 250.16, "ta": "நான் போனதும், நான் செய்ததும் அதிகாரிகள் ஒருவருக்கும் தெரியாது; அதுவரையிலும் நான் யூதருக்காகிலும், ஆசாரியர்கள் பெரியவர்கள் அதிகாரிகளுக்காகிலும், வேலைசெய்கிற மற்றவர்களுக்காகிலும் ஒன்றும் அறிவிக்கவில்லை.", "en": "And the rulers knew not whither I went, or what I did; neither had I as yet told it to the Jews, nor to the priests, nor to the nobles, nor to the rulers, nor to the rest that did the work."}, {"verse": 17, "start": 250.16, "end": 270.28, "ta": "பின்பு நான் அவர்களை நோக்கி: எருசலேம் பாழாயிருக்கிறதையும், அதின் வாசல்கள் அக்கினியால் சுட்டெரிக்கப்பட்டுக்கிடக்கிறதையும், நாம் இருக்கிற சிறுமையையும் பார்க்கிறீர்களே; நாம் இனி நிந்தைக்குள்ளாயிராதபடிக்கு, எருசலேமின் அலங்கத்தைக் கட்டுவோம் வாருங்கள் என்று சொல்லி,", "en": "Then said I unto them, Ye see the distress that we are in, how Jerusalem lieth waste, and the gates thereof are burned with fire: come, and let us build up the wall of Jerusalem, that we be no more a reproach."}, {"verse": 18, "start": 270.28, "end": 287.98, "ta": "என் தேவனுடைய கரம் என்மேல் நன்மையாக இருக்கிறதையும், ராஜா என்னோடே சொன்ன வார்த்தைகளைய`ή் அவர்களுக்கρ அறிவித்தேனͻ அப்பெޠδுது அவர்கள்: எழுந்து கட்Οுவோம் வாருங்கள் என்று சொல்லி, அந்த நல்ல வேலைக்குத் தங்கள் கைகளைத் திடப்படுத்தினார்கள்.", "en": "Then I told them of the hand of my God which was good upon me; as also the king’s words that he had spoken unto me. And they said, Let us rise up and build. So they strengthened their hands for this good work ."}, {"verse": 19, "start": 287.98, "end": 308.17, "ta": "ஓரோனியனான சன்பல்லாத்தும், அம்மோனியனான தொபியா என்னும் ஊழியக்காரனும், அரபியனான கேஷேமும் இதைக் கேட்டபோது, எங்களைப் பரியாசம்பண்ணி, எங்களை நிந்தித்து: நீங்கள் செய்கிற இந்தக் காரியம் என்ன? நீங்கள் ராஜாவுக்கு விரோதமாகக் கலகம்பண்ணப்போகிறீர்களோ என்றார்கள்.", "en": "But when Sanballat the Horonite, and Tobiah the servant, the Ammonite, and Geshem the Arabian, heard it , they laughed us to scorn, and despised us, and said, What is this thing that ye do? will ye rebel against the king?"}, {"verse": 20, "start": 308.17, "end": 329.08, "ta": "அதற்கு நான் மறுமொழியாக: பரலோகத்தின் தேவனானவர் எங்களுக்குக் காரியத்தைக் கைகூடிவரப்பண்ணுவார்; அவருடைய ஊழியக்காரராகிய நாங்கள் எழுந்து கட்டுவோம்; உங்களுக்கோவென்றால் எருசலேமிலே பங்குமில்லை பாத்தியமுமில்லை; உங்கள் பேர் விளங்க ஒன்றும் இல்லையென்று அவர்களுடனே சொன்னேன்.", "en": "Then answered I them, and said unto them, The God of heaven, he will prosper us; therefore we his servants will arise and build: but ye have no portion, nor right, nor memorial, in Jerusalem."}]}, "3": {"chapter": 3, "duration": 450.57, "audio_url": "audio_ot/OT16_03.mp3", "total_verses": 32, "verses": [{"verse": 1, "start": 3.8, "end": 23.67, "ta": "அப்பொழுது பிரதான ஆசாரியனாகிய எலியாசீபும், அவன் சகோதரராகிய ஆசாரியர்களும் எழுந்து ஆட்டுவாசலைக் கட்டினார்கள்; அதைக் கட்டி, அவர்கள் பிரதிஷ்டைபண்ணி, அதின் கதவுகளை வைத்து, மேயா என்கிற கொம்மை முதல் அனானெயேலின் கொம்மைமட்டும் கட்டிப் பிரதிஷ்டைபண்ணினார்கள்.", "en": "Then Eliashib the high priest rose up with his brethren the priests, and they builded the sheep gate; they sanctified it, and set up the doors of it; even unto the tower of Meah they sanctified it, unto the tower of Hananeel."}, {"verse": 2, "start": 23.67, "end": 31.43, "ta": "அவன் அருகே எரிகோவின் மனுஷர் கட்டினார்கள், அவர்கள் அருகே இம்ரியின் குமாரனாகிய சக்கூர் கட்டினான்.", "en": "And next unto him builded the men of Jericho. And next to them builded Zaccur the son of Imri."}, {"verse": 3, "start": 31.43, "end": 41.95, "ta": "மீன்வாசலை அசெனாவின் குமாரர் கட்டினார்கள்; அதற்கு உத்தரம்பாவி, அதற்குக் கதவுகளையும் பூட்டுகளையும் தாழ்ப்பாள்களையும் போட்டார்கள்.", "en": "But the fish gate did the sons of Hassenaah build, who also laid the beams thereof, and set up the doors thereof, the locks thereof, and the bars thereof."}, {"verse": 4, "start": 41.95, "end": 61.24, "ta": "அவர்கள் அருகே கோசின் குமாரனாகிய உரியாவின் மகன் மெரெமோத் பழுதுபார்த்துக் கட்டினான்; அவர்கள் அருகே மெஷேசாபெயேலின் குமாரனாகிய பெரகியாவின் மகன் மெசுல்லாம் பழுதுபார்த்துக் கட்டினான்; அவர்கள் அருகே பானாவின் குமாரனாகிய சாதோக் பழுதுபார்த்துக் கட்டினான்.", "en": "And next unto them repaired Meremoth the son of Urijah, the son of Koz. And next unto them repaired Meshullam the son of Berechiah, the son of Meshezabeel. And next unto them repaired Zadok the son of Baana."}, {"verse": 5, "start": 61.24, "end": 72.85, "ta": "அவர்கள் அருகே தெக்கோவா ஊரார் பழுதுபார்த்துக் கட்டினார்கள்; அவர்களுடைய பிரபுக்களோ, தங்கள் ஆண்டவருடைய வேலைக்குத் தங்கள் கழுத்தைக் கொடுக்கவில்லை.", "en": "And next unto them the Tekoites repaired; but their nobles put not their necks to the work of their Lord."}, {"verse": 6, "start": 72.85, "end": 89.31, "ta": "பழைய வாசலைப் பசெயாசின் குமாரனாகிய யோய்தாவும், பேசோதியாவின் குமாரனாகிய மெசுல்லாமும் பழுதுபார்த்துக் கட்டினார்கள்; அவர்கள் அதற்கு உத்தரம்பாவி, அதற்குக் கதவுகளையும் பூட்டுகளையும் தாழ்ப்பாள்களையும் போட்டார்கள்.", "en": "Moreover the old gate repaired Jehoiada the son of Paseah, and Meshullam the son of Besodeiah; they laid the beams thereof, and set up the doors thereof, and the locks thereof, and the bars thereof."}, {"verse": 7, "start": 89.31, "end": 104.11, "ta": "அவர்கள் அருகே கிபியோன் மிஸ்பா ஊர்களின் மனுஷரான மெலதீயா என்னும் கிபியோனியனும் யாதோன் என்னும் மெரொனோத்தியனும், நதிக்கு இப்புறத்திலிருக்கிற அதிபதியின் சமஸ்தானமட்டும் பழுதுபார்த்துக் கட்டினார்கள்.", "en": "And next unto them repaired Melatiah the Gibeonite, and Jadon the Meronothite, the men of Gibeon, and of Mizpah, unto the throne of the governor on this side the river."}, {"verse": 8, "start": 104.11, "end": 122.46, "ta": "அவர்கள் அருகே தட்டாரில் ஒருவனாகிய அராயாவின் குமாரன் ஊசியேல் பழுதுபார்த்துக் கட்டினான்; அவன் அருகே தைலக்காரரில் ஒருவன் குமாரனாகிய அனனியா பழுதுபார்த்துக்கட்டினான்; அதுமுதற்கொண்டு அகலமான மதில் மட்டும் எருசலேம் இடிக்காமல் விட்டிருந்தது.", "en": "Next unto him repaired Uzziel the son of Harhaiah, of the goldsmiths. Next unto him also repaired Hananiah the son of one of the apothecaries, and they fortified Jerusalem unto the broad wall."}, {"verse": 9, "start": 122.46, "end": 130.8, "ta": "அவர்கள் அருகே எருசலேம் பட்டணத்தின் பாதிக்குப் பிரபுவாகிய ஊரின் குமாரன் ரெப்பாயா பழுதுபார்த்துக் கட்டினான்.", "en": "And next unto them repaired Rephaiah the son of Hur, the ruler of the half part of Jerusalem."}, {"verse": 10, "start": 130.8, "end": 143.57, "ta": "அவர்கள் அருகே அருமாப்பின் குமாரன் யெதாயா தன் வீட்டுக்கு எதிரானதைப் பழுதுபார்த்துக் கட்டினான்; அவன் அருகே ஆசாப்நெயாவின் குமாரன் அத்தூஸ் பழுதுபார்த்துக் கட்டினான்.", "en": "And next unto them repaired Jedaiah the son of Harumaph, even over against his house. And next unto him repaired Hattush the son of Hashabniah."}, {"verse": 11, "start": 143.57, "end": 154.38, "ta": "மற்றப் பங்கையும், சூளைகளின் கொம்மையையும், ஆரீமின் குமாரன் மல்கிஜாவும், பாகாத்மோவாபின் குமாரன் அசூபும் பழுதுபார்த்துக் கட்டினார்கள்.", "en": "Malchijah the son of Harim, and Hashub the son of Pahath-moab, repaired the other piece, and the tower of the furnaces."}, {"verse": 12, "start": 154.38, "end": 165.11, "ta": "அவன் அருகே எருசலேம் பட்டணத்தின் மறுபாதிக்குப் பிரபுவாகிய அலோகேசின் குமாரன் சல்லுூமும், அவன் குமாரத்திகளும் பழுதுபார்த்துக் கட்டினார்கள்.", "en": "And next unto him repaired Shallum the son of Halohesh, the ruler of the half part of Jerusalem, he and his daughters."}, {"verse": 13, "start": 165.11, "end": 183.24, "ta": "பள்ளத்தாக்கின் வாசலை ஆனூனும், சானோவாகின் குடிகளும் பழுதுபார்த்துக் கட்டினார்கள்; அவர்கள் அதைக் கட்டி, அதற்குக் கதவுகளையும் பூட்டுகளையும் தாழ்ப்பாள்களையும் போட்டு, குப்பைமேட்டு வாசல்மட்டாக அலங்கத்தில் ஆயிரம் முழம் கட்டினார்கள்.", "en": "The valley gate repaired Hanun, and the inhabitants of Zanoah; they built it, and set up the doors thereof, the locks thereof, and the bars thereof, and a thousand cubits on the wall unto the dung gate."}, {"verse": 14, "start": 183.24, "end": 196.59, "ta": "குப்பைமேட்டு வாசலைப் பெத்கேரேமின் மகாணத்துப் பிரபுவாகிய ரெக்காவின் குமாரன் மல்கியா பழுதுபார்த்து அதைக் கட்டி, அதற்குக் கதவுகளையும் பூட்டுகளையும் தாழ்ப்பாள்களையும் போட்டான்.", "en": "But the dung gate repaired Malchiah the son of Rechab, the ruler of part of Beth-haccerem; he built it, and set up the doors thereof, the locks thereof, and the bars thereof."}, {"verse": 15, "start": 196.59, "end": 221.54, "ta": "ஊருணிவாசலை மிஸ்பாவின் மாகாணத்துப் பிரபுவாகிய கொல்லோசேயின் குமாரன் சல்லுூம் பழுதுபார்த்து, அதைக் கட்டி மச்சுப்பாவி, அதற்குக் கதவுகளையும் பூட்டுகளையும் தாழ்ப்பாள்களையும் போட்டு, ராஜாவின் சிங்காரத் தோட்டத்தண்டையிலிருக்கிற சீலோவாவின் குளத்து மதிலையும், தாவீதின் நகரத்திலிருந்து இறங்குகிற படிகள் மட்டாக இருக்கிறதையும் கட்டினான்.", "en": "But the gate of the fountain repaired Shallun the son of Col-hozeh, the ruler of part of Mizpah; he built it, and covered it, and set up the doors thereof, the locks thereof, and the bars thereof, and the wall of the pool of Siloah by the king’s garden, and unto the stairs that go down from the city of David."}, {"verse": 16, "start": 221.54, "end": 239.67, "ta": "அவனுக்குப் பின்னாகப் பெத்சூர் மாகாணத்தின் பாதிக்குப் பிரபுவாகிய அஸ்பூகின் குமாரன் நெகேமியா தாவீதின் கல்லறைகளுக்கு எதிரான இடமட்டாகவும், வெட்டப்பட்ட குளமட்டாகவும், பராக்கிரமசாலிகளின் வீடுமட்டாகவும் இருக்கிறதைப் பழுதுபார்த்துக் கட்டினான்.", "en": "After him repaired Nehemiah the son of Azbuk, the ruler of the half part of Beth-zur, unto the place over against the sepulchres of David, and to the pool that was made, and unto the house of the mighty."}, {"verse": 17, "start": 239.67, "end": 252.44, "ta": "அவனுக்குப் பின்னாக லேவியரில் பானியின் குமாரன் ரேகூமும், அவன் அருகே கேகிலா மாகாணத்தில் தன்னுடைய பாதிப்பங்குக்குப் பிரபுவாகிய அசபியாவும் பழுதுபார்த்துக் கட்டினார்கள்.", "en": "After him repaired the Levites, Rehum the son of Bani. Next unto him repaired Hashabiah, the ruler of the half part of Keilah, in his part."}, {"verse": 18, "start": 252.44, "end": 262.52, "ta": "அவனுக்குப் பின்னாக அவனுடைய சகோதரரில் கேகிலா மாகாணத்து மறுபாதிக்குப் பிரபுவாகிய எனாதாதின் குமாரன் பாபாயி பழுதுபார்த்துக் கட்டினான்.", "en": "After him repaired their brethren, Bavai the son of Henadad, the ruler of the half part of Keilah."}, {"verse": 19, "start": 262.52, "end": 274.92, "ta": "அவன் அருகே மிஸ்பாவின் பிரபுவாகிய யெசுவாவின் குமாரன் ஏசர் என்பவன் மதிலின் கோடியிலே ஆயுதசாலையின் படிகளுக்கு எதிரேயிருக்கிற வேறொரு பங்கைப் பழுதுபார்த்துக் கட்டினான்.", "en": "And next to him repaired Ezer the son of Jeshua, the ruler of Mizpah, another piece over against the going up to the armoury at the turning of the wall ."}, {"verse": 20, "start": 274.92, "end": 288.85, "ta": "அவனுக்குப் பின்னாகச் சாபாயின் குமாரன் பாரூக் அந்தக் கோடி துவக்கிப் பிரதான ஆசாரியனாகிய எலியாசீபின் வாசற்படிமட்டும் இருக்கிற பின்னொரு பங்கை வெகு ஜாக்கிரதையோடே பழுதுபார்த்துக் கட்டினான்.", "en": "After him Baruch the son of Zabbai earnestly repaired the other piece, from the turning of the wall unto the door of the house of Eliashib the high priest."}, {"verse": 21, "start": 288.85, "end": 302.92, "ta": "அவனுக்குப் பின்னாகக் கோசின் குமாரனாகிய உரியாவின் மகன் மெரெமோத் எலியாசீபின் வீட்டு வாசற்படி துவக்கி அவனுடைய வீட்டின் கடைக்கோடிமட்டும் இருக்கிற பின்னொரு பங்கைப் பழுதுபார்த்துக் கட்டினான்.", "en": "After him repaired Meremoth the son of Urijah the son of Koz another piece, from the door of the house of Eliashib even to the end of the house of Eliashib."}, {"verse": 22, "start": 302.92, "end": 310.24, "ta": "அவனுக்குப் பின்னாகச் சமனான பூமியில் வாசமாயிருக்கிற ஆசாரியர்கள் பழுதுபார்த்துக் கட்டினார்கள்.", "en": "And after him repaired the priests, the men of the plain."}, {"verse": 23, "start": 310.24, "end": 328.6, "ta": "அவர்களுக்குப் பின்னாக பென்யமீனும், அசூபும் தங்கள் வீட்டுக்கு எதிரே இருக்கிறதைப் பழுதுபார்த்துக் கட்டினார்கள்; அவர்களுக்குப் பின்னாக அனனியாவின் குமாரனாகிய மாசேயாவின் மகன் அசரியா தன் வீட்டின் அருகே இருக்கிறதைப் பழுதுபார்த்துக் கட்டினான்.", "en": "After him repaired Benjamin and Hashub over against their house. After him repaired Azariah the son of Maaseiah the son of Ananiah by his house."}, {"verse": 24, "start": 328.6, "end": 340.27, "ta": "அவனுக்குப் பின்னாக எனாதாதின் குமாரன் பின்னூவி அசரியாவின் வீடு துவக்கி அலங்கத்துக் கோடி வளைவுவரைக்கும் இருக்கிற வேறொரு பங்கைப் பழுதுபார்த்துக் கட்டினான்.", "en": "After him repaired Binnui the son of Henadad another piece, from the house of Azariah unto the turning of the wall , even unto the corner."}, {"verse": 25, "start": 340.27, "end": 356.96, "ta": "ஊசாயின் குமாரன் பாலால் வளைவுக்கு எதிரேயும், காவல் வீட்டின் முற்றத்துக்கடுத்த ராஜாவின் உயரமான அரமனைக்கு வெளிப்புறமாயிருக்கிற கொம்மைக்கு எதிரேயும் இருக்கிறதைக் கட்டினான்; அவனுக்குப் பின்னாகப் பாரோஷின் குமாரன் பெதாயாவும்,", "en": "Palal the son of Uzai, over against the turning of the wall , and the tower which lieth out from the king’s high house, that was by the court of the prison. After him Pedaiah the son of Parosh."}, {"verse": 26, "start": 356.96, "end": 368.42, "ta": "ஓபேலிலே குடியிருக்கிற நிதனீமியரைச் சேர்ந்த மனிதரும் கிழக்கேயிருக்கிற தண்ணீர் வாசலுக்கு வெளிப்புறமான கொம்மைக்கு எதிரேயிருக்கிற இடமட்டும் கட்டினார்கள்.", "en": "Moreover the Nethinims dwelt in Ophel, unto the place over against the water gate toward the east, and the tower that lieth out."}, {"verse": 27, "start": 368.42, "end": 380.02, "ta": "அவர்களுக்குப் பின்னாகத் தெக்கோவா ஊரார் வெளிப்புறமான பெரிய கொம்மைக்கு எதிரே ஓபேலின் மதில்மட்டும் இருக்கிற பின்னொரு பங்கைப் பழுதுபார்த்துக் கட்டினார்கள்.", "en": "After them the Tekoites repaired another piece, over against the great tower that lieth out, even unto the wall of Ophel."}, {"verse": 28, "start": 380.02, "end": 388.65, "ta": "குதிரைவாசல் முதற்கொண்டு ஆசாரியர்கள் அவரவர் தங்கள் வீடுகளுக்கு எதிரே இருக்கிறதைப் பழுதுபார்த்துக் கட்டினார்கள்.", "en": "From above the horse gate repaired the priests, every one over against his house."}, {"verse": 29, "start": 388.65, "end": 404.83, "ta": "அவர்களுக்குப் பின்னாக இம்மேரின் குமாரன் சாதோக் தன் வீட்டுக்கு எதிரே இருக்கிறதைப் பழுதுபார்த்துக் கட்டினான்; அவனுக்குப் பின்னாகக் கிழக்கு வாசலைக் காக்கிற செக்கனியாவின் குமாரன் செமாயா பழுதுபார்த்துக் கட்டினான்.", "en": "After them repaired Zadok the son of Immer over against his house. After him repaired also Shemaiah the son of Shechaniah, the keeper of the east gate."}, {"verse": 30, "start": 404.83, "end": 424.92, "ta": "அவனுக்குப் பின்னாகச் செல்மீயாவின் குமாரன் அனனியாவும், சாலாபின் ஆறாவது குமாரனாகிய ஆனூனும், வேறொரு பங்கைப் பழுதுபார்த்துக்கட்டினார்கள்; அவர்களுக்குப் பின்னாகப் பெரகியாவின் குமாரன் மெசுல்லாம், தன் அறைவீட்டுக்கு எதிரே இருக்கிறதைப் பழுதுபார்த்துக் கட்டினான்.", "en": "After him repaired Hananiah the son of Shelemiah, and Hanun the sixth son of Zalaph, another piece. After him repaired Meshullam the son of Berechiah over against his chamber."}, {"verse": 31, "start": 424.92, "end": 440.0, "ta": "அவனுக்குப் பின்னாகத் தட்டானின் குமாரன் மல்கியா மிப்காத் என்னும் வாசலுக்கு எதிரே நிதனீமியரும் மளிகைக்காரரும் குடியிருக்கிற ஸ்தலமுதல் கோடியின் மேல்வீடுமட்டாகவும் இருக்கிறதைப் பழுதுபார்த்துக் கட்டினான்.", "en": "After him repaired Malchiah the goldsmith’s son unto the place of the Nethinims, and of the merchants, over against the gate Miphkad, and to the going up of the corner."}, {"verse": 32, "start": 440.0, "end": 449.07, "ta": "கோடியின் மேல்வீட்டுக்கும் ஆட்டுவாசலுக்கும் நடுவே இருக்கிறதைத் தட்டாரும் மளிகைக்காரரும் பழுதுபார்த்துக் கட்டினார்கள்.", "en": "And between the going up of the corner unto the sheep gate repaired the goldsmiths and the merchants."}]}, "4": {"chapter": 4, "duration": 298.03, "audio_url": "audio_ot/OT16_04.mp3", "total_verses": 23, "verses": [{"verse": 1, "start": 3.8, "end": 12.46, "ta": "நாங்கள் அலங்கத்தைக் கட்டுகிற செய்தியைச் சன்பல்லாத் கேட்டபோது, அவன் கோபித்து, எரிச்சலடைந்து, யூதரைச் சக்கந்தம்பண்ணி:", "en": "But it came to pass, that when Sanballat heard that we builded the wall, he was wroth, and took great indignation, and mocked the Jews."}, {"verse": 2, "start": 12.46, "end": 31.74, "ta": "அந்த அற்பமான யூதர் செய்கிறது என்ன, அவர்களுக்கு இடங்கொடுக்கப்படுமோ, பலியிடுவார்களோ, ஒருநாளிலே முடித்துப்போடுவார்களோ, சுட்டெரித்துப் போடப்பட்டு மண்மேடுகளான கற்களுக்கு உயிர் கொடுப்பார்களோ, என்று தன் சகோதரருக்கும் சமாரியாவின் சேனைக்கும் முன்பாகச் சொன்னான்.", "en": "And he spake before his brethren and the army of Samaria, and said, What do these feeble Jews? will they fortify themselves? will they sacrifice? will they make an end in a day? will they revive the stones out of the heaps of the rubbish which are burned?"}, {"verse": 3, "start": 31.74, "end": 42.64, "ta": "அப்பொழுது அம்மோனியனாகிய தொபியா அவன் பக்கத்தில் நின்று: அவர்கள் கட்டினாலும் என்ன, ஒரு நரி ஏறிப்போனால் அவர்களுடைய கல் மதில் இடிந்துபோகும் என்றான்.", "en": "Now Tobiah the Ammonite was by him, and he said, Even that which they build, if a fox go up, he shall even break down their stone wall."}, {"verse": 4, "start": 42.64, "end": 55.63, "ta": "எங்கள் தேவனே, நாங்கள் அவமதிக்கப்படுகிறதைக் கேட்டு, அவர்கள் நிந்திக்கிற நிந்தையை அவர்கள் தலையின்மேல் திருப்பி, அவர்களைச் சிறையிருப்பின் தேசத்திலே சூறைக்கு ஒப்புக்கொடும்.", "en": "Hear, O our God; for we are despised: and turn their reproach upon their own head, and give them for a prey in the land of captivity:"}, {"verse": 5, "start": 55.63, "end": 66.8, "ta": "அவர்கள் அக்கிரமத்தை மூடிப்போடாதேயும்; அவர்கள் பாவம் உமக்கு முன்பாகக் கொலைக்கப்படாதிருப்பதாக; கட்டுகிறவர்களுக்கு மனமடிவுண்டாகப் பேசினார்களே.", "en": "And cover not their iniquity, and let not their sin be blotted out from before thee: for they have provoked thee to anger before the builders."}, {"verse": 6, "start": 66.8, "end": 77.35, "ta": "நாங்கள் அலங்கத்தைக் கட்டிவந்தோம்; அலங்கமெல்லாம் பாதிமட்டும் ஒன்றாய் இணைந்து உயர்ந்தது; ஜனங்கள் வேலைசெய்கிறதற்கு ஆவலாயிருந்தார்கள்.", "en": "So built we the wall; and all the wall was joined together unto the half thereof: for the people had a mind to work."}, {"verse": 7, "start": 77.35, "end": 93.48, "ta": "எருசலேமின் அலங்கத்தைக் கட்டுகிற வேலை வளர்ந்தேறுகிறது என்றும் இடிக்கப்பட்ட இடங்கள் அடைபட்டுவருகிறது என்றும் சன்பல்லாத்தும், தொபியாவும், அரபியரும், அம்மோனியரும், அஸ்தோத்தியரும் கேட்டபோது, அவர்கள் மிகவும் எரிச்சலாகி,", "en": "But it came to pass, that when Sanballat, and Tobiah, and the Arabians, and the Ammonites, and the Ashdodites, heard that the walls of Jerusalem were made up, and that the breaches began to be stopped, then they were very wroth,"}, {"verse": 8, "start": 93.48, "end": 100.82, "ta": "எருசலேமின்மேல் யுத்தம்பண்ண எல்லாரும் ஏகமாய் வரவும் வேலையைத் தடுக்கவும் கட்டுப்பாடு பண்ணினார்கள்.", "en": "And conspired all of them together to come and to fight against Jerusalem, and to hinder it."}, {"verse": 9, "start": 100.82, "end": 109.13, "ta": "ஆனாலும் நாங்கள் எங்கள் தேவனை நோக்கி ஜெபம்பண்ணி, அவர்கள் நிமித்தம் இரவும்பகலும் ஜாமங்காக்கிறவர்களை வைத்தோம்.", "en": "Nevertheless we made our prayer unto our God, and set a watch against them day and night, because of them."}, {"verse": 10, "start": 109.13, "end": 119.54, "ta": "அப்பொழுது யூதா மனிதர்: சுமைகாரரின் பெலன் குறைந்துபோகிறது, மண்மேடு மிச்சமாயிருக்கிறது; நாங்கள் அலங்கத்தைக் கட்டக் கூடாது என்றார்கள்.", "en": "And Judah said, The strength of the bearers of burdens is decayed, and there is much rubbish; so that we are not able to build the wall."}, {"verse": 11, "start": 119.54, "end": 133.86, "ta": "எங்கள் சத்துருக்களோவென்றால்: நாங்கள் அவர்கள் நடுவே வந்து, அவர்களைக் கொன்றுபோடுமட்டும், அவர்கள் அதை அறியாமலும் பாராமலும் இருக்கவேண்டும்; இவ்விதமாய் அந்த வேலையை ஓயப்பண்ணுவோம் என்றார்கள்.", "en": "And our adversaries said, They shall not know, neither see, till we come in the midst among them, and slay them, and cause the work to cease."}, {"verse": 12, "start": 133.86, "end": 143.35, "ta": "அதை அவர்களண்டையிலே குடியிருக்கிற யூதரும், பல இடங்களிலுமிருந்து எங்களிடத்துக்கு வந்து, பத்துவிசை எங்களுக்குச் சொன்னார்கள்.", "en": "And it came to pass, that when the Jews which dwelt by them came, they said unto us ten times, From all places whence ye shall return unto us they will be upon you ."}, {"verse": 13, "start": 143.35, "end": 156.98, "ta": "அப்பொழுது நான் அலங்கத்துக்குப் பின்னாக இருக்கிற பள்ளமான இடங்களிலும் மேடுகளிலும் பட்டயங்களையும், ஈட்டிகளையும் வில்லுகளையும் பிடித்திருக்கிற ஜனங்களைக் குடும்பங் குடும்பமாக நிறுத்தினேன்.", "en": "Therefore set I in the lower places behind the wall, and on the higher places, I even set the people after their families with their swords, their spears, and their bows."}, {"verse": 14, "start": 156.98, "end": 181.63, "ta": "அதை நான் பார்த்து எழும்பி, பிரபுக்களையும் அதிகாரிகளையும் மற்ற ஜனங்களையும் நோக்கி: அவர்களுக்குப் பயப்படாதிருங்கள்; நீங்கள் மகத்துவமும் பயங்கரமுமான ஆண்டவரை நினைத்து, உங்கள் சகோதரருக்காகவும், உங்கள் குமாரருக்காகவும், உங்கள் குமாரத்திகளுக்காகவும், உங்கள் மனைவிகளுக்காகவும், உங்கள் வீடுகளுக்காகவும் யுத்தம்பண்ணுங்கள் என்றேன்.", "en": "And I looked, and rose up, and said unto the nobles, and to the rulers, and to the rest of the people, Be not ye afraid of them: remember the Lord, which is great and terrible, and fight for your brethren, your sons, and your daughters, your wives, and your houses."}, {"verse": 15, "start": 181.63, "end": 195.88, "ta": "எங்களுக்குச் செய்தி தெரியவந்ததென்றும், தேவன் அவர்கள் ஆலோசனையை அபத்தமாக்கினாரென்றும், எங்கள் பகைஞர் கேட்டபோது, நாங்கள் எல்லோரும் அவரவர் தங்கள் வேலையைச் செய்ய அலங்கத்துக்குத் திரும்பினோம்.", "en": "And it came to pass, when our enemies heard that it was known unto us, and God had brought their counsel to nought, that we returned all of us to the wall, every one unto his work."}, {"verse": 16, "start": 195.88, "end": 211.88, "ta": "அன்று முதற்கொண்டு என் வேலைக்காரரில் பாதிப்பேர் வேலைசெய்தார்கள், பாதிப்பேர் ஈட்டிகளையும் பரிசைகளையும் வில்லுகளையும் கவசங்களையும் பிடித்து நின்றார்கள்; அதிகாரிகள் யூதா வம்சத்தார் எல்லாருக்கும் பின்னாக நின்றார்கள்.", "en": "And it came to pass from that time forth, that the half of my servants wrought in the work, and the other half of them held both the spears, the shields, and the bows, and the habergeons; and the rulers were behind all the house of Judah."}, {"verse": 17, "start": 211.88, "end": 223.47, "ta": "அலங்கத்திலே கட்டுகிறவர்களும், சுமைசுமக்கிறவர்களும், சுமையேற்றுகிறவர்களும், அவரவர் ஒரு கையினாலே வேலைசெய்து, மறுகையினாலே ஆயுதம் தரித்திருந்தார்கள்.", "en": "They which builded on the wall, and they that bare burdens, with those that laded, every one with one of his hands wrought in the work, and with the other hand held a weapon."}, {"verse": 18, "start": 223.47, "end": 234.09, "ta": "கட்டுகிறவர்கள் அவரவர் தங்கள் பட்டயத்தைத் தங்கள் இடுப்பிலே கட்டிக்கொண்டவர்களாய் வேலைசெய்தார்கள்; எக்காளம் ஊதுகிறவன் என்னண்டையிலே நின்றான்.", "en": "For the builders, every one had his sword girded by his side, and so builded. And he that sounded the trumpet was by me."}, {"verse": 19, "start": 234.09, "end": 246.8, "ta": "நான் பிரபுக்களையும் அதிகாரிகளையும் மற்ற ஜனங்களையும் நோக்கி: வேலை பெரிதும் விஸ்தாரமுமாயிருக்கிறது; நாம் அலங்கத்தின்மேல் சிதறப்பட்டு ஒருவருக்கு ஒருவர் தூரமாயிருக்கிறோம்.", "en": "And I said unto the nobles, and to the rulers, and to the rest of the people, The work is great and large, and we are separated upon the wall, one far from another."}, {"verse": 20, "start": 246.8, "end": 258.04, "ta": "நீங்கள் எவ்விடத்திலே எக்காளச் சத்தத்தைக் கேட்கிறீர்களோ அவ்விடத்திலே வந்து, எங்களோடே கூடுங்கள்; நம்முடைய தேவன் நமக்காக யுத்தம்பண்ணுவார் என்றேன்.", "en": "In what place therefore ye hear the sound of the trumpet, resort ye thither unto us: our God shall fight for us."}, {"verse": 21, "start": 258.04, "end": 269.57, "ta": "இப்படியே நாங்கள் வேலைசெய்துகொண்டிருந்தோம்; அவர்களிலே பாதிப்பேர் கிழக்கு வெளுக்கும் நேரமுதல் நட்சத்திரங்கள் காணுமட்டும் ஈட்டிகளைப் பிடித்திருந்தார்கள்.", "en": "So we laboured in the work: and half of them held the spears from the rising of the morning till the stars appeared."}, {"verse": 22, "start": 269.57, "end": 282.21, "ta": "அக்காலத்திலே நான் ஜனங்களைப் பார்த்து: இராமாறு நமக்குக் காவலுக்கும் பகல்மாறு வேலைக்கும் உதவ, அவரவர் தங்கள் வேலைக்காரரோடுங்கூட எருசலேமுக்குள்ளே இராத்தங்கக்கடவர்கள் என்று சொல்லி,", "en": "Likewise at the same time said I unto the people, Let every one with his servant lodge within Jerusalem, that in the night they may be a guard to us, and labour on the day."}, {"verse": 23, "start": 282.21, "end": 296.53, "ta": "நானாகிலும், என் சகோதரராகிலும், என் வேலைக்காரராகிலும், என்னைப் பின்பற்றி காவல்காக்கிற சேவகராகிலும் எங்கள் வஸ்திரங்களைக் களைந்துபோடாதிருந்தோம்; அவரவருக்கு ஆயுதமும் தண்ணீரும் இருந்தது.", "en": "So neither I, nor my brethren, nor my servants, nor the men of the guard which followed me, none of us put off our clothes, saving that every one put them off for washing."}]}, "5": {"chapter": 5, "duration": 311.78, "audio_url": "audio_ot/OT16_05.mp3", "total_verses": 19, "verses": [{"verse": 1, "start": 3.8, "end": 12.43, "ta": "ஜனங்களுக்குள் அநேகரும் அவர்களுடைய ஸ்திரீகளும் யூதராகிய தங்கள் சகோதரர்மேல் முறையிடுகிற பெரிய கூக்குரலுண்டாயிற்று.", "en": "And there was a great cry of the people and of their wives against their brethren the Jews."}, {"verse": 2, "start": 12.43, "end": 26.34, "ta": "அதென்னவென்றால், அவர்களில் சிலர் நாங்கள் எங்கள் குமாரரோடும் எங்கள் குமாரத்திகளோடும் அநேகரானபடியினால், சாப்பிட்டுப் பிழைக்கும்படிக்கு நாங்கள் தானியத்தைக் கடனாக வாங்கினோம் என்றார்கள்.", "en": "For there were that said, We, our sons, and our daughters, are many: therefore we take up corn for them , that we may eat, and live."}, {"verse": 3, "start": 26.34, "end": 38.26, "ta": "வேறு சிலர் எங்கள் நிலங்களையும் எங்கள் திராட்சத்தோட்டங்களையும் எங்கள் வீடுகளையும் நாங்கள் அடைமானமாக வைத்து, இந்தப் பஞ்சத்திலே தானியம் வாங்கினோம் என்றார்கள்.", "en": "Some also there were that said, We have mortgaged our lands, vineyards, and houses, that we might buy corn, because of the dearth."}, {"verse": 4, "start": 38.26, "end": 49.1, "ta": "இன்னும் சிலர் ராஜாவுக்குத் தீர்வைசெலுத்த, நாங்கள் எங்கள் நிலங்கள்மேலும் எங்கள் திராட்சத்தோட்டங்கள்மேலும், பணத்தைக் கடனாக வாங்கினோம் என்றும்;", "en": "There were also that said, We have borrowed money for the king’s tribute, and that upon our lands and vineyards."}, {"verse": 5, "start": 49.1, "end": 79.71, "ta": "எங்கள் உடலும் எங்கள் சகோதரர் உடலும் சரி; எங்கள் பிள்ளைகளும் அவர்கள் பிள்ளைகளும் சரி; ஆனாலும், இதோ நாங்கள் எங்கள் குமாரரையும் எங்கள் குமாரத்திகளையும் அடிமைத்தனத்திற்கு உட்படுத்தவேண்டியதாயிருக்கிறது; அப்படியே எங்கள் குமாரத்திகளில் சிலர் அடிமைப்பட்டுமிருக்கிறார்கள்; அவர்களை மீட்க எங்களுக்கு நிர்வாகமில்லை; எங்கள் நிலங்களும் எங்கள் திராட்சத்தோட்டங்களும் வேறே மனிதர் கைவசமாயிற்று என்றார்கள்.", "en": "Yet now our flesh is as the flesh of our brethren, our children as their children: and, lo, we bring into bondage our sons and our daughters to be servants, and some of our daughters are brought unto bondage already: neither is it in our power to redeem them; for other men have our lands and vineyards."}, {"verse": 6, "start": 79.71, "end": 85.98, "ta": "அவர்கள் கூக்குரலையும், இந்தவார்த்தைகளையும் நான் கேட்டபோது, மிகவும் கோபங்கொண்டு,", "en": "And I was very angry when I heard their cry and these words."}, {"verse": 7, "start": 85.98, "end": 101.04, "ta": "என் மனதிலே ஆலோசனைபண்ணி, பிற்பாடு பிரபுக்களையும் அதிகாரிகளையும் கடிந்துகொண்டு: நீங்கள் அவரவர் தங்கள் சகோதரர்மேல் ஏன் வட்டி சுமத்துகிறீர்கள் என்று சொல்லி, அவர்களுக்கு விரோதமாக ஒரு பெரிய சபைகூடிவரச்செய்து,", "en": "Then I consulted with myself, and I rebuked the nobles, and the rulers, and said unto them, Ye exact usury, every one of his brother. And I set a great assembly against them."}, {"verse": 8, "start": 101.04, "end": 122.65, "ta": "அவர்களை நோக்கி: புறஜாதியாருக்கு விற்கப்பட்ட யூதராகிய எங்கள் சகோதரரை நாங்கள் எங்கள் சக்திக்குத்தக்கதாய் மீட்டிருக்கையில், நீங்கள் திரும்ப உங்கள் சகோதரரை விற்கலாமா? இவர்கள் நமக்கு விலைப்பட்டுப்போகலாமா என்றேன்; அப்பொழுது அவர்கள் மறு உத்தரவு சொல்ல இடமில்லாமல் மவுனமாயிருந்தார்கள்.", "en": "And I said unto them, We after our ability have redeemed our brethren the Jews, which were sold unto the heathen; and will ye even sell your brethren? or shall they be sold unto us? Then held they their peace, and found nothing to answer ."}, {"verse": 9, "start": 122.65, "end": 135.71, "ta": "பின்னும் நான் அவர்களை நோக்கி: நீங்கள் செய்கிற காரியம் நல்லதல்ல; நம்முடைய பகைஞராகிய புறஜாதியார் நிந்திக்கிறதினிமித்தம் நீங்கள் நம்முடைய தேவனுக்குப் பயந்து நடக்கவேண்டாமா?", "en": "Also I said, It is not good that ye do: ought ye not to walk in the fear of our God because of the reproach of the heathen our enemies?"}, {"verse": 10, "start": 135.71, "end": 146.62, "ta": "நானும் என் சகோதரரும் என் வேலைக்காரரும் இவ்விதமாகவா அவர்களுக்குப் பணமும் தானியமும் கடன்கொடுத்திருக்கிறோம்? இந்த வட்டியை விட்டுவிடுவோமாக.", "en": "I likewise, and my brethren, and my servants, might exact of them money and corn: I pray you, let us leave off this usury."}, {"verse": 11, "start": 146.62, "end": 169.52, "ta": "நீங்கள் இன்றைக்கு அவர்கள் நிலங்களையும், அவர்கள் திராட்சத்தோட்டங்களையும், அவர்கள் ஒலிவத்தோப்புகளையும், அவர்கள் வீடுகளையும், நீங்கள் பணத்திலும் தானியத்திலும் திராட்சரசத்திலும் எண்ணெயிலும் நூற்றுக்கொன்று வீதமாக அவர்களிடத்தில் தண்டிவருகிற வட்டியையும், அவர்களுக்குத் திரும்பக்கொடுத்துவிடுங்கள் என்றேன்.", "en": "Restore, I pray you, to them, even this day, their lands, their vineyards, their oliveyards, and their houses, also the hundredth part of the money, and of the corn, the wine, and the oil, that ye exact of them."}, {"verse": 12, "start": 169.52, "end": 188.57, "ta": "அதற்கு அவர்கள் நாங்கள் அதைத் திரும்பக் கொடுத்துவிட்டு, இனி அப்படி அவர்களிடத்தில் கேட்கமாட்டோம்; நீர் சொல்லுகிறபடியே செய்வோம் என்றார்கள்; அப்பொழுது நான் ஆசாரியர்களை அழைத்து, அவர்கள் இந்த வார்த்தையின்படி செய்ய அவர்களை ஆணையிடுவித்துக்கொண்டேன்.", "en": "Then said they, We will restore them , and will require nothing of them; so will we do as thou sayest. Then I called the priests, and took an oath of them, that they should do according to this promise."}, {"verse": 13, "start": 188.57, "end": 215.75, "ta": "நான் என் வஸ்திரத்தை உதறிப்போட்டு, இப்படி இந்த வார்த்தையை நிறைவேற்றாத எந்த மனிதனையும் அவன் வீட்டிலும் அவன் சம்பாத்தியத்திலும் இருந்து தேவன் உதறிப்போடக்கடவர்; இந்தப்பிரகாரமாக அவன் உதறிப்போடப்பட்டு, வெறுமையாய்ப் போவானாக என்றேன்; அதற்குச் சபையார் எல்லாரும் ஆமென் என்று சொல்லி கர்த்தரைத் துதித்தார்கள்; பின்பு ஜனங்கள் இந்த வார்த்தையின்படியே செய்தார்கள்.", "en": "Also I shook my lap, and said, So God shake out every man from his house, and from his labour, that performeth not this promise, even thus be he shaken out, and emptied. And all the congregation said, Amen, and praised the LORD . And the people did according to this promise."}, {"verse": 14, "start": 215.75, "end": 235.59, "ta": "நான் யூதாதேசத்திலே அதிபதியாயிருக்கும்படி ராஜாவாகிய அர்தசஷ்டா எனக்குக் கற்பித்த நாளாகிய அவருடைய இருபதாம் வருஷம் தொடங்கி, அவருடைய முப்பத்திரண்டாம் வருஷம் வரைக்கும் இருந்த பன்னிரண்டு வருஷகாலமாய், நானும் என் சகோதரரும் அதிபதிகள் வாங்குகிற படியை வாங்கிச் சாப்பிடவில்லை.", "en": "Moreover from the time that I was appointed to be their governor in the land of Judah, from the twentieth year even unto the two and thirtieth year of Artaxerxes the king, that is , twelve years, I and my brethren have not eaten the bread of the governor."}, {"verse": 15, "start": 235.59, "end": 257.35, "ta": "எனக்கு முன்னிருந்த அதிபதிகள் ஜனங்களுக்குப் பாரமாயிருந்து, அவர்கள் கையிலே அப்பமும் திராட்சரசமும் வாங்கினதும் அல்லாமல், நாற்பதுசேக்கல் வெள்ளியும் வாங்கிவந்தார்கள்; அவர்கள் வேலைக்காரர் முதலாய் ஜனங்கள்மேல் அதிகாரம் செலுத்தினார்கள்; நானோ தேவனுக்குப் பயந்ததினால் இப்படிச் செய்யவில்லை.", "en": "But the former governors that had been before me were chargeable unto the people, and had taken of them bread and wine, beside forty shekels of silver; yea, even their servants bare rule over the people: but so did not I, because of the fear of God."}, {"verse": 16, "start": 257.35, "end": 268.97, "ta": "ஒரு வயலையாவது நாங்கள் கொள்ளவில்லை; அந்த அலங்கத்தின் வேலையிலே முயன்று நின்றேன்; என் வேலைக்காரரனைவரும் கூட்டமாய் அந்த வேலைக்குக் கூடிவந்தார்கள்.", "en": "Yea, also I continued in the work of this wall, neither bought we any land: and all my servants were gathered thither unto the work."}, {"verse": 17, "start": 268.97, "end": 280.39, "ta": "யூதரும் மூப்பருமான நூற்றைம்பதுபேரும், எங்களைச் சுற்றிலுமிருக்கிற புறஜாதிகளிடத்திலிருந்து எங்களிடத்திற்கு வந்தவர்களும் என் பந்தியில் சாப்பிட்டார்கள்.", "en": "Moreover there were at my table an hundred and fifty of the Jews and rulers, beside those that came unto us from among the heathen that are about us."}, {"verse": 18, "start": 280.39, "end": 302.22, "ta": "நாளொன்றுக்கு ஒரு காளையும், முதல் தரமான ஆறு ஆடும் சமைக்கப்பட்டது; பட்சிகளும் சமைக்கப்பட்டது; பத்துநாளைக்கு ஒருதரம் நானாவிதத் திராட்சரசமும் செலவழிந்தது. இப்படியெல்லாம் இருந்தபோதும், இந்த ஜனங்கள் பட்டபாடு கடினமாயிருந்தபடியால், அதிபதிகள் வாங்குகிற படியை நான் வாங்கவில்லை.", "en": "Now that which was prepared for me daily was one ox and six choice sheep; also fowls were prepared for me, and once in ten days store of all sorts of wine: yet for all this required not I the bread of the governor, because the bondage was heavy upon this people."}, {"verse": 19, "start": 302.22, "end": 310.28, "ta": "என் தேவனே, நான் இந்த ஜனத்துக்காகச் செய்த எல்லாவற்றின்படியும் எனக்கு நன்மையுண்டாக என்னை நினைத்தருளும்.", "en": "Think upon me, my God, for good, according to all that I have done for this people."}]}, "6": {"chapter": 6, "duration": 264.85, "audio_url": "audio_ot/OT16_06.mp3", "total_verses": 19, "verses": [{"verse": 1, "start": 3.8, "end": 17.17, "ta": "நான் அலங்கத்தைக் கட்டிமுடித்ததையும், இனி அதிலே திறப்பு ஒன்றுமில்லை என்பதையும், சன்பல்லாத்தும், தொபியாவும், அரபியனான கேஷேமும் எங்களுக்குண்டாயிருந்த மற்றப் பகைஞரும் கேள்விப்பட்டபோது,", "en": "Now it came to pass, when Sanballat, and Tobiah, and Geshem the Arabian, and the rest of our enemies, heard that I had builded the wall, and that there was no breach left therein; (though at that time I had not set up the doors upon the gates;)"}, {"verse": 2, "start": 17.17, "end": 36.37, "ta": "நான் வாசல்களுக்கு இன்னும் கதவுபோடாதிருக்கையில், சன்பல்லாத்தும், கேஷேமும் ஆள் அனுப்பி: நாம் ஓனோ பள்ளத்தாக்கில் இருக்கிற கிராமங்கள் ஒன்றில் ஒருவரையொருவர் கண்டு பேசுவோம் வாரும் என்று கூப்பிட்டார்கள்; அவர்களோவென்றால், எனக்குப் பொல்லாப்புச் செய்ய நினைத்தார்கள்.", "en": "That Sanballat and Geshem sent unto me, saying, Come, let us meet together in some one of the villages in the plain of Ono. But they thought to do me mischief."}, {"verse": 3, "start": 36.37, "end": 50.91, "ta": "அப்பொழுது நான் அவர்களிடத்திற்கு ஆட்களை அனுப்பி: நான் பெரிய வேலையைச் செய்கிறேன், நான் வரக் கூடாது, நான் அந்த வேலையைவிட்டு உங்களிடத்திற்கு வருகிறதினால் அது மினக்கட்டுப்போவானேன் என்று சொல்லச்சொன்னேன்.", "en": "And I sent messengers unto them, saying, I am doing a great work, so that I cannot come down: why should the work cease, whilst I leave it, and come down to you?"}, {"verse": 4, "start": 50.91, "end": 60.24, "ta": "அவர்கள் இந்தப்பிரகாரமாக நாலுதரம் எனக்குச் சொல்லியனுப்பினார்கள்; நானும் இந்தப்பிரகாரமாகவே அவர்களுக்கு மறுமொழி அனுப்பினேன்.", "en": "Yet they sent unto me four times after this sort; and I answered them after the same manner."}, {"verse": 5, "start": 60.24, "end": 69.9, "ta": "ஐந்தாந்தரமும் சன்பல்லாத்து அந்தப் பிரகாரமாகவே தன் வேலைக்காரனையும், அவன் கையிலே முத்திரைபோடாத ஒரு கடிதத்தையும் எனக்கு அனுப்பினான்.", "en": "Then sent Sanballat his servant unto me in like manner the fifth time with an open letter in his hand;"}, {"verse": 6, "start": 69.9, "end": 81.29, "ta": "அதிலே: நீரும் யூதரும் கலகம்பண்ண நினைக்கிறீர்கள் என்றும், அதற்காக நீர் அலங்கத்தைக் கட்டுகிறீர் என்றும், இவ்விதமாக நீர் அவர்களுக்கு ராஜாவாகப் போகிறீர் என்றும்,", "en": "Wherein was written, It is reported among the heathen, and Gashmu saith it, that thou and the Jews think to rebel: for which cause thou buildest the wall, that thou mayest be their king, according to these words."}, {"verse": 7, "start": 81.29, "end": 104.67, "ta": "யூதாவிலே ஒரு ராஜா இருக்கிறார் என்று உம்மைக்குறித்து எருசலேமிலே கூறுகிற தீர்க்கதரிசிகளையும் சம்பாதித்தீரென்றும் புறஜாதிகளுக்குள்ளே பிரஸ்தாபமாயிருக்கிறது, கஷ்மூமுவும் அப்படிச் சொல்லுகிறான்; இப்போதும் அந்தச் செய்தி ராஜாவுக்கு எட்டுமே; ஆகையால் நாம் ஒருவரோடொருவர் ஆலோசனைபண்ணுகிறதற்காக நீர் வரவேண்டும் என்று எழுதியிருந்தது.", "en": "And thou hast also appointed prophets to preach of thee at Jerusalem, saying, There is a king in Judah: and now shall it be reported to the king according to these words. Come now therefore, and let us take counsel together."}, {"verse": 8, "start": 104.67, "end": 114.68, "ta": "அதற்கு நான் நீர் சொல்லுகிற அந்தக் காரியங்களில் ஒன்றும் நடக்கவில்லை; அவைகள் உம்முடைய மனோராஜ்யமே ஒழிய வேறல்ல என்று சொல்லியனுப்பினேன்.", "en": "Then I sent unto him, saying, There are no such things done as thou sayest, but thou feignest them out of thine own heart."}, {"verse": 9, "start": 114.68, "end": 127.23, "ta": "அந்த வேலை நடந்தேறாதபடிக்கு எங்கள் கை சலித்துப்போம் என்று சொல்லி, அவர்கள் எல்லாரும் எங்களைப் பயமுறுத்தப்பார்த்தார்கள். ஆதலால் தேவனே நீர் என் கைகளைத் திடப்படுத்தியருளும்,", "en": "For they all made us afraid, saying, Their hands shall be weakened from the work, that it be not done. Now therefore, O God , strengthen my hands."}, {"verse": 10, "start": 127.23, "end": 149.52, "ta": "மெகதாபெயேலின் குமாரனாகிய தெலாயாவின் மகன் செமாயா தன் வீட்டிலே அடைக்கப்பட்டிருக்கும்போது, நான் அவனிடத்தில் போனேன்; அப்பொழுது அவன் நாம் இருவருமாய் தேவனுடைய வீடாகிய ஆலயத்துக்குள்ளே போய் தேவாலயத்தின் கதவுகளைப் பூட்டுவோம் வாரும்; உம்மைக் கொன்றுபோட வருவார்கள், இரவிலே உம்மைக் கொன்றுபோட வருவார்கள் என்றான்.", "en": "Afterward I came unto the house of Shemaiah the son of Delaiah the son of Mehetabeel, who was shut up; and he said, Let us meet together in the house of God, within the temple, and let us shut the doors of the temple: for they will come to slay thee; yea, in the night will they come to slay thee."}, {"verse": 11, "start": 149.52, "end": 161.18, "ta": "அதற்கு நான்; என்னைப்போன்ற மனிதன் ஓடிப்போவானோ? என்னைப்போன்றவன் உயிர்பிழைக்கும்படி தேவாலயத்திலே போய்ப் பதுங்குவானோ? நான் போவதில்லை என்றேன்.", "en": "And I said, Should such a man as I flee? and who is there , that, being as I am , would go into the temple to save his life? I will not go in."}, {"verse": 12, "start": 161.18, "end": 173.86, "ta": "தேவன் அவனை அனுப்பவில்லையென்றும், தொபியாவும் சன்பல்லாத்தும் அவனுக்குக் கூலிகொடுத்ததினால், அவன் எனக்கு விரோதமாய் அந்தத் தீர்க்கதரிசனத்தைச் சொன்னான் என்றும் அறிந்துகொண்டேன்.", "en": "And, lo, I perceived that God had not sent him; but that he pronounced this prophecy against me: for Tobiah and Sanballat had hired him."}, {"verse": 13, "start": 173.86, "end": 186.07, "ta": "நான் பயந்து அப்படிச் செய்து பாவங்கட்டிக்கொள்ளுகிறதற்கும், என்னை நிந்திக்கத்தக்க அபகீர்த்திக்கு முகாந்தரம் உண்டாக்குகிறதற்கும் அவனுக்குக் கைக்கூலி கொடுத்திருந்தார்கள்.", "en": "Therefore was he hired, that I should be afraid, and do so, and sin, and that they might have matter for an evil report, that they might reproach me."}, {"verse": 14, "start": 186.07, "end": 201.63, "ta": "என் தேவனே, தொபியாவும் சன்பல்லாத்தும் செய்த இந்தச் செய்கைகளுக்குத்தக்கதாக நீர் அவர்களையும், நொவதியாள் என்னும் தீர்க்கதரிசியானவளையும், எனக்குப் பயமுண்டாக்கப்பார்த்த மற்றத் தீர்க்கதரிசிகளையும் நினைத்துக்கொள்ளும்.", "en": "My God, think thou upon Tobiah and Sanballat according to these their works, and on the prophetess Noadiah, and the rest of the prophets, that would have put me in fear."}, {"verse": 15, "start": 201.63, "end": 209.73, "ta": "அப்படியே அலங்கமானது ஐம்பத்திரண்டு நாளைக்குள்ளே கட்டப்பட்டு, எலுூல் மாதம் இருபத்தைந்தாந்தேதியிலே முடிந்தது.", "en": "So the wall was finished in the twenty and fifth day of the month Elul, in fifty and two days."}, {"verse": 16, "start": 209.73, "end": 223.85, "ta": "எங்கள் பகைஞர் எல்லாரும் அதைக் கேட்டபோதும், எங்கள் சுற்றுப்புறத்தாராகிய புறஜாதியான அனைவரும் கண்டபோதும், மிகவும் முனையற்றுப்போய், இந்தக் கிரியை எங்கள் தேவனால் கைகூடி வந்ததென்று அறிந்தார்கள்.", "en": "And it came to pass, that when all our enemies heard thereof , and all the heathen that were about us saw these things , they were much cast down in their own eyes: for they perceived that this work was wrought of our God."}, {"verse": 17, "start": 223.85, "end": 235.17, "ta": "அந்த நாட்களில் யூதாவிலுள்ள பெரிய மனிதரிடத்திலிருந்து தொபியாவுக்குப் போகிறதும், தொபியாவினிடத்திலிருந்து அவர்களுக்கு வருகிறதுமான கடிதங்கள் அநேகமாயிருந்தது.", "en": "Moreover in those days the nobles of Judah sent many letters unto Tobiah, and the letters of Tobiah came unto them."}, {"verse": 18, "start": 235.17, "end": 251.49, "ta": "அவன் ஆராகின் குமாரனாகிய செகனியாவுக்கு மருமகனாயிருந்ததுமல்லாமல், அவன் குமாரனாகிய யோகனான் பெரகியாவின் குமாரனாகிய மெசுல்லாமின் குமாரத்தியை விவாகம்பண்ணியிருந்தபடியாலும், யூதாவில் அநேகர் அவனுக்கு ஆணையிட்டுக் கொடுத்திருந்தார்கள்.", "en": "For there were many in Judah sworn unto him, because he was the son in law of Shechaniah the son of Arah; and his son Johanan had taken the daughter of Meshullam the son of Berechiah."}, {"verse": 19, "start": 251.49, "end": 263.35, "ta": "அவன் செய்யும் நன்மைகளையும் அவர்கள் எனக்கு முன்பாக விவரித்து, என் வார்த்தைகளை அவனுக்குக் கொண்டுபோவார்கள்; தொபியா எனக்குப் பயமுண்டாகக் கடிதங்களை அனுப்புவான்.", "en": "Also they reported his good deeds before me, and uttered my words to him. And Tobiah sent letters to put me in fear."}]}, "7": {"chapter": 7, "duration": 509.15, "audio_url": "audio_ot/OT16_07.mp3", "total_verses": 73, "verses": [{"verse": 1, "start": 3.8, "end": 12.0, "ta": "அலங்கம் கட்டிமுடிந்து, கதவுகள் போடப்பட்டு, வாசல் காவலாளரையும் பாடகரையும், லேவியரையும் ஏற்படுத்தினபின்பு,", "en": "Now it came to pass, when the wall was built, and I had set up the doors, and the porters and the singers and the Levites were appointed,"}, {"verse": 2, "start": 12.0, "end": 25.35, "ta": "நான் என் சகோதரனாகிய ஆனானியையும், அநேகரைப்பார்க்கிலும் உண்மையுள்ளவனும் தேவனுக்குப் பயந்தவனுமாயிருந்த அரமனைத்தலைவனாகிய அனனியாவையும், எருசலேமின் காவல்விசாரணைக்கு ஏற்படுத்தினேன்.", "en": "That I gave my brother Hanani, and Hananiah the ruler of the palace, charge over Jerusalem: for he was a faithful man, and feared God above many."}, {"verse": 3, "start": 25.35, "end": 44.08, "ta": "அவர்களை நோக்கி: வெயில் ஏறுமட்டும் எருசலேமின் வாசல்கள் திறக்கப்படவேண்டாம், நீங்கள் நிற்கும்போதே கதவுகளைச் சாத்தித் தாழ்ப்பாள் போட்டு, எருசலேமின் குடிகளில் காவலாளர் அவரவர் தங்கள் காவலிலே, அவரவர் தங்கள் வீடுகளுக்கு எதிராக நிறுத்தப்படவேண்டும் என்றேன்.", "en": "And I said unto them, Let not the gates of Jerusalem be opened until the sun be hot; and while they stand by, let them shut the doors, and bar them: and appoint watches of the inhabitants of Jerusalem, every one in his watch, and every one to be over against his house."}, {"verse": 4, "start": 44.08, "end": 52.56, "ta": "பட்டணம் விஸ்தாரமும் பெரிதுமாயிருந்தது, அதற்குள்ளே ஜனங்கள் கொஞ்சமாயிருந்தார்கள், வீடுகளும் கட்டப்படவில்லை.", "en": "Now the city was large and great: but the people were few therein, and the houses were not builded."}, {"verse": 5, "start": 52.56, "end": 73.26, "ta": "அப்பொழுது வம்ச அட்டவணைகளைப் பார்க்கிறதற்கு, நான் பிரபுக்களையும் அதிகாரிகளையும் ஜனங்களையும் கூடிவரச்செய்ய, என் தேவன் என் மனதிலே ஒரு எண்ணத்தை உண்டாக்கினார்; முந்தி வந்தவர்களின் வம்ச அட்டவணைப் புஸ்தகம் அப்பொழுது எனக்கு அகப்பட்டது; அதிலே எழுதியிருக்க நான் கண்டது என்னவென்றால்,", "en": "And my God put into mine heart to gather together the nobles, and the rulers, and the people, that they might be reckoned by genealogy. And I found a register of the genealogy of them which came up at the first, and found written therein,"}, {"verse": 6, "start": 73.26, "end": 91.78, "ta": "பாபிலோன் ராஜாவாகிய நேபுகாத்நேச்சார் சிறைபிடித்துப்போனவர்களும், சிறையிருப்பிலிருந்து செருபாபேலோடும், யெசுவா, நெகேமியா, அசரியா, ராமியா, நகமானி, மொர்தெகாய், பில்சான், மிஸ்பெரேத், பிக்வாயி, நெகூம், பானா என்பவர்களோடுங்கூட வந்து,", "en": "These are the children of the province, that went up out of the captivity, of those that had been carried away, whom Nebuchadnezzar the king of Babylon had carried away, and came again to Jerusalem and to Judah, every one unto his city;"}, {"verse": 7, "start": 91.78, "end": 102.73, "ta": "எருசலேமுக்கும் யூதாவுக்கும் திரும்பித் தங்கள் தங்கள் பட்டணங்களிலே குடியிறங்கினவர்களுமான இந்தத் தேசத்தின் புத்திரராகிய இஸ்ரவேல் ஜனங்களான மனிதரின் தொகையாவது:", "en": "Who came with Zerubbabel, Jeshua, Nehemiah, Azariah, Raamiah, Nahamani, Mordecai, Bilshan, Mispereth, Bigvai, Nehum, Baanah. The number, I say , of the men of the people of Israel was this;"}, {"verse": 8, "start": 102.73, "end": 107.47, "ta": "பாரோஷின் புத்திரர் இரண்டாயிரத்து நூற்று எழுபத்திரண்டுபேர்.", "en": "The children of Parosh, two thousand an hundred seventy and two."}, {"verse": 9, "start": 107.47, "end": 111.85, "ta": "செபத்தியாவின் புத்திரர் முந்நூற்று எழுபத்திரண்டுபேர்.", "en": "The children of Shephatiah, three hundred seventy and two."}, {"verse": 10, "start": 111.85, "end": 115.74, "ta": "ஆராகின் புத்திரர் அறுநூற்று ஐம்பத்திரண்டுபேர்.", "en": "The children of Arah, six hundred fifty and two."}, {"verse": 11, "start": 115.74, "end": 124.43, "ta": "யெசுவா யோவாப் என்பவர்களின் சந்ததிக்குள்ளிருந்த பாகாத்மோவாபின் புத்திரர் இரண்டாயிரத்து எண்ணூற்றுப் பதினெட்டுப்பேர்.", "en": "The children of Pahath-moab, of the children of Jeshua and Joab, two thousand and eight hundred and eighteen."}, {"verse": 12, "start": 124.43, "end": 128.74, "ta": "ஏலாமின் புத்திரர் ஆயிரத்திருநூற்று ஐம்பத்துநாலுபேர்.", "en": "The children of Elam, a thousand two hundred fifty and four."}, {"verse": 13, "start": 128.74, "end": 132.77, "ta": "சத்தூவின் புத்திரர் எண்ணூற்று நாற்பத்தைந்துபேர்.", "en": "The children of Zattu, eight hundred forty and five."}, {"verse": 14, "start": 132.77, "end": 136.3, "ta": "சக்காயின் புத்திரர் எழுநூற்று அறுபதுபேர்.", "en": "The children of Zaccai, seven hundred and threescore."}, {"verse": 15, "start": 136.3, "end": 140.54, "ta": "பின்னூவின் புத்திரர் அறுநூற்று நாற்பத்தெட்டுப்பேர்.", "en": "The children of Binnui, six hundred forty and eight."}, {"verse": 16, "start": 140.54, "end": 144.57, "ta": "பெபாயின் புத்திரர் அறுநூற்று இருபத்தெட்டுப்பேர்.", "en": "The children of Bebai, six hundred twenty and eight."}, {"verse": 17, "start": 144.57, "end": 149.66, "ta": "அஸ்காதின் புத்திரர் இரண்டாயிரத்து முந்நூற்று இருபத்திரண்டுபேர்.", "en": "The children of Azgad, two thousand three hundred twenty and two."}, {"verse": 18, "start": 149.66, "end": 153.61, "ta": "அதோனிகாமின் புத்திரர் அறுநூற்று அறுபத்தேழுபேர்.", "en": "The children of Adonikam, six hundred threescore and seven."}, {"verse": 19, "start": 153.61, "end": 157.78, "ta": "பிக்வாயின் புத்திரர் இரண்டாயிரத்து அறுபத்தேழுபேர்.", "en": "The children of Bigvai, two thousand threescore and seven."}, {"verse": 20, "start": 157.78, "end": 161.6, "ta": "ஆதீனின் புத்திரர் அறுநூற்று ஐம்பத்தைந்துபேர்.", "en": "The children of Adin, six hundred fifty and five."}, {"verse": 21, "start": 161.6, "end": 166.83, "ta": "எசேக்கியாவின் சந்ததியான ஆதேரின் புத்திரர் தொண்ணூற்று எட்டுப்பேர்.", "en": "The children of Ater of Hezekiah, ninety and eight."}, {"verse": 22, "start": 166.83, "end": 170.85, "ta": "ஆசூமின் புத்திரர் முந்நூற்று இருபத்தெட்டுப்பேர்.", "en": "The children of Hashum, three hundred twenty and eight."}, {"verse": 23, "start": 170.85, "end": 174.81, "ta": "பேசாயின் புத்திரர் முந்நூற்று இருபத்துநாலுபேர்.", "en": "The children of Bezai, three hundred twenty and four."}, {"verse": 24, "start": 174.81, "end": 178.49, "ta": "ஆரீப்பின் புத்திரர் நூற்றுப்பன்னிரண்டுபேர்.", "en": "The children of Hariph, an hundred and twelve."}, {"verse": 25, "start": 178.49, "end": 182.09, "ta": "கிபியோனின் புத்திரர் தொண்ணூற்று ஐந்துபேர்.", "en": "The children of Gibeon, ninety and five."}, {"verse": 26, "start": 182.09, "end": 187.32, "ta": "பெத்லகேம் ஊராரும், நெத்தோபா ஊராரும் நூற்று எண்பத்தெட்டுப்பேர்.", "en": "The men of Beth-lehem and Netophah, an hundred fourscore and eight."}, {"verse": 27, "start": 187.32, "end": 191.07, "ta": "ஆனதோத்தூர் மனிதர் நூற்று இருபத்தெட்டுப்பேர்.", "en": "The men of Anathoth, an hundred twenty and eight."}, {"verse": 28, "start": 191.07, "end": 194.46, "ta": "பெத்அஸ்மாவேத் ஊரார் நாற்பத்திரண்டுபேர்.", "en": "The men of Beth-azmaveth, forty and two."}, {"verse": 29, "start": 194.46, "end": 200.61, "ta": "கீரியாத்யாரீம், கெபிராபேரோத் ஊர்களின் மனிதர் எழுநூற்று நாற்பத்துமூன்றுபேர்.", "en": "The men of Kirjath-jearim, Chephirah, and Beeroth, seven hundred forty and three."}, {"verse": 30, "start": 200.61, "end": 205.13, "ta": "ராமா, காபா ஊர்களின் மனிதர் அறுநூற்று இருபத்தொருபேர்.", "en": "The men of Ramah and Geba, six hundred twenty and one."}, {"verse": 31, "start": 205.13, "end": 208.59, "ta": "மிக்மாஸ் ஊரார் நூற்று இருபத்திரண்டுபேர்.", "en": "The men of Michmas, an hundred and twenty and two."}, {"verse": 32, "start": 208.59, "end": 213.4, "ta": "பெத்தேல், ஆயி ஊர்களின் மனிதர் நூற்று இருபத்துமூன்றுபேர்.", "en": "The men of Beth-el and Ai, an hundred twenty and three."}, {"verse": 33, "start": 213.4, "end": 216.58, "ta": "வேறொரு நேபோ ஊரார் ஐம்பத்திரண்டுபேர்.", "en": "The men of the other Nebo, fifty and two."}, {"verse": 34, "start": 216.58, "end": 221.45, "ta": "மற்றொரு ஏலாம் புத்திரர் ஆயிரத்து இருநூற்று ஐம்பத்துநாலுபேர்.", "en": "The children of the other Elam, a thousand two hundred fifty and four."}, {"verse": 35, "start": 221.45, "end": 224.77, "ta": "ஆரீம் புத்திரர் முந்நூற்று இருபதுபேர்.", "en": "The children of Harim, three hundred and twenty."}, {"verse": 36, "start": 224.77, "end": 228.52, "ta": "எரிகோ புத்திரர் முந்நூற்று அறுபத்தைந்துபேர்.", "en": "The children of Jericho, three hundred forty and five."}, {"verse": 37, "start": 228.52, "end": 233.89, "ta": "லோத், ஆதீத், ஓனோ ஊர்களின் புத்திரர் எழுநூற்று இருபத்தொருபேர்.", "en": "The children of Lod, Hadid, and Ono, seven hundred twenty and one."}, {"verse": 38, "start": 233.89, "end": 238.41, "ta": "செனாகா புத்திரர் மூவாயிரத்துத் தொளாயிரத்து முப்பதுபேர்.", "en": "The children of Senaah, three thousand nine hundred and thirty."}, {"verse": 39, "start": 238.41, "end": 245.62, "ta": "ஆசாரியரானவர்கள்: யெசுவா குடும்பத்தானாகிய யெதாயாவின் புத்திரர் தொளாயிரத்து எழுபத்துமூன்றுபேர்.", "en": "The priests: the children of Jedaiah, of the house of Jeshua, nine hundred seventy and three."}, {"verse": 40, "start": 245.62, "end": 249.58, "ta": "இம்மேரின் புத்திரர் ஆயிரத்து ஐம்பத்திரண்டுபேர்.", "en": "The children of Immer, a thousand fifty and two."}, {"verse": 41, "start": 249.58, "end": 254.1, "ta": "பஸ்கூரின் புத்திரர் ஆயிரத்து இருநூற்று நாற்பத்தேழுபேர்.", "en": "The children of Pashur, a thousand two hundred forty and seven."}, {"verse": 42, "start": 254.1, "end": 257.63, "ta": "ஆரீமின் புத்திரர் ஆயிரத்துப் பதினேழுபேர்.", "en": "The children of Harim, a thousand and seventeen."}, {"verse": 43, "start": 257.63, "end": 265.69, "ta": "லேவியரானவர்கள்: ஒதியாவின் புத்திரருக்குள்ளே கத்மியேலின் குமாரனாகிய யெசுவாவின் புத்திரர் எழுபத்துநாலுபேர்.", "en": "The Levites: the children of Jeshua, of Kadmiel, and of the children of Hodevah, seventy and four."}, {"verse": 44, "start": 265.69, "end": 270.56, "ta": "பாடகரானவர்கள்: ஆசாபின் புத்திரர் நூற்று நாற்பத்தெட்டுப்பேர்.", "en": "The singers: the children of Asaph, an hundred forty and eight."}, {"verse": 45, "start": 270.56, "end": 285.12, "ta": "வாசல் காவலாளரானவர்கள்; சல்லுூமின் புத்திரர் அதேரின் புத்திரர், தல்மோனின் புத்திரர், அக்கூபின் புத்திரர், அதிதாவின் புத்திரர், சோபாயின் புத்திரர், ஆக நூற்று முப்பத்தெட்டுப்பேர்.", "en": "The porters: the children of Shallum, the children of Ater, the children of Talmon, the children of Akkub, the children of Hatita, the children of Shobai, an hundred thirty and eight."}, {"verse": 46, "start": 285.12, "end": 291.48, "ta": "நிதனீமியரானவர்கள்: சீகாவின்புத்திரர், அசுபாவின் புத்திரர், தபாகோத்தின் புத்திரர்,", "en": "The Nethinims: the children of Ziha, the children of Hashupha, the children of Tabbaoth,"}, {"verse": 47, "start": 291.48, "end": 296.29, "ta": "கேரோசின் புத்திரர், சீயாவின் புத்திரர், பாதோனின் புத்திரர்,", "en": "The children of Keros, the children of Sia, the children of Padon,"}, {"verse": 48, "start": 296.29, "end": 301.38, "ta": "லெபானாவின் புத்திரர், அகாபாவின் புத்திரர், சல்மாயின் புத்திரர்,", "en": "The children of Lebana, the children of Hagaba, the children of Shalmai,"}, {"verse": 49, "start": 301.38, "end": 306.25, "ta": "ஆனானின் புத்திரர், கித்தேலின் புத்திரர், காகாரின் புத்திரர்,", "en": "The children of Hanan, the children of Giddel, the children of Gahar,"}, {"verse": 50, "start": 306.25, "end": 311.34, "ta": "ராயாகின் புத்திரர், ரேத்சீனின் புத்திரர், நெகோதாவின் புத்திரர்,", "en": "The children of Reaiah, the children of Rezin, the children of Nekoda,"}, {"verse": 51, "start": 311.34, "end": 316.22, "ta": "காசாமின் புத்திரர், ஊசாவின் புத்திரர், பாசெயாகின் புத்திரர்,", "en": "The children of Gazzam, the children of Uzza, the children of Phaseah,"}, {"verse": 52, "start": 316.22, "end": 321.37, "ta": "பேசாயின் புத்திரர், மெயுநீமின் புத்திரர், நெபிஷசீமின் புத்திரர்,", "en": "The children of Besai, the children of Meunim, the children of Nephishesim,"}, {"verse": 53, "start": 321.37, "end": 326.53, "ta": "பக்பூக்கின் புத்திரர், அகுபாவின் புத்திரர், அர்கூரின் புத்திரர்,", "en": "The children of Bakbuk, the children of Hakupha, the children of Harhur,"}, {"verse": 54, "start": 326.53, "end": 331.62, "ta": "பஸ்லீதின் புத்திரர், மெகிதாவின் புத்திரர், அர்ஷாவின் புத்திரர்,", "en": "The children of Bazlith, the children of Mehida, the children of Harsha,"}, {"verse": 55, "start": 331.62, "end": 336.64, "ta": "பர்கோசின் புத்திரர், சிசெராவின் புத்திரர், தாமாவின் புத்திரர்,", "en": "The children of Barkos, the children of Sisera, the children of Tamah,"}, {"verse": 56, "start": 336.64, "end": 340.17, "ta": "நெத்சியாகின் புத்திரர், அதிபாவின் புத்திரர்,", "en": "The children of Neziah, the children of Hatipha."}, {"verse": 57, "start": 340.17, "end": 348.51, "ta": "சாலொமோனுடைய வேலைக்காரரின் புத்திரரானவர்கள்: சோதாயின் புத்திரர், சொபெரேத்தின் புத்திரர், பெருதாவின் புத்திரர்,", "en": "The children of Solomon’s servants: the children of Sotai, the children of Sophereth, the children of Perida,"}, {"verse": 58, "start": 348.51, "end": 353.53, "ta": "யாலாவின் புத்திரர், தர்கோனின் புத்திரர், கித்தேலின் புத்திரர்,", "en": "The children of Jaala, the children of Darkon, the children of Giddel,"}, {"verse": 59, "start": 353.53, "end": 361.72, "ta": "செபத்தியாவின் புத்திரர், அத்தீலின் புத்திரர், பொகெரேத் செபாயிமிலுள்ள புத்திரர், ஆமோனின் புத்திரர்.", "en": "The children of Shephatiah, the children of Hattil, the children of Pochereth of Zebaim, the children of Amon."}, {"verse": 60, "start": 361.72, "end": 369.07, "ta": "நிதனிமியரும் சாலொமோனுடைய வேலையாட்களின் புத்திரரும் ஏகத்துக்கு முந்நூற்றுத் தொண்ணூற்றிரண்டுபேர்.", "en": "All the Nethinims, and the children of Solomon’s servants, were three hundred ninety and two."}, {"verse": 61, "start": 369.07, "end": 384.13, "ta": "தெல்மெலாகிலும், தெல்அர்சாவிலும், கேருபிலும், ஆதோனிலும், இம்மேரிலும் இருந்துவந்தும், தாங்கள் இஸ்ரவேலர் என்று தங்கள் பிதாக்களின் வம்சத்தையும், தங்கள் பூர்வோத்தரத்தையும் சொல்லமாட்டாமல் இருந்தவர்கள்:", "en": "And these were they which went up also from Tel-melah, Tel-haresha, Cherub, Addon, and Immer: but they could not shew their father’s house, nor their seed, whether they were of Israel."}, {"verse": 62, "start": 384.13, "end": 392.32, "ta": "தெலாயாவின் புத்திரர், தொபியாவின் புத்திரர், நெகோதாவின் புத்திரர், ஆக அறுநூற்று நாற்பத்திரண்டுபேர்.", "en": "The children of Delaiah, the children of Tobiah, the children of Nekoda, six hundred forty and two."}, {"verse": 63, "start": 392.32, "end": 406.1, "ta": "ஆசாரியர்களில் அபாயாவின் புத்திரர், கோசின் புத்திரர், கிலேயாத்தியனான பர்சில்லாயின் குமாரத்திகளில் ஒருத்தியை விவாகம்பண்ணி, அவர்கள் வம்ச நாமம் தரிக்கப்பட்ட பர்சில்லாயின் புத்திரர்.", "en": "And of the priests: the children of Habaiah, the children of Koz, the children of Barzillai, which took one of the daughters of Barzillai the Gileadite to wife, and was called after their name."}, {"verse": 64, "start": 406.1, "end": 415.08, "ta": "இவர்கள் தங்கள் வம்ச அட்டவணையைத் தேடி, அதைக் காணாமற்போய் ஆசாரிய ஊழியத்துக்கு விலக்கமானவர்கள் என்று எண்ணப்பட்டார்கள்.", "en": "These sought their register among those that were reckoned by genealogy, but it was not found: therefore were they, as polluted, put from the priesthood."}, {"verse": 65, "start": 415.08, "end": 425.54, "ta": "ஊரீம் தும்மீம் என்பவைகளுள்ள ஒரு ஆசாரியன் எழும்புமட்டும், அவர்கள் மகா பரிசுத்தமானதிலே புசிக்கத்தகாதென்று திர்ஷாதா அவர்களுக்குச் சொன்னான்.", "en": "And the Tirshatha said unto them, that they should not eat of the most holy things, till there stood up a priest with Urim and Thummim."}, {"verse": 66, "start": 425.54, "end": 432.04, "ta": "சபையார் எல்லாரும் ஏகத்துக்கு நாற்பத்தீராயிரத்து முந்நூற்று அறுபதுபேராயிருந்தார்கள்.", "en": "The whole congregation together was forty and two thousand three hundred and threescore,"}, {"verse": 67, "start": 432.04, "end": 444.12, "ta": "அவர்களைத்தவிர ஏழாயிரத்துமுந்நூற்று முப்பத்தேழுபேரான அவர்களுடைய வேலைக்காரரும் வேலைக்காரிகளும் இருநூற்று நாற்பத்தைந்து பாடகரும் பாடகிகளும் அவர்களுக்கு இருந்தார்கள்.", "en": "Beside their manservants and their maidservants, of whom there were seven thousand three hundred thirty and seven: and they had two hundred forty and five singing men and singing women."}, {"verse": 68, "start": 444.12, "end": 451.47, "ta": "அவர்களுடைய குதிரைகள் எழுநூற்று முப்பத்தாறு, அவர்கள் கோவேறு கழுதைகள் இருநூற்று நாற்பத்தைந்து.", "en": "Their horses, seven hundred thirty and six: their mules, two hundred forty and five:"}, {"verse": 69, "start": 451.47, "end": 457.41, "ta": "ஒட்டகங்கள் நானூற்று முப்பத்தைந்து, கழுதைகள் ஆறாயிரத்து எழுநூற்று இருபது.", "en": "Their camels, four hundred thirty and five: six thousand seven hundred and twenty asses."}, {"verse": 70, "start": 457.41, "end": 470.2, "ta": "வம்சத்தலைவரில் சிலர் வேலைக்கென்று கொடுத்ததாவது: திர்ஷாதா ஆயிரம் தங்கக்காசையும் ஐம்பது கலங்களையும், ஐந்நூற்று முப்பது ஆசாரிய வஸ்திரங்களையும் பொக்கிஷத்துக்குக் கொடுத்தான்.", "en": "And some of the chief of the fathers gave unto the work. The Tirshatha gave to the treasure a thousand drams of gold, fifty basons, five hundred and thirty priests’ garments."}, {"verse": 71, "start": 470.2, "end": 480.44, "ta": "வம்சத்தலைவரில் சிலர் வேலையின் பொக்கிஷத்துக்கு இருபதினாயிரம் தங்கக்காசையும், இரண்டாயிரத்து இருநூறு ராத்தல் வெள்ளியையும் கொடுத்தார்கள்.", "en": "And some of the chief of the fathers gave to the treasure of the work twenty thousand drams of gold, and two thousand and two hundred pound of silver."}, {"verse": 72, "start": 480.44, "end": 490.34, "ta": "மற்ற ஜனங்கள் இருபதினாயிரம் தங்கக்காசையும், இரண்டாயிரம் ராத்தல் வெள்ளியையும், அறுபத்தேழு ஆசாரிய வஸ்திரங்களையும் கொடுத்தார்கள்.", "en": "And that which the rest of the people gave was twenty thousand drams of gold, and two thousand pound of silver, and threescore and seven priests’ garments."}, {"verse": 73, "start": 490.34, "end": 507.65, "ta": "ஆசாரியரும் லேவியரும், வாசல் காவலாளரும், பாடகரும், ஜனங்களில் சிலரும் நிதனீமியரும், இஸ்ரவேலர் அனைவரும் தங்கள் தங்கள் பட்டணங்களில் குடியேறினார்கள்; ஏழாம் மாதமானபோது, இஸ்ரவேல் புத்திரர் தங்கள் பட்டணங்களில் இருந்தார்கள்.", "en": "So the priests, and the Levites, and the porters, and the singers, and some of the people, and the Nethinims, and all Israel, dwelt in their cities; and when the seventh month came, the children of Israel were in their cities."}]}, "8": {"chapter": 8, "duration": 317.71, "audio_url": "audio_ot/OT16_08.mp3", "total_verses": 18, "verses": [{"verse": 1, "start": 3.8, "end": 19.49, "ta": "ஜனங்கள் எல்லாரும் தண்ணீர்வாசலுக்கு முன்னான வீதியிலே ஒருமனப்பட்டுக் கூடி, கர்த்தர் இஸ்ரவேலுக்குக் கற்பித்த மோசேயின் நியாயப்பிரமாண புஸ்தகத்தைக் கொண்டுவரவேண்டுமென்று வேதபாரகனாகிய எஸ்றாவுக்குச் சொன்னார்கள்.", "en": "And all the people gathered themselves together as one man into the street that was before the water gate; and they spake unto Ezra the scribe to bring the book of the law of Moses, which the LORD had commanded to Israel."}, {"verse": 2, "start": 19.49, "end": 31.36, "ta": "அப்படியே ஏழாம் மாதம் முதல்தேதியில் ஆசாரியனாகிய எஸ்றா நியாயப்பிரமாணத்தைப் புருஷரும் ஸ்திரீகளும், கேட்டு அறியத்தக்க அனைவருமாகிய சபைக்கு முன்பாகக் கொண்டுவந்து,", "en": "And Ezra the priest brought the law before the congregation both of men and women, and all that could hear with understanding, upon the first day of the seventh month."}, {"verse": 3, "start": 31.36, "end": 50.35, "ta": "தண்ணீர் வாசலுக்கு முன்னான வீதிக்கு எதிரேயிருந்து காலமேதொடங்கி மத்தியானமட்டும் புருஷருக்கும் ஸ்திரீகளுக்கும், கேட்டு அறியத்தக்க மற்றவர்களுக்கும் முன்பாக அதை வாசித்தான்; சகல ஜனங்களும் நியாயப்பிரமாண புஸ்தகத்திற்குக் கவனமாய்ச் செவிகொடுத்தார்கள்.", "en": "And he read therein before the street that was before the water gate from the morning until midday, before the men and the women, and those that could understand; and the ears of all the people were attentive unto the book of the law."}, {"verse": 4, "start": 50.35, "end": 76.81, "ta": "வேதபாரகனாகிய எஸ்றா அதற்கென்று மரத்தால் செய்யப்பட்ட ஒரு பிரசங்கபீடத்தின்மேல் நின்றான்; அவனண்டையில் அவனுக்கு வலதுபக்கமாக மத்தித்தியாவும், செமாவும், அனாயாவும், உரியாவும், இல்க்கியாவும் மாசெயாவும், அவனுக்கு இடதுபக்கமாகப் பெதாயாவும், மீசவேலும், மல்கியாவும், அசூமும், அஸ்பதானாவும், சகரியாவும், மெசுல்லாமும் நின்றார்கள்.", "en": "And Ezra the scribe stood upon a pulpit of wood, which they had made for the purpose; and beside him stood Mattithiah, and Shema, and Anaiah, and Urijah, and Hilkiah, and Maaseiah, on his right hand; and on his left hand, Pedaiah, and Mishael, and Malchiah, and Hashum, and Hashbadana, Zechariah, and Meshullam."}, {"verse": 5, "start": 76.81, "end": 88.46, "ta": "எஸ்றா சகல ஜனங்களுக்கும் உயரநின்று, சகல ஜனங்களும் காணப் புஸ்தகத்தைத் திறந்தான்; அவன் அதைத்திறந்தபோது, ஜனங்கள் எல்லாரும் எழுந்துநின்றார்கள்.", "en": "And Ezra opened the book in the sight of all the people; (for he was above all the people;) and when he opened it, all the people stood up:"}, {"verse": 6, "start": 88.46, "end": 106.28, "ta": "அப்பொழுது எஸ்றா மகத்துவமுள்ள தேவனாகிய கர்த்தரை ஸ்தோத்திரித்தான்; ஜனங்களெல்லாரும் தங்கள் கைகளைக் குவித்து, அதற்கு மறுமொழியாக, ஆமென் ஆமென் என்று சொல்லி, குனிந்து, முகங்குப்புறவிழுந்து, கர்த்தரைப் பணிந்துகொண்டார்கள்.", "en": "And Ezra blessed the LORD , the great God. And all the people answered, Amen, Amen, with lifting up their hands: and they bowed their heads, and worshipped the LORD with their faces to the ground."}, {"verse": 7, "start": 106.28, "end": 126.07, "ta": "யெசுவா, பானி, செரெபியா, யாமின், அக்கூப், சபெதாயி, ஒதியா, மாசெயா கேலிதா, அசரியா, யோசபாத், ஆனான், பெலாயா என்பவர்களும், லேவியரும், நியாயப்பிரமாணத்தை ஜனங்களுக்கு விளங்கப்பண்ணினார்கள்; ஜனங்கள் தங்கள் நிலையிலே நின்றார்கள்.", "en": "Also Jeshua, and Bani, and Sherebiah, Jamin, Akkub, Shabbethai, Hodijah, Maaseiah, Kelita, Azariah, Jozabad, Hanan, Pelaiah, and the Levites, caused the people to understand the law: and the people stood in their place."}, {"verse": 8, "start": 126.07, "end": 136.62, "ta": "அவர்கள் தேவனுடைய நியாயப்பிரமாணப் புஸ்தகத்தை தீர்க்கதரிசனமாக வாசித்து, அர்த்தஞ்சொல்லி, வாசித்ததை அவர்களுக்கு விளங்கப்பண்ணினார்கள்.", "en": "So they read in the book in the law of God distinctly, and gave the sense, and caused them to understand the reading."}, {"verse": 9, "start": 136.62, "end": 161.76, "ta": "ஜனங்கள் எல்லாரும் நியாயப்பிரமாணத்தின் வார்த்தைகளைக் கேட்டபோது, அழுதபடியால் திர்ஷாதா என்னப்பட்ட நெகேமியாவும், வேதபாரகனாகிய எஸ்றா என்னும் ஆசாரியனும், ஜனங்களுக்கு விளக்கிக்காட்டின லேவியரும் சகல ஜனங்களையும் நோக்கி: இந்த நாள் உங்கள் தேவனாகிய கர்த்தருக்குப் பரிசுத்தமான நாள்; நீங்கள் துக்கப்படவும் அழவும் வேண்டாம் என்றார்கள்.", "en": "And Nehemiah, which is the Tirshatha, and Ezra the priest the scribe, and the Levites that taught the people, said unto all the people, This day is holy unto the LORD your God; mourn not, nor weep. For all the people wept, when they heard the words of the law."}, {"verse": 10, "start": 161.76, "end": 183.68, "ta": "பின்னும் அவன் அவர்களை நோக்கி: நீங்கள் போய்க் கொழுமையானதைப் புசித்து, மதுரமானதைக் குடித்து, ஒன்றுமில்லாதவர்களுக்குப் பங்குகளை அனுப்புங்கள்; இந்த நாள் நம்முடைய ஆண்டவருக்குப் பரிசுத்தமான நாள், விசாரப்படவேண்டாம்; கர்த்தருக்குள் மகிழ்ச்சியாயிருப்பதே உங்களுடைய பெலன் என்றான்.", "en": "Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our Lord: neither be ye sorry; for the joy of the LORD is your strength."}, {"verse": 11, "start": 183.68, "end": 192.62, "ta": "லேவியரும் ஜனங்களையெல்லாம் அமர்த்தி: அழாதிருங்கள், இந்த நாள் பரிசுத்தமான நாள், விசாரப்படவேண்டாம் என்றார்கள்.", "en": "So the Levites stilled all the people, saying, Hold your peace, for the day is holy; neither be ye grieved."}, {"verse": 12, "start": 192.62, "end": 206.55, "ta": "அப்பொழுது ஜனங்கள் எல்லாரும் தங்களுக்கு அறிவிக்கப்பட்ட வார்த்தைகளை உணர்ந்துகொண்டபடியால், புசித்துக் குடிக்கவும், பங்குகளை அனுப்பவும், மிகுந்த சந்தோஷம் கொண்டாடவும் போனார்கள்.", "en": "And all the people went their way to eat, and to drink, and to send portions, and to make great mirth, because they had understood the words that were declared unto them."}, {"verse": 13, "start": 206.55, "end": 220.11, "ta": "மறுநாளில் ஜனத்தின் சகல வம்சத்தலைவரும், ஆசாரியரும், லேவியரும், நியாயப்பிரமாணத்தின் வார்த்தைகளை அறிந்துகொள்ளவேண்டும் என்று வேதபாரகனாகிய எஸ்றாவினிடத்தில் கூடி வந்தார்கள்.", "en": "And on the second day were gathered together the chief of the fathers of all the people, the priests, and the Levites, unto Ezra the scribe, even to understand the words of the law."}, {"verse": 14, "start": 220.11, "end": 234.77, "ta": "அப்பொழுது நியாயப்பிரமாணத்திலே, இஸ்ரவேல் புத்திரர் ஏழாம் மாதத்தின் பண்டிகையிலே கூடாரங்களில் குடியிருக்கவேண்டும் என்று கர்த்தர் மோசேயைக்கொண்டு கற்பித்த காரியம் எழுதியிருக்கிறதைக் கண்டவர்கள்.", "en": "And they found written in the law which the LORD had commanded by Moses, that the children of Israel should dwell in booths in the feast of the seventh month:"}, {"verse": 15, "start": 234.77, "end": 258.82, "ta": "ஆகையால் எழுதியிருக்கிறபடி கூடாரங்களைப் போடும்படிக்கு நீங்கள் மலைகளுக்குப் புறப்பட்டுப்போய் ஒலிவக்கிளைகளையும், காட்டு ஒலிவக்கிளைகளையும், மிருதுச் செடிகளின் கிளைகளையும் பேரீச்ச மட்டைகளையும், அடர்ந்தமரக்கிளைகளையும் கொண்டுவாருங்களென்று தங்களுடைய சகல பட்டணங்களிலும், எருசலேமிலும் கூறிப் பிரசித்தப்படுத்தினார்கள்.", "en": "And that they should publish and proclaim in all their cities, and in Jerusalem, saying, Go forth unto the mount, and fetch olive branches, and pine branches, and myrtle branches, and palm branches, and branches of thick trees, to make booths, as it is written."}, {"verse": 16, "start": 258.82, "end": 276.99, "ta": "அப்படியே ஜனங்கள் வெளியேபோய் அவைகளைக் கொண்டுவந்து, அவரவர் தங்கள் வீடுகள்மேலும், தங்கள் முற்றங்களிலும், தேவனுடைய ஆலயப்பிராகாரங்களிலும், தண்ணீர்வாசல் வீதியிலும், எப்பிராயீம் வாசல் வீதியிலும் தங்களுக்குக் கூடாரங்களை போட்டார்கள்.", "en": "So the people went forth, and brought them , and made themselves booths, every one upon the roof of his house, and in their courts, and in the courts of the house of God, and in the street of the water gate, and in the street of the gate of Ephraim."}, {"verse": 17, "start": 276.99, "end": 299.42, "ta": "இந்தப்பிரகாரமாகச் சிறையிருப்பிலிருந்து திரும்பி வந்தவர்களின் சபையார் எல்லாரும் கூடாரங்களைப்போட்டு, கூடாரங்களில் குடியிருந்தார்கள்; இப்படியே நூனின் குமாரனாகிய யோசுவாவின் நாட்கள்முதல் அந்நாள்மட்டும் இஸ்ரவேல் புத்திரர் செய்யாதிருந்து இப்பொழுது செய்தபடியால், மிகுந்த சந்தோஷமுண்டாயிருந்தது.", "en": "And all the congregation of them that were come again out of the captivity made booths, and sat under the booths: for since the days of Jeshua the son of Nun unto that day had not the children of Israel done so. And there was very great gladness."}, {"verse": 18, "start": 299.42, "end": 316.21, "ta": "முதலாம் நாள் தொடங்கிக் கடைசிநாள்மட்டும், தினம்தினம் தேவனுடைய நியாயப்பிரமாண புஸ்தகம் வாசிக்கப்பட்டது; ஏழுநாள் பண்டிகையை ஆசரித்தார்கள்; எட்டாம்நாளோவெனில், முறைமையின்படியே விசேஷித்த ஆசரிப்பு நாளாயிருந்தது.", "en": "Also day by day, from the first day unto the last day, he read in the book of the law of God. And they kept the feast seven days; and on the eighth day was a solemn assembly, according unto the manner."}]}, "9": {"chapter": 9, "duration": 660.34, "audio_url": "audio_ot/OT16_09.mp3", "total_verses": 38, "verses": [{"verse": 1, "start": 3.8, "end": 15.08, "ta": "அந்த மாதம் இருபத்துநாலாந்தேதியிலே இஸ்ரவேல் புத்திரர் உபவாசம்பண்ணி, இரட்டுடுத்தி, தங்கள்மேல் புழுதியைப் போட்டுக்கொண்டவர்களாய்க் கூடிவந்தார்கள்.", "en": "Now in the twenty and fourth day of this month the children of Israel were assembled with fasting, and with sackclothes, and earth upon them."}, {"verse": 2, "start": 15.08, "end": 26.21, "ta": "இஸ்ரவேல் சந்ததியார் மறு ஜாதியாரையெல்லொம் விட்டுப்பிரிந்து வந்து நின்று தங்கள் பாவங்களையும் தங்கள் பிதாக்களின் அக்கிரமங்களையும் அறிக்கையிட்டார்கள்.", "en": "And the seed of Israel separated themselves from all strangers, and stood and confessed their sins, and the iniquities of their fathers."}, {"verse": 3, "start": 26.21, "end": 45.75, "ta": "அவர்கள் எழுந்திருந்து, தங்கள் நிலையில் நின்றார்கள்; அப்பொழுது ஒரு ஜாமமட்டும் அவர்களுடைய தேவனாகிய கர்த்தரின் நியாயப்பிரமாணப் புஸ்தகம் வாசிக்கப்பட்டது; பின்பு ஒரு ஜாமமட்டும் அவர்கள் பாவ அறிக்கை பண்ணி, தங்கள் தேவனாகிய கர்த்தரைப் பணிந்துகொண்டார்கள்.", "en": "And they stood up in their place, and read in the book of the law of the LORD their God one fourth part of the day; and another fourth part they confessed, and worshipped the LORD their God."}, {"verse": 4, "start": 45.75, "end": 59.04, "ta": "யெசுவா, பானி கத்மியேல் செப்பனியா, புன்னி, செரெபியா பானி, கெனானி என்பவர்கள் லேவியருடையபடிகளின்மேல் நின்று தங்கள் தேவனாகிய கர்த்தரை நோக்கி மகா சத்தமாய் ஓலமிட்டார்கள்.", "en": "Then stood up upon the stairs, of the Levites, Jeshua, and Bani, Kadmiel, Shebaniah, Bunni, Sherebiah, Bani, and Chenani, and cried with a loud voice unto the LORD their God."}, {"verse": 5, "start": 59.04, "end": 85.98, "ta": "பின்பு லேவியரான யெசுவா, கத்மியேல், பானி, ஆசாப்நெயா, செரெபியா, ஒதியா, செபனியா, பெத்தகியா என்பவர்கள் ஜனங்களைப் பார்த்து: நீங்கள் எழுந்திருந்து, அநாதியாய் என்றென்றைக்குமிருக்கிற உங்கள் தேவனாகிய கர்த்தரை ஸ்தோத்திரியுங்கள் என்று சொல்லி, கர்த்தரை நோக்கி: எந்த ஸ்துதி ஸ்தோத்திரத்துக்கும் மேலான உம்முடைய மகிமையுள்ள நாமத்துக்கு ஸ்தோத்திரமுண்டாவதாக.", "en": "Then the Levites, Jeshua, and Kadmiel, Bani, Hashabniah, Sherebiah, Hodijah, Shebaniah, and Pethahiah, said, Stand up and bless the LORD your God for ever and ever: and blessed be thy glorious name, which is exalted above all blessing and praise."}, {"verse": 6, "start": 85.98, "end": 107.31, "ta": "நீர் ஒருவரே கர்த்தர்; நீர் வானங்களையும், வானாதி வானங்களையும், அவைகளுடைய சர்வ சேனைகளையும் பூமியையும் அதிலுள்ள எல்லாவற்றையும், சமுத்திரங்களையும் அவைகளிலுள்ள எல்லாவற்றையும் உண்டாக்கினீர்; அவைகளையெல்லாம் நீர் காப்பாற்றுகிறீர்; வானசேனைகள் உம்மைப் பணிந்துகொள்ளுகிறது.", "en": "Thou, even thou, art LORD alone; thou hast made heaven, the heaven of heavens, with all their host, the earth, and all things that are therein, the seas, and all that is therein, and thou preservest them all; and the host of heaven worshippeth thee."}, {"verse": 7, "start": 107.31, "end": 118.8, "ta": "ஆபிராமைத் தெரிந்துகொண்டு, அவனை ஊர் என்னும் கல்தேயரின் பட்டணத்திலிருந்து புறப்படப்பண்ணி, அவனுக்கு ஆபிரகாம் என்னும் பேரிட்ட தேவனாகிய கர்த்தர் நீர்.", "en": "Thou art the LORD the God, who didst choose Abram, and broughtest him forth out of Ur of the Chaldees, and gavest him the name of Abraham;"}, {"verse": 8, "start": 118.8, "end": 138.56, "ta": "அவன் இருதயத்தை உமக்கு முன்பாக உண்மையுள்ளதாகக்கண்டு, கானானியர் ஏத்தியர், எமோரியர், பெரிசியர், எபூசியர், கிர்காசியருடைய தேசத்தை அவன் சந்ததிக்குக் கொடுக்கும்படி, அவனோடு உடன்படிக்கைபண்ணி, உம்முடைய வார்த்தைகளை நிறைவேற்றினீர்; நீர் நீதியுள்ளவர்.", "en": "And foundest his heart faithful before thee, and madest a covenant with him to give the land of the Canaanites, the Hittites, the Amorites, and the Perizzites, and the Jebusites, and the Girgashites, to give it, I say , to his seed, and hast performed thy words; for thou art righteous:"}, {"verse": 9, "start": 138.56, "end": 147.32, "ta": "எகிப்திலே எங்கள் பிதாக்கள் அநுபவித்த சிறுமையை நீர் கண்டு, சிவந்த சமுத்திரத்தில் அவர்கள் கூப்பிடுதலைக்கேட்டீர்.", "en": "And didst see the affliction of our fathers in Egypt, and heardest their cry by the Red sea;"}, {"verse": 10, "start": 147.32, "end": 169.37, "ta": "பார்வோனிடத்திலும், அவனுடைய எல்லா ஊழியக்காரரிடத்திலும், அவன் தேசத்தின் சகல ஜனத்தினிடத்திலும், அடையாளங்களையும் அற்புதங்களையும் செய்தீர்; அவர்கள் உமது ஜனங்களை அகந்தையாய் நடத்தினார்கள் என்பதை அறிந்திருந்தீர்; இப்படியே இந்நாள்வரைக்கும் இருக்கிறபடி உமக்குக் கீர்த்தியை உண்டாக்கினீர்.", "en": "And shewedst signs and wonders upon Pharaoh, and on all his servants, and on all the people of his land: for thou knewest that they dealt proudly against them. So didst thou get thee a name, as it is this day."}, {"verse": 11, "start": 169.37, "end": 184.53, "ta": "நீர் அவர்களுக்கு முன்பாகச் சமுத்திரத்தைப் பிரித்ததினால், கடலின் நடுவாகக் கால்நனையாமல் நடந்தார்கள்; வலுவான தண்ணீர்களிலே கல்லைப்போடுகிறதுபோல, அவர்களைத் தொடர்ந்தவர்களை ஆழங்களிலே போட்டுவிட்டீர்.", "en": "And thou didst divide the sea before them, so that they went through the midst of the sea on the dry land; and their persecutors thou threwest into the deeps, as a stone into the mighty waters."}, {"verse": 12, "start": 184.53, "end": 195.38, "ta": "நீர் பகலிலே மேகஸ்தம்பத்தினாலும் அவர்கள் நடக்கவேண்டிய வழியை அவர்களுக்கு வெளிச்சமாக்க இரவிலே அக்கினி ஸ்தம்பத்தினாலும், அவர்களை வழிநடத்தினீர்.", "en": "Moreover thou leddest them in the day by a cloudy pillar; and in the night by a pillar of fire, to give them light in the way wherein they should go."}, {"verse": 13, "start": 195.38, "end": 208.59, "ta": "நீர் சீனாய் மலையிலிறங்கி வானத்திலிருந்து அவர்களோடே பேசி, அவர்களுக்குச் செம்மையான நீதிநியாயங்களையும், நல்ல கட்டளைகளும் கற்பனைகளுமாகிய உண்மையான பிரமாணங்களையும் கொடுத்தீர்.", "en": "Thou camest down also upon mount Sinai, and spakest with them from heaven, and gavest them right judgments, and true laws, good statutes and commandments:"}, {"verse": 14, "start": 208.59, "end": 221.52, "ta": "உமது பரிசுத்த ஓய்வுநாளை அவர்களுக்குத் தெரியப்படுத்தி, உமது தாசனாகிய மோசேயைக்கொண்டு, அவர்களுக்குக் கற்பனைகளையும், கட்டளைகளையும் நியாயப்பிரமாணங்களையும் கற்பித்தீர்.", "en": "And madest known unto them thy holy sabbath, and commandedst them precepts, statutes, and laws, by the hand of Moses thy servant:"}, {"verse": 15, "start": 221.52, "end": 239.34, "ta": "அவர்கள் பசிக்கு வானத்திலிருந்து அப்பம் கொடுத்து, அவர்கள் தாகத்துக்குக் கன்மலையிலிருந்து தண்ணீர் புறப்படப்பண்ணி, நீர் அவர்களுக்குக் கொடுப்பேன் என்று ஆணையிட்ட தேசத்தைச் சுதந்தரித்துக்கொள்ளப் பிரவேசியுங்கள் என்று அவர்களுக்குச் சொன்னீர்.", "en": "And gavest them bread from heaven for their hunger, and broughtest forth water for them out of the rock for their thirst, and promisedst them that they should go in to possess the land which thou hadst sworn to give them."}, {"verse": 16, "start": 239.34, "end": 249.4, "ta": "எங்கள் பிதாக்களாகிய அவர்களோ அகங்காரமாய் நடந்து, தங்கள் கழுத்தைக் கடினப்படுத்தி, உம்முடைய கற்பனைகளுக்குச் செவிகொடாதேபோனார்கள்.", "en": "But they and our fathers dealt proudly, and hardened their necks, and hearkened not to thy commandments,"}, {"verse": 17, "start": 249.4, "end": 277.7, "ta": "அவர்கள் செவிகொடுக்க மனதில்லாமலும், அவர்களிடத்திலே நீர் செய்த உம்முடைய அற்புதங்களை நினையாமலும் போய், தங்கள் கழுத்தைக் கடினப்படுத்தி, தங்கள் அடிமைத்தனத்துக்குத் திரும்பும்படிக்கு அவர்கள் கலகம்பண்ணி, ஒரு தலைவனை ஏற்படுத்தினார்கள்; ஆகிலும் வெகுவாய் மன்னிக்கிறவரும் இரக்கமும் மனஉருக்கமும், நீடிய சாந்தமும், மகா கிருபையுமுள்ளவருமான தேவனாகிய நீர் அவர்களைக் கைவிடவில்லை.", "en": "And refused to obey, neither were mindful of thy wonders that thou didst among them; but hardened their necks, and in their rebellion appointed a captain to return to their bondage: but thou art a God ready to pardon, gracious and merciful, slow to anger, and of great kindness, and forsookest them not."}, {"verse": 18, "start": 277.7, "end": 291.49, "ta": "அவர்கள் வார்ப்பிக்கப்பட்ட ஒரு கன்றுக்குட்டியைத் தங்களுக்கு உண்டாக்கி: இது உன்னை எகிப்திலிருந்து கொண்டுவந்த உன் தெய்வம் என்று சொல்லி, கோபமூட்டத்தக்க பெரிய அக்கிரமங்களைச் செய்திருந்தாலும்,", "en": "Yea, when they had made them a molten calf, and said, This is thy God that brought thee up out of Egypt, and had wrought great provocations;"}, {"verse": 19, "start": 291.49, "end": 310.31, "ta": "நீர் உம்முடைய மிகுந்த மன உருக்கத்தின்படியே, அவர்களை வனாந்தரத்திலே கைவிடவில்லை; அவர்களை வழிநடத்தப் பகலிலே மேகஸ்தம்பமும், அவர்களுக்கு வெளிச்சத்தையும் அவர்கள் நடக்கவேண்டிய வழியையும் காட்ட இரவிலே அக்கினி ஸ்தம்பமும், அவர்களை விட்டு விலகவில்லை.", "en": "Yet thou in thy manifold mercies forsookest them not in the wilderness: the pillar of the cloud departed not from them by day, to lead them in the way; neither the pillar of fire by night, to shew them light, and the way wherein they should go."}, {"verse": 20, "start": 310.31, "end": 322.02, "ta": "அவர்களுக்கு அறிவை உணர்த்த உம்முடைய நல்ல ஆவியைக் கட்டளையிட்டீர், அவர்கள் வாய்க்கு உம்முடைய மன்னாவை அருளி, அவர்கள் தாகத்துக்குத் தண்ணீரைக் கொடுத்தீர்.", "en": "Thou gavest also thy good spirit to instruct them, and withheldest not thy manna from their mouth, and gavest them water for their thirst."}, {"verse": 21, "start": 322.02, "end": 336.03, "ta": "இப்படி நாற்பது வருஷமாக வனாந்தரத்தில் அவர்களுக்கு ஒன்றும் குறைவுபடாதபடிக்கு அவர்களைப் பராமரித்துவந்தீர்; அவர்கள் வஸ்திரங்கள் பழமையாய்ப்போகவுமில்லை, அவர்கள் கால்கள் வீங்கவுமில்லை.", "en": "Yea, forty years didst thou sustain them in the wilderness, so that they lacked nothing; their clothes waxed not old, and their feet swelled not."}, {"verse": 22, "start": 336.03, "end": 351.83, "ta": "அவர்களுக்கு ராஜ்யங்களையும் ஜனங்களையும் ஒப்புக்கொடுத்து, அவைகளை எல்லை எல்லையாக அவர்களுக்குப் பங்கிட்டீர்; எஸ்போனின் ராஜாவாகிய சீகோனின் தேசத்தையும் பாசானின் ராஜாவாகிய ஓகின் தேசத்தையும் கட்டிக்கொண்டார்கள்.", "en": "Moreover thou gavest them kingdoms and nations, and didst divide them into corners: so they possessed the land of Sihon, and the land of the king of Heshbon, and the land of Og king of Bashan."}, {"verse": 23, "start": 351.83, "end": 363.97, "ta": "அவர்கள் பிள்ளைகளை வானத்து நட்சத்திரங்களைப்போலப் பெருகப்பண்ணி, சுதந்தரித்துக்கொள்ளும்படி நீர் அவர்கள் பிதாக்களுக்குச் சொன்ன தேசத்திலே அவர்களை அழைத்து வந்தீர்.", "en": "Their children also multipliedst thou as the stars of heaven, and broughtest them into the land, concerning which thou hadst promised to their fathers, that they should go in to possess it ."}, {"verse": 24, "start": 363.97, "end": 384.58, "ta": "அப்படியே பிள்ளைகள் உட்பிரவேசித்து, தேசத்தைச் சுதந்தரித்துக்கொண்டார்கள்; நீர் அவர்களுக்கு முன்பாகத் தேசத்தின் குடிகளாகிய கானானியரைத் தாழ்த்தி, அவர்களையும் அவர்கள் ராஜாக்களையும், தேசத்தின் ஜனங்களையும், தங்கள் இஷ்டப்படி செய்ய, அவர்கள் கையிலே ஒப்புக்கொடுத்தீர்.", "en": "So the children went in and possessed the land, and thou subduedst before them the inhabitants of the land, the Canaanites, and gavest them into their hands, with their kings, and the people of the land, that they might do with them as they would."}, {"verse": 25, "start": 384.58, "end": 409.08, "ta": "அவர்கள் அரணான பட்டணங்களையும், செழுமையான பூமியையும் கட்டிக்கொண்டு, சகலவித உடமைகள் நிறைந்த வீடுகளையும், வெட்டப்பட்ட துரவுகளையும் ஏராளமான திராட்சத்தோட்டங்களையும் ஒலிவத்தோப்புகளையும், கனிகொடுக்கும் விருட்சங்களையும் சுதந்தரித்துக்கொண்டு புசித்துத் திருப்தியாகிக் கொழுத்து, உம்முடைய பெரிய தயையினால் செல்வமாய் வாழ்ந்தார்கள்.", "en": "And they took strong cities, and a fat land, and possessed houses full of all goods, wells digged, vineyards, and oliveyards, and fruit trees in abundance: so they did eat, and were filled, and became fat, and delighted themselves in thy great goodness."}, {"verse": 26, "start": 409.08, "end": 431.27, "ta": "ஆனாலும் அவர்கள் கீழ்ப்படியாதவர்களாகி உமக்கு விரோதமாய்க் கலகம்பண்ணி, உம்முடைய நியாயப்பிரமாணத்தை தங்களுக்குப் புறம்பே எறிந்துவிட்டு, தங்களை உம்மிடத்தில் திருப்பும்படி அவர்களைத் திடசாட்சியாய்க் கடிந்துகொண்ட உம்முடைய தீர்க்கதரிசிகளைக் கொன்றுபோட்டு, கோபமூட்டுகிற பெரிய அக்கிரமங்களைச் செய்தார்கள்.", "en": "Nevertheless they were disobedient, and rebelled against thee, and cast thy law behind their backs, and slew thy prophets which testified against them to turn them to thee, and they wrought great provocations."}, {"verse": 27, "start": 431.27, "end": 455.2, "ta": "ஆகையால் அவர்களை நெருக்குகிற அவர்கள் சத்துருக்களின் கையில் அவர்களை ஒப்புக்கொடுத்தீர்; அவர்கள் நெருக்கம் அநுபவிக்கிற காலத்தில் அவர்கள் உம்மை நோக்கிக் கூப்பிடுகிறபோதோ, நீர் பரலோகத்திலிருந்து கேட்டு உம்முடைய மிகுந்த இரக்கத்தினால் அவர்களை அவர்கள் சத்துருக்களுக்கு நீங்கலாக்கிவிடுகிற இரட்சகர்களை அவர்களுக்குக் கொடுத்தீர்.", "en": "Therefore thou deliveredst them into the hand of their enemies, who vexed them: and in the time of their trouble, when they cried unto thee, thou heardest them from heaven; and according to thy manifold mercies thou gavest them saviours, who saved them out of the hand of their enemies."}, {"verse": 28, "start": 455.2, "end": 481.27, "ta": "அவர்களுக்கு இளைப்பாறுதல் உண்டானபோதோ, உமக்கு முன்பாக மறுபடியும் பொல்லாப்புச் செய்யத்தொடங்கினார்கள்; ஆகையால் அவர்கள் சத்துருக்கள் அவர்களை ஆளும்படிக்கு அவர்கள் கையிலே ஒப்புவித்தீர்; அவர்கள் மனந்திரும்பி உம்மை நோக்கிக் கூப்பிட்டபோதோ, நீர் பரலோகத்திலிருந்து கேட்டு, அவர்களை உம்முடைய இரக்கங்களின்படியே அநேகந்தரம், விடுதலையாக்கிவிட்டீர்.", "en": "But after they had rest, they did evil again before thee: therefore leftest thou them in the hand of their enemies, so that they had the dominion over them: yet when they returned, and cried unto thee, thou heardest them from heaven; and many times didst thou deliver them according to thy mercies;"}, {"verse": 29, "start": 481.27, "end": 507.92, "ta": "அவர்களை உம்முடைய நியாயப்பிரமாணத்துக்குத் திருப்ப அவர்களைத் திடசாட்சியாய்க் கடிந்துகொண்டீர்; அவர்கள் அகங்காரங் கொண்டு, உம்முடைய கற்பனைகளுக்குச் செவிகொடாமல் கீழ்ப்படிந்து நடக்கிற மனுஷன் செய்து பிழைக்கிற உம்முடைய நீதி நியாயங்களுக்கு விரோதமாகப் பாவஞ்செய்து, தங்கள் தோளை முரண்டுத்தனமாய் விலக்கி, செவிகொடாமல் தங்கள் கழுத்தைக் கடினப்படுத்திக்கொண்டார்கள்.", "en": "And testifiedst against them, that thou mightest bring them again unto thy law: yet they dealt proudly, and hearkened not unto thy commandments, but sinned against thy judgments, (which if a man do, he shall live in them;) and withdrew the shoulder, and hardened their neck, and would not hear."}, {"verse": 30, "start": 507.92, "end": 525.88, "ta": "நீர் அநேக வருஷமாக அவர்கள்மேல் பொறுமையாயிருந்து, உம்முடைய ஆவியினால் பேசின உம்முடைய தீர்க்கதரிசிகளைக்கொண்டு அவர்களைத் திடசாட்சியாய்க் கடிந்துகொண்டாலும், அவர்கள் செவிகொடாதபடியினாலே, அவர்களை அந்நிய தேசஜனங்களின் கையில் ஒப்புக்கொடுத்தீர்.", "en": "Yet many years didst thou forbear them, and testifiedst against them by thy spirit in thy prophets: yet would they not give ear: therefore gavest thou them into the hand of the people of the lands."}, {"verse": 31, "start": 525.88, "end": 537.16, "ta": "ஆகிலும் உம்முடைய மிகுந்த இரக்கங்களின்படியே, அவர்களை நிர்மூலமாக்காமலும் அவர்களைக் கைவிடாமலும் இருந்தீர்; நீர் கிருபையும் இரக்கமுமுள்ள தேவன்.", "en": "Nevertheless for thy great mercies’ sake thou didst not utterly consume them, nor forsake them; for thou art a gracious and merciful God."}, {"verse": 32, "start": 537.16, "end": 567.25, "ta": "இப்பொழுதும் உடன்படிக்கையையும் கிருபையையும் காக்கிற வல்லமையும் பயங்கரமுமுள்ள மகா தேவனாகிய எங்கள் தேவனே, அசீரியா ராஜாக்களின் நாட்கள் முதற்கொண்டு இந்நாள்வரைக்கும் எங்களுக்கும் எங்கள் ராஜாக்களுக்கும், எங்கள் பிரபுக்களுக்கும், எங்கள் ஆசாரியர்களுக்கும் எங்கள் தீர்க்கதரிசிகளுக்கும், எங்கள் பிதாக்களுக்கும் உம்முடைய ஜனங்கள் அனைவருக்கும் நேரிட்ட சகல வருத்தமும் உமக்கு முன்பாக அற்பமாய்க் காணப்படாதிருப்பதாக.", "en": "Now therefore, our God, the great, the mighty, and the terrible God, who keepest covenant and mercy, let not all the trouble seem little before thee, that hath come upon us, on our kings, on our princes, and on our priests, and on our prophets, and on our fathers, and on all thy people, since the time of the kings of Assyria unto this day."}, {"verse": 33, "start": 567.25, "end": 577.02, "ta": "எங்களுக்கு நேரிடப்பண்ணின எல்லாவற்றிலும் நீர் நீதியுள்ளவர்; நீர் உண்மையாய் நடப்பித்தீர்; நாங்களோ ஆகாமியம் பண்ணினோம்.", "en": "Howbeit thou art just in all that is brought upon us; for thou hast done right, but we have done wickedly:"}, {"verse": 34, "start": 577.02, "end": 594.19, "ta": "எங்கள் ராஜாக்களும், எங்கள் பிரபுக்களும், எங்கள் ஆசாரியர்களும் எங்கள் பிதாக்களும் உம்முடைய நியாயப்பிரமாணத்தின்படி செய்யாமலும், உம்முடைய கற்பனைகளையும் நீர் அவர்களைக் கடிந்துகொண்ட உம்முடைய சாட்சிகளையும் கவனியாமலும்போனார்கள்.", "en": "Neither have our kings, our princes, our priests, nor our fathers, kept thy law, nor hearkened unto thy commandments and thy testimonies, wherewith thou didst testify against them."}, {"verse": 35, "start": 594.19, "end": 612.65, "ta": "அவர்கள் தங்கள் ராஜ்யத்திலும், நீர் அவர்களுக்குக் கொடுத்த உம்முடைய பெரிய தயையிலும், நீர் அவர்களுக்கு முன்பாகத் திறந்துவைத்த விசாலமும் செழிப்புமான தேசத்திலும் உமக்கு ஊழியஞ்செய்யாமலும், தங்கள் துர்க்கருமங்களை விட்டுத் திரும்பாமலும் போனார்கள்.", "en": "For they have not served thee in their kingdom, and in thy great goodness that thou gavest them, and in the large and fat land which thou gavest before them, neither turned they from their wicked works."}, {"verse": 36, "start": 612.65, "end": 626.23, "ta": "இதோ, இன்றையதினம் நாங்கள் அடிமைகளாயிருக்கிறோம், இதோ பலனையும் நன்மையையும் அனுபவிக்கும்படி நீர் எங்கள் பிதாக்களுக்குக் கொடுத்த இந்தத் தேசத்தில்தானே நாங்கள் அடிமைகளாயிருக்கிறோம்.", "en": "Behold, we are servants this day, and for the land that thou gavest unto our fathers to eat the fruit thereof and the good thereof, behold, we are servants in it:"}, {"verse": 37, "start": 626.23, "end": 644.33, "ta": "அதின் வருமானம் எங்கள் பாவங்களினிமித்தம் நீர் எங்கள்மேல் வைத்த ராஜாக்களுக்குத் திரளாகப்போகிறது; அவர்கள் தங்களுக்கு இஷ்டமானபடியே எங்கள் சரீரங்களையும் எங்கள் மிருக ஜீவன்களையும் ஆளுகிறார்கள்; நாங்கள் மகா இக்கட்டில் அகப்பட்டிருக்கிறோம்.", "en": "And it yieldeth much increase unto the kings whom thou hast set over us because of our sins: also they have dominion over our bodies, and over our cattle, at their pleasure, and we are in great distress."}, {"verse": 38, "start": 644.33, "end": 658.84, "ta": "இவையெல்லாம் இப்படி இருக்கிறபடியால் நாங்கள் உறுதியான உடன்படிக்கைபண்ணி அதை எழுதிவைக்கிறோம்; எங்கள் பிரபுக்களும் எங்கள் லேவியரும், எங்கள் ஆசாரியரும் அதற்கு முத்திரைபோடுவார்கள் என்றார்கள்.", "en": "And because of all this we make a sure covenant , and write it; and our princes, Levites, and priests, seal unto it ."}]}, "10": {"chapter": 10, "duration": 349.74, "audio_url": "audio_ot/OT16_10.mp3", "total_verses": 39, "verses": [{"verse": 1, "start": 3.8, "end": 11.44, "ta": "முத்திரைபோட்டவர்கள் யாரென்றால்: அகலியாவின் குமாரனாகிய திர்ஷாதா என்னும் நெகேமியா, சிதேகியா,", "en": "Now those that sealed were , Nehemiah, the Tirshatha, the son of Hachaliah, and Zidkijah,"}, {"verse": 2, "start": 11.44, "end": 14.07, "ta": "செராயா, அசரியா, எரேமியா,", "en": "Seraiah, Azariah, Jeremiah,"}, {"verse": 3, "start": 14.07, "end": 16.45, "ta": "பஸ்கூர் அமரியா, மல்கிஜா,", "en": "Pashur, Amariah, Malchijah,"}, {"verse": 4, "start": 16.45, "end": 19.32, "ta": "அத்தூஸ், செபனியா, மல்லுூக்,", "en": "Hattush, Shebaniah, Malluch,"}, {"verse": 5, "start": 19.32, "end": 21.95, "ta": "ஆரீம், மெரெமோத், ஒபதியா,", "en": "Harim, Meremoth, Obadiah,"}, {"verse": 6, "start": 21.95, "end": 24.81, "ta": "தானியேல், கிநேதோன், பாருக்,", "en": "Daniel, Ginnethon, Baruch,"}, {"verse": 7, "start": 24.81, "end": 27.75, "ta": "மெசுல்லாம், அபியா, மீயாமின்,", "en": "Meshullam, Abijah, Mijamin,"}, {"verse": 8, "start": 27.75, "end": 32.21, "ta": "மாசியா, பில்காய், செமாயா என்னும் ஆசாரியர்களும்,", "en": "Maaziah, Bilgai, Shemaiah: these were the priests."}, {"verse": 9, "start": 32.21, "end": 40.97, "ta": "லேவியராகிய அசனியாவின் குமாரன் யெசுவா, எனாதாதின் குமாரரில் ஒருவனாகிய பின்னூயி, கத்மியேல் என்பவர்களும்,", "en": "And the Levites: both Jeshua the son of Azaniah, Binnui of the sons of Henadad, Kadmiel;"}, {"verse": 10, "start": 40.97, "end": 46.7, "ta": "அவர்கள் சகோதரராகிய செபனியா, ஒதியா, கேலிதா, பெலாயா, ஆனான்,", "en": "And their brethren, Shebaniah, Hodijah, Kelita, Pelaiah, Hanan,"}, {"verse": 11, "start": 46.7, "end": 49.08, "ta": "மீகா, ரேகோப், அசபியா,", "en": "Micha, Rehob, Hashabiah,"}, {"verse": 12, "start": 49.08, "end": 51.95, "ta": "சக்கூர், செரெபியா, செபனியா,", "en": "Zaccur, Sherebiah, Shebaniah,"}, {"verse": 13, "start": 51.95, "end": 55.29, "ta": "ஒதியா, பானி, பெனினு என்பவர்களும்,", "en": "Hodijah, Bani, Beninu."}, {"verse": 14, "start": 55.29, "end": 61.26, "ta": "ஜனத்தின் தலைவராகிய பாரோஷ், பாகாத்மோவாப், ஏலாம், சத்தூ, பானி,", "en": "The chief of the people; Parosh, Pahath-moab, Elam, Zatthu, Bani,"}, {"verse": 15, "start": 61.26, "end": 63.89, "ta": "புன்னி, அஸ்காத், பெபாயி,", "en": "Bunni, Azgad, Bebai,"}, {"verse": 16, "start": 63.89, "end": 66.59, "ta": "அதோனியா, பிக்வாய், ஆதின்,", "en": "Adonijah, Bigvai, Adin,"}, {"verse": 17, "start": 66.59, "end": 69.06, "ta": "ஆதேர், இஸ்கியா, அசூர்,", "en": "Ater, Hizkijah, Azzur,"}, {"verse": 18, "start": 69.06, "end": 71.45, "ta": "ஒதியா, ஆசூ, பெத்சாய்,", "en": "Hodijah, Hashum, Bezai,"}, {"verse": 19, "start": 71.45, "end": 73.91, "ta": "ஆரீப், ஆனதோத், நெபாய்,", "en": "Hariph, Anathoth, Nebai,"}, {"verse": 20, "start": 73.91, "end": 76.94, "ta": "மக்பியாஸ், மெசுல்லாம், ஏசீர்,", "en": "Magpiash, Meshullam, Hezir,"}, {"verse": 21, "start": 76.94, "end": 79.88, "ta": "மெஷெசாபெயேல், சாதோக், யதுவா,", "en": "Meshezabeel, Zadok, Jaddua,"}, {"verse": 22, "start": 79.88, "end": 82.51, "ta": "பெலத்தியா, ஆனான், ஆனாயா,", "en": "Pelatiah, Hanan, Anaiah,"}, {"verse": 23, "start": 82.51, "end": 84.9, "ta": "ஓசெயா, அனனியா, அசூப்,", "en": "Hoshea, Hananiah, Hashub,"}, {"verse": 24, "start": 84.9, "end": 87.6, "ta": "அல்லோகேஸ், பிலகா, சோபேக்,", "en": "Hallohesh, Pileha, Shobek,"}, {"verse": 25, "start": 87.6, "end": 90.07, "ta": "ரேகூம், அஷபனா, மாசெயா,", "en": "Rehum, Hashabnah, Maaseiah,"}, {"verse": 26, "start": 90.07, "end": 92.46, "ta": "அகியா, கானான், ஆனான்,", "en": "And Ahijah, Hanan, Anan,"}, {"verse": 27, "start": 92.46, "end": 96.44, "ta": "மல்லுூக், ஆரிம், பானா என்பவர்களுமே.", "en": "Malluch, Harim, Baanah."}, {"verse": 28, "start": 96.44, "end": 120.47, "ta": "ஜனங்களில் மற்றவர்களாகிய ஆசாரியரும், லேவியரும் வாசல் காவலாளரும், பாடகரும், நிதனீமியரும், தேசங்களின் ஜனங்களைவிட்டுப் பிரிந்து விலகி தேவனுடைய நியாயப்பிரமாணத்துக்குத் திரும்பின அனைவரும் அவர்கள் மனைவிகளும், அவர்கள் குமாரரும் அவர்கள் குமாரத்திகளுΠξகிய அறிவும் Ϊுத்தியும் உள͠γவர்களெல்லாரும்,", "en": "And the rest of the people, the priests, the Levites, the porters, the singers, the Nethinims, and all they that had separated themselves from the people of the lands unto the law of God, their wives, their sons, and their daughters, every one having knowledge, and having understanding;"}, {"verse": 29, "start": 120.47, "end": 144.66, "ta": "தங்களுக்குப் பெரியவர்களாகிய தங்கள் சகோதரரோடே கூடிக்கொண்டு: தேவனுடைய தாசனாகிய மோசேயைக்கொண்டு கொடுக்கப்பட்ட தேவனுடைய நியாயப்பிரமாணத்தின்படி நடந்துகொள்வோம் என்றும், எங்கள் ஆண்டவராகிய கர்த்தரின் கற்பனைகளையும் சகல நீதிநியாயங்களையும், கட்டளைகளையும் எல்லாம் கைக்கொண்டு, அவைகளின்படி செய்வோம் என்றும்,", "en": "They clave to their brethren, their nobles, and entered into a curse, and into an oath, to walk in God’s law, which was given by Moses the servant of God, and to observe and do all the commandments of the LORD our Lord, and his judgments and his statutes;"}, {"verse": 30, "start": 144.66, "end": 155.89, "ta": "நாங்கள் எங்கள் குமாரத்திகளை தேசத்தின் ஜனங்களுக்குக் கொடாமலும், எங்கள் குமாரருக்கு அவர்கள் குமாரத்திகளைக் கொள்ளாமலும் இருப்போம் என்றும்,", "en": "And that we would not give our daughters unto the people of the land, nor take their daughters for our sons:"}, {"verse": 31, "start": 155.89, "end": 181.35, "ta": "தேசத்தின் ஜனங்கள் ஓய்வுநாளிலே சரக்குகளையும், எந்தவிதத் தானியதவசத்தையும் விற்கிறதற்குக் கொண்டுவந்தால், நாங்கள் அதை ஓய்வுநாளிலும் பரிசுத்தநாளிலும் அவர்கள் கையில் கொள்ளாதிருப்போம் என்றும், நாங்கள் ஏழாம் வருஷத்தை விடுதலை வருஷமாக்கிச் சகல கடன்களையும் விட்டுவிடுவோம் என்றும் ஆணையிட்டுப் பிரமாணம்பண்ணினார்கள்.", "en": "And if the people of the land bring ware or any victuals on the sabbath day to sell, that we would not buy it of them on the sabbath, or on the holy day: and that we would leave the seventh year, and the exaction of every debt."}, {"verse": 32, "start": 181.35, "end": 204.59, "ta": "மேலும்: நாங்கள் எங்கள் தேவனுடைய ஆலயத்தின் ஆராதனைக்காக சமுகத்தப்பங்களுக்கும், நித்தியபோஜனபலிக்கும் ஓய்வுநாட்களிலும் மாதப்பிறப்புகளிலும் செலுத்தும் நித்திய சர்வாங்க தகனபலிகளுக்கும் பண்டிகைகளுக்கும், பிரதிஷ்டையான பொருள்களுக்கும், இஸ்ரவேலுக்காக பாவநிவிர்த்தி உண்டாக்கும் பலிகளுக்கும்,", "en": "Also we made ordinances for us, to charge ourselves yearly with the third part of a shekel for the service of the house of our God;"}, {"verse": 33, "start": 204.59, "end": 217.01, "ta": "எங்கள் தேவனுடைய ஆலயத்தின் சகல வேலைக்கும், வருஷந்தோறும் நாங்கள் சேக்கலில் மூன்றில் ஒரு பங்கைக் கொடுப்போம் என்கிற கடனை எங்கள்மேல் ஏற்றுக்கொண்டோம்.", "en": "For the shewbread, and for the continual meat offering, and for the continual burnt offering, of the sabbaths, of the new moons, for the set feasts, and for the holy things , and for the sin offerings to make an atonement for Israel, and for all the work of the house of our God."}, {"verse": 34, "start": 217.01, "end": 243.35, "ta": "நியாயப்பிரமாணத்தில் எழுதியிருக்கிறபடியே எங்கள் தேவனாகிய கர்த்தருடைய பலிபீடத்தின்மேல் எரிகிறதற்காக, குறிக்கப்பட்ட காலங்களில் வருஷாவருஷம் எங்கள் பிதாக்களுடைய குடும்பங்களின்படியே, எங்கள் தேவனுடைய ஆலயத்துக்கு கொண்டுவரவேண்டிய விறகு காணிக்கைக்காகவும், ஆசாரியருக்கும், லேவியருக்கும், ஜனத்துக்கும் சீட்டுப்போட்டோம்.", "en": "And we cast the lots among the priests, the Levites, and the people, for the wood offering, to bring it into the house of our God, after the houses of our fathers, at times appointed year by year, to burn upon the altar of the LORD our God, as it is written in the law:"}, {"verse": 35, "start": 243.35, "end": 254.81, "ta": "நாங்கள் வருஷந்தோறும் எங்கள் தேவனுடைய ஆலயத்துக்கு எங்கள் தேசத்தின் முதற்பலனையும், சகலவித விருட்சங்களின் எல்லா முதற்கனிகளையும் கொண்டுவரவும்,", "en": "And to bring the firstfruits of our ground, and the firstfruits of all fruit of all trees, year by year, unto the house of the LORD :"}, {"verse": 36, "start": 254.81, "end": 274.39, "ta": "நியாயப்பிரமாணத்தில் எழுதியிருக்கிறபடியே, எங்கள் குமாரரில் முதற்பேறுகளையும், எங்கள் ஆடுமாடுகளாகிய மிருகஜீவன்களின் தலையீற்றுகளையும், எங்கள் தேவனுடைய ஆலயத்துக்கும் எங்கள் தேவனுடைய ஆலயத்திலே ஊழியஞ்செய்கிற ஆசாரியரிடத்துக்கும் கொண்டுவரவும்,", "en": "Also the firstborn of our sons, and of our cattle, as it is written in the law, and the firstlings of our herds and of our flocks, to bring to the house of our God, unto the priests that minister in the house of our God:"}, {"verse": 37, "start": 274.39, "end": 303.27, "ta": "நாங்கள் எங்கள் பிசைந்தமாவில் முதற்பாகத்தையும் எங்கள் படைப்புகளையும், சகல மரங்களின் முந்தின பலனாகிய திராட்சப்பழரசத்தையும் எண்ணெயையும், எங்கள் தேவனுடைய ஆலயத்தின் அறைகளில் வைக்கும்படி ஆசாரியரிடத்துக்கும், எங்கள் நிலப்பயிர்களில் தசமபாகம் லேவியரிடத்திற்கும் கொண்டுவரவும், லேவியராகிய இவர்கள் எங்கள் வெள்ளாண்மையின் பட்டணங்களிலெல்லாம் தசமபாகம் சேர்க்கவும்,", "en": "And that we should bring the firstfruits of our dough, and our offerings, and the fruit of all manner of trees, of wine and of oil, unto the priests, to the chambers of the house of our God; and the tithes of our ground unto the Levites, that the same Levites might have the tithes in all the cities of our tillage."}, {"verse": 38, "start": 303.27, "end": 321.34, "ta": "லேவியர் தசமபாகம் சேர்க்கும்போது ஆரோனின் குமாரனாகிய ஒரு ஆசாரியன் லேவியரோடேகூட இருக்கவும், தசமபாகமாகிய அதிலே லேவியர் பத்தில் ஒரு பங்கை எங்கள் தேவனுடைய ஆலயத்திலுள்ள பொக்கிஷ அறைகளில் கொண்டுவரவும் திட்டம்பண்ணிக்கொண்டோம்.", "en": "And the priest the son of Aaron shall be with the Levites, when the Levites take tithes: and the Levites shall bring up the tithe of the tithes unto the house of our God, to the chambers, into the treasure house."}, {"verse": 39, "start": 321.34, "end": 348.24, "ta": "பரிசுத்தஸ்தலத்தின் பணிமுட்டுகளும், ஊழியஞ்செய்கிற ஆசாரியரும் வாசல் காவலாளரும், பாடகரும் இருக்கிற அந்த அறைகளிலே இஸ்ரவேல் புத்திரரும் லேவிபுத்திரரும் தானியம் திராட்சரசம் எண்ணெய் என்பவைகளின் படைப்புகளைக் கொண்டுவரவேண்டியது; இவ்விதமாய் நாங்கள் எங்கள் தேவனுடைய ஆலயத்தைப் பராமரியாமல் விடுவதில்லையென்று திட்டம்பண்ணிக்கொண்டோம்.", "en": "For the children of Israel and the children of Levi shall bring the offering of the corn, of the new wine, and the oil, unto the chambers, where are the vessels of the sanctuary, and the priests that minister, and the porters, and the singers: and we will not forsake the house of our God."}]}, "11": {"chapter": 11, "duration": 374.73, "audio_url": "audio_ot/OT16_11.mp3", "total_verses": 36, "verses": [{"verse": 1, "start": 3.8, "end": 22.24, "ta": "ஜனத்தின் அதிகாரிகள் எருசலேமிலே குடியிருந்தார்கள்; மற்ற ஜனங்கள், தங்களுக்குள்ளே பத்துப்பேரில் ஒருவனை எருசலேமென்னும் பரிசுத்த நகரத்திலும் ஒன்பதுபேரை மற்றப் பட்டணங்களிலும் குடியிருக்கப்பண்ணி, சீட்டுகளைப் போட்டார்கள்.", "en": "And the rulers of the people dwelt at Jerusalem: the rest of the people also cast lots, to bring one of ten to dwell in Jerusalem the holy city, and nine parts to dwell in other cities."}, {"verse": 2, "start": 22.24, "end": 30.76, "ta": "ஆனாலும் எருசலேமிலே குடியிருக்க மனப்பூர்வமாய்ச் சம்மதித்த மனுஷர்களையெல்லாம் ஜனங்கள் வாழ்த்தினார்கள்.", "en": "And the people blessed all the men, that willingly offered themselves to dwell at Jerusalem."}, {"verse": 3, "start": 30.76, "end": 49.67, "ta": "யூதாவின் பட்டணங்களில் இஸ்ரவேலரும் ஆசாரியரும், லேவியரும் நிதனீமியரும் சாலொமோனுடைய வேலைக்காரரின் புத்திரரும், அவரவர் தங்கள் பட்டணங்களிலுள்ள தங்கள் காணிபூமியிலே குடியிருந்தார்கள்; எருசலேமிலே குடியிருந்த நாடுகளின் தலைவர் யாரென்றால்:", "en": "Now these are the chief of the province that dwelt in Jerusalem: but in the cities of Judah dwelt every one in his possession in their cities, to wit , Israel, the priests, and the Levites, and the Nethinims, and the children of Solomon’s servants."}, {"verse": 4, "start": 49.67, "end": 70.56, "ta": "எருசலேமிலே யூதா புத்திரரில் சிலரும், பென்யமீன் புத்திரரில் சிலரும் குடியிருந்தார்கள்; யூதா புத்திரரிலே பேரேசின் புத்திரருக்குள் ஒருவனான மகலாலெயேலின் குமாரனாகிய செபதியாவின் குமாரன் அமரியாவுக்குப் பிறந்த சகரியாவுக்குக் குமாரனான உசியாவின் மகன் அத்தாயாவும்,", "en": "And at Jerusalem dwelt certain of the children of Judah, and of the children of Benjamin. Of the children of Judah; Athaiah the son of Uzziah, the son of Zechariah, the son of Amariah, the son of Shephatiah, the son of Mahalaleel, of the children of Perez;"}, {"verse": 5, "start": 70.56, "end": 82.86, "ta": "சீலோனின் குமாரன் சகரியாவுக்குக் குமாரனாகிய யோயாரிபுக்குக் குமாரனான அதாயாவுக்குப் பிறந்த அசாயாவின் குமாரன் கொல்லோசேபெற்ற பாருக்கின் மகன் மாசெயாவுமே.", "en": "And Maaseiah the son of Baruch, the son of Col-hozeh, the son of Hazaiah, the son of Adaiah, the son of Joiarib, the son of Zechariah, the son of Shiloni."}, {"verse": 6, "start": 82.86, "end": 91.92, "ta": "எருசலேமிலே குடியிருக்கிற பேரேசின் புத்திரரெல்லாரும் நானூற்று அறுபத்தெட்டுப் பராக்கிரமசாலிகளாயிருந்தார்கள்.", "en": "All the sons of Perez that dwelt at Jerusalem were four hundred threescore and eight valiant men."}, {"verse": 7, "start": 91.92, "end": 110.6, "ta": "பென்யமீன் புத்திரரில் யாரென்றால் சல்லு என்பவன்; இவன் மெசுல்லாமுக்கும், இவன் யோவேலுக்கும், இவன் பெதாயாவுக்கும், இவன் கொலாயாவுக்கும், இவன் மாசெயாவுக்கும், இவன் இதியேலுக்கும், இவன் எசாயாவுக்கும் குமாரனானவன்.", "en": "And these are the sons of Benjamin; Sallu the son of Meshullam, the son of Joed, the son of Pedaiah, the son of Kolaiah, the son of Maaseiah, the son of Ithiel, the son of Jesaiah."}, {"verse": 8, "start": 110.6, "end": 117.54, "ta": "அவனுக்குப்பின் கப்பாய், சல்லாய் முதலானவர்கள் தொளாயிரத்து இருபத்தெட்டுப்பேர்.", "en": "And after him Gabbai, Sallai, nine hundred twenty and eight."}, {"verse": 9, "start": 117.54, "end": 128.65, "ta": "அவர்கள்மேல் விசாரிப்புக்காரனான சிக்ரியின் குமாரன் யோவேலும் பட்டணத்தின்மேல் இரண்டாவது விசாரிப்புக்காரனான செனுவாவின் குமாரன் யூதாவுமே.", "en": "And Joel the son of Zichri was their overseer: and Judah the son of Senuah was second over the city."}, {"verse": 10, "start": 128.65, "end": 133.93, "ta": "ஆசாரியர்களில் யோயாரிபின் குமாரன் யெதாயா, யாகின் என்பவர்களும்,", "en": "Of the priests: Jedaiah the son of Joiarib, Jachin."}, {"verse": 11, "start": 133.93, "end": 146.07, "ta": "அகிதூபின் குமாரன் மெராயோத்துக்குப் பிறந்த சாதோக்கின் குமாரன் மெசுல்லாம் பெற்ற இல்க்கியாவின் மகன் செராயா என்னும் தேவனுடைய ஆலயத்தின் விசாரணைக்கர்த்தனும்,", "en": "Seraiah the son of Hilkiah, the son of Meshullam, the son of Zadok, the son of Meraioth, the son of Ahitub, was the ruler of the house of God."}, {"verse": 12, "start": 146.07, "end": 162.62, "ta": "ஆலயத்திலே பணிவிடை செய்கிற அவர்கள் சகோதரராகிய எண்ணூற்று இருபத்திரண்டுபேரும், மல்கியாவின் குமாரன் பஸ்கூருக்கு மகனான சகரியாவின் குமாரன் அம்சிக்குப் பிறந்த பெல்லியாவின் குமாரன் எரோகாமுக்குப் பிறந்த அதாயாவும்,", "en": "And their brethren that did the work of the house were eight hundred twenty and two: and Adaiah the son of Jeroham, the son of Pelaliah, the son of Amzi, the son of Zechariah, the son of Pashur, the son of Malchiah,"}, {"verse": 13, "start": 162.62, "end": 175.31, "ta": "பிதா வம்சத்தலைவனாகிய அவனுடைய சகோதரர் இருநூற்று நாற்பத்திரண்டுபேரும் இம்மேரின் குமாரன் மெசில்லேமோத்தின் மகனாகிய அகசாய்க்குப் பிறந்த அசரெயேலின் மகனான அமாசாயும்,", "en": "And his brethren, chief of the fathers, two hundred forty and two: and Amashai the son of Azareel, the son of Ahasai, the son of Meshillemoth, the son of Immer,"}, {"verse": 14, "start": 175.31, "end": 187.14, "ta": "அவர்களுடைய சகோதரராகிய பராக்கிரமசாலிகள் நூற்று இருபத்தெட்டுப்பேருமே, இவர்கள்மேல் அகெதோலிமின் குமாரன் சப்தியேல் விசாரிப்புக்காரனாயிருந்தான்.", "en": "And their brethren, mighty men of valour, an hundred twenty and eight: and their overseer was Zabdiel, the son of one of the great men."}, {"verse": 15, "start": 187.14, "end": 194.78, "ta": "லேவியரிலே புன்னியின் குமாரன் சபியாவின் மகனாகிய அஸ்ரிக்காமின் குமாரனான அசூபின் மகன் செமாயாவும்,", "en": "Also of the Levites: Shemaiah the son of Hashub, the son of Azrikam, the son of Hashabiah, the son of Bunni;"}, {"verse": 16, "start": 194.78, "end": 201.88, "ta": "தேவனுடைய ஆலயத்தின் வெளிவேலையை விசாரிக்கிற லேவியரின் தலைவரிலே சபெதாயும், யோசபாத்தும்,", "en": "And Shabbethai and Jozabad, of the chief of the Levites, had the oversight of the outward business of the house of God."}, {"verse": 17, "start": 201.88, "end": 221.03, "ta": "ஆசாபின் குமாரன் சப்தியின் குமாரனாகிய மீகாவின் மகன் மத்தனியா ஜெபத்தில் ஸ்தோத்திரப்பாட்டைத் துவக்குகிற தலைவனும் அவன் சகோதரரில் இரண்டாவதான பக்பூக்கியா என்னும் ஒருவனும், எதுத்தூனின் குமாரன் காலாவின் மகனாகிய சமுவாவின் குமாரன் அப்தாவுமே.", "en": "And Mattaniah the son of Micha, the son of Zabdi, the son of Asaph, was the principal to begin the thanksgiving in prayer: and Bakbukiah the second among his brethren, and Abda the son of Shammua, the son of Galal, the son of Jeduthun."}, {"verse": 18, "start": 221.03, "end": 227.33, "ta": "பரிசுத்த பட்டணத்திலிருந்த லேவியர் எல்லாரும் இருநூற்று எண்பத்துநாலுபேர்.", "en": "All the Levites in the holy city were two hundred fourscore and four."}, {"verse": 19, "start": 227.33, "end": 236.32, "ta": "வாசல் காவலாளர் அக்கூபும், தல்மோனும் வாசல்களில் காவல்காக்கிற அவர்கள் சகோதரரும் நூற்றுஎழுபத்திரண்டுபேர்.", "en": "Moreover the porters, Akkub, Talmon, and their brethren that kept the gates, were an hundred seventy and two."}, {"verse": 20, "start": 236.32, "end": 246.25, "ta": "மற்ற இஸ்ரவேலரும், ஆசாரியரும், லேவியரும் யூதாவின் சகல பட்டணங்களிலும், அவரவர் தங்கள் சுதந்தரத்திலிருந்தார்கள்.", "en": "And the residue of Israel, of the priests, and the Levites, were in all the cities of Judah, every one in his inheritance."}, {"verse": 21, "start": 246.25, "end": 255.39, "ta": "நிதனீமியர் ஒபேலிலே குடியிருந்தார்கள்; அவர்கள்மேல் சீகாவும் கிஸ்பாவும் விசாரிப்புக்காரராயிருந்தார்கள்.", "en": "But the Nethinims dwelt in Ophel: and Ziha and Gispa were over the Nethinims."}, {"verse": 22, "start": 255.39, "end": 272.66, "ta": "எருசலேமிலிருக்கிற லேவியரின் விசாரிப்புக்காரன் மீகாவின் குமாரன் மத்தனியாவின் மகனாகிய அசபியாவுக்குப் பிறந்த பானியின் குமாரன் ஊசி என்பவன் தேவனுடைய ஆலயத்தின் ஊழியத்துக்கு நிற்கிற பாடகராகிய ஆசாபின் குமாரரில் ஒருவன்.", "en": "The overseer also of the Levites at Jerusalem was Uzzi the son of Bani, the son of Hashabiah, the son of Mattaniah, the son of Micha. Of the sons of Asaph, the singers were over the business of the house of God."}, {"verse": 23, "start": 272.66, "end": 280.38, "ta": "பாடகராகிய அவர்களுக்காக அன்றாடகப்படி கொடுக்கப்படும்படி ராஜாவினால் கட்டளையிடப்பட்டிருந்தது.", "en": "For it was the king’s commandment concerning them, that a certain portion should be for the singers, due for every day."}, {"verse": 24, "start": 280.38, "end": 291.65, "ta": "யூதாவின் குமாரனாகிய சேராக்கின் புத்திரரில் மெசசாபெயேலின் குமாரன் பெத்தகியா ஜனத்தின் காரியங்களுக்கெல்லாம் ராஜாவின் சமுகத்தில் நின்றான்.", "en": "And Pethahiah the son of Meshezabeel, of the children of Zerah the son of Judah, was at the king’s hand in all matters concerning the people."}, {"verse": 25, "start": 291.65, "end": 308.12, "ta": "தங்கள் நாட்டுப்புறங்களான கிராமங்களில் இருக்கிறவர்களுக்குள்ளே யூதாவின் புத்திரரில் சிலர் கீரியாத்அர்பாவிலும் அதின் கிராமங்களிலும், தீபோனிலும் அதின் கிராமங்களிலும், எகாப்செயேலிலும் அதின் கிராமங்களிலும்,", "en": "And for the villages, with their fields, some of the children of Judah dwelt at Kirjath-arba, and in the villages thereof, and at Dibon, and in the villages thereof, and at Jekabzeel, and in the villages thereof,"}, {"verse": 26, "start": 308.12, "end": 312.22, "ta": "யெசுவாவிலும், மோலாதாகிலும், பெத்பெலேதிலும்,", "en": "And at Jeshua, and at Moladah, and at Beth-phelet,"}, {"verse": 27, "start": 312.22, "end": 317.5, "ta": "ஆத்சார்சூகாவிலும், பெயெர்செபாவிலும், அதின் கிராமங்களிலும்,", "en": "And at Hazar-shual, and at Beer-sheba, and in the villages thereof,"}, {"verse": 28, "start": 317.5, "end": 322.08, "ta": "சிக்லாகிலும், மேகோனாகிலும், அதின் கிராமங்களிலும்,", "en": "And at Ziklag, and at Mekonah, and in the villages thereof,"}, {"verse": 29, "start": 322.08, "end": 326.33, "ta": "என்ரிம்மோனிலும், சாரேயாகிலும், யர்மூத்திலும்,", "en": "And at En-rimmon, and at Zareah, and at Jarmuth,"}, {"verse": 30, "start": 326.33, "end": 343.04, "ta": "சானோவாலும், அதுல்லாமிலும் அவைகளின் கிராமங்களிலும், லாகீசிலும் அதின் நாட்டுப்புறங்களிலும், அசெக்காவிலும் அதின் கிராமங்களிலும், பெயெர்செபா தொடங்கி இன்னோமின் பள்ளத்தாக்குமட்டும் குடியேறினார்கள்.", "en": "Zanoah, Adullam, and in their villages, at Lachish, and the fields thereof, at Azekah, and in the villages thereof. And they dwelt from Beer-sheba unto the valley of Hinnom."}, {"verse": 31, "start": 343.04, "end": 351.55, "ta": "கேபாவின் ஊராராயிருந்த பென்யமீன் புத்திரர், மிக்மாஸ், ஆயா, பெத்தேல் ஊர்களிலும் அதின் கிளைகளிலும்,", "en": "The children also of Benjamin from Geba dwelt at Michmash, and Aija, and Beth-el, and in their villages,"}, {"verse": 32, "start": 351.55, "end": 353.92, "ta": "ஆனதோத், நோப், அனனியா,", "en": "And at Anathoth, Nob, Ananiah,"}, {"verse": 33, "start": 353.92, "end": 356.6, "ta": "ஆத்சோர், ஆமா, கித்தாயிம்,", "en": "Hazor, Ramah, Gittaim,"}, {"verse": 34, "start": 356.6, "end": 359.28, "ta": "ஆதீத், செபோயிம், நெபலாத்,", "en": "Hadid, Zeboim, Neballat,"}, {"verse": 35, "start": 359.28, "end": 366.85, "ta": "லோத், ஓனோ என்னும் ஊர்களிலும், சிற்பாசாரிகளின் பள்ளத்தாக்கிலும் குடியிருந்தார்கள்.", "en": "Lod, and Ono, the valley of craftsmen."}, {"verse": 36, "start": 366.85, "end": 373.23, "ta": "லேவியரிலே சில வகுப்பார் யூதாவிலும், சிலர் பென்யமீனிலும் இருந்தார்கள்.", "en": "And of the Levites were divisions in Judah, and in Benjamin."}]}, "12": {"chapter": 12, "duration": 501.24, "audio_url": "audio_ot/OT16_12.mp3", "total_verses": 47, "verses": [{"verse": 1, "start": 3.8, "end": 13.02, "ta": "செயல்த்தியேலின் குமாரனாகிய செருபாபேலோடும் யெசுவாவோடும் வந்த ஆசாரியரும் லேவியரும் யாரென்றால்: செராயா எரேமியா, எஸ்றா,", "en": "Now these are the priests and the Levites that went up with Zerubbabel the son of Shealtiel, and Jeshua: Seraiah, Jeremiah, Ezra,"}, {"verse": 2, "start": 13.02, "end": 15.61, "ta": "அமரியா, மல்லூக், அத்தூஸ்,", "en": "Amariah, Malluch, Hattush,"}, {"verse": 3, "start": 15.61, "end": 18.28, "ta": "செகனியா, ரெகூம், மெரெமோத்,", "en": "Shechaniah, Rehum, Meremoth,"}, {"verse": 4, "start": 18.28, "end": 20.57, "ta": "இத்தோ, கிநேதோ, அபியா,", "en": "Iddo, Ginnetho, Abijah,"}, {"verse": 5, "start": 20.57, "end": 23.16, "ta": "மியாமின், மாதியா, பில்கா,", "en": "Miamin, Maadiah, Bilgah,"}, {"verse": 6, "start": 23.16, "end": 25.75, "ta": "செமாயா, யோயாரிப், யெதாயா,", "en": "Shemaiah, and Joiarib, Jedaiah,"}, {"verse": 7, "start": 25.75, "end": 37.71, "ta": "சல்லு, ஆமோக், இல்க்கியா, யெதாயா என்பவர்கள்; இவர்கள் யெசுவாவின் நாட்களில், ஆசாரியருக்கும் தங்கள் சகோதரருக்கும் தலைவராயிருந்தார்கள்.", "en": "Sallu, Amok, Hilkiah, Jedaiah. These were the chief of the priests and of their brethren in the days of Jeshua."}, {"verse": 8, "start": 37.71, "end": 50.06, "ta": "லேவியர் யாரென்றால்: யெசுவா பின்னூயி, கத்மியேல், செரெபியா, யூதா, மத்தனியா என்பவர்கள்; இவனும் இவன் சகோதரரும் துதிசெய்தலை விசாரித்தார்கள்.", "en": "Moreover the Levites: Jeshua, Binnui, Kadmiel, Sherebiah, Judah, and Mattaniah, which was over the thanksgiving, he and his brethren."}, {"verse": 9, "start": 50.06, "end": 57.3, "ta": "பக்புக்கியா, உன்னி என்கிற அவர்கள் சகோதரர் அவர்களுக்கு எதிரே காவல்காத்திருந்தார்கள்.", "en": "Also Bakbukiah and Unni, their brethren, were over against them in the watches."}, {"verse": 10, "start": 57.3, "end": 65.07, "ta": "யெசுவா யொயாசீமைப் பெற்றான், யாயசீம் எலியாசிபைப் பெற்றான், எலியாசிப் யொயதாவைப் பெற்றான்.", "en": "And Jeshua begat Joiakim, Joiakim also begat Eliashib, and Eliashib begat Joiada,"}, {"verse": 11, "start": 65.07, "end": 70.33, "ta": "யொயதா யோனத்தானைப் பெற்றான், யோனத்தான் யதுவாலைப் பெற்றான்.", "en": "And Joiada begat Jonathan, and Jonathan begat Jaddua."}, {"verse": 12, "start": 70.33, "end": 80.61, "ta": "யொயகீமின் நாட்களிலே பிதா வம்சங்களின் தலைவரான ஆசாரியர்கள் யாரென்றால்: செராயாவின் சந்ததியில் மெராயா, எரேமியாவின் சந்ததியில் அனனியா,", "en": "And in the days of Joiakim were priests, the chief of the fathers: of Seraiah, Meraiah; of Jeremiah, Hananiah;"}, {"verse": 13, "start": 80.61, "end": 85.87, "ta": "எஸ்றாவின் சந்ததியில் மெசுல்லாம், அமரியாவின் சந்ததியில் யோகனான்,", "en": "Of Ezra, Meshullam; of Amariah, Jehohanan;"}, {"verse": 14, "start": 85.87, "end": 91.28, "ta": "மெலிகுவின் சந்ததியில் யோனத்தான், செபனியாவின் சந்ததியில் யோசேப்பு,", "en": "Of Melicu, Jonathan; of Shebaniah, Joseph;"}, {"verse": 15, "start": 91.28, "end": 96.01, "ta": "ஆரீமின் சந்ததியில் அத்னா, மெராயோதின் சந்ததியில் எல்காய்,", "en": "Of Harim, Adna; of Meraioth, Helkai;"}, {"verse": 16, "start": 96.01, "end": 101.19, "ta": "இத்தோவின் சந்ததியில் சகரியா, கிநெதோனின் சந்ததியில் மெசுல்லாம்,", "en": "Of Iddo, Zechariah; of Ginnethon, Meshullam;"}, {"verse": 17, "start": 101.19, "end": 108.05, "ta": "அபியாவின் சந்ததியில் சிக்ரி, மினியாமீன்மொவதியா, என்பவர்களின் சந்ததியில் பில்தாய்,", "en": "Of Abijah, Zichri; of Miniamin, of Moadiah, Piltai;"}, {"verse": 18, "start": 108.05, "end": 113.76, "ta": "பில்காவின் சந்ததியில் சம்முவா, செமாயாவின் சந்ததியில் யோனத்தான்.", "en": "Of Bilgah, Shammua; of Shemaiah, Jehonathan;"}, {"verse": 19, "start": 113.76, "end": 120.24, "ta": "யோயாரிபின் சந்ததியில் மத்தனா, யெதாயாவின் சந்ததியில் நெதனெயேல் என்பவர்கள்.", "en": "And of Joiarib, Mattenai; of Jedaiah, Uzzi;"}, {"verse": 20, "start": 120.24, "end": 125.04, "ta": "சல்லாயின் சந்ததியில் கல்லாய், ஆமோக்கின் சந்ததியில் ஏபேர்,", "en": "Of Sallai, Kallai; of Amok, Eber;"}, {"verse": 21, "start": 125.04, "end": 131.75, "ta": "இல்க்கியாவின் சந்ததியில் அசபியா, யெதாயாவின் சந்ததியில் நெதனெயேல் என்பவர்கள்.", "en": "Of Hilkiah, Hashabiah; of Jedaiah, Nethaneel."}, {"verse": 22, "start": 131.75, "end": 147.45, "ta": "எலியாசிபின் நாட்களில் யொயதா, யோகனான், யதுவா என்கிற லேவியர் பிதா வம்சங்களின் தலைவராக எழுதப்பட்டார்கள்; பெர்சியனாகிய தரியுவின் ராஜ்யபாரமட்டும் இருந்த ஆசாரியர்களும் அப்படியே எழுதப்பட்டார்கள்;", "en": "The Levites in the days of Eliashib, Joiada, and Johanan, and Jaddua, were recorded chief of the fathers: also the priests, to the reign of Darius the Persian."}, {"verse": 23, "start": 147.45, "end": 157.96, "ta": "லேவி புத்திரராகிய பிதா வம்சங்களின் தலைவர் எலியாசிபின் குமாரனாகிய யோகனானின் நாட்கள்மட்டும் நாளாகமப் புஸ்தகத்தில் எழுதப்பட்டார்கள்.", "en": "The sons of Levi, the chief of the fathers, were written in the book of the chronicles, even until the days of Johanan the son of Eliashib."}, {"verse": 24, "start": 157.96, "end": 179.15, "ta": "லேவியரின் தலைவராகிய அபியாவும், செரெபியாவும், கத்மியேலின் குமாரன் யெசுவாவும், அவர்களுக்கு எதிரே நிற்கிற அவர்கள் சகோதரரும், தேவனுடைய மனுஷனாகிய தாவீதினுடைய கற்பனையின்படியே துதிக்கவும், தோத்திரிக்கவும், ஒருவருக்கொருவர் எதிர்முகமாக முறைமுறையாயிருந்தார்கள்.", "en": "And the chief of the Levites: Hashabiah, Sherebiah, and Jeshua the son of Kadmiel, with their brethren over against them, to praise and to give thanks, according to the commandment of David the man of God, ward over against ward."}, {"verse": 25, "start": 179.15, "end": 191.49, "ta": "மத்தனியா, பக்புக்கியா, ஒபதியா, மெசுல்லாம், தல்மோன், அக்கூப் என்பவர்கள் வாசல்களிலிருக்கிற பொக்கிஷ அறைகளைக் காவல்காக்கிறவர்களாயிருந்தார்கள்.", "en": "Mattaniah, and Bakbukiah, Obadiah, Meshullam, Talmon, Akkub, were porters keeping the ward at the thresholds of the gates."}, {"verse": 26, "start": 191.49, "end": 205.82, "ta": "யோத்சதாக்கின் குமாரனாகிய யெசுவாவின் குமாரன் யொயகீமின் நாட்களிலும், அதிபதியாகிய நெகேமியாவும், வேதபாரகனாகிய எஸ்றா என்னும் ஆசாரியனும் இருக்கிற நாட்களிலும் அவர்கள் இருந்தார்கள்.", "en": "These were in the days of Joiakim the son of Jeshua, the son of Jozadak, and in the days of Nehemiah the governor, and of Ezra the priest, the scribe."}, {"verse": 27, "start": 205.82, "end": 224.95, "ta": "எருசலேமின் அலங்கத்தைப் பிரதிஷ்டைபண்ணுகையில், துதியினாலும், பாடலினாலும் கைத்தாளம் தம்புரு சுரமண்டலம் முதலான கீதவாத்தியங்களினாலும், பிரதிஷ்டையை மகிழ்ச்சியோடே கொண்டாட எல்லா இடங்களிலும் இருக்கிற லேவியரை எருசலேமுக்கு வரும்படி தேடினார்கள்.", "en": "And at the dedication of the wall of Jerusalem they sought the Levites out of all their places, to bring them to Jerusalem, to keep the dedication with gladness, both with thanksgivings, and with singing, with cymbals, psalteries, and with harps."}, {"verse": 28, "start": 224.95, "end": 233.33, "ta": "அப்படியே பாடகரின் புத்திரர் எருசலேமின் சுற்றுப்புறங்களான சமபூமியிலும், நெத்தோபாத்தியரின் கிராமங்களிலும்,", "en": "And the sons of the singers gathered themselves together, both out of the plain country round about Jerusalem, and from the villages of Netophathi;"}, {"verse": 29, "start": 233.33, "end": 247.27, "ta": "பெத்கில்காலிலும், கேபா, அஸ்மாவேத் ஊர்களின் நாட்டுப்புறங்களிலுமிருந்துவந்து கூடினார்கள்; பாடகர் எருசலேமைச் சுற்றிலும் தங்களுக்குக் கிராமங்களைக் கட்டியிருந்தார்கள்.", "en": "Also from the house of Gilgal, and out of the fields of Geba and Azmaveth: for the singers had builded them villages round about Jerusalem."}, {"verse": 30, "start": 247.27, "end": 256.95, "ta": "ஆசாரியரும் லேவியரும் தங்களைச் சுத்தம்பண்ணிக்கொண்டு, ஜனத்தையும் பட்டணவாசல்களையும் அலங்கத்தையும் சுத்தம்பண்ணினார்கள்.", "en": "And the priests and the Levites purified themselves, and purified the people, and the gates, and the wall."}, {"verse": 31, "start": 256.95, "end": 274.94, "ta": "அப்பொழுது நான் யூதாவின் பிரபுக்களை அலங்கத்தின்மேல் ஏறப்பண்ணி, துதிசெய்து நடந்துபோகும்படி இரண்டு பெரிய கூட்டத்தாரை நிறுத்தினேன்; அவர்களில் ஒரு கூட்டத்தார் அலங்கத்தின்மேல் வலதுபுறமாகக் குப்பைமேட்டு வாசலுக்குப் போனார்கள்.", "en": "Then I brought up the princes of Judah upon the wall, and appointed two great companies of them that gave thanks, whereof one went on the right hand upon the wall toward the dung gate:"}, {"verse": 32, "start": 274.94, "end": 280.12, "ta": "அவர்கள் பிறகாலே ஒசாயாவும், யூதாவின் பிரபுக்களில் பாதிப்பேரும்,", "en": "And after them went Hoshaiah, and half of the princes of Judah,"}, {"verse": 33, "start": 280.12, "end": 282.79, "ta": "அசரியா, எஸ்றா, மெசுல்லாம்,", "en": "And Azariah, Ezra, and Meshullam,"}, {"verse": 34, "start": 282.79, "end": 287.21, "ta": "யூதா, பென்யமீன், செமாயா, எரேமியா என்பவர்களும்,", "en": "Judah, and Benjamin, and Shemaiah, and Jeremiah,"}, {"verse": 35, "start": 287.21, "end": 300.85, "ta": "பூரிகைகளைப் பிடிக்கிற ஆசாரியரின் புத்திரரில் ஆசாப்பின் குமாரன் சக்கூரின் மகனாகிய மிகாயாவுக்குக் குமாரனான மத்தனியாவின் மகன் செமாயாவுக்குப் பிறந்த யோனத்தானின் குமாரன் சகரியாவும்,", "en": "And certain of the priests’ sons with trumpets; namely , Zechariah the son of Jonathan, the son of Shemaiah, the son of Mattaniah, the son of Michaiah, the son of Zaccur, the son of Asaph:"}, {"verse": 36, "start": 300.85, "end": 319.44, "ta": "தேவனுடைய மனுஷனாகிய தாவீதின் கீதவாத்தியங்களை வாசிக்கிற அவன் சகோதரரான செமாயா, அசரெயேல், மிலாலாய், கிலாலாய், மகாய், நெதனெயேல், யூதா, அனானி என்பவர்களும் போனார்கள்; வேதபாரகனாகிய எஸ்றா இவர்களுக்கு முன்பாக நடந்தான்.", "en": "And his brethren, Shemaiah, and Azarael, Milalai, Gilalai, Maai, Nethaneel, and Judah, Hanani, with the musical instruments of David the man of God, and Ezra the scribe before them."}, {"verse": 37, "start": 319.44, "end": 335.67, "ta": "அங்கேயிருந்து அவர்கள் தங்களுக்கு எதிரான ஊருணிவாசலுக்கு வந்தபோது, அலங்கத்தைப்பார்க்கிலும் உயரமான தாவீது நகரத்தின் படிகளில் ஏறி, தாவீது வீட்டின்மேலாகக் கிழக்கேயிருக்கிற தண்ணீர் வாசல்மட்டும் போனார்கள்.", "en": "And at the fountain gate, which was over against them, they went up by the stairs of the city of David, at the going up of the wall, above the house of David, even unto the water gate eastward."}, {"verse": 38, "start": 335.67, "end": 351.75, "ta": "துதிசெய்கிற இரண்டாம் கூட்டத்தார் எதிரேயிருக்கிற வழியாய் நடந்துபோனார்கள், அவர்கள் பிறகாலே நான் போனேன்; ஜனத்தில் பாதிப்பேர் அலங்கத்தின்மேல் சூளைகளின் கொம்மையைக்கடந்து, அகழ் மதில்மட்டும் நெடுகப்போய்,", "en": "And the other company of them that gave thanks went over against them , and I after them, and the half of the people upon the wall, from beyond the tower of the furnaces even unto the broad wall;"}, {"verse": 39, "start": 351.75, "end": 366.61, "ta": "எப்பிராயீம் வாசலையும் பழையவாசலையும், மீன் வாசலையும், அனானெயேலின் கொம்மையையும், மேயா என்கிற கொம்மையையும் கடந்து, ஆட்டுவாசல்மட்டும் புறப்பட்டுக் காவல்வீட்டுவாசலிலே நின்றார்கள்.", "en": "And from above the gate of Ephraim, and above the old gate, and above the fish gate, and the tower of Hananeel, and the tower of Meah, even unto the sheep gate: and they stood still in the prison gate."}, {"verse": 40, "start": 366.61, "end": 377.66, "ta": "அதற்குப்பின்பு துதி செய்கிற இரண்டு கூட்டத்தாரும் தேவனுடைய ஆலயத்திலே வந்து நின்றார்கள்; நானும் என்னோடேகூட இருக்கிற தலைவரில் பாதிப்பேரும்,", "en": "So stood the two companies of them that gave thanks in the house of God, and I, and the half of the rulers with me:"}, {"verse": 41, "start": 377.66, "end": 387.72, "ta": "பூரிகைகளைப் பிடிக்கிற எலியாக்கீம், மாசெயா, மினியாமீன், மிகாயா, எலியோனாய், சகரியா, அனானியா என்கிற ஆசாரியர்களும்,", "en": "And the priests; Eliakim, Maaseiah, Miniamin, Michaiah, Elioenai, Zechariah, and Hananiah, with trumpets;"}, {"verse": 42, "start": 387.72, "end": 402.58, "ta": "மாசெயா, செமாயா, எலெயாசார், ஊசி, யோகனான், மல்கியா, ஏலாம், ஏசேர் என்பவர்களும் நின்றோம்; பாடகரும் அவர்கள் விசாரிப்புக்காரனாகிய யெஷாகியாவும சத்தமாய்ப் பாடினார்கள்.", "en": "And Maaseiah, and Shemaiah, and Eleazar, and Uzzi, and Jehohanan, and Malchijah, and Elam, and Ezer. And the singers sang loud, with Jezrahiah their overseer."}, {"verse": 43, "start": 402.58, "end": 419.65, "ta": "அந்நாளிலே மிகுதியான பலிகளைச் செலுத்தி தேவன் தங்களுக்கு மகா சந்தோஷத்தை உண்டாக்கினதினால் மகிழ்ச்சியாயிருந்தார்கள்; ஸ்திரீகளும் பிள்ளைகளுங்கூடக் களிகூர்ந்தார்கள்; எருசலேமின் களிப்பு தூரத்திலே கேட்கப்பட்டது.", "en": "Also that day they offered great sacrifices, and rejoiced: for God had made them rejoice with great joy: the wives also and the children rejoiced: so that the joy of Jerusalem was heard even afar off."}, {"verse": 44, "start": 419.65, "end": 449.98, "ta": "அன்றையதினம் பொக்கிஷங்களையும், படைப்புகளையும், முதல் கனிகளையும், தசமபாகங்களையும் வைக்கும் அறைகளின்மேல், ஆசாரியர்களுக்கும் லேவியர்களுக்கும் நியாயப்பிரமாணத்தின்படியே வரவேண்டிய பட்டணங்களுடைய நிலங்களின் பங்குகளை அவைகளில் சேர்க்கும்படிக்கு, சில மனுஷர் விசாரிப்புக்காரராக வைக்கப்பட்டார்கள்; ஊழியஞ்செய்து நிற்கிற ஆசாரியர்மேலும் லேவியர்மேலும் யூதா மனிதர் சந்தோஷமாயிருந்தார்கள்.", "en": "And at that time were some appointed over the chambers for the treasures, for the offerings, for the firstfruits, and for the tithes, to gather into them out of the fields of the cities the portions of the law for the priests and Levites: for Judah rejoiced for the priests and for the Levites that waited."}, {"verse": 45, "start": 449.98, "end": 462.25, "ta": "பாடகரும், வாசல் காவலாளரும், தாவீதும் அவன் குமாரனாகிய சாலொமோனும் கற்பித்தபடியே தங்கள் தேவனுடைய காவலையும், சுத்திகரிப்பின் காவலையும் காத்தார்கள்.", "en": "And both the singers and the porters kept the ward of their God, and the ward of the purification, according to the commandment of David, and of Solomon his son."}, {"verse": 46, "start": 462.25, "end": 475.28, "ta": "தாவீதும் ஆசாப்பும் இருந்த பூர்வநாட்களில் பாடகரின் தலைவரும் வைக்கப்பட்டு, தேவனுக்குத் துதியும் தோத்திரங்களும் செலுத்துகிற சங்கீதங்கள் திட்டம்பண்ணப்பட்டிருந்தது.", "en": "For in the days of David and Asaph of old there were chief of the singers, and songs of praise and thanksgiving unto God."}, {"verse": 47, "start": 475.28, "end": 499.74, "ta": "ஆகையால் செரூபாபேலின் நாட்களிலும், நெகேமியாவின் நாட்களிலும் இஸ்ரவேலர் எல்லாரும் பாடகருக்கும் வாசல் காவலாளருக்கும் அன்றாடகத் திட்டமாகிய பங்குகளைக் கொடுத்தார்கள்; அவர்கள் லேவியருக்கென்று பிரதிஷ்டைபண்ணிக் கொடுத்தார்கள்; லேவியர் ஆரோனின் புத்திரருக்கென்று அவர்கள் பங்கைப் பிரதிஷ்டைபண்ணிக் கொடுத்தார்கள்.", "en": "And all Israel in the days of Zerubbabel, and in the days of Nehemiah, gave the portions of the singers and the porters, every day his portion: and they sanctified holy things unto the Levites; and the Levites sanctified them unto the children of Aaron."}]}, "13": {"chapter": 13, "duration": 467.7, "audio_url": "audio_ot/OT16_13.mp3", "total_verses": 31, "verses": [{"verse": 1, "start": 3.8, "end": 22.84, "ta": "அன்றையதினம் ஜனங்கள் கேட்க மோசேயின் புஸ்தகத்தை வாசித்தார்கள்; அதிலே அம்மோனியரும் மோவாபியரும், இஸ்ரவேல் புத்திரருக்கு அப்பமும் தண்ணீரும் கொடுக்க எதிர்கொண்டுவராமல், அவர்களைச் சபிக்க அவர்களுக்கு விரோதமாய்ப் பிலேயாமைக் கூலிபொருந்திக்கொண்டபடியினால்,", "en": "On that day they read in the book of Moses in the audience of the people; and therein was found written, that the Ammonite and the Moabite should not come into the congregation of God for ever;"}, {"verse": 2, "start": 22.84, "end": 33.47, "ta": "அவர்கள் என்றைக்கும், அந்தச் சாபத்தை ஆசீர்வாதமாகத் திருப்பின எங்கள் தேவனுடைய சபைக்குட்படலாகாது என்று எழுதியிருக்கிறதாகக் காணப்பட்டது.", "en": "Because they met not the children of Israel with bread and with water, but hired Balaam against them, that he should curse them: howbeit our God turned the curse into a blessing."}, {"verse": 3, "start": 33.47, "end": 42.4, "ta": "ஆகையால் அவர்கள் அந்தக் கட்டளையைக் கேட்டபோது, பல ஜாதியான ஜனங்களையெல்லாம் இஸ்ரவேலைவிட்டுப் பிரித்துவிட்டார்கள்.", "en": "Now it came to pass, when they had heard the law, that they separated from Israel all the mixed multitude."}, {"verse": 4, "start": 42.4, "end": 52.0, "ta": "இதற்குமுன்னே எங்கள் தேவனுடைய ஆலயத்தின் அறைகளை விசாரிக்க வைக்கப்பட்ட ஆசாரியனாகிய எலியாசிப் தொபியாவோடே சம்பந்தங்கலந்தவனாயிருந்து,", "en": "And before this, Eliashib the priest, having the oversight of the chamber of the house of our God, was allied unto Tobiah:"}, {"verse": 5, "start": 52.0, "end": 74.8, "ta": "முற்காலத்தில் காணிக்கைகளும் சாம்பிராணியும், பணிமுட்டுகளும், லேவியருக்கும் பாடகருக்கும் வாசல்காவலருக்கும் கட்டளைபண்ணப்பட்ட தானியம் திராட்சரசம் எண்ணெய் என்பவைகளிலே தசமபாகமும், ஆசாரியரைச் சேருகிற படைப்பான காணிக்கைகளும் வைக்கப்பட்டிருந்த இடத்தில் ஒரு பெரிய அறையை அவனுக்கு ஆயத்தம்பண்ணியிருந்தான்.", "en": "And he had prepared for him a great chamber, where aforetime they laid the meat offerings, the frankincense, and the vessels, and the tithes of the corn, the new wine, and the oil, which was commanded to be given to the Levites, and the singers, and the porters; and the offerings of the priests."}, {"verse": 6, "start": 74.8, "end": 90.82, "ta": "இதெல்லாம் நடக்கும்போது நான் எருசலேமில் இல்லை; பாபிலோன் ராஜாவாகிய அர்தசஷ்டாவின் முப்பத்திரண்டாம் வருஷத்திலே நான் ராஜாவினிடத்திற்குப்போய், சில நாளுக்குப்பின்பு திரும்ப ராஜாவினிடத்தில் உத்தரவு பெற்றுக்கொண்டு,", "en": "But in all this time was not I at Jerusalem: for in the two and thirtieth year of Artaxerxes king of Babylon came I unto the king, and after certain days obtained I leave of the king:"}, {"verse": 7, "start": 90.82, "end": 103.14, "ta": "எருசலேமுக்கு வந்தேன்; அப்பொழுது எலியாசிப் தொபியாவுக்கு தேவனுடைய ஆலயத்துப் பிராகாரங்களில் ஒரு அறையை ஆயத்தம்பண்ணினதினால் செய்த பொல்லாப்பை அறிந்துகொண்டேன்.", "en": "And I came to Jerusalem, and understood of the evil that Eliashib did for Tobiah, in preparing him a chamber in the courts of the house of God."}, {"verse": 8, "start": 103.14, "end": 112.67, "ta": "அதினால் நான் மிகவும் மனமடிவாகி, தொபியாவின் வீட்டுத் தட்டுமுட்டுகளையெல்லாம் அந்த அறையிலிருந்து வெளியே எறிந்துவிட்டேன்.", "en": "And it grieved me sore: therefore I cast forth all the household stuff of Tobiah out of the chamber."}, {"verse": 9, "start": 112.67, "end": 124.4, "ta": "பின்பு நான் அறைவீடுகளைச் சுத்திகரிக்கச்சொல்லி, தேவனுடைய ஆலயப்பணிமுட்டுகளையும் காணிக்கைகளையும் சாம்பிராணியையும் அங்கே திரும்பக்கொண்டுவந்து வைத்தேன்.", "en": "Then I commanded, and they cleansed the chambers: and thither brought I again the vessels of the house of God, with the meat offering and the frankincense."}, {"verse": 10, "start": 124.4, "end": 138.79, "ta": "பின்னையும் லேவியருக்கு அவர்கள் பங்குகள் கொடுக்கப்படவில்லையென்பதையும், பணிவிடை செய்கிற லேவியரும் பாடகரும் அவரவர் தங்கள் வெளிநிலங்களுக்கு ஓடிப்போனார்கள் என்பதையும் நான் அறிந்துகொண்டேன்.", "en": "And I perceived that the portions of the Levites had not been given them: for the Levites and the singers, that did the work, were fled every one to his field."}, {"verse": 11, "start": 138.79, "end": 150.97, "ta": "அப்பொழுது நான் தலைமையானவர்களோடே வழக்காடி, தேவனுடைய ஆலயம் கைவிடப்பட்டுப்போவானேன் என்று சொல்லி, அவர்களைச் சேர்த்து, அவரவர் நிலையில் அவர்களை வைத்தேன்.", "en": "Then contended I with the rulers, and said, Why is the house of God forsaken? And I gathered them together, and set them in their place."}, {"verse": 12, "start": 150.97, "end": 159.98, "ta": "அப்பொழுது யூதர் எல்லாரும் தானியம் திராட்சரசம் எண்ணெய் என்பவைகளில் தசமபாகத்தைப் பொக்கிஷ அறைகளில் கொண்டுவந்தார்கள்.", "en": "Then brought all Judah the tithe of the corn and the new wine and the oil unto the treasuries."}, {"verse": 13, "start": 159.98, "end": 186.77, "ta": "அப்பொழுது நான் ஆசாரியராகிய செலேமியாவையும் வேதபாரகனாகிய சாதோக்கையும் லேவியரில் பெதாயாவையும், இவர்களுக்குக் கைத்துணையாக மத்தனியாவின் குமாரன்சக்கூரின் மகனாகிய ஆனானையும் பொக்கிஷ அறைகளின்மேல் விசாரிப்புக்காரராக வைத்தேன்; அவர்கள் உண்மையுள்ளவர்களென்று எண்ணப்பட்டார்கள்; ஆகையால் தங்கள் சகோதரருக்குப் பங்கிடுகிற வேலை அவர்களுக்கு ஒப்புவிக்கப்பட்டது.", "en": "And I made treasurers over the treasuries, Shelemiah the priest, and Zadok the scribe, and of the Levites, Pedaiah: and next to them was Hanan the son of Zaccur, the son of Mattaniah: for they were counted faithful, and their office was to distribute unto their brethren."}, {"verse": 14, "start": 186.77, "end": 198.95, "ta": "என் தேவனே, நான் என் தேவனுடைய ஆலயத்துக்காகவும் அதின் முறைமைகளுக்காகவும் செய்த நற்கிரியைகளைக் குலைத்துப்போடாமல், இந்தக் காரியத்திலே என்னை நினைத்தருளும்.", "en": "Remember me, O my God, concerning this, and wipe not out my good deeds that I have done for the house of my God, and for the offices thereof."}, {"verse": 15, "start": 198.95, "end": 225.88, "ta": "அந்த நாட்களில் நான் யூதாவிலே ஓய்வுநாளில் சிலர் ஆலைகளை மிதிக்கிறதையும், சிலர் ஆலைகளை தானியப் பொதிகளைக் கழுதைகள்மேல் ஏற்றிக்கொண்டு வருகிறதையும் திராட்சரசம், திராட்சப்பழம், அத்திப்பழம் முதலானவைகளின் பற்பல சுமைகளை ஓய்வுநாளிலே எருசலேமுக்குக் கொண்டுவருகிறதையும் கண்டு, அவர்கள் தின்பண்டம் விற்கிற நாளைப்பற்றி அவர்களைத் திடசாட்சியாய்க் கடிந்துகொண்டேன்.", "en": "In those days saw I in Judah some treading wine presses on the sabbath, and bringing in sheaves, and lading asses; as also wine, grapes, and figs, and all manner of burdens, which they brought into Jerusalem on the sabbath day: and I testified against them in the day wherein they sold victuals."}, {"verse": 16, "start": 225.88, "end": 238.14, "ta": "மீனையும் சகலவித சரக்குகளையும் கொண்டுவந்து, ஓய்வுநாளிலே யூதா புத்திரருக்கும் எருசலேமில் இருக்கிறவர்களுக்கும் விற்கிற சில தீரியரும் உள்ளே குடியிருந்தார்கள்.", "en": "There dwelt men of Tyre also therein, which brought fish, and all manner of ware, and sold on the sabbath unto the children of Judah, and in Jerusalem."}, {"verse": 17, "start": 238.14, "end": 248.1, "ta": "ஆகையால் நான் யூதாவின் பெரியவர்களைக் கடிந்துகொண்டு: நீங்கள் ஓய்வுநாளைப் பரிசுத்தக் குலைச்சலாக்குகிற இந்தப் பொல்லாத செய்கையென்ன?", "en": "Then I contended with the nobles of Judah, and said unto them, What evil thing is this that ye do, and profane the sabbath day?"}, {"verse": 18, "start": 248.1, "end": 269.28, "ta": "உங்கள் பிதாக்கள் இப்படிச்செய்ததினாலல்லவா, நமது தேவன் நம்மேலும் இந்தநகரத்தின்மேலும் இந்தத்தீங்கையெல்லாம் வரப்பண்ணினார்; நீங்களோவென்றால் ஓய்வுநாளைப் பரிசுத்தக் குலைச்சலாக்குகிறதினால் இஸ்ரவேலின்மேலிருக்கிற உக்கிரத்தை அதிகரிக்கப்பண்ணுகிறீர்கள் என்று அவர்களுக்குச் சொன்னேன்.", "en": "Did not your fathers thus, and did not our God bring all this evil upon us, and upon this city? yet ye bring more wrath upon Israel by profaning the sabbath."}, {"verse": 19, "start": 269.28, "end": 290.1, "ta": "ஆகையால் ஓய்வுநாளுக்குமுன்னே எருசலேமின் பட்டணவாசலில், மாலைமயங்கும்போது, கதவுகளைப்பூட்டவும், ஓய்வுநாள் முடியுமட்டும் அவைகளைத் திறவாதிருக்கவும் வேண்டுமென்று கட்டளையிட்டு, ஓய்வுநாளிலே ஒரு சுமையும் உள்ளே வராதபடிக்கு வாசலண்டையிலே என் வேலைக்காரரில் சிலரை நிறுத்தினேன்.", "en": "And it came to pass, that when the gates of Jerusalem began to be dark before the sabbath, I commanded that the gates should be shut, and charged that they should not be opened till after the sabbath: and some of my servants set I at the gates, that there should no burden be brought in on the sabbath day."}, {"verse": 20, "start": 290.1, "end": 299.25, "ta": "அதினால் வர்த்தகரும், சகலவித சரக்குகளை விற்கிறவர்களும், இரண்டொருதரம் எருசலேமுக்குப் புறம்பே இராத்தங்கினார்கள்.", "en": "So the merchants and sellers of all kind of ware lodged without Jerusalem once or twice."}, {"verse": 21, "start": 299.25, "end": 318.81, "ta": "அப்பொழுது நான் அவர்களைத் திடசாட்சியாய்க் கடிந்துகொன்டு, நீங்கள் அலங்கத்தண்டையிலே இராத்தங்குகிறது என்ன? நீங்கள் மறுபடியும் இப்படிச் செய்தால், உங்கள்மேல் கைபோடுவேன் என்று அவர்களோடே சொன்னேன்; அதுமுதல் அவர்கள் ஓய்வுநாளில் வராதிருந்தார்கள்.", "en": "Then I testified against them, and said unto them, Why lodge ye about the wall? if ye do so again, I will lay hands on you. From that time forth came they no more on the sabbath."}, {"verse": 22, "start": 318.81, "end": 336.3, "ta": "ஓய்வுநாளைப் பரிசுத்தமாக்கும்படிக்கு, உங்களைச் சுத்தம்பண்ணிக்கொண்டு வாசல்களைக் காக்க வாருங்களென்று லேவியருக்கும் சொன்னேன்என் தேவனே, இதைக்குறித்து நீர் என்னை நினைத்தருளி, உம்முடைய மிகுந்த கிருபையின்படி எனக்கு இரங்குவீராக.", "en": "And I commanded the Levites that they should cleanse themselves, and that they should come and keep the gates, to sanctify the sabbath day. Remember me, O my God, concerning this also, and spare me according to the greatness of thy mercy."}, {"verse": 23, "start": 336.3, "end": 344.71, "ta": "அஸ்தோத், அம்மோன், மோவாப் ஜாதிகளான ஸ்திரீகளைச் சேர்த்துக்கொண்ட சில யூதரையும் அந்த நாட்களில் கண்டேன்.", "en": "In those days also saw I Jews that had married wives of Ashdod, of Ammon, and of Moab:"}, {"verse": 24, "start": 344.71, "end": 356.89, "ta": "அவர்கள் பிள்ளைகள் பேசின பேச்சில் பாதி அஸ்தோத் பாஷையாயிருந்தது; இவர்கள் அந்தந்த ஜாதிகளின் பாஷையைத் தவிர யூதபாஷையைத் திட்டமாய்ப் பேச அறியாதிருந்தார்கள்.", "en": "And their children spake half in the speech of Ashdod, and could not speak in the Jews’ language, but according to the language of each people."}, {"verse": 25, "start": 356.89, "end": 381.76, "ta": "அவர்களையும் நான் கடிந்துகொண்டு அவர்கள்மேல் வரும் சாபத்தைக் கூறி அவர்களில் சிலரை அடித்து, மயிரைப் பிய்த்து: நீங்கள் உங்கள் குமாரத்திகளை அவர்கள் குமாரருக்குக் கொடாமலும், அவர்கள் குமாரத்திகளில் ஒருவரையும் உங்கள் குமாரருக்காகிலும் உங்களுக்காகிலும் கொள்ளாமலும் இருக்கவேண்டுமென்று அவர்களை தேவன்மேல் ஆணையிடப்பண்ணி, நான் அவர்களை நோக்கி:", "en": "And I contended with them, and cursed them, and smote certain of them, and plucked off their hair, and made them swear by God, saying , Ye shall not give your daughters unto their sons, nor take their daughters unto your sons, or for yourselves."}, {"verse": 26, "start": 381.76, "end": 405.24, "ta": "இஸ்ரவேலின் ராஜாவாகிய சாலொமோன் இதினாலே பாவஞ்செய்தானல்லவா? அவனைப்போன்ற ராஜா அநேகம் ஜாதிகளுக்குள்ளே உண்டாயிருந்ததில்லை; அவன் தன் தேவனாலே சிநேகிக்கப்பட்டவனாயிருந்தான்; தேவன் அவனை இஸ்ரவேலனைத்தின்மேலும் ராஜாவாக வைத்தார்; அப்பபடிப்பட்டவனையும் மறுஜாதியான ஸ்திரீகள் பாவஞ்செய்யப்பண்ணினார்களே.", "en": "Did not Solomon king of Israel sin by these things? yet among many nations was there no king like him, who was beloved of his God, and God made him king over all Israel: nevertheless even him did outlandish women cause to sin."}, {"verse": 27, "start": 405.24, "end": 419.19, "ta": "நீங்கள் மறுஜாதியான ஸ்திரீகளைச் சேர்த்துக்கொள்ளுகிறதினால், நம்முடைய தேவனுக்குத் துரோகிகளாகி, இந்தப் பெரிய பொல்லாப்பையெல்லாம் செய்யும்படி, உங்களுக்கு இடங்கொடுப்போமோ என்றேன்.", "en": "Shall we then hearken unto you to do all this great evil, to transgress against our God in marrying strange wives?"}, {"verse": 28, "start": 419.19, "end": 431.36, "ta": "யொயதாவின் புத்திரரிலே பிரதான ஆசாரியனாகிய எலியாசிபினுடைய குமாரன் ஒருவன் ஓரோனியனான சன்பல்லாத்துக்கு மருமகனானான்; ஆகையால் அவனை என்னைவிட்டுத் துரத்தினேன்.", "en": "And one of the sons of Joiada, the son of Eliashib the high priest, was son in law to Sanballat the Horonite: therefore I chased him from me."}, {"verse": 29, "start": 431.36, "end": 444.06, "ta": "என் தேவனே, அவர்கள் ஆசாரிய ஊழியத்தையும், ஆசாரிய ஊழியத்துக்கும் லேவியருக்கும் இருக்கிற உடன்படிக்கையையும் தீட்டுப்படுத்தினார்களென்று அவர்களை நினைத்துக்கொள்ளும்.", "en": "Remember them, O my God, because they have defiled the priesthood, and the covenant of the priesthood, and of the Levites."}, {"verse": 30, "start": 444.06, "end": 453.95, "ta": "இப்படியே நான் மறுஜாதியாரையெல்லாம் நீக்கி, ஆசாரியரையும் லேவியரையும் சுத்திகரித்து, அவரவரை அவர்கள் வேலையின் முறைகளில் நிறுத்தி,", "en": "Thus cleansed I them from all strangers, and appointed the wards of the priests and the Levites, every one in his business;"}, {"verse": 31, "start": 453.95, "end": 466.2, "ta": "குறிக்கப்பட்ட காலங்களில் செலுத்தப்படவேண்டிய விறகுகாணிக்கையையும் முதற்பலன்களையுங்குறித்துத் திட்டம்பண்ணினேன்என் தேவனே எனக்கு நன்மையுண்டாக என்னை நினைத்தருளும்.", "en": "And for the wood offering, at times appointed, and for the firstfruits. Remember me, O my God, for good."}]}}};
}
